   psortie       VARCHAR2(300);
   const_ok      NUMBER;
   wpage         NUMBER;
   numpage       NUMBER;
   i             NUMBER;
   ie            NUMBER;
   ip            NUMBER;
   repet         NUMBER;
   w_trt         VARCHAR2(1);
   ver           VARCHAR2(1) := '!';
   hor           VARCHAR2(1) := '-';
   csg           VARCHAR2(1) := '-';
   csd           VARCHAR2(1) := '-';
   cig           VARCHAR2(1) := '-';
   cid           VARCHAR2(1) := '-';
   w_time        VARCHAR2(8);
   w_dat_ech_a   NUMBER;
   w_dat_ech_m   NUMBER;
   w_dat_ech_j   NUMBER;
   w_dat_ori_a   NUMBER;
   w_dat_ori_m   NUMBER;
   w_dat_ori_j   NUMBER;
   w_dat_ori     DATE;
   w_dat_ech     DATE;
   w_mpfr        VARCHAR2(1);
   w_mpjf        VARCHAR2(1);
   w_mpnr        VARCHAR2(2);
   w_ecran       VARCHAR2(15);
   w_mpnj        NUMBER(3,0);
   w_mpje        NUMBER(2,0);
   w_rac_ann     NUMBER(4,0);
   w_calc_me     NUMBER(2,0);
   w_calc_jr     NUMBER(2,0);
   w_calc_ae     NUMBER(2,0);
   w_calc_reste  NUMBER(1,0);
   w_calc_w      NUMBER(3,0);
   w_calc_i      NUMBER(5,0);
   w_dat_form    DATE;
