   w_mm          NUMBER;
   w_mm1         NUMBER;
   w_a2          NUMBER;
   w_a1          NUMBER;
   typ_err       NUMBER;
   w_aa          NUMBER(3,2);
   begin_work    NUMBER;

   TYPE w_tmois_fmois_type IS TABLE OF NUMBER INDEX BY BINARY_INTEGER;
   w_tmois_fmois w_tmois_fmois_type;

   TYPE t_cpt_numcpt_type IS TABLE OF VARCHAR2(8) INDEX BY BINARY_INTEGER;
   TYPE t_cpt_intr_type IS TABLE OF VARCHAR2(15) INDEX BY BINARY_INTEGER;
   t_cpt_numcpt    t_cpt_numcpt_type;
   t_cpt_intr    t_cpt_intr_type;

   -- variables necessaires a l'utilisation de la fct PRECSUIV
   zone_prec     NUMBER;
   zone_suiv     NUMBER;
   ligne_prec    NUMBER;
   ligne_suiv    NUMBER;

   wtmp          cp_edi%ROWTYPE;
   wres          cp_res%ROWTYPE;

   TYPE clcum_c1_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   TYPE clcum_c2_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   TYPE clcum_c3_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   TYPE clcum_c4_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   TYPE clcum_c5_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   TYPE clcum_c6_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   TYPE clcum_c7_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   TYPE clcum_c8_type IS TABLE OF NUMBER(15,3) INDEX BY BINARY_INTEGER;
   clcum_c1      clcum_c1_type;
   clcum_c2      clcum_c2_type;
   clcum_c3      clcum_c3_type;
   clcum_c4      clcum_c4_type;
   clcum_c5      clcum_c5_type;
   clcum_c6      clcum_c6_type;
   clcum_c7      clcum_c7_type;
   clcum_c8      clcum_c8_type;

   TYPE cpt_mjcum_type IS TABLE OF NUMBER INDEX BY BINARY_INTEGER;
   cpt_mjcum     cpt_mjcum_type;

   TYPE w_iden_type IS RECORD
   (    heur     VARCHAR2(8),
        pgm      VARCHAR2(12)
   );
   w_iden        w_iden_type;

   w_l1          CHAR(187);
   w_l2          w_l1%TYPE;
   w_l3          w_l1%TYPE;
   w_l4          w_l1%TYPE;
   w_l5          w_l1%TYPE;
   w_l6          w_l1%TYPE;
   w_l7          w_l1%TYPE;

--lk   arg1          VARCHAR2(1);
   arg1          NUMBER(6);
   arg2          VARCHAR2(187);
   p1            NUMBER;
   p2            NUMBER;
   p3            NUMBER;
   p4            NUMBER;
   wedit         NUMBER;
   w_cum_solde_cr   NUMBER(15,3);
   w_cum_solde_db   NUMBER(15,3);
   w_cum_solde_c2   NUMBER(15,3);
   w_cum_solde_c3   NUMBER(15,3);
   w_cum_solde_c4   NUMBER(15,3);
   w_cum_solde_c5   NUMBER(15,3);
   w_needlg      NUMBER;
   indic         NUMBER;
   indi          NUMBER;
   w_bala        VARCHAR2(3);
   w_ord         VARCHAR2(6);
   char8         VARCHAR2(8);
   w_sens        VARCHAR2(1);

   w_faitout     BOOLEAN;

