-- CONNECT KERNEL
CREATE Function CPT_CHAINE_CRITERE
  ( param1 IN varchar2)
  RETURN  varchar2 IS
--
-- Renvoie une chaîne tout en remplaçant les caractères '*' par des '_'
-- sauf le caractère '*' en fin de chaîne qui sera remplacé par un '%'
-- ajouter un '%' à la fin de la chaîne
--
-- MODIFICATION HISTORY
-- Person      Date     Comments
-- BT          15/04/02 Mise en place du programme

   resultat                 VARCHAR2(10);
BEGIN
    resultat := param1;
    IF substr(resultat,length(param1),1) = '*' THEN
        resultat := REPLACE(SUBSTR(resultat,1,LENGTH(resultat)-1),'*','_')||'%';
    ELSE
        resultat := REPLACE(resultat,'*','_')||'%';
    END IF;
    RETURN (resultat);
EXCEPTION
   WHEN others THEN
       RETURN ('  ');
END;
/
 
CREATE FUNCTION        FN_GET_PARAM(v_appli Varchar2, v_codpar VARCHAR2, v_cle VARCHAR2, v_zone Varchar2) RETURN VARCHAR2 IS
   w_valc			CASPPAR.VALC%TYPE;
BEGIN
   If v_appli like '%ASSIST%' Then
	  SELECT Decode(v_zone,'C',valc,'L',libpar,'N',to_char(valn),'T',to_char(valt)) INTO w_valc FROM CASPPAR
       WHERE codpar=v_codpar and cle=v_cle;
   Elsif v_appli like '%CASANTE%' Then
	  SELECT Decode(v_zone,'C',valc,'L',libpar,'N',to_char(valn),'T',to_char(valt)) INTO w_valc FROM ASPPAR
       WHERE codpar=v_codpar and cle=v_cle;
   Elsif v_appli like '%KERNEL%' Then
	  SELECT Decode(v_zone,'C',valc,'L',libpar,'N',to_char(valn),'T',to_char(valt)) INTO w_valc FROM utppar
       WHERE codpar=v_codpar and cle=v_cle;
   End if;
   RETURN (w_valc);
EXCEPTION
	 WHEN NO_DATA_FOUND THEN
	   RETURN ('XXXX');
END;
/
 
CREATE FUNCTION        FN_LANG_TEXTE(v_code_msg Varchar2, v_code_langue Varchar2) RETURN Varchar2 IS
  v_message			Utmsg.message%Type;
BEGIN
  If v_code_langue is null or v_code_langue = 'FR' Then
  	 Select message Into v_message From Utmsg
  	  Where code_msg = v_code_msg;
  Else
  	 Select message Into v_message From Utmsg_langue
  	  Where code_msg = v_code_msg
  	    And code_langue = v_code_langue;
  End if;

  Return (v_message);
EXCEPTION
	WHEN others THEN
			 Return (null);
END;
/
 
CREATE Function Fn_periode_3car (v_cdos Varchar2, v_periode_in Varchar2) Return Varchar2 Is
  d_datdeb			Date;
  v_periode			Cp_per.periode%TYpe;
Begin
  If length(v_periode_in) < 4 Then
	 v_periode := v_periode_in;
  Else
	 d_datdeb := to_date('20'||v_periode_in||'01','yyyymmdd');

	 Select min(periode) Into v_periode From Cp_per
	  Where cdos=v_cdos and datdeb = d_datdeb;
  End if;
  Return (v_periode);
End;
/
 
CREATE Function        FN_RTAX_TAUX(v_codrtax Varchar2, n_num Number) RETURN NUMBER is
  v_codtax1		Utprtax.codtax1%Type;
  v_codtax2		Utprtax.codtax2%Type;
  v_codtax3		Utprtax.codtax3%Type;
  v_codtax4		Utprtax.codtax4%Type;
  v_exonere		Utprtax.exonere%Type;
  n_taux		Number;
BEGIN
  If v_codrtax is not null Then
	 Select exonere, codtax1, codtax2, codtax3, codtax4 Into v_exonere,v_codtax1, v_codtax2, v_codtax3, v_codtax4 From Utprtax
	  Where codrtax = v_codrtax;
	 If v_exonere = 'O' Then
	    n_taux := 0;
	 Else
		Select sum(valt) Into n_taux From Utppar
		 Where codpar = 'TAXES'
		   And cle in (v_codtax1, v_codtax2, v_codtax3, v_codtax4);
	 End if;
  End if;
  Return (n_taux);
END;
/
 
