-- CONNECT CAISSE
CREATE FUNCTION        FN_PRMP_DB(v_codeta VARCHAR2, v_codart VARCHAR2, d_date DATE) RETURN NUMBER IS
   n_qte			GCSTOCK.qtestock%TYPE;
   n_prmp			GCPRMP.prmp%TYPE;
   n_mont			GCPRMP.montant%TYPE;
   v_pun			Gcppar.valc%Type;
BEGIN
	Select max(valc) Into v_pun From Gcppar
	 Where codpar='PARGEN' and cle='PUN';
	v_pun := Nvl(v_pun,'N');

	 IF d_date >= TRUNC(sysdate,'dd') THEN
		If v_codeta is not null Then
	 	   SELECT sum(prmp) INTO n_prmp FROM GCPRMP
	 	    WHERE codeta = v_codeta
	 	      AND codart = v_codart
	 	      And periode='999912';
		Else
		   Select sum(quantite*prmp), sum(quantite), max(prmp) Into n_mont, n_qte, n_prmp From CAISSE.gcprmp
		    Where codart = v_codart
			  And periode = '999912';
		   If Nvl(n_qte,0) != 0 and Nvl(n_mont,0) != 0 Then
			  n_prmp := n_mont / n_qte;
		   End if;
	  	End if;
	 ELSE
		-- Calculer le stock à la date de relevé
		If v_pun = 'O' or v_codeta is null Then
		   SELECT SUM(decode(t.sens,'E',1,-1)*d.qtebrd*nvl(d.coeff,1)), SUM(decode(t.sens,'E',d.montrevient,-d.montrevient)) INTO n_qte, n_mont
			 FROM GCBRDD d, GCBRDE e, GCPTBRD t
			WHERE d.codart = v_codart
			  AND d.typlig = '0'
			  And e.etat != 'A'
			  AND d.idbrd=e.idbrd
			  AND e.datbrd <= d_date
			  AND e.codtbrd = t.codtbrd
			  AND t.majstock = 'O';
		Else
		   SELECT SUM(decode(t.sens,'E',1,-1)*d.qtebrd*nvl(d.coeff,1)), SUM(decode(t.sens,'E',d.montrevient,-d.montrevient)) INTO n_qte, n_mont
			 FROM GCBRDD d, GCBRDE e, GCPTBRD t
			WHERE d.codart = v_codart
			  AND d.typlig = '0'
			  And e.etat != 'A'
			  AND d.idbrd=e.idbrd
			  AND e.datbrd <= d_date
			  AND e.codeta = v_codeta
			  AND e.codtbrd = t.codtbrd
			  AND t.majstock = 'O';
		End if;
		IF n_qte*n_mont <= 0 THEN
		 -- Lire le PRMP qui est en ligne
		   SELECT max(prmp) INTO n_prmp FROM GCPRMP
			WHERE codeta = Nvl(v_codeta, codeta)
			  AND codart = v_codart
			  And periode='999912';
		ELSE
		 n_prmp := n_mont / n_qte;
		END IF;
	END IF;
	RETURN nvl(n_prmp,0);
END;
/
 
CREATE Function        Fn_qtestock(v_codart Varchar2, v_coddep Varchar2)
Return Number Is
  n_qte			Number;
Begin
  If v_coddep is null Then
     Select sum(qtestock) Into n_qte From Gcstock
      Where codart = v_codart;
  Else
     Select sum(qtestock) Into n_qte From Gcstock
      Where codart = v_codart
	    And coddep = v_coddep;
  End if;

  Return (n_qte);
End;
/
 
CREATE Function        Fn_qte_statut(v_codart Varchar2, v_coddep Varchar2, v_codstat Varchar2)
Return Number Is
  n_qte			Number;
Begin
  If v_coddep is null Then
     Select sum(quantite) Into n_qte From Gcstock_statut
      Where codart = v_codart;
  Else
     Select sum(quantite) Into n_qte From Gcstock_statut
      Where codart = v_codart
	    And coddep = v_coddep
		And codstat = v_codstat;
  End if;

  Return (n_qte);
End;
/
 
-- CONNECT XCPTA
CREATE FUNCTION       F_GEN_NUMPCE_DB(i_cdos    IN CP_ECR.CDOS%TYPE,
                      i_codjou  IN CP_PCE.CODJOU%TYPE,
                      i_periode IN CP_PCE.PERIODE%TYPE,
					  w_coduti IN CP_ECR.CODUTI%TYPE) RETURN NUMBER
IS
   w_numpce	NUMBER(8):= Null;
   w_retour	INTEGER;
   w_vall		COPAR.VALC%TYPE;
BEGIN
   begin
	   select valc into w_vall
	   from copar where codpar = 'PARGEN-'||i_cdos
	   and cle = 'NPA';
   exception
   	 when no_data_found then
   	   w_vall := null;
   end;
   IF nvl(w_vall,'M') = 'O' THEN
      BEGIN
         SELECT NVL(TO_NUMBER(NUMPCE),0) + 1
           INTO w_numpce
           FROM CP_PCE
          WHERE CDOS    = i_cdos
            AND CODJOU  = i_codjou
            AND PERIODE = substr(i_periode,1,1)||'99' FOR UPDATE OF NUMPCE;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN
            BEGIN
               w_numpce := 1;
               INSERT INTO CP_PCE (CDOS,CODJOU,PERIODE,NUMPCE,DATCRE,DATMOD,CODUTI)
                           VALUES (i_cdos, i_codjou, substr(i_periode,1,1)||'99', w_numpce, sysdate,sysdate,Nvl(w_coduti,'XXXX'));
               Return (w_numpce);
            EXCEPTION
               WHEN OTHERS THEN
					raise_application_error(-20502,'Impossible de générer le N° de pièce pour ce journal et cette année');
            END;
      END;

      BEGIN
         UPDATE CP_PCE
            SET NUMPCE  = TO_CHAR(w_numpce)
          WHERE CDOS    = i_cdos
            AND CODJOU  = i_codjou
            AND PERIODE = substr(i_periode,1,1)||'99';
      END;
	 ELSE
      BEGIN
         SELECT NVL(TO_NUMBER(NUMPCE),0) + 1
           INTO w_numpce
           FROM CP_PCE
          WHERE CDOS    = i_cdos
            AND CODJOU  = i_codjou
            AND PERIODE = i_periode FOR UPDATE OF NUMPCE;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN
            BEGIN
               w_numpce := 1;
               INSERT INTO CP_PCE (CDOS,CODJOU,PERIODE,NUMPCE,DATCRE,DATMOD,CODUTI)
                           VALUES (i_cdos, i_codjou, i_periode, w_numpce, sysdate,sysdate,Nvl(w_coduti,'XXXX'));
               Return (w_numpce);
            EXCEPTION
               WHEN OTHERS THEN
					raise_application_error(-20502,'Impossible de générer le N° de pièce pour ce journal et cette période');
            END;

        -- Fin Modif
      END;

      BEGIN
         UPDATE CP_PCE
            SET NUMPCE  = TO_CHAR(w_numpce)
          WHERE CDOS    = i_cdos
            AND CODJOU  = i_codjou
            AND PERIODE = i_periode;
      END;
   END IF;

   RETURN (w_numpce);

RETURN NULL; EXCEPTION
  WHEN OTHERS THEN
       RAISE;
END;
/
 
