CREATE FUNCTION         fn_article_datderach(v_codeta VARCHAR2, v_codart VARCHAR2, d_datarr Varchar2, v_list_brd VARCHAR2) RETURN DATE is
  d_date	DATE;
BEGIN
  SELECT max(e.datbrd) INTO d_date FROM CAISSE.Gcbrdd d, CAISSE.Gcbrde e
   WHERE d.idbrd = e.idbrd
	 AND d.typlig='0'
     --AND (v_codeta is null or (v_codeta is not null and d.coddep in (select coddep from CAISSE.gcpdep where codeta=v_codeta)))
     AND codart = v_codart
     AND e.datbrd <= SYSDATE --d_datarr
	 AND d.codtbrd in ('RCL','RCI','AL');
     --AND INSTR(v_list_brd,d.codtbrd) != 0;

  RETURN (d_date);
END;
/
 
CREATE FUNCTION         fn_article_datderachat(v_codeta VARCHAR2, v_codart VARCHAR2, d_datarr Date) RETURN DATE is
  d_date	DATE;
BEGIN
  SELECT max(e.datbrd) INTO d_date FROM CAISSE.Gcbrdd d, CAISSE.Gcbrde e
   WHERE d.idbrd = e.idbrd
	 AND d.typlig='0'
     AND (v_codeta is null or (v_codeta is not null and d.coddep in (select coddep from CAISSE.gcpdep where codeta=v_codeta)))
     AND codart = v_codart
     AND e.datbrd <= d_datarr
     --AND INSTR(v_list_brd,d.codtbrd) != 0;
	 AND d.codtbrd in ('RCL','RCI','AL');

  RETURN (d_date);
END;
/
 
