CREATE FUNCTION         fn_article_datdervte(v_codeta VARCHAR2, v_codart VARCHAR2, d_datarr Varchar2) RETURN DATE is
  d_date	DATE;
BEGIN
  SELECT max(e.datbrd) INTO d_date FROM CAISSE.Gcbrdd d, CAISSE.Gcbrde e
   WHERE d.idbrd = e.idbrd
