CREATE FUNCTION         fn_article_qteachat(v_codeta VARCHAR2, v_codart VARCHAR2, d_datdeb Date, d_datfin Date) RETURN NUMBER is
  n_qte		Number;
BEGIN
  SELECT sum(d.qtebrd*nvl(d.coeff,1)) INTO n_qte FROM CAISSE.Gcbrdd d, CAISSE.Gcbrde e
   WHERE d.idbrd = e.idbrd
	 AND d.typlig='0'
     AND (v_codeta is null or (v_codeta is not null and d.coddep in (select coddep from CAISSE.gcpdep where codeta=v_codeta)))
     AND codart = v_codart
     AND e.datbrd between d_datdeb and d_datfin
	 And d.codtbrd in ('RCI','RCL','AL');
     --AND INSTR(v_list_brd,d.codtbrd) != 0;

  RETURN (n_qte);
END;
/
 
CREATE FUNCTION         fn_article_qtes_vte(v_codart varchar2, datedebut date, datefin date, magasin varchar2) RETURN NUMBER IS
  n_qte		number;
  n_nbre	number;
begin
  SELECT sum(d.qtebrd), count(*) INTO n_qte, n_nbre
    FROM CAISSE.gcbrdd d, CAISSE.gcbrde e, CAISSE.gcptbrd t
   Where d.codart=v_codart
	  And d.idbrd = e.idbrd
	  And e.datbrd between datedebut and datefin
	  And d.coddep like magasin||'%'
	  And d.codtbrd = t.codtbrd
	  And t.type='VEN';

  RETURN n_qte;
end;
/
 
CREATE FUNCTION         fn_article_qte_derachat (v_codart VARCHAR2) return NUMBER is
  n_qte	Number;
  v_res	Varchar2(100);
BEGIN
  SELECT max(to_char(e.datbrd,'yyyymmdd')||to_char(d.qtebrd*nvl(d.coeff,1))) INTO v_res
    FROM CAISSE.gcbrdd d, CAISSE.gcbrde e--, CAISSE.gcptbrd tb
   WHERE d.typlig='0'
     AND d.codart = v_codart
     AND d.idbrd=e.idbrd
	 --And d.codtbrd = tb.codtbrd
	 And d.codtbrd in ('RCL','RCI','AL');

  If v_res is not null Then
     n_qte := Substr(v_res,9);
  End if;
  RETURN (n_qte);
END;
/
 
CREATE FUNCTION         fn_der_puachv (v_codart VARCHAR2, v_codtie Varchar2) return VARCHAR2 is
  v_res		Varchar2(100);
  w_coddev	Varchar2(3);
  w_pubrd	Number;
BEGIN
  SELECT max(to_char(e.datbrd,'yyyymmdd')||e.coddev||to_char(d.pubrd)) INTO v_res
	FROM CAISSE.gcbrdd d, CAISSE.gcbrde e--, CAISSE.gcptbrd tb
   WHERE d.typlig='0'
	 AND d.codart = v_codart
	 AND d.idbrd=e.idbrd
	 ANd e.codtie = v_codtie
	 --And d.codtbrd = tb.codtbrd
	 And d.codtbrd in ('RCL','RCI','AL');
  w_coddev 	:= Substr(v_res,9,3);
  w_pubrd	:= Substr(v_res,12);

  RETURN (rpad(w_coddev,3,' ') || to_char(w_pubrd));
END;
/
 
CREATE FUNCTION         fn_prmp(w_codart varchar2, w_codeta varchar2 default null)
return number
is
  w_montant	Number;
  w_qte		Number;
  w_prmp	number;
begin
  If w_codeta is null Then
	 Select sum(quantite*prmp), sum(quantite), max(prmp) Into w_montant, w_qte, w_prmp From CAISSE.gcprmp
      Where codart = w_codart
		And periode = '999912';
	 If Nvl(w_qte,0) != 0 and Nvl(w_montant,0) != 0 Then
	    w_prmp := w_montant / w_qte;
	 End if;
  Else
     SELECT sum(prmp) INTO w_prmp FROM CAISSE.gcprmp p
      WHERE p.codart = w_codart
        And p.periode = '999912'
        AND p.codeta = W_codeta;
  End if;
  RETURN (w_prmp);
end;
/
 
CREATE FUNCTION         fn_prmp_global(w_codart varchar2)
return number
is
  w_prmp	number;
begin
  SELECT sum(prmp*quantite), sum INTO w_prmp FROM CAISSE.gcprmp p
   WHERE p.codart = w_codart
     And
     And p.periode = '999912';
  RETURN (w_prmp);
end;
/
 
CREATE FUNCTION         fn_qteencde(w_codart varchar2, w_coddep Varchar2 default null, w_codeta Varchar2 default null)
return number
is
  w_qte	number;
begin
  SELECT sum(qtecde) sum INTO w_qte FROM CAISSE.gcstock
   WHERE codart = w_codart
     And (w_coddep is null or (w_coddep is not null and coddep = w_coddep))
	 And (w_codeta is null or (w_codeta is not null and coddep in (Select coddep From CAISSE.Gcpdep Where codeta = w_codeta)));

  RETURN (w_qte);
end;
/
 
CREATE FUNCTION         fn_qtestock(w_codart varchar2, w_coddep Varchar2 default null, w_codeta Varchar2 default null)
return number
is
  w_qte	number;
begin
  SELECT sum(qtestock) sum INTO w_qte FROM CAISSE.gcstock
   WHERE codart = w_codart
     And (w_coddep is null or (w_coddep is not null and coddep = w_coddep))
	 And (w_codeta is null or (w_codeta is not null and coddep in (Select coddep From CAISSE.Gcpdep Where codeta = w_codeta)));

  RETURN (w_qte);
end;
/
 
CREATE FUNCTION         fn_tarif(w_codart varchar2, w_codtarif varchar2)
return number
is
  w_tarif	number;
begin
  If w_codtarif = '0' Then
	 Select tarifstd into w_tarif From CAISSE.gcpart
	  Where codart = w_codart;
  Else
	 Select sum(tarif) INTO w_tarif From CAISSE.gcptarif_art t
	  Where t.codart = w_codart
		And t.codtarif = W_codtarif;
  End if;
  RETURN (w_tarif);
end;
/
 
CREATE FUNCTION         NZ (n_num Number) return NUMBER is
  v_res		Number;
BEGIN
  If n_num = 0 Then
	 v_res := null;
  Else
	 v_res := n_num;
  End if;

  RETURN (v_res);
END;
/
 
