CREATE PROCEDURE load_file_to_table (p_file_id IN UT_STORE_FILES.FILE_ID%TYPE, p_file_name IN Varchar2, p_file_resume IN Varchar2, v_user IN Varchar2) AS
v_bfile BFILE;
v_blob BLOB;
BEGIN
-- insert file id and file name in the table.

-- Note the use of empty_blob(). This initializes the blob object first.

-- Why: You need to initialize a blob object before you access or populate it.

INSERT INTO UT_STORE_FILES (file_id, file_name, file_copy, file_resume, user_creat, date_creat)
					VALUES (p_file_id, p_file_name, empty_blob(), p_file_resume, v_user, sysdate) RETURN file_copy INTO v_blob;

-- v_blob contains the initialized blob object

-- Get a BFILE locator that is associated with the physical file on the DIRECTORY

v_bfile := BFILENAME('SRC_FILES', p_file_name);

-- Open the file using DBMS_LOB

DBMS_LOB.FILEOPEN(v_bfile, Dbms_Lob.File_Readonly);

-- Load the file into the BLOB pointer

DBMS_LOB.LOADFROMFILE(v_blob, v_bfile, Dbms_Lob.Getlength(v_bfile));

-- Close the file

DBMS_LOB.FILECLOSE(v_bfile);
COMMIT;
END;

create or replace
PROCEDURE load_file_to_target (p_file_id IN Number, p_file_name IN Varchar2) AS
v_blob BLOB;
v_start NUMBER := 1;
v_bytelen NUMBER := 32000;
v_len NUMBER ;
v_len_copy NUMBER;

v_raw_var RAW(32000);
v_output utl_file.file_type;
BEGIN
-- define output directory and open the file in write byte mode
v_output := utl_file.fopen('TGT_FILES', p_file_name,'wb', 32760);

v_start := 1;
v_bytelen := 32000;

-- get length of blob
SELECT DBMS_LOB.GETLENGTH(file_copy)
INTO v_len
FROM UT_STORE_FILES
where file_id = p_file_id  ;

-- save blob length
v_len_copy := v_len;
-- Get the blob
select file_copy
into v_blob
FROM UT_STORE_FILES
where file_id = p_file_id  ;
-- Maximum size of buffer parameter is 32767 before which you have to flush your buffer
IF v_len < 32760 THEN
utl_file.put_raw(v_output,v_blob);
utl_file.fflush(v_output);
ELSE -- write in separate buffers
v_start := 1;
WHILE v_start < v_len and v_bytelen > 0
LOOP
DBMS_LOB.READ(v_blob,v_bytelen,v_start,v_raw_var);
utl_file.put_raw(v_output,v_raw_var);
utl_file.fflush(v_output);

-- set the start position for next flush
v_start := v_start + v_bytelen;

-- set the end position if less than 32000 bytes
v_len_copy := v_len_copy - v_bytelen;
IF v_len_copy < 32000 THEN
v_bytelen := v_len_copy;
END IF;

end loop;
utl_file.fclose(v_output);
END IF;

END;
/
 
CREATE PROCEDURE load_file_to_target (p_file_id IN Number, p_file_name IN Varchar2) AS
v_blob BLOB;
v_start NUMBER := 1;
v_bytelen NUMBER := 32000;
v_len NUMBER ;
v_len_copy NUMBER;

v_raw_var RAW(32000);
v_output utl_file.file_type;
BEGIN
-- define output directory and open the file in write byte mode
v_output := utl_file.fopen('TGT_FILES', p_file_name,'wb', 32760);

v_start := 1;
v_bytelen := 32000;

-- get length of blob
SELECT DBMS_LOB.GETLENGTH(file_copy)
INTO v_len
FROM UT_STORE_FILES
where file_id = p_file_id  ;

-- save blob length
v_len_copy := v_len;
-- Get the blob
select file_copy
into v_blob
FROM UT_STORE_FILES
where file_id = p_file_id  ;
-- Maximum size of buffer parameter is 32767 before which you have to flush your buffer
IF v_len < 32760 THEN
utl_file.put_raw(v_output,v_blob);
utl_file.fflush(v_output);
ELSE -- write in separate buffers
v_start := 1;
WHILE v_start < v_len and v_bytelen > 0
LOOP
DBMS_LOB.READ(v_blob,v_bytelen,v_start,v_raw_var);
utl_file.put_raw(v_output,v_raw_var);
utl_file.fflush(v_output);

-- set the start position for next flush
v_start := v_start + v_bytelen;

-- set the end position if less than 32000 bytes
v_len_copy := v_len_copy - v_bytelen;
IF v_len_copy < 32000 THEN
v_bytelen := v_len_copy;
END IF;

end loop;
utl_file.fclose(v_output);
END IF;

END;
/
 
CREATE procedure mycopy( src varchar2, src_name varchar2, dest varchar2 ,dest_name varchar2 ) IS
   fs UTL_FILE.FILE_TYPE ;
   fd UTL_FILE.FILE_TYPE ;
   tmp RAW(32000) ;
begin
   fs := UTL_FILE.FOPEN(src, src_name , 'rb', 32000 ) ;
   fd := UTL_FILE.FOPEN(dest, dest_name , 'wb', 32000 ) ;
begin
   loop
      utl_file.get_raw( fs, tmp, 32000 );
      utl_file.put_raw(fd, tmp, TRUE );
   end loop ;
EXCEPTION
   when others then
      utl_file.fclose(fs);
      utl_file.fclose(fd);
   end;
end;
/
 
CREATE PROCEDURE        PR_COMPTABILISER_ACHAT_LOCAL(n_idbrd Number, b_ma Boolean) IS
  Cursor cf is Select e.codtbrd, e.numbrd, e.datbrd, e.numdoc, e.datdoc, t.divers tie_divers
					,e.datech, e.codtie, e.nomtie, t.numcpt, e.cuti, e.datcre, e.codrtax
					,e.mht, e.mtax1, e.mtax2, e.mtax3, e.mtax4, e.marrondi, e.mttc
				  from gcbrde e, gcptie t, gcptbrd tb
				 where e.idbrd = n_idbrd
				   And e.codtie = t.codtie
				   And e.codtbrd = tb.codtbrd
				   And e.etat != 'C';

  cf_row		cf%rowtype;
  v_cdos		Gcppar.valc%Type;
  v_codeta		Cp_int.codets%Type;
  v_codjou		Gcppar.valc%type;
  v_codabr		Gcppar.valc%type;
  v_devsise		Cp_dos.ddev%type := 'CFA';
  v_libecr		Varchar2(30);
  v_numpce		Cp_int.numpce%Type;
  v_reflet		Varchar2(8);
  v_codtax		Utprtax.codtax1%Type;

  v_numtie		Cp_int.numtie%TYPE;
  v_numcpt		Cp_int.numcpt%TYPE;
  v_coddes1		Varchar2(8);
  v_cptachat	Cp_int.numcpt%TYPE;

  n_numbrd_sce	Gcbrde.numbrd%Type;
  n_numfac_sce	Gcbrde.numfac%Type;

  w_message		Varchar2(500);

  n_numsai_out	Number;

  n_mht			Number;
  n_mtax1		Number;
  n_mtax2		Number;
  n_mtax3		Number;
  n_mtax4		Number;
  v_codrtax		Utprtax.codrtax%Type;

  n_net			Number;
  n_total_ma	Number;
  n_arrondi		Number;
  n_arrondi_ma	Number;
BEGIN
  Select max(valc) Into v_cdos From Gcppar
   Where codpar = 'XCPTA' and cle='DOS';
  If v_cdos is null Then
     Return;
  End if;

  Select max(valc) Into v_codjou From Gcppar
   Where codpar = 'XCPTA' and cle='ALJ';

  Select max(valc) Into v_coddes1 From Gcppar
   Where codpar = 'XCPTA' and cle='ALS';

  -- Compte d'achat par défaut
  Select max(valc) Into v_cptachat From Gcppar
   Where codpar = 'XCPTA' and cle='ALC';

  -- Compte de libellé abrégé
  Select max(valc) Into v_codabr From Gcppar
   Where codpar = 'XCPTA' and cle='ALA';

  If v_cptachat is null Then
	 raise_application_error(-20052,'Compte d''achat par défaut non paramétré');
  Elsif v_codjou is null Then
	 raise_application_error(-20052,'Code journal d''achat local non paramétré');
  End if;

  v_devsise := 'CFA';
  v_codabr	:= null;
  v_codeta	:= '01';

  FOR cf_row IN cf LOOP
    If cf_row.mttc <= 0 Then
       v_libecr := Substr('LP '||to_char(cf_row.numbrd)||' - No '||cf_row.numdoc,1,30);
    Else
       v_libecr := Substr('LP '||to_char(cf_row.numbrd)||' - No '||cf_row.numdoc,1,30);
    End if;

    v_numpce := to_char(cf_row.numbrd);
    v_reflet := substr(cf_row.numdoc, 1, 8);

	v_codrtax := cf_row.codrtax;
	n_mht  := cf_row.mht;
	n_mtax1 := cf_row.mtax1;
	n_mtax2 := cf_row.mtax2;
	n_mtax3 := cf_row.mtax3;
	n_mtax4 := cf_row.mtax4;

	-- Calcul du MA
	Select sum(qtebrd * zlibre_m1) Into n_total_ma From Gcbrdd
	 Where idbrd = n_idbrd;
	n_total_ma := Nvl(n_total_ma,0);

	-- 1ère écriture au débit du compte d'achat
	Begin
		INSERT INTO cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
                          devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti, coddes1)
                   Values(v_cdos, v_codeta, v_codjou, v_cptachat, v_numpce, cf_row.datbrd, cf_row.datbrd, cf_row.datbrd,
                          v_devsise, 1, 'D', n_mht, null,v_libecr, v_codabr, sysdate, sysdate, cf_row.cuti, v_coddes1);
 	End;

    -- Ecritures taxes
	If n_mtax1 != 0 Then
	   Select codtax1 Into v_codtax From Utprtax
		Where codrtax = v_codrtax;
	   Select max(numcpt_ach) Into v_numcpt From Utptaxe
		Where codtaxe = v_codtax;

	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datbrd, cf_row.datbrd, cf_row.datbrd,
						   v_devsise, 1, 'D', n_mtax1, v_reflet, v_libecr, v_codabr, sysdate, sysdate, cf_row.cuti);
	End if;

	If n_mtax2 != 0 Then
	   Select codtax2 Into v_codtax From Utprtax
		Where codrtax = v_codrtax;
	   Select max(numcpt_ach) Into v_numcpt From Utptaxe
		Where codtaxe = v_codtax;
	   /*Select max(valc) Into v_numcpt From Utppar
		Where codpar='TAXES' and cle = v_codtax;*/

	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datbrd, cf_row.datbrd, cf_row.datbrd,
						   v_devsise, 1, 'D', n_mtax2, v_reflet, v_libecr, v_codabr, sysdate, sysdate, cf_row.cuti);
	End if;

	-- Ecritures Arrondi, l'arrondi doit être retiré du total MA
	If Nvl(cf_row.marrondi,0) != 0 and Nvl(cf_row.marrondi,0) <= n_total_ma Then
	   n_arrondi := 0;
	   n_arrondi_ma := Nvl(cf_row.marrondi,0);
	Else
	   n_arrondi := Nvl(cf_row.marrondi,0);
	   n_arrondi_ma := 0;
	End if;

	If n_arrondi != 0 Then
	   Select max(valc) Into v_numcpt From Gcppar
		Where codpar = 'XCPTA' and cle='ADR';
	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech, coddes1,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datbrd, cf_row.datbrd, cf_row.datbrd, v_coddes1,
						   v_devsise, 1, 'C', n_arrondi, v_reflet, v_libecr, v_codabr, sysdate, sysdate, cf_row.cuti);
	End if;

    -- Ecriture FACTURE TTC DU FOURNISSEUR
    n_net := cf_row.mttc - nvl(n_arrondi,0);
    if Nvl(n_net,0)  != 0 then
       -- Si vente au comptant pour un client à terme.
	   v_numtie := cf_row.codtie;
	   v_numcpt := cf_row.numcpt;

	   -- Ecriture de contrepartie dans le compte du fournisseur.
	   insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
				   values (v_cdos, v_codeta, v_codjou, v_numcpt, v_numtie, v_numpce, cf_row.datbrd, cf_row.datbrd, cf_row.datech,
						   v_devsise, 1, 'C', n_net, v_reflet, v_libecr, v_codabr, sysdate, sysdate, cf_row.cuti);
    end if;

	Pr_interfacer_piece(v_cdos, v_codjou, v_numpce, cf_row.datbrd, n_numsai_out);

	If n_numsai_out is null Then
	   raise_application_error(-20503,'erreur lors de l''interface de la pièce');
	Else
	   Update gcbrde set etat = 'C', numsai=n_numsai_out
	    Where idbrd = n_idbrd;
	End if;

	-- l'arrondi est retiré du total MA
    n_total_ma := n_total_ma - n_arrondi_ma;
	If nvl(n_total_ma,0) != 0 and b_ma Then
	   If cf_row.mttc <= 0 Then
		  v_libecr := Substr('MA/LP '||to_char(cf_row.numbrd)||' - No '||cf_row.numdoc,1,30);
	   Else
		  v_libecr := Substr('MA/LP '||to_char(cf_row.numbrd)||' - No '||cf_row.numdoc,1,30);
	   End if;


	   Select max(valc) Into v_numcpt From Gcppar
		Where codpar = 'XCPTA' and cle='ALM';
	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech, coddes1,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datbrd, cf_row.datbrd, cf_row.datbrd, v_coddes1,
						   v_devsise, 1, 'D', n_total_ma, v_reflet, v_libecr, v_codabr, sysdate, sysdate, cf_row.cuti);

	   v_numtie := cf_row.codtie;
	   v_numcpt := cf_row.numcpt;

	   -- Ecriture de contrepartie dans le compte du fournisseur.
	   insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
				   values (v_cdos, v_codeta, v_codjou, v_numcpt, v_numtie, v_numpce, cf_row.datbrd, cf_row.datbrd, cf_row.datech,
						   v_devsise, 1, 'C', n_total_ma, v_reflet, v_libecr, v_codabr, sysdate, sysdate, cf_row.cuti);
	   Pr_interfacer_piece(v_cdos, v_codjou, v_numpce, cf_row.datbrd, n_numsai_out);
	End if;
  END LOOP;
/*
EXCEPTION
  when OTHERS then
	  Insert into gcbrde_log (idbrd, datop, coduti, libop) values (n_idbrd, sysdate, 'DBCF', substr(v_libecr||','||w_message,1,200));

      Update gcbrde set etat = 'O'
	   Where idbrd = n_idbrd;

	  Delete cp_int
	   Where cdos = v_cdos
	     And codjou = v_codjou
	     And datcpt = cf_row.datbrd
	     And numpce = v_numpce;
	  Raise;		*/
END;
/
 
CREATE PROCEDURE        PR_COMPTABILISER_FACTURE(n_idbrd Number) IS
  Cursor cf is Select e.codeta, e.codtbrd, e.numfac, e.num_ptvte, e.idbrd_sce, e.datfac, t.sscls_vte, t.divers tie_divers, tb.ven_comptant
					,e.datech, e.codtie, e.nomtie, t.numcpt, e.cuti, e.datcre, e.codrtax, e.codmrgl, e.coddev, e.comm
					,e.mht, e.mtax1, e.mtax2, e.mtax3, e.mtax4, e.mtax_art, e.mtax_unite, e.marrondi, e.mt_acompte, e.mttc
				  from gcbrde e, gcptie t, gcptbrd tb
				 where e.idbrd = n_idbrd
				   And e.codtie = t.codtie
				   And e.codtbrd = tb.codtbrd
				   And e.mttc != 0
				   And e.etat != 'C';

  cf_row		cf%rowtype;
  v_cdos		Gcppar.valc%Type;
  v_codeta		Cp_int.codets%Type;
  v_codjou		Gcppar.valc%type;
  v_codabrv		Gcppar.valc%type;
  v_devise		Cp_dos.ddev%type := 'CFA';
  v_libecr		Cp_int.libecr%Type;
  v_libecr2		Cp_int.libecr%Type;
  v_numpce		Cp_int.numpce%Type;
  v_reflet		Cp_int.reflet%Type;
  v_exo			Varchar2(1);
  v_codtax		Utprtax.codtax1%Type;
  v_typcpt		Cp_cpt.typcpt%Type;

  v_numtie		Cp_int.numtie%TYPE;
  v_numcpt		Cp_int.numcpt%TYPE;
  v_coddes1		Cp_int.coddes1%Type;
  c_int			CP_INT%ROWTYPE;
  v_cptvente	Cp_int.numcpt%TYPE;
  v_cptvenexo	Cp_int.numcpt%TYPE;
  v_cptavce		Cp_int.numcpt%TYPE;
  v_codcai		Gcpptvte.codcai%Type;

  n_numbrd_sce	Gcbrde.numbrd%Type;
  n_numfac_sce	Gcbrde.numfac%Type;

  w_message		Varchar2(500);

  v_numfac_sce	Number;
  v_ctpjou		Cp_jou.ctpjou%Type;
  v_ctpjou_tie	Cp_jou.ctpjou_tie%Type;

  n_numjou		Caijournal.numjou%Type;
  n_numbon		Caimvt.numbon%Type;
  n_idbon		Caimvt.idbon%Type;
  v_codmvt		Gcppar.valc%Type;
  n_numsai		Number(8);
  n_numsai_out	Number(8);

  n_mht_i		Number(16,4);
  n_mht			Number(16,4);
  n_mtax1		Number(16,4);
  n_mtax2		Number(16,4);
  n_mtax3		Number(16,4);
  n_mtax4		Number(16,4);
  n_mtax_u		Number(16,4);
  n_solde		Number(16,4);
  v_codrtax		Utprtax.codrtax%Type;
  v_tieavce		Gcpptvte.numtie_cpt_avce%Type;
  v_cpteffet	Gcppar.valc%Type;
  v_cptesp		Gcppar.valc%Type;
  v_cpttax_u	Gcppar.valc%Type;
  v_typrgl		Utpmrgl.typrgl%Type;

  n_numlet		Cp_aux.numlet%Type;
  n_count		Number;

  n_total_db	Number;
  n_total_cr	Number;

  d_datdem		Date;
  v_libfmt_gac	Gcppar.valc%Type;
  v_devref		Gcppar.valc%Type;
  v_ref			Varchar2(30);
  v_libmrgl		Varchar2(10);
  v_regal		Varchar2(1);
  v_valc		Gcppar.valc%Type;
BEGIN
  Select max(valc) Into v_cdos From Gcppar
   Where codpar = 'XCPTA' and cle='DOS';
  If v_cdos is null Then
	 Return;
  End if;


  -- Tester l'Ã©quilibre de la piÃ¨ce
  Begin
	Select numsai Into n_numsai From Gcbrde_vte
	 Where idbrd = n_idbrd;

	Select num_ptvte||'/'||to_char(numfac) Into v_ref From Gcbrde
 	 Where idbrd = n_idbrd;

	If n_numsai is not null Then
	   Select count(*) Into n_count From Cp_ecr Where cdos=v_cdos and numsai=n_numsai;
	   If n_count > 0 Then
		  raise_application_error(-20052,'Facture '||v_ref||', erreur doublon dÃ©tectÃ©.');
	   End if;
	End if;
  Exception
	When no_data_found Then
		 raise_application_error(-20052,'Facture '||v_ref||', no record found in GCBRDE_VTE.');
  End;
  n_numsai := null;


  Select max(valc) Into v_codjou From Gcppar
   Where codpar = 'XCPTA' and cle='VTJ';

  Select max(valc) Into c_int.coddes1 From Gcppar
   Where codpar = 'XCPTA' and cle='VTS';

  -- Compte de ventes par dÃ©faut
  Select max(valc) Into v_cptvente From Gcppar
   Where codpar = 'XCPTA' and cle='VTC';

  -- Compte de ventes par dÃ©faut
  Select max(valc) Into v_cptvenexo From Gcppar
   Where codpar = 'XCPTA' and cle='VTD';

  -- Compte des avance
  Select max(valc) Into v_cptavce From Gcppar
   Where codpar = 'BORDVTES' and cle='NCA';

  -- Compte des effets
  Select max(valc) Into v_cpteffet From Gcppar
   Where codpar = 'XCPTA-VTE' and cle='EFC';

  -- Compte des espÃ¨ces encaissÃ©s
  Select max(valc) Into v_cptesp From Gcppar
   Where codpar = 'XCPTA-VTE' and cle='ESP';

  -- Compte des espÃ¨ces encaissÃ©s
  Select max(valc) Into v_cpttax_u From Gcppar
   Where codpar = 'XCPTA-VTE' and cle='CTU';

  Select max(valc) Into v_codeta From Gcppar
   Where codpar = 'XCPTA-VTE' and cle='ETS';

  -- Devise par dÃ©faut
  Select max(valc) Into v_devref From Utppar
   Where codpar='PARGEN' and cle = 'DEV';

  Select max(valc) Into v_libfmt_gac From Gcppar
   Where codpar = 'XCPTA-VTE' and cle='LFG';

   v_codabrv	:= null;

  n_total_db	:= 0;
  n_total_cr	:= 0;

  FOR cf_row IN cf LOOP
	v_codeta := Nvl(v_codeta, cf_row.codeta);

	If cf_row.coddev is null Then
	   v_devise := v_devref;
	Elsif cf_row.coddev = v_devref Then
	   v_devise := v_devref;
	Else
	   v_devise := cf_row.coddev;
	End if;


	If cf_row.ven_comptant = 'O' and cf_row.codmrgl is not null Then
	   Select max(valc) Into v_valc From Gcppar
	    Where codpar = 'REGAL' and cle='SSP';
	   If v_valc is not null Then
		  v_libmrgl := '-'||cf_row.codmrgl;
	   End if;
	End if;


    If cf_row.mttc <= 0 Then
	   If v_libfmt_gac = 'O' Then
		  v_libecr := 'F/'||to_char(cf_row.numfac)||' '||cf_row.comm;
	   Else
		   v_libecr := 'Avoir No '||cf_row.num_ptvte||'/'||to_char(cf_row.numfac)||v_libmrgl;
		   Begin
			 Select numbrd, numfac Into n_numbrd_sce, n_numfac_sce From Gcbrde
			  Where idbrd = cf_row.idbrd_sce;
		   Exception
			  when NO_DATA_FOUND then
				   n_numfac_sce := null;
				   n_numbrd_sce := null;
		   End;
		   If n_numfac_sce is not null Then
			  v_libecr := v_libecr || '/Fact. No '||to_char(n_numfac_sce);
		   End if;
	   End if;
    Else
       If v_libfmt_gac = 'O' Then
		  v_libecr := 'F/'||to_char(cf_row.numfac)||' '||cf_row.comm;
	   Else
		  v_libecr := 'Facture NÂ° '||cf_row.num_ptvte||'/'||to_char(cf_row.numfac)||v_libmrgl;
	   End if;
    End if;

	If cf_row.tie_divers = 'O' and cf_row.ven_comptant = 'N' Then
	   v_libecr := Substr(v_libecr||' -'||cf_row.nomtie,1,50);
	End if;

	If length (cf_row.num_ptvte||to_char(cf_row.numfac)) > 8 Then
	    v_numpce := cf_row.num_ptvte||Substr(to_char(cf_row.numfac),8-length (cf_row.num_ptvte||to_char(cf_row.numfac)));
	Else
	    v_numpce := cf_row.num_ptvte||to_char(cf_row.numfac);
	End if;
    v_reflet := Substr(cf_row.num_ptvte||to_char(cf_row.numfac),1,15);
	If cf_row.mttc = cf_row.mht Then
	   v_exo := 'O';
	   v_codrtax := null;
	   n_mht  := cf_row.mht;
	   n_mtax_u:= Nvl(cf_row.mtax_unite,0);
	   n_mtax1 := 0;
	   n_mtax2 := 0;
	   n_mtax3 := 0;
	   n_mtax4 := 0;
	Else
	   v_exo := 'N';
	   v_codrtax := cf_row.codrtax;
	   n_mht  := cf_row.mht;
	   n_mtax_u:= Nvl(cf_row.mtax_unite,0);
	   n_mtax1 := Nvl(cf_row.mtax1,0) + Nvl(cf_row.mtax_art,0);
	   n_mtax2 := cf_row.mtax2;
	   n_mtax3 := cf_row.mtax3;
	   n_mtax4 := cf_row.mtax4;
	End if;

	-- Est ce qu'il s'agit d'un bordereau HT
	Select count(*) Into n_count From Gcppar
	 Where codpar = 'BORDVTES'
	   And cle = 'BHT'
	   And Instr(valc, cf_row.codtbrd) != 0;
	n_count := Nvl(n_count,0);

	-- Code caisse et section anaytique des ventes par point de vente
	Select coddes1_vte, Decode(n_count,0,codcai, codcai_ht), numtie_cpt_avce Into v_coddes1, v_codcai, v_tieavce From Gcpptvte
	 Where num_ptvte = cf_row.num_ptvte;

    -- DÃ©termination du journal de ventes s'il s'agit d'une vente au comptant.
    If cf_row.ven_comptant = 'O'  and v_codcai is not null then
	   -- Journal de caisse associÃ© au point de vente
	   Select codjou, datdem Into v_codjou, d_datdem From Caicaisse
		Where codcai = v_codcai;
	   -- On ne passe pas de mouvement dans la caisse si la date est antÃ©rieure Ã  la date de dÃ©marrage
	   If cf_row.datfac <= d_datdem Then
		  v_codcai := null;
	   End if;
	   Select ctpjou, ctpjou_tie Into v_ctpjou, v_ctpjou_tie From Cp_jou
	    Where cdos = v_cdos and codjou = v_codjou;
    End if;

	-- 1Ã¨re Ã©criture dans le compte de vente
	Begin
		-- D'abord en fonction des comptes par famille
		n_mht_i := 0;
		For c_row In (Select Decode(v_exo,'O',numcpt_exo,numcpt_tax) numcpt, sum(d.montht) montht From Gcbrdd d, Gcpart a, Gcpcptvte c
					   Where d.idbrd = n_idbrd
						 And d.codart = a.codart
						 And a.codfam = c.codfam and a.codsfam=c.codsfam
						 And c.sscls = cf_row.sscls_vte
					   Group by Decode(v_exo,'O',numcpt_exo,numcpt_tax))
		Loop
			If c_row.numcpt is not null Then
				INSERT INTO cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
								  devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti, coddes1)
						   Values(v_cdos, v_codeta, v_codjou, c_row.numcpt, v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datfac,
								  v_devise, 1, 'C', c_row.montht, null,v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti, v_coddes1);
				n_mht_i := n_mht_i + Nvl(c_row.montht,0);
			End if;
		End Loop;

		-- Et ensuite par compte de vente par point de vente
		If n_mht_i != n_mht Then
		   INSERT INTO cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
							   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti, coddes1)
						Values(v_cdos, v_codeta, v_codjou, DECODE(v_exo, 'O', v_cptvenexo,v_cptvente), v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datfac,
							   v_devise, 1, 'C', n_mht - n_mht_i, null,v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti, v_coddes1);
		End if;

		n_total_cr := n_total_cr + n_mht;
 	End;

    -- Ecritures taxes
	If n_mtax1 != 0 Then
	   Select codtax1 Into v_codtax From Utprtax
		Where codrtax = v_codrtax;
	   Select max(numcpt_vte) Into v_numcpt From Utptaxe
		Where codtaxe = v_codtax;

	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datfac,
						   v_devise, 1, 'C', n_mtax1, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
	   n_total_cr := n_total_cr + n_mtax1;
	End if;

	If n_mtax2 != 0 Then
	   Select codtax2 Into v_codtax From Utprtax
		Where codrtax = v_codrtax;
	   Select max(numcpt_vte) Into v_numcpt From Utptaxe
		Where codtaxe = v_codtax;
	   /*Select max(valc) Into v_numcpt From Utppar
		Where codpar='TAXES' and cle = v_codtax;*/

	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datfac,
						   v_devise, 1, 'C', n_mtax2, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
	   n_total_cr := n_total_cr + n_mtax2;
	End if;

	-- Taxe Ã  l'unitÃ©
	If n_mtax_u != 0 Then
	   v_numcpt := v_cpttax_u;
	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datfac,
						   v_devise, 1, 'C', n_mtax_u, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
	   n_total_cr := n_total_cr + n_mtax_u;
	End if;

	-- Ecritures Arrondi.
	If cf_row.marrondi != 0 Then
	   Select max(valc) Into v_numcpt From Gcppar
		Where codpar = 'XCPTA' and cle='ROF';
	   insert into cp_int (cdos, codets, codjou, numcpt, numpce, datcpt, datpce, datech, coddes1,
						   devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					values(v_cdos, v_codeta, v_codjou, v_numcpt, v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datfac, v_coddes1,
						   v_devise, 1, 'C', cf_row.marrondi, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
	   n_total_cr := n_total_cr + cf_row.marrondi;
	End if;

    -- Ecriture FACTURE TTC DU CLIENT
    if cf_row.mttc != 0 then
       -- Si vente au comptant pour un client Ã  terme.
	   v_numcpt := cf_row.numcpt;

	   If v_numcpt is not null Then
		   Select typcpt Into v_typcpt From Cp_cpt
			Where cdos = v_cdos and numcpt = v_numcpt;
		   If v_typcpt = 'C' Then
			  v_numtie := cf_row.codtie;
		   Else
			  v_numtie := null;
		   End if;
	   End if;

       If cf_row.tie_divers = 'N' or cf_row.ven_comptant = 'N' Then
		  -- Ecriture de contrepartie dans le compte de client car il s'agit d'un client Ã  terme.
          insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
                              devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
					   values (v_cdos, v_codeta, v_codjou, v_numcpt, v_numtie, v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datech,
							   v_devise, 1, 'D', cf_row.mttc, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
		  n_total_db := n_total_db + cf_row.mttc;
       End if;

	   If cf_row.ven_comptant = 'O' Then
	      Select typrgl Into v_typrgl From Utpmrgl
		   Where codmrgl = cf_row.codmrgl;

		  n_solde := cf_row.mttc;

		   -- GÃ©nÃ©ration des Ã©critures de caisse pour les encaissements.
		  If Nvl(v_typrgl,'-') != 'ES' and v_cpteffet is not null Then
		      -- GÃ©nÃ©rer l'Ã©criture pour constater l'EFFET Ã  encaisser.
			  insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
								  devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
						  values (v_cdos, v_codeta, v_codjou, v_cpteffet, null, v_numpce, cf_row.datfac, cf_row.datfac, null,
								  v_devise, 1, 'D', cf_row.mttc, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
			  n_total_db := n_total_db + cf_row.mttc;
		   Elsif v_typrgl = 'ES' and v_codcai is null Then
		      -- GÃ©nÃ©rer l'Ã©criture pour constater l'EFFET Ã  encaisser.
			  insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
								  devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
						  values (v_cdos, v_codeta, v_codjou, v_cptesp, null, v_numpce, cf_row.datfac, cf_row.datfac, null,
								  v_devise, 1, 'D', cf_row.mttc, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
			  n_total_db := n_total_db + cf_row.mttc;
		   ElsIf v_codcai is not null Then
			  -- GÃ©nÃ©rer l'Ã©criture dans le caisse correspondante
			  Select valc Into v_codmvt From Gcppar
			   Where codpar = 'BORDVTES' and cle = 'RCS';

			  -- NumÃ©ro du bon
			  Select max(numbon) Into n_numbon From Caimvt
			   Where codcai = v_codcai and codmvt = v_codmvt;
			  n_numbon := nvl(n_numbon,0)+1;

			  Select max(numjou) Into n_numjou From Caijournal
			   Where codcai = v_codcai
				 And datclo is null;
			  If n_numjou is null Then
				 -- Ouvrir automatiquement un journal
				 Select max(numjou) Into n_numjou From Caijournal
				  Where codcai = v_codcai;
				 n_numjou := Nvl(n_numjou,0) + 1;
				 Insert into Caijournal (codcai, numjou, utiouv, datouv, solde_ouv)
								values  (v_codcai, n_numjou, cf_row.cuti, Trunc(cf_row.datcre,'dd'),0);
			  End if;

			  -- S'il y'a eu un acompte (forcÃ©ment en espÃ¨ces)
			  If Nvl(cf_row.mt_acompte,0) != 0  and v_cptavce is not null Then
				 If not (cf_row.tie_divers = 'O' and cf_row.ven_comptant = 'N') Then
					-- Reprendre le nom du client dans l'Ã©criture qui va dans le compte d'avance
				    v_libecr2 := Substr(v_libecr||' -'||cf_row.nomtie,1,50);
				 Else
					v_libecr2 := v_libecr;
				 End if;

				 insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
									  devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
							  values (v_cdos, v_codeta, v_codjou, v_cptavce, v_tieavce, v_numpce, cf_row.datfac, cf_row.datfac, null,
									  v_devise, 1, 'D', cf_row.mt_acompte, v_reflet, v_libecr2, v_codabrv, sysdate, sysdate, cf_row.cuti);

				 n_total_db := n_total_db + cf_row.mt_acompte;
				 n_solde := cf_row.mttc - Nvl(cf_row.mt_acompte,0);
			  Else
				 n_solde := cf_row.mttc;
			  End if;

			  If nvl(n_solde,0) != 0 Then
				  Select seq_cai_idbon.nextval Into n_idbon From Dual;
				  insert into Caimvt (idbon, numbon, codcai, datbon, codmvt, numjou, nompers, montant, libbon, codedi, cuti, datcre, etat)
							   values(n_idbon, n_numbon, v_codcai, cf_row.datfac, v_codmvt, n_numjou, substr(cf_row.nomtie,1,40), n_solde, v_libecr, 'O', cf_row.cuti, sysdate, 'C');

				  -- Le solde Ã  payer dans le compte de contrepartie de ce journal.
				  insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
									  devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
							  values (v_cdos, v_codeta, v_codjou, v_ctpjou, v_ctpjou_tie, v_numpce, cf_row.datfac, cf_row.datfac, null,
									  v_devise, 1, 'D', n_solde, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
				  n_total_db := n_total_db + n_solde;
			  End if;
		   End if;

		   -- GÃ©nÃ©rer la contrepartie de l'Ã©criture d'encaissement dans le compte du client.
		   If cf_row.tie_divers = 'N' Then
			  insert into cp_int (cdos, codets, codjou, numcpt, numtie, numpce, datcpt, datpce, datech,
								  devpce, crspce, sens, pce_mt, reflet, libecr, codabr, datcre, datmod, coduti)
						  values (v_cdos, v_codeta, v_codjou, v_numcpt, v_numtie, v_numpce, cf_row.datfac, cf_row.datfac, cf_row.datech,
								  v_devise, 1, 'C', cf_row.mttc, v_reflet, v_libecr, v_codabrv, sysdate, sysdate, cf_row.cuti);
			  n_total_cr := n_total_cr + cf_row.mttc;
		   End if;
	   End if;
    End if;

	-- Tester l'Ã©quilibre de la piÃ¨ce
	If Nvl(n_total_db,0) != Nvl(n_total_cr,0) Then
	  raise_application_error(-20052,'Facture '||cf_row.num_ptvte||'/'||to_char(cf_row.numfac)||', ecart total dÃ©bit "'||to_char(n_total_db)||'", total credit "'||to_char(n_total_cr)||'".');
	End if;

	Pr_interfacer_piece(v_cdos, v_codjou, v_numpce, cf_row.datfac, n_numsai_out);

	If n_numsai_out is null Then
	   raise_application_error(-20503,'erreur lors de l''interface de la piÃ¨ce');
	Else
	   Update gcbrde set etat = 'C', numsai=n_numsai_out
		Where idbrd = n_idbrd;

	   Update gcbrde_vte set numsai=n_numsai_out
		Where idbrd = n_idbrd;

	   If n_numbon is not null Then
		  Update Caimvt set etat = 'C', numsai=n_numsai_out
		   Where codcai=v_codcai and codmvt=v_codmvt and numbon=n_numbon;
	   End if;

	   -- Lettrer l'Ã©criture gÃ©nÃ©rÃ©e si vte au comptant sur client Ã  terme
       If cf_row.ven_comptant = 'O' and cf_row.tie_divers = 'N'  and n_solde = cf_row.mttc Then
	      v_numcpt := cf_row.numcpt;
		  v_numtie := cf_row.codtie;
		  Select nvl(numlet,0)+1 Into n_numlet From Cp_aux
		   Where cdos = v_cdos and numcpt = v_numcpt and numtie = v_numtie;

		  Update cp_ecr_let set  pce_mtdb_let=pce_mtdb, pce_mtcr_let=pce_mtcr
								,grp_mtdb_let=grp_mtdb, grp_mtcr_let=grp_mtcr
								,dos_mtdb_let=grp_mtdb, dos_mtcr_let=dos_mtcr
								,cpt_mtdb_let=grp_mtdb, cpt_mtcr_let=cpt_mtcr
								,numlet = n_numlet, datlet = cf_row.datfac, codlet = 'T'
		   Where cdos = v_cdos
			 And numsai = n_numsai_out
			 And numcpt = v_numcpt and numtie = v_numtie;

		  Insert into cp_ecr_let_det (cdos, numsai, numlig, numslg, numsai_det, numlig_det, numslg_det, numlet
									  ,dos_mtdb, dos_mtcr, cpt_mtdb, cpt_mtcr, pce_mtdb, pce_mtcr, grp_mtdb, grp_mtcr)
							  Select  v_cdos, n_numsai_out, numlig, numslg, numsai, numlig, numslg, n_numlet
									  ,dos_mtdb, dos_mtcr, cpt_mtdb, cpt_mtcr, pce_mtdb, pce_mtcr, grp_mtdb, grp_mtcr
								From Cp_ecr_let
							   Where cdos = v_cdos
								 And numcpt = v_numcpt and numtie = v_numtie
								 And numsai = n_numsai_out;

		  Update cp_ecr set codmaj='O', utimaj=cf_row.cuti, datmaj=sysdate
		   Where cdos = v_cdos
			 And numsai = n_numsai_out;

		  Update cp_aux set numlet = nvl(numlet,0)+1
		    Where cdos = v_cdos and numcpt = v_numcpt and numtie = v_numtie;
	   End if;
	End if;
  end loop;
/*
EXCEPTION
  when OTHERS then
	  Insert into gcbrde_log (idbrd, datop, coduti, libop) values (n_idbrd, sysdate, 'DBCF', substr(v_libecr||','||w_message,1,200));

      Update gcbrde set etat = 'O'
	   Where idbrd = n_idbrd;

	  Delete cp_int
	   Where cdos = v_cdos
	     And codjou = v_codjou
	     And datcpt = cf_row.datfac
	     And numpce = v_numpce;
	  Raise;		*/
END;
/
 
CREATE PROCEDURE        PR_CONSO_MOYENNE (v_codart  Varchar2, d_deb_ana DATE, d_fin_ana DATE, v_rupt Varchar2,
			n_qteconso OUT NUMBER, n_moyconso OUT NUMBER, n_nbrconso OUT NUMBER, d_debconso OUT DATE, d_finconso OUT DATE) IS
  -- pour calculer les périodes de rupture
  CURSOR c_mvt(v_codart Varchar2) IS
  		SELECT e.datbrd, SUM(decode(tb.sens,'E',d.qtebrd*nvl(d.coeff,1),0)) qtein, SUM(decode(tb.sens,'S',d.qtebrd*nvl(d.coeff,1),0)) qteout
  		--FROM apmvt m, apcodmvt c
		FROM Gcbrdd d, Gcbrde e, Gcptbrd tb
  		WHERE d.codart = v_codart
		  And e.etat != 'A'
		  And tb.majstock = 'O'
		  And d.typlig =  '0'
		  AND d.idbrd = e.idbrd and e.codtbrd = tb.codtbrd
  		  AND e.datbrd between d_deb_ana and d_fin_ana
  		GROUP BY e.datbrd
  		ORDER BY e.datbrd;

  d_deb_conso		DATE;
  d_fin_conso		DATE;
  d_date			DATE;
  d_debrupt			DATE;
  n_qte				Number;
  n_qte_conso		Number;
  --n_nbrconso		Number;
  d_ddebconso		Date;
  d_dfinconso		Date;
  n_max_qteach		Number;

  n_duree			NUMBER;
  n_rythme			NUMBER;
  w_nbj_rupt		NUMBER;
  v_codtbrd_lst		Gcppar.memo%Type;
BEGIN
  Select nvl(valc,memo) Into v_codtbrd_lst From Gcppar
   Where codpar='BORDEREAUX' and cle='RPR';

  Select max(valn) Into w_nbj_rupt From Gcppar Where codpar='REAPPRO' and cle='NJR';
  w_nbj_rupt := Nvl(w_nbj_rupt,1);


   -- Calculer la conso. dans la période avec la période effective de consommation.
   SELECT SUM(decode(tb.sens,'E',-d.qtebrd*nvl(d.coeff,1),d.qtebrd*nvl(d.coeff,1))), count(*), min(e.datbrd), max(e.datbrd)
		  --,Max(decode(tb.type,'APP',d.qtebrd*nvl(d.coeff,1)))
     INTO n_qte_conso, n_nbrconso, d_ddebconso, d_dfinconso--, n_max_qteach
	 FROM Gcbrdd d, Gcbrde e, Gcptbrd tb
    WHERE d.codart = v_codart
	  And d.codtbrd = tb.codtbrd
	  And tb.majstock = 'O'
	  And e.etat != 'A'
	  And d.typlig = '0'
	  And d.idbrd = e.idbrd
      AND e.datbrd between d_deb_ana and d_fin_ana
	  And Instr(v_codtbrd_lst, d.codtbrd||';') != 0;
      /*AND d.codtbrd IN (SELECT valc FROM Gcppar
						 WHERE codpar='RPROMVT' and cle != '*');*/
   n_qte_conso := NVL(n_qte_conso,0);
   IF n_qte_conso < 0 THEN
      n_qte_conso := 0;
   END IF;

   -- Exclure les périodes de rupture.
   IF v_rupt='O' THEN
      -- Calculer le stock en debut de période.
      SELECT sum(decode(tb.sens,'E',d.qtebrd*nvl(coeff,1),-d.qtebrd*nvl(coeff,1))) INTO n_qte
	   FROM Gcbrdd d, Gcbrde e, Gcptbrd tb
       WHERE d.codart = v_codart
	     And d.idbrd = e.idbrd
		 And e.etat != 'A'
	     And d.codtbrd = tb.codtbrd
		 And d.typlig = '0' and tb.majstock = 'O'
         AND e.datbrd < d_deb_ana;

      IF Nvl(n_qte,0) <= 1 THEN
		 d_date := null;
		 d_debrupt := d_deb_ana;
      ELSE
         d_date := d_deb_ana;
		 d_debrupt := null;
      END IF;
      n_duree := 0;

      FOR mvt_row IN c_mvt(v_codart) LOOP
          n_qte := n_qte + nvl(mvt_row.qtein,0) - nvl(mvt_row.qteout,0);
          IF d_date IS NOT NULL THEN	-- Une période qui a été mouvementée
			 n_duree := n_duree + (mvt_row.datbrd - d_date);
			 d_debrupt := null;
		  ELSE				-- Une rupture qui se termine.
			 IF d_debrupt is null THEN
				null;
			 END IF;
			 IF (mvt_row.datbrd - d_debrupt) < w_nbj_rupt THEN
				n_duree := n_duree + (mvt_row.datbrd - d_debrupt);
			 END IF;
		  END IF;
          IF n_qte <= 0 THEN
			 d_debrupt := mvt_row.datbrd;
			 d_date := null;
		  ELSIF Nvl(n_max_qteach,0) >= 50 and n_qte <= 1 Then
			 d_debrupt := mvt_row.datbrd;
			 d_date := null;
		  ELSE
			 d_debrupt := null;
			 d_date := mvt_row.datbrd;
		  END IF;
      END LOOP;

      IF d_date IS NOT NULL THEN		-- Il y'a du stock à la fin de la période.
         n_duree := n_duree + (d_fin_ana - d_date);
      END IF;
      n_duree := n_duree + 1;
   ELSE
      n_duree := d_fin_ana - d_deb_ana;
   END IF;

   -- Calcul du rythme de consommation mensuel
   IF n_duree != 0 THEN
      n_rythme := ROUND((n_qte_conso * 305/10) / n_duree, 3);
   ELSE
      n_rythme := 0;
   END IF;

   -- Variables de retour.
   n_qteconso := n_qte_conso;
   n_moyconso := n_rythme;
   --n_nbrconso := n_nbrconso;
   d_debconso := d_ddebconso;
   d_finconso := d_dfinconso;
END;
/
 
CREATE procedure        pr_customer_act_desact is

Begin
	-- 1. Blocage des client sans activit‚ depuis 03 mois

	-- Mettre … jour la table UTLOG_APP
	-- Client ayant trois mois d'inactivit‚ et qui n'ont pas ˆtre pris en compte dans ce job il y a trois mois (pour ‚viter de rebloquer les clients qui ont ‚t‚ manuellement d‚bloquer)
	Insert into utlog_app (code_appli, code_util, entite, id_element, date_log, ligne_log)
	Select '100','SQL','GCTIE', codtie, sysdate, 'Suspend on "'||to_char(sysdate,'dd-mon-yy hh24:mi')||'" due to three months inactivity' from gcptie t
	 Where susp = 'N'
	   and not exists (select * from cp_ecr_gen Where cdos='01' and numcpt=t.numcpt and numtie=nvl(t.numtie, t.codtie) and datcpt >= add_months(sysdate,-3))
	   and not exists (Select * From Gcbrde Where codtie=t.codtie and datbrd >= add_months(sysdate,-3))
	   and not exists (Select * From utlog_app Where entite='GCPTIE' and id_element=t.codtie and ligne_log like 'Suspend%on%' and date_log  >= add_months(sysdate,-3));


	-- Mettre … jour la table GCPTIE
	Update gcptie t set susp='O', memo=Substr(memo||chr(10)||'Suspend on "'||to_char(sysdate,'dd-mon-yy hh24:mi')||'" due to three months inactivity',1,255)
	 Where susp = 'N'
	   and not exists (select * from cp_ecr_gen Where cdos='01' and numcpt=t.numcpt and numtie=nvl(t.numtie, t.codtie) and datcpt >= add_months(sysdate,-3))
	   and not exists (Select * From Gcbrde Where codtie=t.codtie and datbrd >= add_months(sysdate,-3))
	   and not exists (Select * From utlog_app Where entite='GCPTIE' and id_element=t.codtie and ligne_log like 'Suspend%on%' and date_log  >= add_months(sysdate,-3));

	-- 2. D‚clocage des clients bloqu‚s ayant un rŠglement sur les 03 mois
	--Select codtie, nomtie from gcptie t


	Insert into utlog_app (code_appli, code_util, entite, id_element, date_log, ligne_log)
	Select '100','SQL','GCTIE', codtie, sysdate, 'Reactivate on "'||to_char(sysdate,'dd-mon-yy hh24:mi')||'" because payment found' from gcptie t
	 Where susp='O'
	 and exists (select * from cp_ecr_gen g, cp_ecr e Where g.cdos='01' and g.cdos=e.cdos and g.numsai=e.numsai and g.numcpt=t.numcpt and g.numtie=nvl(t.numtie, t.codtie) and g.datcpt >= add_months(sysdate,-3)
	 and e.codjou in (select codjou from cp_jou where cdos='01' and typjou='TRE'))
	 and exists (Select * From utlog_app Where entite='GCPTIE' and id_element=t.codtie and ligne_log like 'Suspend%on%' and date_log  >= add_months(sysdate,-3));


	Update gcptie t set susp='N'
	 Where susp='O'
	 and exists (select * from cp_ecr_gen g, cp_ecr e Where g.cdos='01' and g.cdos=e.cdos and g.numsai=e.numsai and g.numcpt=t.numcpt and g.numtie=nvl(t.numtie, t.codtie) and g.datcpt >= add_months(sysdate,-3)
	 and e.codjou in (select codjou from cp_jou where cdos='01' and typjou='TRE'))
	 and exists (Select * From utlog_app Where entite='GCPTIE' and id_element=t.codtie and ligne_log like 'Suspend%on%' and date_log  >= add_months(sysdate,-3));

	commit;
End;
/
 
CREATE PROCEDURE PR_DELETTRER_ECRITURE(v_cdos Varchar2, n_numsai Number, n_numlig Number, n_numslg NUmber default 1) IS
BEGIN
	-- Delettrer Ã©critures lettrÃ©es par les Ã©critures de cette piÃ¨ce.
	For l_row In (Select * From Cp_ecr_let_det Where cdos = v_cdos and numsai = n_numsai and numlig = n_numlig and numslg = n_numslg)
	Loop
	  Update cp_ecr_let set dos_mtdb_let = dos_mtdb_let - nvl(l_row.dos_mtdb,0)
							,cpt_mtdb_let = cpt_mtdb_let - nvl(l_row.cpt_mtdb,0)
							,grp_mtdb_let = grp_mtdb_let - nvl(l_row.grp_mtdb,0)
							,pce_mtdb_let = pce_mtdb_let - nvl(l_row.pce_mtdb,0)
							,dos_mtcr_let = dos_mtcr_let - nvl(l_row.dos_mtcr,0)
							,cpt_mtcr_let = cpt_mtcr_let - nvl(l_row.cpt_mtcr,0)
							,grp_mtcr_let = grp_mtcr_let - nvl(l_row.grp_mtcr,0)
							,pce_mtcr_let = pce_mtcr_let - nvl(l_row.pce_mtcr,0)
							,codlet = null, datlet = null, numlet = null
	   Where cdos = l_row.cdos and numsai = l_row.numsai_det and numlig = l_row.numlig_det and numslg = l_row.numslg_det;
    End loop;
	Delete cp_ecr_let_det Where cdos=v_cdos and numsai = n_numsai and numlig=n_numlig and numslg=n_numslg;

	 For l_row In (Select * From Cp_ecr_let_det Where cdos = v_cdos and numsai_det = n_numsai and numlig_det = n_numlig and numslg_det = n_numslg)
	 Loop
		-- DÃ©lettrer l'Ã©criture maÃ®tre
		Update cp_ecr_let_det set dos_mtdb = dos_mtdb - nvl(l_row.dos_mtcr,0)
								,cpt_mtdb = cpt_mtdb - nvl(l_row.cpt_mtcr,0)
								,grp_mtdb = grp_mtdb - nvl(l_row.grp_mtcr,0)
								,pce_mtdb = pce_mtdb - nvl(l_row.pce_mtcr,0)
								,dos_mtcr = dos_mtcr - nvl(l_row.dos_mtdb,0)
								,cpt_mtcr = cpt_mtcr - nvl(l_row.cpt_mtdb,0)
								,grp_mtcr = grp_mtcr - nvl(l_row.grp_mtdb,0)
								,pce_mtcr = pce_mtcr - nvl(l_row.pce_mtdb,0)
		Where cdos = l_row.cdos and numsai = l_row.numsai and numlig = l_row.numlig and numslg = l_row.numslg;

		Update cp_ecr_let set dos_mtdb_let = dos_mtdb_let - nvl(l_row.dos_mtcr,0)
							,cpt_mtdb_let = cpt_mtdb_let - nvl(l_row.cpt_mtcr,0)
							,grp_mtdb_let = grp_mtdb_let - nvl(l_row.grp_mtcr,0)
							,pce_mtdb_let = pce_mtdb_let - nvl(l_row.pce_mtcr,0)
							,dos_mtcr_let = dos_mtcr_let - nvl(l_row.dos_mtdb,0)
							,cpt_mtcr_let = cpt_mtcr_let - nvl(l_row.cpt_mtdb,0)
							,grp_mtcr_let = grp_mtcr_let - nvl(l_row.grp_mtdb,0)
							,pce_mtcr_let = pce_mtcr_let - nvl(l_row.pce_mtdb,0)
							,codlet = null, datlet = null, numlet = null
		Where cdos = l_row.cdos and numsai = l_row.numsai and numlig = l_row.numlig and numslg = l_row.numslg;

		-- DÃ©lettrer l'Ã©criture dÃ©tail
		Update cp_ecr_let set dos_mtdb_let = dos_mtdb_let - nvl(l_row.dos_mtdb,0)
							,cpt_mtdb_let = cpt_mtdb_let - nvl(l_row.cpt_mtdb,0)
							,grp_mtdb_let = grp_mtdb_let - nvl(l_row.grp_mtdb,0)
							,pce_mtdb_let = pce_mtdb_let - nvl(l_row.pce_mtdb,0)
							,dos_mtcr_let = dos_mtcr_let - nvl(l_row.dos_mtcr,0)
							,cpt_mtcr_let = cpt_mtcr_let - nvl(l_row.cpt_mtcr,0)
							,grp_mtcr_let = grp_mtcr_let - nvl(l_row.grp_mtcr,0)
							,pce_mtcr_let = pce_mtcr_let - nvl(l_row.pce_mtcr,0)
							,codlet = null, datlet = null, numlet = null
		Where cdos = l_row.cdos and numsai = l_row.numsai_det and numlig = l_row.numlig_det and numslg = l_row.numslg_det;
   End loop;
   Delete cp_ecr_let_det Where cdos=v_cdos and numsai_det = n_numsai and numlig_det = n_numlig and numslg_det = n_numslg;

   Update cp_ecr_let set  DOS_MTDB_LET=null, DOS_MTCR_LET=null, CPT_MTDB_LET=null, CPT_MTCR_LET=null, PCE_MTDB_LET=null, PCE_MTCR_LET=null, GRP_MTDB_LET=null, GRP_MTCR_LET=null, numlet=null, datlet=null, codlet=null
    Where cdos = v_cdos and numsai = n_numsai and numlig = n_numlig and numslg = n_numslg;
END;
/
 
CREATE PROCEDURE PR_DELETTRER_PIECE(v_cdos Varchar2, n_numsai Number) IS
BEGIN
	-- Delettrer écritures lettrées par les écritures de cette pièce.
	For l_row In (Select * From Cp_ecr_let_det Where cdos = v_cdos and numsai = n_numsai)
	Loop
	  Update cp_ecr_let set dos_mtdb_let = dos_mtdb_let - nvl(l_row.dos_mtdb,0)
							,cpt_mtdb_let = cpt_mtdb_let - nvl(l_row.cpt_mtdb,0)
							,grp_mtdb_let = grp_mtdb_let - nvl(l_row.grp_mtdb,0)
							,pce_mtdb_let = pce_mtdb_let - nvl(l_row.pce_mtdb,0)
							,dos_mtcr_let = dos_mtcr_let - nvl(l_row.dos_mtcr,0)
							,cpt_mtcr_let = cpt_mtcr_let - nvl(l_row.cpt_mtcr,0)
							,grp_mtcr_let = grp_mtcr_let - nvl(l_row.grp_mtcr,0)
							,pce_mtcr_let = pce_mtcr_let - nvl(l_row.pce_mtcr,0)
							,codlet = null, datlet = null, numlet = null
	   Where cdos = l_row.cdos and numsai = l_row.numsai_det and numlig = l_row.numlig_det and numslg = l_row.numslg_det;
    End loop;
	Delete cp_ecr_let_det Where cdos=v_cdos and numsai = n_numsai;

	 For l_row In (Select * From Cp_ecr_let_det Where cdos = v_cdos and numsai_det = n_numsai)
	 Loop
		-- Délettrer l'écriture maître
		Update cp_ecr_let_det set dos_mtdb = dos_mtdb - nvl(l_row.dos_mtcr,0)
								,cpt_mtdb = cpt_mtdb - nvl(l_row.cpt_mtcr,0)
								,grp_mtdb = grp_mtdb - nvl(l_row.grp_mtcr,0)
								,pce_mtdb = pce_mtdb - nvl(l_row.pce_mtcr,0)
								,dos_mtcr = dos_mtcr - nvl(l_row.dos_mtdb,0)
								,cpt_mtcr = cpt_mtcr - nvl(l_row.cpt_mtdb,0)
								,grp_mtcr = grp_mtcr - nvl(l_row.grp_mtdb,0)
								,pce_mtcr = pce_mtcr - nvl(l_row.pce_mtdb,0)
		Where cdos = l_row.cdos and numsai = l_row.numsai and numlig = l_row.numlig and numslg = l_row.numslg;

		Update cp_ecr_let set dos_mtdb_let = dos_mtdb_let - nvl(l_row.dos_mtcr,0)
							,cpt_mtdb_let = cpt_mtdb_let - nvl(l_row.cpt_mtcr,0)
							,grp_mtdb_let = grp_mtdb_let - nvl(l_row.grp_mtcr,0)
							,pce_mtdb_let = pce_mtdb_let - nvl(l_row.pce_mtcr,0)
							,dos_mtcr_let = dos_mtcr_let - nvl(l_row.dos_mtdb,0)
							,cpt_mtcr_let = cpt_mtcr_let - nvl(l_row.cpt_mtdb,0)
							,grp_mtcr_let = grp_mtcr_let - nvl(l_row.grp_mtdb,0)
							,pce_mtcr_let = pce_mtcr_let - nvl(l_row.pce_mtdb,0)
							,codlet = null, datlet = null, numlet = null
		Where cdos = l_row.cdos and numsai = l_row.numsai and numlig = l_row.numlig and numslg = l_row.numslg;

		-- Délettrer l'écriture détail
		Update cp_ecr_let set dos_mtdb_let = dos_mtdb_let - nvl(l_row.dos_mtdb,0)
							,cpt_mtdb_let = cpt_mtdb_let - nvl(l_row.cpt_mtdb,0)
							,grp_mtdb_let = grp_mtdb_let - nvl(l_row.grp_mtdb,0)
							,pce_mtdb_let = pce_mtdb_let - nvl(l_row.pce_mtdb,0)
							,dos_mtcr_let = dos_mtcr_let - nvl(l_row.dos_mtcr,0)
							,cpt_mtcr_let = cpt_mtcr_let - nvl(l_row.cpt_mtcr,0)
							,grp_mtcr_let = grp_mtcr_let - nvl(l_row.grp_mtcr,0)
							,pce_mtcr_let = pce_mtcr_let - nvl(l_row.pce_mtcr,0)
							,codlet = null, datlet = null, numlet = null
		Where cdos = l_row.cdos and numsai = l_row.numsai_det and numlig = l_row.numlig_det and numslg = l_row.numslg_det;
   End loop;
   Delete cp_ecr_let_det Where cdos=v_cdos and numsai_det = n_numsai;
END;
/
 
CREATE PROCEDURE        PR_INTERFACER_PIECE(w_cdos Varchar2, w_codjou Varchar2, w_numpce_in Varchar2, w_datcpt Date, w_numsai_out OUT NUMBER) IS
   w_retour 	number;
   w_liberr		varchar2(2000);
   w_mess 		varchar2(2000);
   nb_enr_tot 	number := 0;
   nb_enr_err 	number := 0;
   nb_pce_err 	number := 0;
   ets_numsite 	cp_ets.numsite%type;
   typ_ven 	varchar(3);
   w_bid1 	cp_ecr_gen.cours_pce_cpt%type;
   w_bid2 	cp_ecr_gen.cours_pce_cpt%type;
   w_coddes 	cp_des.coddes%type;
   w_nb_let 	integer;
   w_devcpt 	Utpdevise.coddev%type;
   w_numlet 	cp_ecr_let.numlet%type;

   tot_mtdb 	number(16,4)   := 0;
   tot_mtcr tot_mtdb%type := 0;
   pce_mtdb tot_mtdb%type := 0;
   pce_mtcr tot_mtdb%type := 0;
   lig_mtdb tot_mtdb%type := 0;
   lig_mtcr tot_mtdb%type := 0;
   ven_mtdb tot_mtdb%type := 0;
   ven_mtcr tot_mtdb%type := 0;

   a_int cp_int%rowtype;

   w_int cp_int%rowtype;
   w_jou cp_jou%rowtype;
   w_cpt cp_cpt%rowtype;
   w_aux cp_aux%rowtype;
   w_ets cp_ets%rowtype;
   w_par cp_par%rowtype;
   w_pro cp_pro%rowtype;
   w_dev utpdevise%rowtype;
   w_des cp_des%rowtype;
   w_tre cp_tre%rowtype;
   pce cp_ecr%rowtype;
   gen cp_ecr_gen%rowtype;
   ana cp_ecr_ana%rowtype;
   let cp_ecr_let%rowtype;

   w_numpce	cp_ecr.numpce%Type;
   w_numsai cp_ecr_gen.numsai%type;
   w_numlig cp_ecr_gen.numlig%type;
   w_numslg cp_ecr_ana.numslg%type;

   debut boolean := false;
   rupt_piece boolean := false;
   rupt_ligne boolean := false;
   rupt_ventil boolean := false;
   fin boolean := false;

   arret exception;
   anomalie exception;

   w_ddev	cp_dos.ddev%type;
   w_periode	cp_per.periode%type;

   n_nbecr		Number;
   n_nbecr_d	Number;
   n_nbecr_c	Number;

   cursor cur_int is
      select * from cp_int
       where cdos = w_cdos
         and codjou = w_codjou
		 and datcpt = w_datcpt
         and numpce = w_numpce_in
		 --and devpce = w_ddev
       order by cdos, codjou, codets, numpce, datcpt, devpce, numcpt, numtie, sens, reflet,
                coddes1, coddes2, coddes3, coddes4, coddes5, coddes6, coddes7, coddes8, coddes9
         for update of coderr, liberr;

	FUNCTION F_GEN_NUMSAI(i_cdos IN CP_ECR.CDOS%TYPE) RETURN NUMBER
	IS
	  w_numsai	CP_ECR.NUMSAI%TYPE;
	  w_numsai_deb	CP_ECR.NUMSAI%TYPE;
	  w_numsai_fin	CP_ECR.NUMSAI%TYPE;
	  w_numsite	CP_PAR.NUMSITE%TYPE;
	  w_retour	INTEGER;
	BEGIN
	   -- Le num‚ro de saisi est d‚sormais pr‚fix‚ du code site et
	   -- obtenu de la table cp_par.
	   BEGIN
		 SELECT  NVL(NUMSAI,0) + 1, numsite
		   INTO  w_numsai, w_numsite
		   FROM  CP_PAR
		  WHERE  CDOS = i_cdos FOR UPDATE OF NUMSAI;
	   EXCEPTION
		 WHEN NO_DATA_FOUND THEN
			  w_mess := 'erreur attrib. num‚ro saisie';
			  RAISE anomalie;
	   END;

	   w_numsai_deb := w_numsite * 1000000;
	   w_numsai_fin := w_numsai_deb + 999999;
	   IF w_numsai < w_numsai_deb OR w_numsai >= w_numsai_fin THEN
		  BEGIN
			SELECT  NVL(MAX(NUMSAI),w_numsai_deb)
			  INTO  w_numsai
			  FROM  CP_ECR
			 WHERE  CDOS = i_cdos
			   AND NUMSAI between w_numsai_deb and w_numsai_fin;
		  EXCEPTION
			WHEN NO_DATA_FOUND THEN
			   w_numsai := 0;
		  END;
		  w_numsai := w_numsai + 1;
	   END IF;

	   BEGIN
		  UPDATE CP_PAR
			 SET NUMSAI = w_numsai
		   WHERE CDOS = i_cdos;
	   END;

	   RETURN(w_numsai);

	RETURN NULL; EXCEPTION
	   WHEN OTHERS THEN
			Raise arret;
	END;

BEGIN
   Select ddev into w_ddev From cp_dos
    Where cdos=w_cdos;

   -- Obtenir la p‚riode … partir de la date comptable
   Select Min(periode) Into w_periode From cp_per
    Where cdos=w_cdos
      and w_datcpt between datdeb and datfin;

   if w_periode is null then
      w_mess := 'P‚riode obligatoire';
      raise arret;
   end if;

   begin
      select * into w_par
        from cp_par
       where cdos = w_cdos;
    exception
      when no_data_found then
         w_mess := 'Fichier paramŠtre (cp_par) absent';
         raise arret;
   end;

   -- Recherche du d‚s‚quilibre
   open cur_int;
   loop
      fetch cur_int into w_int;

      -- Rupture piŠce
      if nb_enr_tot = 0 or cur_int%notfound or
         w_int.cdos   != a_int.cdos or
         w_int.codjou != a_int.codjou or
         w_int.codets != a_int.codets or
         w_int.numpce != a_int.numpce or
         w_int.datcpt != a_int.datcpt or
         w_int.devpce != a_int.devpce
      then
         if pce_mtdb != pce_mtcr then
            nb_pce_err := nb_pce_err + 1;
            update cp_int_fou
               set coderr = '99',
                   liberr = 'PiŠce d‚s‚quilibr‚e'
             where cdos   = a_int.cdos and
                   codjou = a_int.codjou and
                   codets = a_int.codets and
                   numpce = a_int.numpce and
                   datcpt = a_int.datcpt and
                   devpce = a_int.devpce and
                   rownum = 1;
         end if;
         a_int := w_int;
         pce_mtdb   := 0;
         pce_mtcr   := 0;
      end if;

      exit when cur_int%notfound;

      nb_enr_tot := nb_enr_tot + 1;
      if w_int.sens = 'D' then
         pce_mtdb := pce_mtdb + w_int.pce_mt;
         tot_mtdb := tot_mtdb + w_int.pce_mt;
      else
         pce_mtcr := pce_mtcr + w_int.pce_mt;
         tot_mtcr := tot_mtcr + w_int.pce_mt;
      end if;
      w_int.coderr := '';
      w_int.liberr := '';

      while true loop

         -- Code ‚tablissement
         begin
            select * into w_ets
              from cp_ets
             where cdos = w_int.cdos
               and codets = w_int.codets;
         exception
            when no_data_found then
               w_int.coderr := '02';
               w_int.liberr := 'Etablissement inexistant';
               exit;
         end;

         -- Code journal
         begin
            select * into w_jou
              from cp_jou
             where cdos = w_int.cdos
               and codjou = w_int.codjou;
         exception
            when no_data_found then
               w_int.coderr := '03';
               w_int.liberr := 'Journal inexistant';
               exit;
         end;

         -- Num‚ro de compte g‚n‚ral
         begin
            select * into w_cpt
              from cp_cpt
             where cdos = w_int.cdos
               and numcpt = w_int.numcpt;
         exception
            when no_data_found then
               w_int.coderr := '04';
               w_int.liberr := 'Compte g‚n‚ral inexistant';
               exit;
         end;

         -- Num‚ro de compte tiers
         if w_cpt.typcpt = 'C' then
            begin
               select * into w_aux
                 from cp_aux
                where cdos = w_int.cdos
                  and numcpt = w_int.numcpt
                  and numtie = w_int.numtie;
            exception
               when no_data_found then
                  w_int.coderr := '05';
                  w_int.liberr := 'Compte tiers inexistant';
                  exit;
	       when others then
			   raise;
            end;
         else
            if nvl(w_int.numtie,' ') != ' ' then
               w_int.coderr := '05';
               w_int.liberr := 'Comptes tiers et g‚n‚ral inc.';
               exit;
            end if;
            w_aux.coddev := null;
         end if;

         -- Num‚ro de piŠce
         if w_jou.gesnum = 'N' then
            if nvl(w_int.numpce,' ') = ' ' then
               w_int.coderr := '06';
               w_int.liberr := 'Num‚ro de piŠce obligatoire';
               exit;
            end if;
         end if;

         -- Devise piŠce
         begin
            select * into w_dev
              from utpdevise
             where coddev = w_int.devpce;
         exception
            when no_data_found then
               w_int.coderr := '10';
               w_int.liberr := 'Devise inexistante';
               exit;
         end;

		 /*
         w_devcpt := nvl(w_aux.coddev,w_cpt.coddev);
         if w_devcpt is not null and
            w_int.devpce != w_ets.coddev and w_int.devpce != w_devcpt then
               w_int.coderr := '10';
               w_int.liberr := 'Devises piŠce et compte inc.';
               exit;
         end if;
		*/
         -- Sens
         if w_int.sens not in ('C','D') then
            w_int.coderr := '12';
            w_int.liberr := 'Sens = C ou D';
            exit;
         end if;

         -- Montant
         if nvl(w_int.pce_mt,0) = 0 then
            w_int.coderr := '13';
            w_int.liberr := 'Montant obligatoire';
            exit;
         end if;

         -- R‚f‚rence de lettrage
         begin
            select * into w_pro
              from cp_pro
             where cdos = w_int.cdos
               and codpro = w_cpt.codpro;
         exception
            when no_data_found then
               w_pro.geslet := 'N';
         end;
         if w_pro.geslet = 'O' then
            if nvl(w_int.reflet,' ') = ' ' then
               w_int.coderr := '14';
               w_int.liberr := 'R‚f. de lettrage obligatoire';
               exit;
            end if;
         end if;

         -- Destinations
         if w_pro.gesana = 'O' then
            for i in 1..w_par.nbraxe loop
               if     i = 1 then w_coddes := w_int.coddes1;
               elsif  i = 2 then w_coddes := w_int.coddes2;
               elsif  i = 3 then w_coddes := w_int.coddes3;
               elsif  i = 4 then w_coddes := w_int.coddes4;
               elsif  i = 5 then w_coddes := w_int.coddes5;
               elsif  i = 6 then w_coddes := w_int.coddes6;
               elsif  i = 7 then w_coddes := w_int.coddes7;
               elsif  i = 8 then w_coddes := w_int.coddes8;
               elsif  i = 9 then w_coddes := w_int.coddes9;
               end if;
               begin
                  select * into w_des
                    from cp_des
                   where cdos = w_int.cdos
                     and typdes = 'IMP'
                     and numaxe = i
                     and coddes = w_coddes;
               exception
                  when no_data_found then
                     w_int.coderr := to_char(i + 14);
                     w_int.liberr := 'Destination Axe '||to_char(i)||' inexistante';
                     exit;
               end;
            end loop;
            if w_int.coderr is not null then
               exit;
            end if;
         end if;

         -- Libell‚ ‚criture
         if nvl(w_int.libecr,' ') = ' ' then
            w_int.coderr := '24';
            w_int.liberr := 'Libell‚ ‚criture obligatoire';
            exit;
         end if;

         -- Nature analytique
         if w_pro.gesana = 'O' and nvl(w_cpt.codnat,' ') = ' ' then
            w_int.coderr := '25';
            w_int.liberr := 'Nature ana. non renseign‚';
            exit;
         end if;

         -- Code de tr‚sorerie
         if w_pro.gestre = 'O' then
            if nvl(w_int.codtre,' ') = ' ' then
               w_int.coderr := '26';
               w_int.liberr := 'Code tr‚sorerie non renseign‚';
               exit;
            else
               begin
                  select * into w_tre
                    from cp_tre
                   where cdos = w_int.cdos
                     and codtre = w_int.codtre;
               exception
                  when no_data_found then
                    w_int.coderr := '27';
                    w_int.liberr := 'Code tr‚sorerie inexistant';
                    exit;
               end;
            end if;
         end if;

         exit;

      end loop;

      if w_int.coderr is not null then
         nb_enr_err := nb_enr_err + 1;
      end if;

      update cp_int
         set coderr = w_int.coderr,
             liberr = w_int.liberr
       where current of cur_int;

   end loop;
   close cur_int;

   if nb_enr_err != 0 then
      w_mess := to_char(nb_enr_tot)||'  Lignes trait‚es   *   '||
                   to_char(nb_enr_err)||'  Lignes en erreur';
	  Select max(liberr) Into w_liberr From cp_int
	   Where cdos = w_cdos and codjou = w_codjou and numpce = w_numpce_in and datcpt = w_datcpt;
	  If w_liberr is not null Then
		 w_mess := w_mess||', '||w_liberr;
	  End if;
      raise arret;
   else
      if nb_pce_err != 0 then
         w_mess := 'Pr‚sence de piŠce(s) d‚s‚quilibr‚e(s)';
         raise arret;
      end if;
   end if;

   nb_enr_tot   := 0;
   tot_mtdb    := 0;
   tot_mtcr    := 0;

   open cur_int;
   loop
      fetch cur_int into w_int;

      -- Ruptures

      debut := false;
      rupt_piece := false;
      rupt_ligne := false;
      rupt_ventil := false;
      fin := false;

      if nb_enr_tot = 0 then
         debut := true;
         if cur_int%notfound then
            fin := true;
         end if;
      elsif cur_int%notfound then
         fin := true;
         rupt_piece := true;
         rupt_ligne := true;
         rupt_ventil := true;
      elsif w_int.cdos != a_int.cdos or
         w_int.codjou  != a_int.codjou  or
         w_int.codets  != a_int.codets  or
         w_int.numpce  != a_int.numpce  or
         w_int.datcpt  != a_int.datcpt  or
         w_int.devpce  != a_int.devpce  or w_numlig = 9999
      then
         rupt_piece := true;
         rupt_ligne := true;
         rupt_ventil := true;
      elsif w_int.numcpt  != a_int.numcpt  or
         w_int.numtie  != a_int.numtie  or
		 w_int.libecr  != a_int.libecr or
         w_int.sens    != a_int.sens    or w_numslg = 999
      then
         rupt_ligne := true;
         rupt_ventil := true;
      elsif w_int.reflet  != a_int.reflet  or
         w_int.coddes1 != a_int.coddes1 or
         w_int.coddes2 != a_int.coddes2 or
         w_int.coddes3 != a_int.coddes3 or
         w_int.coddes4 != a_int.coddes4 or
         w_int.coddes5 != a_int.coddes5 or
         w_int.coddes6 != a_int.coddes6 or
         w_int.coddes7 != a_int.coddes7 or
         w_int.coddes8 != a_int.coddes8 or
         w_int.coddes9 != a_int.coddes9
      then
         rupt_ventil := true;
      end if;

      -- Mise … jour des zones … contr“le non bloquant
      if w_jou.gesnum = 'O' THEN
         a_int.numpce := w_numpce_in;
      end if;

      if w_pro.gesana = 'N' then
         a_int.coddes1 := null;
         a_int.coddes2 := null;
         a_int.coddes3 := null;
         a_int.coddes4 := null;
         a_int.coddes5 := null;
         a_int.coddes6 := null;
         a_int.coddes7 := null;
         a_int.coddes8 := null;
         a_int.coddes9 := null;
      end if;

      if w_pro.geslet = 'N' then
         a_int.reflet := null;
--       a_int.numtie := null;
      end if;

      if w_cpt.typcpt != 'C' then
         a_int.numtie := null;
      end if;

      begin
         select codabr into a_int.codabr
           from cp_abr
          where cdos = a_int.cdos
            and codabr = a_int.codabr;
      exception
         when no_data_found then
            a_int.codabr := null;
      end;

      -- Insertion des lignes d'‚critures
      if rupt_ventil then
         if typ_ven = 'ANA' then
            ana.cdos := a_int.cdos;
            ana.codets := a_int.codets;
            ana.numsai := w_numsai;
            ana.numlig := w_numlig;
            ana.numslg := w_numslg;
            ana.numcpt := a_int.numcpt;
            ana.numtie := a_int.numtie;
            ana.datcpt := a_int.datcpt;
            ana.codnat := w_cpt.codnat;
            ana.libecr := a_int.libecr;
            ana.quantite := a_int.quantite;
            ana.options := '1';
            ana.pourcent := null;
            ana.sens := a_int.sens;
            ana.dos_mtdb := null;
            ana.dos_mtcr := null;
            ana.cpt_mtdb := null;
            ana.cpt_mtcr := null;
            ana.pce_mtdb := null;
            ana.pce_mtcr := null;
            ana.grp_mtdb := null;
            ana.grp_mtcr := null;
            if ana.sens = 'D' then
               ana.pce_mtdb := ven_mtdb;
            else
               ana.pce_mtcr := ven_mtcr;
            end if;

			If a_int.devpce = w_ddev or a_int.crspce is null Then
			   ana.dos_mtdb := ana.pce_mtdb;
			   ana.dos_mtcr := ana.pce_mtcr;
			   ana.cpt_mtdb := ana.pce_mtdb;
			   ana.cpt_mtcr := ana.pce_mtcr;
			   ana.grp_mtdb := ana.pce_mtdb;
			   ana.grp_mtcr := ana.pce_mtcr;
			Else
			   ana.dos_mtdb := Round(ana.pce_mtdb * a_int.crspce);
			   ana.dos_mtcr := Round(ana.pce_mtcr * a_int.crspce);
			   ana.cpt_mtdb := ana.pce_mtdb;
			   ana.cpt_mtcr := ana.pce_mtcr;
			   ana.grp_mtdb := ana.dos_mtdb;
			   ana.grp_mtcr := ana.dos_mtcr;

			   --pr_gen_mont_dos(ana.dos_mtdb,ana.dos_mtcr,ana.pce_mtdb,ana.pce_mtcr,a_int.devpce,ana.datcpt,ana.cdos,w_ddev);
			   --pr_gen_mont_cpt(ana.cpt_mtdb,ana.cpt_mtcr,w_bid1,ana.pce_mtdb,ana.pce_mtcr,a_int.devpce,ana.datcpt,ana.cdos,w_ddev,w_devcpt);
               --pr_gen_mont_grp(ana.grp_mtdb,ana.grp_mtcr,w_bid1,w_bid2,ana.pce_mtdb,ana.pce_mtcr,a_int.devpce,ana.datcpt,ana.cdos,w_ddev,ana.dos_mtdb,ana.dos_mtcr);
			End if;

            for i in 1..w_par.nbraxe loop
               if     i = 1 then ana.coddes := a_int.coddes1;
               elsif  i = 2 then ana.coddes := a_int.coddes2;
               elsif  i = 3 then ana.coddes := a_int.coddes3;
               elsif  i = 4 then ana.coddes := a_int.coddes4;
               elsif  i = 5 then ana.coddes := a_int.coddes5;
               elsif  i = 6 then ana.coddes := a_int.coddes6;
               elsif  i = 7 then ana.coddes := a_int.coddes7;
               elsif  i = 8 then ana.coddes := a_int.coddes8;
               elsif  i = 9 then ana.coddes := a_int.coddes9;
               end if;
               ana.numaxe := i;

               begin
                  insert into cp_ecr_ana
				   ( cdos     ,codets   ,numsai   ,numlig   ,numaxe   ,
                     numslg   ,numcpt   ,numtie   ,datcpt   ,codnat   ,
                     coddes   ,libecr   ,quantite ,options  ,pourcent ,
                     sens     ,dos_mtdb ,dos_mtcr ,cpt_mtdb ,cpt_mtcr ,
                     pce_mtdb ,pce_mtcr ,grp_mtdb ,grp_mtcr )
				  values (
                     ana.cdos     ,ana.codets   ,ana.numsai   ,ana.numlig   ,ana.numaxe   ,
                     ana.numslg   ,ana.numcpt   ,ana.numtie   ,ana.datcpt   ,ana.codnat   ,
                     ana.coddes   ,ana.libecr   ,ana.quantite ,ana.options  ,ana.pourcent ,
                     ana.sens     ,ana.dos_mtdb ,ana.dos_mtcr ,ana.cpt_mtdb ,ana.cpt_mtcr ,
                     ana.pce_mtdb ,ana.pce_mtcr ,ana.grp_mtdb ,ana.grp_mtcr );
               exception
                  when others then
                     w_mess := 'Anomalie insertion cp_ecr_ana';
                     raise anomalie;
               end;

            end loop;

         elsif typ_ven = 'LET' then
            let.cdos := a_int.cdos;
            let.codets := a_int.codets;
            let.numsai := w_numsai;
            let.numlig := w_numlig;
            let.numslg := w_numslg;
            let.niveau := null;
            let.numcpt := a_int.numcpt;
            let.numtie := a_int.numtie;
            let.libecr := a_int.libecr;
            let.datcpt := a_int.datcpt;
            let.datech := a_int.datech;
            let.reflet := a_int.reflet;
            let.codlet := null;
            let.datlet := null;
            let.numlet := null;
            let.devlet := null;
            let.sens := a_int.sens;
            let.dos_mtdb := null;
            let.dos_mtcr := null;
            let.cpt_mtdb := null;
            let.cpt_mtcr := null;
            let.pce_mtdb := null;
            let.pce_mtcr := null;
            let.grp_mtdb := null;
            let.grp_mtcr := null;
            let.numsai_source := null;
            let.numlig_source := null;
            let.dos_mtdb_let := null;
            let.dos_mtcr_let := null;
            let.cpt_mtdb_let := null;
            let.cpt_mtcr_let := null;
            let.pce_mtdb_let := null;
            let.pce_mtcr_let := null;
            let.grp_mtdb_let := null;
            let.grp_mtcr_let := null;
            if let.sens = 'D' then
               let.pce_mtdb := ven_mtdb;
            else
               let.pce_mtcr := ven_mtcr;
            end if;

			If a_int.devpce = w_ddev or a_int.crspce is null Then
			   let.dos_mtdb := let.pce_mtdb;
			   let.dos_mtcr := let.pce_mtcr;
			   let.cpt_mtdb := let.pce_mtdb;
			   let.cpt_mtcr := let.pce_mtcr;
			   let.grp_mtdb := let.pce_mtdb;
			   let.grp_mtcr := let.pce_mtcr;
			Else
			   let.dos_mtdb := Round(let.pce_mtdb * a_int.crspce);
			   let.dos_mtcr := Round(let.pce_mtcr * a_int.crspce);
			   let.cpt_mtdb := let.pce_mtdb;
			   let.cpt_mtcr := let.pce_mtcr;
			   let.grp_mtdb := let.dos_mtdb;
			   let.grp_mtcr := let.dos_mtcr;

			   --pr_gen_mont_dos(let.dos_mtdb,let.dos_mtcr,let.pce_mtdb,let.pce_mtcr,a_int.devpce,let.datcpt,let.cdos,w_ddev);
               --pr_gen_mont_cpt(let.cpt_mtdb,let.cpt_mtcr,w_bid1,let.pce_mtdb,let.pce_mtcr,a_int.devpce,let.datcpt,let.cdos,w_ddev,w_devcpt);
               --pr_gen_mont_grp(let.grp_mtdb,let.grp_mtcr,w_bid1,w_bid2,let.pce_mtdb,let.pce_mtcr,a_int.devpce,let.datcpt,let.cdos,w_ddev,let.dos_mtdb,let.dos_mtcr);
			End if;

            begin
              insert into cp_ecr_let (
                 cdos          ,codets        ,numsai        ,numlig        ,numslg        ,
                 niveau        ,numcpt        ,numtie        ,libecr        ,datcpt        ,
                 datech        ,reflet        ,codlet        ,datlet        ,numlet        ,
                 devlet        ,sens          ,dos_mtdb      ,dos_mtcr      ,cpt_mtdb      ,
                 cpt_mtcr      ,pce_mtdb      ,pce_mtcr      ,grp_mtdb      ,grp_mtcr      ,
                 numsai_source ,numlig_source ,dos_mtdb_let  ,dos_mtcr_let  ,cpt_mtdb_let  ,
                 cpt_mtcr_let  ,pce_mtdb_let  ,pce_mtcr_let  ,grp_mtdb_let  ,grp_mtcr_let )
		values (
                 let.cdos          ,let.codets        ,let.numsai        ,let.numlig        ,let.numslg        ,
                 let.niveau        ,let.numcpt        ,let.numtie        ,let.libecr        ,let.datcpt        ,
                 let.datech        ,let.reflet        ,let.codlet        ,let.datlet        ,let.numlet        ,
                 let.devlet        ,let.sens          ,let.dos_mtdb      ,let.dos_mtcr      ,let.cpt_mtdb      ,
                 let.cpt_mtcr      ,let.pce_mtdb      ,let.pce_mtcr      ,let.grp_mtdb      ,let.grp_mtcr      ,
                 let.numsai_source ,let.numlig_source ,let.dos_mtdb_let  ,let.dos_mtcr_let  ,let.cpt_mtdb_let  ,
                 let.cpt_mtcr_let  ,let.pce_mtdb_let  ,let.pce_mtcr_let  ,let.grp_mtdb_let  ,let.grp_mtcr_let );
            exception
               when others then
                  w_mess := 'Anomalie insertion cp_ecr_let';
                  raise anomalie;
            end;
         end if;
      end if;

      if rupt_ligne then
         gen.cdos   := a_int.cdos;
         gen.codets := a_int.codets;
         gen.numsai := w_numsai;
         gen.numlig := w_numlig;
         gen.numcpt := a_int.numcpt;
         gen.numtie := a_int.numtie;
         if a_int.numtie is not null then
            gen.typlig := 'TIE';
         else
            gen.typlig := 'DET';
         end if;
         gen.codabr := a_int.codabr;
         gen.libecr := a_int.libecr;
         gen.datcpt := a_int.datcpt;
         if w_pro.geslet = 'N' then
            gen.datech := null;
            gen.decomp := null;
            gen.numlet := null;
            gen.reflet := null;
         else
            gen.decomp := 'O';
            if w_nb_let = 0 then
               gen.numlet := null;
            else
               gen.numlet := w_numlet;
            end if;
            gen.reflet := a_int.reflet;
            if gen.datech is not null then
               gen.datech := a_int.datech;
            else
               gen.datech := a_int.datcpt;
            end if;
         end if;
         gen.datval := null;
         gen.codmdr := null;
         if w_pro.gestre = 'N' then
            gen.codtre := null;
         else
            gen.codtre := a_int.codtre;
         end if;
         gen.ctpcpt := null;
         gen.ctptie := null;
         gen.sens   := a_int.sens;
         gen.dos_mtdb := null;
         gen.dos_mtcr := null;
         gen.cours_pce_cpt := null;
         gen.cpt_mtdb := null;
         gen.cpt_mtcr := null;
         gen.pce_mtdb := null;
         gen.pce_mtcr := null;
         gen.cours_pce_dos := null;
         gen.cours_dos_grp := null;
         gen.grp_mtdb := null;
         gen.grp_mtcr := null;
         if gen.sens = 'D' then
            gen.pce_mtdb := lig_mtdb;
         else
            gen.pce_mtcr := lig_mtcr;
         end if;

		If a_int.devpce = w_ddev or a_int.crspce is null Then
		   gen.dos_mtdb := gen.pce_mtdb;
		   gen.dos_mtcr := gen.pce_mtcr;
		   gen.cours_pce_dos := 1;
		   gen.cpt_mtdb := gen.pce_mtdb;
		   gen.cpt_mtcr := gen.pce_mtcr;
		   gen.cours_pce_cpt := 1;
		   gen.grp_mtdb := gen.pce_mtdb;
		   gen.grp_mtcr := gen.pce_mtcr;
		   gen.cours_dos_grp := 1;
		Else
		   gen.dos_mtdb := Round(gen.pce_mtdb * a_int.crspce);
		   gen.dos_mtcr := Round(gen.pce_mtcr * a_int.crspce);
		   gen.cours_pce_dos := a_int.crspce;
		   gen.cpt_mtdb := gen.pce_mtdb;
		   gen.cpt_mtcr := gen.pce_mtcr;
		   gen.cours_pce_cpt := 1;
		   gen.grp_mtdb := gen.dos_mtdb;
		   gen.grp_mtcr := gen.dos_mtcr;
		   gen.cours_dos_grp := 1;
		   -- pr_gen_mont_dos(gen.dos_mtdb,gen.dos_mtcr,gen.pce_mtdb,gen.pce_mtcr,a_int.devpce,gen.datcpt,gen.cdos,w_ddev);
			--pr_gen_mont_cpt(gen.cpt_mtdb,gen.cpt_mtcr,gen.cours_pce_cpt,gen.pce_mtdb,gen.pce_mtcr,a_int.devpce,gen.datcpt,gen.cdos,w_ddev,w_devcpt);
			--pr_gen_mont_grp(gen.grp_mtdb,gen.grp_mtcr,gen.cours_pce_dos,gen.cours_dos_grp,gen.pce_mtdb,gen.pce_mtcr,a_int.devpce,gen.datcpt,gen.cdos,w_ddev,gen.dos_mtdb,gen.dos_mtcr);
		 End if;

         begin
            insert into cp_ecr_gen (
               cdos          ,codets        ,numsai        ,numlig        ,numcpt        ,
               numtie        ,codabr        ,libecr        ,datcpt        ,datech        ,
               datval        ,codmdr        ,codtre        ,ctpcpt        ,ctptie        ,
               decomp        ,typlig        ,sens          ,numlet        ,reflet        ,
               dos_mtdb      ,dos_mtcr      ,cours_pce_cpt ,cpt_mtdb      ,cpt_mtcr      ,
               pce_mtdb      ,pce_mtcr      ,cours_pce_dos ,cours_dos_grp ,grp_mtdb      ,
               grp_mtcr      ,rapproche)
			values (
               gen.cdos          ,gen.codets        ,gen.numsai        ,gen.numlig        ,gen.numcpt        ,
               gen.numtie        ,gen.codabr        ,gen.libecr        ,gen.datcpt        ,gen.datech        ,
               gen.datval        ,gen.codmdr        ,gen.codtre        ,gen.ctpcpt        ,gen.ctptie        ,
               gen.decomp        ,gen.typlig        ,gen.sens          ,gen.numlet        ,gen.reflet        ,
               gen.dos_mtdb      ,gen.dos_mtcr      ,gen.cours_pce_cpt ,gen.cpt_mtdb      ,gen.cpt_mtcr      ,
               gen.pce_mtdb      ,gen.pce_mtcr      ,gen.cours_pce_dos ,gen.cours_dos_grp ,gen.grp_mtdb      ,
               gen.grp_mtcr      ,gen.rapproche);
         exception
            when others then
               w_mess := 'Anomalie insertion cp_ecr_gen';
               raise anomalie;
         end;
      end if;

      -- Insertion entˆte piŠces
      if rupt_piece then
         pce.cdos := a_int.cdos;
         pce.codets := a_int.codets;
         pce.codjou := a_int.codjou;
         pce.periode := w_periode;
         pce.datcpt := a_int.datcpt;
         pce.datsai := sysdate;
         if a_int.datpce is null then
            pce.datpce := a_int.datcpt;
         else
            pce.datpce := a_int.datpce;
         end if;
         if w_jou.gesnum = 'O' THEN
            pce.numpce := w_numpce;
         else
            pce.numpce := a_int.numpce;
         end if;
         pce.numsai := w_numsai;
         pce.devpce := a_int.devpce;
         -- pce.crspce := 1; ---f_lec_crschg(pce.cdos,pce.devpce,pce.datcpt);
         If a_int.crspce is null Then
         	pce.crspce := 1; --f_lec_crschg(pce.cdos,pce.devpce,pce.datpce);
         Else
         	pce.crspce := a_int.crspce;
         End if;
         pce.libecr := a_int.libecr;
         pce.dos_mtot := null;
         pce.pce_mtot := pce_mtdb;
         pce.codedi := 'O';
         pce.codmaj := 'N';
		 pce.codinterf := 'O';
		 pce.memopce := a_int.memopce;
		 pce.typpce	 := a_int.typpce;
         pce.datcre := sysdate;
         pce.datmod := sysdate;
         pce.coduti := a_int.coduti;

		 pce.dos_mtot := pce.pce_mtot;
         --pr_gen_mont_dos(pce.dos_mtot,w_bid1,pce.pce_mtot,w_bid2,a_int.devpce,gen.datcpt,gen.cdos,w_ddev);

         begin
            insert into cp_ecr (
			   cdos     ,codets   ,codjou   ,
               periode  ,datcpt   ,datsai   ,
               datpce   ,numpce   ,numsai   ,
               devpce   ,crspce   ,libecr   ,
               dos_mtot ,pce_mtot ,codedi   ,
               codmaj   ,datcre   ,datmod   ,
               codinterf, typpce, coduti   )
			values (
               pce.cdos     ,pce.codets   ,pce.codjou   ,
               pce.periode  ,pce.datcpt   ,pce.datsai   ,
               pce.datpce   ,pce.numpce   ,pce.numsai   ,
               pce.devpce   ,pce.crspce   ,pce.libecr   ,
               pce.dos_mtot ,pce.pce_mtot ,pce.codedi   ,
               pce.codmaj   ,pce.datcre   ,pce.datmod   ,
               pce.codinterf, pce.typpce , pce.coduti   );
         exception
            when others then
               w_mess := 'Anomalie insertion cp_ecr';
              raise anomalie;
         end;

      end if;

      exit when fin;

      if debut or rupt_piece then
         w_numsai := f_gen_numsai(w_cdos);

         select coddev, numsite into w_ddev, ets_numsite
          from cp_ets
         where cdos = w_int.cdos
           and codets = w_int.codets;

         select * into w_jou
          from cp_jou
         where cdos = w_int.cdos
           and codjou = w_int.codjou;

         if w_jou.gesnum = 'O' THEN
            w_numpce := w_numpce_in; --f_gen_numpce(w_int.cdos,w_int.codjou,w_periode);
         end if;

         w_numlig := 0;
         pce_mtdb := 0;
         pce_mtcr := 0;
      end if;

      if debut or rupt_ligne then
         select * into w_cpt
          from cp_cpt
         where cdos = w_int.cdos
           and numcpt = w_int.numcpt;

         select * into w_pro
          from cp_pro
         where cdos = w_int.cdos
           and codpro = w_cpt.codpro;

         w_aux.coddev := null;
         if w_pro.gesana = 'O' then
            typ_ven := 'ANA';
         elsif w_pro.geslet = 'O' then
            typ_ven := 'LET';
            if w_int.numtie is not null then
               select * into w_aux
                 from cp_aux
                where cdos = w_int.cdos
                  and numcpt = w_int.numcpt
                  and numtie = w_int.numtie;
            end if;
         else
            typ_ven := ' ';
         end if;

         w_devcpt := nvl(nvl(w_aux.coddev,w_cpt.coddev),w_ddev);
         w_numlet := null;
         w_nb_let := 0;
         w_numlig := w_numlig + 1;
         w_numslg := 0;
         lig_mtdb := 0;
         lig_mtcr := 0;
      end if;

      if debut or rupt_ventil then
         w_numslg := w_numslg + 1;
         ven_mtdb := 0;
         ven_mtcr := 0;
      end if;

      nb_enr_tot := nb_enr_tot + 1;
      if w_int.sens = 'D' then
         ven_mtdb := ven_mtdb + w_int.pce_mt;
         lig_mtdb := lig_mtdb + w_int.pce_mt;
         pce_mtdb := pce_mtdb + w_int.pce_mt;
         tot_mtdb := tot_mtdb + w_int.pce_mt;
      else
         ven_mtcr := ven_mtcr + w_int.pce_mt;
         lig_mtcr := lig_mtcr + w_int.pce_mt;
         pce_mtcr := pce_mtcr + w_int.pce_mt;
         tot_mtcr := tot_mtcr + w_int.pce_mt;
      end if;

      a_int := w_int;

      delete from cp_int where current of cur_int;

   end loop;
   close cur_int;

   -- Mettre … jour les comptes de contrepartie
   Select count(*), sum(decode(sens,'D',1)), sum(decode(sens,'C',1))
	 Into n_nbecr, n_nbecr_d, n_nbecr_c
	 From cp_ecr_gen g
	where cdos = w_cdos
	  And numsai = w_numsai;

   If n_nbecr = 2 Then
	  Update cp_ecr_gen g set ctpcpt=(select numcpt from cp_ecr_gen where cdos=w_cdos and numsai=w_numsai and numlig!=g.numlig),
							  ctptie=(select numtie from cp_ecr_gen where cdos=w_cdos and numsai=w_numsai and numlig!=g.numlig)
	   Where cdos= w_cdos and numsai = w_numsai;
   Else
	  If n_nbecr_d = 1 Then
		 Update cp_ecr_gen g set ctpcpt = (select numcpt from cp_ecr_gen where cdos=w_cdos and numsai=w_numsai and sens = 'D'),
								 ctptie = (select numtie from cp_ecr_gen where cdos=w_cdos and numsai=w_numsai and sens = 'D')
		  Where cdos= w_cdos and numsai = w_numsai and sens = 'C';
	  Elsif n_nbecr_c = 1 Then
	     Update cp_ecr_gen g set ctpcpt = (select numcpt from cp_ecr_gen where cdos=w_cdos and numsai=w_numsai and sens = 'C'),
								 ctptie = (select numtie from cp_ecr_gen where cdos=w_cdos and numsai=w_numsai and sens = 'C')
		  Where cdos= w_cdos and numsai = w_numsai and sens = 'D';
	  End if;
   End if;

   w_numsai_out := pce.numsai;
EXCEPTION
   when arret then
		if w_int.liberr is not null Then
		   raise_application_error(-20502,w_int.liberr);
		elsif w_mess is not null Then
		   raise_application_error(-20502,w_mess);
		else
		   raise_application_error(-20502,'erreur lors de l''interface de la pièce');
		end if;
   when anomalie then
		if w_int.liberr is not null Then
		   raise_application_error(-20502,w_int.liberr);
		elsif w_mess is not null Then
		   raise_application_error(-20502,w_mess);
		else
		   raise_application_error(-20502,'erreur lors de l''interface de la pièce');
		end if;
END;
/
 
CREATE PROCEDURE        PR_REAPPRO_AUTO IS
  d_deb_ana		DATE;
  d_fin_ana		DATE := SYSDATE;
  w_qtestock	NUMBER;
  w_qteda		NUMBER;
  w_qtecde		NUMBER;
  w_qtereser	NUMBER;

  v_derach			Varchar2(20);
  d_derach			DATE;
  v_codtie			Gcbrde.codtie%Type;
  d_date			DATE;
  d_debrupt			DATE;
  n_qte				Number;
  d_deb_conso		DATE;
  d_fin_conso		DATE;
  n_qte_conso		Number;
  n_nbrconso		Number;
  d_deb_conso2		DATE;
  d_fin_conso2		DATE;
  n_qte_conso2		Number;
  n_nbrconso2		Number;

  n_nbart			NUMBER;
  n_nbartr			NUMBER;
  n_duree			NUMBER;
  n_rythme			NUMBER;
  n_rythme2			NUMBER;
  w_nbrmois_loc		Number;
  w_nbrmois_imp		Number;
  w_nbrmois_cde		Number;
  n_nbj_rupt		NUMBER;
  v_rupt			VARCHAR2(1);

  n_retour			NUMBER;
  w_total			NUMBER;
  w_nb				NUMBER;
  n_nbdec			NUMBER;
  n_qteacder		NUMBER;
  w_mess_suite		VARCHAR2(50);

  d_datarr			Date;
  n_valn			Number;
  v_typnatt			Gcpnatt.typnatt%Type;
  v_import			Varchar2(1);

/*
  PROCEDURE PR_ROLLBACK IS
  BEGIN
    rollback;
    insert into aplog (CDOS,CUTI,DATC,LIGNE,NUMERO_SESSION,TERMINAL,OSUSER)
		values(w_cdos,'DB',sysdate,'Erreur lors du calcul du réapprovisionnement.',null,null,null);
    commit;
  END;
*/
  FUNCTION FN_NBDEC_UNITE(w_unite VARCHAR2) RETURN NUMBER IS
     w_nbdec	Gcppar.valn%TYPE;
  BEGIN
     SELECT valn INTO w_nbdec FROM Gcppar
      WHERE codpar='UNITES' and cle=w_unite;
     RETURN nvl(w_nbdec,0);
  EXCEPTION
     WHEN no_data_found THEN
          RETURN (0);
  END;


BEGIN
  n_nbart := 0;
  n_nbartr := 0;

  w_total := 0;

  d_datarr		:= Trunc(sysdate,'dd');

  d_fin_ana 	:= d_datarr;
  d_deb_ana 	:= ADD_MONTHS(d_fin_ana, -12); --g_row.nbrmois_cal);

  Select max(valn) Into n_valn From Gcppar Where codpar='REAPPRO' and cle='NJR';
  n_nbj_rupt 	:= Nvl(n_valn,1);

  IF n_nbj_rupt > 0 THEN
	 v_rupt := 'O';
  ELSE
	 v_rupt := 'N';
  END IF;

  Select max(valn) Into n_valn From Gcppar Where codpar='REAPPRO' and cle='NML';
  w_nbrmois_loc := Nvl(n_valn, 1/2);

  Select max(valn) Into n_valn From Gcppar Where codpar='REAPPRO' and cle='NMI';
  w_nbrmois_loc := Nvl(n_valn, 3);

  -- Effacer l'ancien enregistrement.
  Delete Gcpart_moy_conso;

  FOR a_row IN (Select codart, codcrit, unistk, codnata From Gcpart Where tensto='O'/*typart like 'PE%' or typart like 'GE%'*/) -- Where codart = 'LG-RAC ARTSC096PML2')
  LOOP
	  n_nbart := n_nbart + 1;
	  n_nbdec := FN_NBDEC_UNITE(a_row.unistk);

	  Pr_conso_moyenne(a_row.codart, d_deb_ana, d_fin_ana, v_rupt, n_qte_conso, n_rythme, n_nbrconso, d_deb_conso, d_fin_conso);

	  -- Date du dernier achat.
	  Select max(to_char(e.datbrd,'yyyymmdd')||e.codtie) Into v_derach From Gcbrdd d, Gcbrde e, Gcptbrd tb
	   Where d.codart=a_row.codart
		 And d.idbrd = e.idbrd
		 And d.codtbrd = tb.codtbrd
		 And e.etat != 'A'
		 And d.qtebrd != 0
		 And tb.type='APP' and tb.majstock = 'O';
	  d_derach := To_date(Substr(v_derach,1,8),'yyyymmdd');
	  v_codtie := Substr(v_derach,9);

	  If v_codtie is not null Then
		 Select max(n.typnatt) Into v_typnatt From Gcptie t, Gcpnatt n
		  Where t.codtie = v_codtie
			And t.codnatt = n.codnatt;
	     If v_typnatt = 'I' Then
			v_import := 'O';
		 Else
			v_import := 'N';
		 End if;
	  Else
		 v_import := 'N';
		 /*
		 -- Lire la nature d'article importé ou local
		 Select max(import) Into v_import From Gcpart a, Gcpnata n
		  Where a.codart = a_row.codart
		    And a.codnata = n.codnata;
		*/
	  End if;

	  If v_import = 'O' Then
	     w_nbrmois_cde := w_nbrmois_imp;
	  Else
	     w_nbrmois_cde := w_nbrmois_loc;
	  End if;

	  -- Calcul de la moyenne de conso à partir de la date de dernier achat.
	  If d_derach is not null Then
		 Pr_conso_moyenne(a_row.codart, d_derach, d_fin_ana, v_rupt,n_qte_conso2, n_rythme2, n_nbrconso2, d_deb_conso2, d_fin_conso2);
	  Else
		 n_qte_conso2 	:= null;
		 n_rythme2		:= null;
		 n_nbrconso2		:= null;
		 d_deb_conso2	:= null;
		 d_fin_conso2	:= null;
	  End if;

	  Select sum(qtestock), sum(qtecde), sum(qtereserv), sum(qteda) Into w_qtestock, w_qtecde, w_qtereser, w_qteda From Gcstock
	   Where codart = a_row.codart;
	  w_qtestock := Nvl(w_qtestock,0);
	  w_qtecde := Nvl(w_qtecde,0);
	  w_qtereser := Nvl(w_qtereser,0);
	  w_qteda := Nvl(w_qteda,0);


	  -- Mettre à jour le stock mini
	  -- Vérifier si le stock est suffisant sinon générer un réappro
	  -- Générer dans la table des articles à réapprovisionner
      INSERT INTO Gcpart_moy_conso (codart, datarr, qtestock, qtecde, qteda, qtereserv, qteconso ,qtemoyconso, qteacder, nbrconso, ddebconso, dfinconso
									,datderach, qteconso2 ,qtemoyconso2, nbrconso2)
						   VALUES  (a_row.codart, d_datarr, w_qtestock, w_qtecde, w_qteda, w_qtereser, n_qte_conso, n_rythme, 0, n_nbrconso, d_deb_conso, d_fin_conso
									,d_derach, n_qte_conso2, n_rythme2, n_nbrconso2);

	  -- Calcul de la qté à cder.
	  If a_row.codcrit = 'A' Then
		 n_qteacder := n_rythme * w_nbrmois_cde - w_qtestock - w_qtecde - w_qteda;
		 n_qteacder := ROUND(n_qteacder, n_nbdec);
		 IF n_qteacder < 0 THEN
			n_qteacder := 0;
		 END IF;
	  Else
		 n_qteacder := 0;
	  End if;

	  IF n_qteacder > 0 THEN
		 UPDATE Gcpart_moy_conso SET qteacder = n_qteacder
		  WHERE codart=a_row.codart;
		 n_nbartr := nvl(n_nbartr,0) + 1;
	  END IF;
  END LOOP;

  Standard.commit;
END;
/
 
CREATE PROCEDURE        PR_REVALORISER_ARTICLE_DB(v_codeta VARCHAR2, v_codart VARCHAR2, d_date DATE) IS
  CURSOR c_mvt(p_codeta VARCHAR2, p_codart VARCHAR2, p_datmvt DATE)
		IS SELECT d.codtbrd, d.qtebrd, d.coeff, d.purevient, d.montrevient, e.datbrd, e.crschg, e.coeffrev, e.typven, t.opsais, t.sens, t.type, dp.type_depot
		     FROM gcbrdd d, gcbrde e, gcptbrd t, gcpdep dp
		    WHERE d.typlig = '0'		-- Uniquement les lignes de type stock.
		    	AND d.codart=p_codart
		      AND d.idbrd = e.idbrd
		      And d.coddep = dp.coddep
		      AND e.etat != 'A'			-- Ne pas prendre en compte les bord. annul‚s
		      AND e.datbrd >= p_datmvt
		      AND e.codtbrd=t.codtbrd
		      AND t.majstock = 'O'
		      AND (e.codeta=p_codeta  or p_codeta is null)
		   ORDER BY e.datbrd, t.sens, d.codtbrd, d.idbrd, d.numlig
		   FOR UPDATE of d.montrevient, d.purevient;

  n_qte				GCPRMP.quantite%type;
  n_montant		Number; -- GCPRMP.montant%type;
  n_prmp			Number; -- GCPRMP.prmp%type;
  n_prmp_next	Number; -- GCPRMP.prmp%type;
  n_niveau		Number := 0;
  d_date_next	Date;

  n_retour		NUMBER;
  n_pubrd			Number;

  v_nomsoc		Utppar.Valc%Type;

	FUNCTION FN_PROCHAIN_PUREV (v_codeta VARCHAR2, v_codart VARCHAR2, d_datarr DATE, d_date_next OUT DATE) RETURN NUMBER IS
	  n_next_prmp			gcprmp.prmp%type;
	  v_date_pu				Varchar2(30);
	  d_dder_entree		DATE;
	  d_dder_sortie		DATE;
	BEGIN
	   BEGIN
		 SELECT min(to_char(e.datbrd,'yyyymmdd')||to_char(round(purevient,2))) Into v_date_pu
		   FROM gcbrdd d, gcbrde e
		  WHERE d.idbrd=e.idbrd
			AND d.codart=v_codart
			AND e.datbrd > d_datarr
			  And (   v_codeta is null
					 or (v_codeta is not null and d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=v_codeta))
					)
			  AND d.codtbrd in (SELECT codtbrd FROM gcptbrd WHERE majstock='O' and opsais='P')
			  AND nvl(purevient,0) > 0;
			 n_next_prmp := To_number(substr(v_date_pu,9));
			 d_date_next := To_date(substr(v_date_pu,1,8),'yyyymmdd');
	   EXCEPTION
		 WHEN no_data_found THEN
					  n_next_prmp := 0;
	   END;

	   RETURN nvl(n_next_prmp,0);
	END;

	FUNCTION FN_DERNIER_PUREV (v_codeta VARCHAR2, v_codart VARCHAR2, d_datarr DATE) RETURN NUMBER IS
	  n_last_prmp			gcprmp.prmp%type;
	  n_last_prmp_e		gcprmp.prmp%type;
	  n_last_prmp_s		gcprmp.prmp%type;
	  d_dder_entree		DATE;
	  d_dder_sortie		DATE;
	  v_date_pu				Varchar2(30);
	BEGIN
	  -- PremiŠrement dans le dernier mouvement valoris‚ lors de la fin du mois.
	  BEGIN
		 --SELECT max(purevient), max(e.datbrd) INTO n_last_prmp_s, d_dder_sortie
		 SELECT max(to_char(e.datbrd,'yyyymmdd')||to_char(round(purevient,2))) Into v_date_pu
		   FROM gcbrdd d, gcbrde e
		  WHERE d.idbrd=e.idbrd
			AND d.codart=v_codart
			AND e.datbrd <= d_datarr
			  And (   v_codeta is null
					 or (v_codeta is not null and d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=v_codeta))
					)
			  AND d.codtbrd in (SELECT codtbrd FROM gcptbrd WHERE majstock='O' and opsais = 'Q')
			  AND nvl(purevient,0) > 0;
		  d_dder_sortie := To_date(substr(v_date_pu,1,8),'yyyymmdd');
		  n_last_prmp := To_number(substr(v_date_pu,9));
	   EXCEPTION
		  WHEN no_data_found THEN
					 n_last_prmp_s := 0;
					 n_last_prmp := 0;
	   END;

	   -- Si echec alors rechercher le dernier mouvement valoris‚ … la saisie.
	   If Nvl(n_last_prmp,0) = 0 Then
			   BEGIN
				 --SELECT max(purevient), max(e.datbrd) INTO n_last_prmp_s, d_dder_sortie
				 SELECT max(to_char(e.datbrd,'yyyymmdd')||to_char(round(purevient,2))) Into v_date_pu
				   FROM gcbrdd d, gcbrde e
				  WHERE d.idbrd=e.idbrd
					AND d.codart=v_codart
					AND e.datbrd <= d_datarr
					  And (   v_codeta is null
							 or (v_codeta is not null and d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=v_codeta))
							)
					  AND d.codtbrd in (SELECT codtbrd FROM gcptbrd WHERE majstock='O' and opsais='P')
					  AND nvl(purevient,0) > 0;
				  d_dder_entree := To_date(substr(v_date_pu,1,8),'yyyymmdd');
				  n_last_prmp := To_number(substr(v_date_pu,9));
			   EXCEPTION
				 WHEN no_data_found THEN
							  --n_last_prmp_e := 0;
							  n_last_prmp := 0;
							d_dder_entree := to_date('01/01/1900','dd/mm/yyyy');
			   END;
		 End if;
	   RETURN nvl(n_last_prmp,0);
	END;
BEGIN
	Select max(valc) Into v_nomsoc From Utppar
	 Where codpar = 'PARGEN' and cle = 'SOC';

	-- Calculer le prix moyen pond‚r‚ … DATREC-1
	SELECT sum(decode(t.sens,'E',d.qtebrd,-d.qtebrd)*nvl(coeff,1)),
		 sum(decode(t.sens,'E', d.montrevient, -d.montrevient))
	INTO n_qte, n_montant
	FROM gcbrdd d, gcbrde e, gcptbrd t
	 WHERE d.codart=v_codart and typlig = '0'
	   AND d.idbrd = e.idbrd
	   And (e.codeta = v_codeta or v_codeta is null)
	   And e.etat != 'A'
	   AND e.codtbrd = t.codtbrd and t.majstock = 'O'
	   AND e.datbrd < d_date;

	n_montant 	:= NVL(n_montant,0);
	n_qte 			:= NVL(n_qte, 0);

	n_niveau := n_niveau + 1;

	-- PRMP ISSUE DES MVTS A DATE-1
	n_prmp_next := Fn_prochain_purev(v_codeta, v_codart, d_date, d_date_next);
	if n_qte = 0 or n_montant = 0 or sign(n_montant) != sign(n_qte) then
		 n_prmp := FN_DERNIER_PUREV(v_codeta, v_codart, d_date);
		 If nvl(n_prmp,0) = 0 Then
			  n_prmp := n_prmp_next;
		 End if;
	else
		 n_prmp := Round(n_montant / n_qte,3);
	end if;
	-- MSG('OUI_INFO','(… DATE-1) montant ='||to_char(n_montant)||' , quantite ='||to_char(n_qte));

	-- D‚sactiver le trigger pendant la revalorisation
	Begin
		Insert into Gcpart_rvals (codart, dattrt) values (v_codart, sysdate);
	Exception
		When others Then null;
	End;

	n_niveau := n_niveau + 1;
	Update gcbrdd set purevient = 1, montrevient = Round(qtebrd*nvl(coeff,1))
	 Where codtbrd in (Select codtbrd from Gcptbrd Where majstock='O' and opsais='Q')
	   And typlig='0'
	   and codart = v_codart
	   And exists (Select * From Gcbrde Where idbrd = Gcbrdd.idbrd and datbrd >= d_date and (codeta=v_codeta or v_codeta is null));


	-- REVALORISER TOUS LES MOUVEMENTS
	FOR mvt_row IN c_mvt(v_codeta, v_codart, d_date) LOOP
	  IF mvt_row.opsais in ('P','M')
		and Not (v_nomsoc like 'STE%REGAL%' and mvt_row.codtbrd = 'IN' and mvt_row.type_depot = 'M')
	  THEN
			IF n_qte <= 0 or n_montant < 0 THEN
			  If d_date_next < mvt_row.datbrd Then
				 n_prmp_next := Fn_prochain_purev(v_codeta, v_codart, mvt_row.datbrd, d_date_next);
			  End if;

			  -- S'il n'ya plus de PRMP next alors next_prmp = prmp du mouvement.
			  If nvl(n_prmp_next,0) = 0 and mvt_row.opsais = 'P' Then
				 n_prmp_next := mvt_row.purevient;
			  End if;
			End if;

				-- Recalculer le PRMP.
			if mvt_row.sens='E' then
			   n_montant := NVL(n_montant,0)+ NVL(mvt_row.montrevient,0);
			   n_qte     := NVL(n_qte,0)+ NVL(mvt_row.qtebrd,0)* Nvl(mvt_row.coeff,1);
			else
			   n_montant := NVL(n_montant,0)- NVL(mvt_row.montrevient,0);
			   n_qte     := NVL(n_qte,0)- NVL(mvt_row.qtebrd,0)* Nvl(mvt_row.coeff,1);
			end if;

					-- Recalculer le PRMP.
			if n_qte = 0 then 	null; -- n_prmp := 0;  ne pas annuler le prmp.
			elsif n_qte < 0 or n_montant < 0 then null;
			else	    					n_prmp := Round(n_montant / n_qte,3);
			end if;
			--MSG('OUI_INFO','(aprŠs une entr‚e) montant ='||to_char(n_montant)||' , quantite ='||to_char(n_qte));

		ELSE
			--MSG('OUI_INFO','Maj d''un mvt PRMP ='||to_char(n_prmp));
			-- Valoriser le mouvement.
			-- Si prmp est ‚gale … 0 conserver le montant du mouvement.
			IF (n_qte <= 0 or n_montant < 0) and nvl(n_prmp_next,0) != 0 THEN
				 n_prmp := n_prmp_next;
			End if;

			IF nvl(n_prmp,0) != 0 THEN
			   UPDATE gcbrdd set montrevient=ROUND(qtebrd*Nvl(coeff,1)*n_prmp), purevient=n_prmp
				WHERE current of c_mvt;

				 IF mvt_row.typven is null and mvt_row.type != 'VEN' THEN
						-- 2016-04-15, Tenir compte du coeffrev et du cours de change
						If nvl(mvt_row.coeffrev,1)*nvl(mvt_row.crschg,1) != 0  Then
							 n_pubrd := (n_prmp*nvl(mvt_row.coeff,1)) / (nvl(mvt_row.coeffrev,1)*nvl(mvt_row.crschg,1));
						Else
							 n_pubrd := (n_prmp*nvl(mvt_row.coeff,1));
						End if;
							UPDATE gcbrdd set pubrd=n_pubrd, montbrd=ROUND(qtebrd*Nvl(coeff,1)*n_prmp)
					   WHERE current of c_mvt;
				 END IF;

						-- Mettre … jour les montants et les quantites.
				if mvt_row.sens='E' then
				   n_montant := NVL(n_montant,0)+ NVL(ROUND(mvt_row.qtebrd*Nvl(mvt_row.coeff,1)*n_prmp,0),0);
				   n_qte     := NVL(n_qte,0)+ NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				else
				   n_montant := NVL(n_montant,0)- NVL(ROUND(mvt_row.qtebrd*Nvl(mvt_row.coeff,1)*n_prmp,0),0);
				   n_qte     := NVL(n_qte,0)- NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				end if;
			  ELSE
				if mvt_row.sens='E' then
				   n_montant := NVL(n_montant,0)+ NVL(mvt_row.montrevient,0);
				   n_qte     := NVL(n_qte,0)+ NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				else
				   n_montant := NVL(n_montant,0)- NVL(mvt_row.montrevient,0);
				   n_qte     := NVL(n_qte,0)- NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				end if;
			END IF;
			/* Pas de recalcul du prmp s'il s'agit d'un mvt … valoriser.
				-- MAJ le PRMP (surtout pour le cas ou la w_qte serait … z‚ro).
				if n_qte = 0 then 	null; -- ne pas annuler le prmp n_prmp := 0;
				else	    					n_prmp := n_montant / n_qte;
				end if;
			*/
		END IF;
	END LOOP;

	  Update Gcprmp p set quantite = (select sum(qtestock) from Gcstock
									where codart=p.codart
										and coddep in (select coddep from Gcpdep where codeta=p.codeta))
	   Where codart=v_codart
	     And periode='999912';

	  Insert into Gcprmp (codart, codeta, periode, quantite)
							 Select v_codart, codeta, '999912', sum(qtestock) From Gcstock s, Gcpdep d
							  Where s.codart = v_codart
								And s.coddep = d.coddep
								And not exists (Select * From Gcprmp Where codart=v_codart and codeta=d.codeta and periode='999912')
							 Group by codeta;


	UPDATE GCPRMP SET prmp = n_prmp, montant = Round(quantite*n_prmp)
	 WHERE (codeta = v_codeta or v_codeta is null)
	   AND codart = v_codart
	   AND periode = '999912';


	Delete Gcpart_rvals Where codart = v_codart;
END;
/
 
CREATE PROCEDURE Synchro_XCAISSE_DLA_YDE IS
	Cursor c_art IS SELECT * FROM gcpart
				   WHERE datcre >= SYSDATE - 10
					  or datmod >= SYSDATE - 10;

	out_file		UTL_FILE.FILE_TYPE;
	al_row			GCPART%TYPE;
	ad_row			GCPART%TYPE;

	b_delta			BOOLEAN;

	v_cdos			Varchar2(30); --CEPPAR.valc%TYPE;
	v_tarif_std		Varchar2(30); --CEPPAR.valc%TYPE;

	v_codnata		GCPART.codnata%TYPE;
	v_codrtax		Varchar2(30); --CEPPAR.valc%TYPE;
	v_codcrit		Varchar2(30); --CEPPAR.valc%TYPE;
	v_codray		Varchar2(30); --CEPPAR.valc%TYPE;

	FUNCTION FN_GET_CEPARAMC(v_codpar VARCHAR2, v_cle VARCHAR2) RETURN VARCHAR2 IS
	   w_valc			Varchar2(30); --CEPPAR.VALC%TYPE;
	BEGIN
	   SELECT valc INTO w_valc FROM CEPPAR
		WHERE codpar=v_codpar and cle=v_cle;
	   RETURN (w_valc);
	EXCEPTION
		 WHEN NO_DATA_FOUND THEN
		   RETURN (null);
	END;
BEGIN
	-- Acquisition des paramètres
	BEGIN
	  v_cdos 		:= FN_GET_CEPARAMC('DELTA','001');
	  v_tarif_std 	:= FN_GET_CEPARAMC('DELTA','002');
	  v_codrtax		:= FN_GET_CEPARAMC('DELTA','A04');
	  v_codcrit		:= FN_GET_CEPARAMC('DELTA','A05');
	  v_codray		:= FN_GET_CEPARAMC('DELTA','A06');
	  v_codnata		:= FN_GET_CEPARAMC('DELTA','A07');
	  v_repertoire  := FN_GET_CEPARAMC('??','??');
	EXCEPTION
	  WHEN others THEN
		   Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
		              values ('DB','DB',null,null,sysdate,sysdate,'Problème lors de la récupération des paramètres d''importation.');
		   RETURN;
	END;

	If v_repertoire is null Then
	   Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
	              values ('DB','DB',null,null,sysdate,sysdate,'Repertoire de tranfert non paramétré (CEPPAR)');
	   RETURN;
	Elsif v_cdos IS NULL or v_tarif_std IS NULL or v_codnat IS NULL THEN
	   Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
	              values ('DB','DB',null,null,sysdate,sysdate,'Paramètres DOSSIER et/ou TARIF incorrect (CEPPAR)');
	   RETURN;
	End if;

	-- Création du fichier de BD
	Begin
	out_file := UTL_FILE.FOPEN(v_repertoire||'\'||to_char(sysdate,'yyyymmdd-hh24')||'.CSV', 'w');
	UTL_FILE.put_line(out_file, 'Article;Désignation;Ancien code barre;Nouveau code barre;Ancien Tarif;Nouveau Tarif;Ancien Tarif promo;Nouveau Tarif promo');
	Exception
	  When others Then
		   Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
		              values ('DB','DB',null,null,sysdate,sysdate,'Erreur lors de la création du fichier "'||v_repertoire||'\'||to_char(sysdate,'yyyymmdd-hh24')||'.CSV'||'".');
		   RETURN;
	End;

	-- Mise à jour des compteurs de codes barres
	Update gcppar set valn = to_number(v_codbarre)
	Where codpar = 'CPT_CBMAN'
	  and cle = art_row.codart
	  and valn < to_number(v_codbarre);


	FOR al_row IN c_art LOOP
		b_delta := False;

		Select count(*) Into n_count From gcpart_YDE
		 Where codart = al_row.codart;

		-- Vérifier dans Delta si l'article existe
		If n_count = 0 Then
		   Select count(*) Into n_count From apart
			Where cdos=v_cdos and codart = al_row.codart;

		   If n_count > 0 Then
			  b_delta := True;
		   Else
			  b_delta := False;
			  -- Est ce une DLV
			  If (al_row.codart like '%*1' or al_row.codart like '%*2' or al_row.codart like '%*3') Then
				 Select count(*) Into n_count From gcpart
				  Where codart=Substr(al_row.codart,1,length(al_row.codart)-2);
			  End if;
			End if;
		Else
			b_delta := False;
		End if;

		If n_count = 0 Then		-- L'article n'existe ni dans XCaisse YDE, ni dans DELTA et n'est pas une DLV  ((probablement une fusion)
		   UTL_File.put_line(out_file, v_codart||';Inexistant dans Delta et XCAISSE');
		Else
		   If not b_delta Then  -- L'article existe dans XCAISSE YDE
			  Begin
				Select * Into ad_row From gcpart_YDE
				 Where codart=al_row.codart;
			  Exception
				When others Then
					 ad_row.libart := null;
					 ad_row.codbarre := null;
					 ad_row.datcre := null;
					 ad_row.datmod := null;
					 ad_row.tarifstd := null;
					 ad_row.tarifpro := null;
					 ad_row.codbarre := null;
			  End;

			  If ad_row.gestion_locale = 'O' Then
 			     UTL_FILE.put_line(out_file, al_row.codart||al_row.libart||';Gestion locale');
			  ElsIf (ad_row.datcre is null or al_row.datcre >= ad_row.datcre) or (al_row.datmod >= ad_row.datmod or ad_row.datmod is null) or (al_row.etat != ad_row.etat) Then
				 If al_row.etat != ad_row.etat Then
					If al_row.etat = 'I' Then
					   UTL_FILE.put_line(out_file, al_row.codart||';Article désactivé');
					Elsif al_row.etat = 'S' Then
					   UTL_FILE.put_line(out_file, al_row.codart||';Article supprimé');
					End if;
			     ElsIf  nvl(ad_row.tarifstd,0) != nvl(al_row.tarifstd,0) or nvl(al_row.codbarre,'-') != nvl(ad_row.codbarre,'-')
					 or nvl(ad_row.tarifpro,0) != nvl(al_row.tarifpro,0) Then
					 UTL_FILE.put_line(out_file, al_row.codart||';'||al_row.libart||';'||to_char(ad_row.tarifpro)||';'||to_char(iif_n(al_row.promo='O',al_row.tarifpro,null)));
				 End if;

			     Update gcpart_YDE set codbarre=al_row.codbarre, codnata=al_row.codnata ,tarifstd=nvl(al_row.tarifstd,tarifstd)
											,promo=al_row.promo, pro_ddeb=al_row.pro_ddeb, pro_dfin=al_row.pro_dfin, tarifpro=nvl(al_row.tarifpro, tarifpro), pro_tauxrem=al_row.pro_tauxrem
											,datmod=SYSDATE, muti='DB'
											,etat=al_row.etat
				  where codart = al_row.codart;

				 -- Mettre à jour la table des codes barres
				 If SQL%Rowcount > 0 Then
					Delete gcpart_barre@XAPP_YDE
					 Where codart = al_row.codart;

					Insert into gcpart_barre@XAPP_YDE
					Select * From gcpart
					 Where codart = al_row.codart;
				 End if;

			     -- S'il s'agit d'une DLV
				 If SQL%Rowcount = 0 and (al_row.codart like '%*1' or al_row.codart like '%*2' or al_row.codart like '%*3') Then
					  INSERT INTO GCPART_YDE
										(codart, tensto, libartr, libart, libart2, unistk, uniach, univen, coeff_ach, coeff_ven,
										 kit, geslot, etat, divers, codrtax, codcrit, mrgmin,
										 typart, codray, codnata, codfam, codsfam, pdsnet, pdsbrut, volume,
										 tarifstd, tarifpro, promo, pro_ddeb, pro_dfin, pro_tauxrem,
										 prmp, codbarre, datcre, cuti)
								 Select  al_row.codart, tensto, libartr, libart, libart2, unistk, uniach, univen, coeff_ach,coeff_ven,
										 kit, geslot, etat, divers, codrtax, codcrit, mrgmin,
										 typart, codray, codnata, codfam, codsfam, pdsnet, pdsbrut, volume,
										 al_row.tarifstd, al_row.tarifpro, al_row.promo, al_row.pro_ddeb, al_row.pro_dfin, 0,
										 0, al_row.codbarre, sysdate,'DB'
								  From  gcpart
								  Where codart= Substr(al_row.codart,1,length(al_row.codart)-2);
				 End if;
			 End if;
		   Else
			 Select sum(tarifec) Into n_tarif From aptarif
			  Where cdos=v_cdos and codart=al_row.codart and codtarif=v_tarif_std;

			 Text_io.put_line(out_file, al_row.codart||';Importé de DELTA');

			 -- Transférer du chapitre si inexistant
			 INSERT INTO GCPFART@XAPP_YDE (codfam, libfam)
							SELECT codcha, libchap FROM apchapitre
							 WHERE cdos=v_cdos
							   and codcha=(select codcha from apart where cdos=v_cdos and codart=al_row.codart)
							   AND not exists (SELECT * FROM GCPFART
												WHERE codfam=apchapitre.codcha);
			 -- Transfert de la rubrique si elle n'existe pas
			 INSERT INTO GCPSFART@XAPP_YDE (codfam, codsfam, libsfam)
									SELECT codchap, codrub, librub FROM aprubrique
									 WHERE cdos=v_cdos
									   AND (codchap,codrub)=(select codcha, codrub from apart where cdos=v_cdos and codart=art_row.codart)
									   AND not exists (SELECT * FROM GCPSFART
														WHERE codfam=aprubrique.codchap and codsfam=aprubrique.codrub);


			 -- Transférer l'article dans XP
			 INSERT INTO gcpart_YDE (codart, tensto, libartr, libart, libart2, unistk, uniach, univen, coeff_ach, 									coeff_ven,
										 kit, geslot, etat, divers, codrtax, codcrit, mrgmin,
										 typart, codray, codnata, codfam, codsfam, pdsnet, pdsbrut, volume,
										 tarifstd, tarifpro, promo, pro_ddeb, pro_dfin, pro_tauxrem,
										 prmp, codbarre, datcre, cuti)
								 Select  al_row.codart, tensto, NVL(libartr,'.'), libart1, libart2, unisto, uniach, unisto, 1,1,
										 'N', 'N', 'A', 'N', DECODE(codtax1,'0',v_codrtax,null), v_codcrit,0,
										 codfam, v_codray, v_codnata, codcha, codrub, poidsnet, poidsbrut, volume,
										 n_tarif, null, 'N',	null, null, 0,
										 0, refcons, nvl(datcre,sysdate),'DB'
								   from  apart
								  Where cdos=V_cdos and codart=al_row.codart;

			  -- Mettre à jour la table des codes barres
			  If SQL%Rowcount > 0 Then
			 	 Delete gcpart_barre@XAPP_YDE
				  Where codart = al_row.codart;

				 Insert into gcpart_barre@XAPP_YDE
				 Select * From gcpart
				  Where codart = al_row.codart;
			  End if;
		   End if;
	    End if;
	END LOOP;

    Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
			  values ('DB','DB',null,null,sysdate,sysdate,'Mise à jour XCAISSE YDE éffectuée avec succès.');
	COMMIT;

	UTL_FILE.FCLOSE(out_file);
EXCEPTION
  when OTHERS then
       UTL_FILE.FCLOSE(out_file);
       ROLLBACK;
END;
/
 
-- CONNECT CAISSE
CREATE PROCEDURE        PR_REVALORISER_ARTICLE_DB(v_codeta VARCHAR2, v_codart VARCHAR2, d_date DATE) IS
  CURSOR c_mvt(p_codeta VARCHAR2, p_codart VARCHAR2, p_datmvt DATE)
		IS SELECT d.idbrd, e.codeta, d.coddep, d.numlig, d.codtbrd, e.numbrd, d.unibrd, d.desbrd1, d.qtebrd, d.coeff, d.purevient, d.montrevient, e.datbrd, e.crschg, e.coeffrev, e.typven, e.etat, t.opsais, t.sens, t.type, t.transfert, dp.type_depot
		     FROM gcbrdd d, gcbrde e, gcptbrd t, gcpdep dp
		    WHERE d.typlig = '0'		-- Uniquement les lignes de type stock.
		      AND d.codart=p_codart
		      AND d.idbrd = e.idbrd
		      And d.coddep = dp.coddep
		      AND e.etat != 'A'			-- Ne pas prendre en compte les bord. annul‚s
		      AND e.datbrd >= p_datmvt
		      AND e.codtbrd=t.codtbrd
		      AND t.majstock = 'O'
		      AND e.codeta=nvl(p_codeta, e.codeta)
		   ORDER BY e.datbrd, Decode(t.sens||t.opsais,'EP',0,'SP',1,2), /*d.qtebrd*nvl(d.coeff,1) DESC, */d.codtbrd, d.idbrd, d.numlig
		   FOR UPDATE of d.montrevient, d.purevient;

  n_qte				GCPRMP.quantite%type;
  n_montant		Number; -- GCPRMP.montant%type;
  n_prmp			Number; -- GCPRMP.prmp%type;
  n_prmp_next	Number; -- GCPRMP.prmp%type;
  n_niveau		Number := 0;
  d_date_next	Date;

  n_retour		NUMBER;
  n_pubrd		Number;

  n_count		Number;
  b_regal		Boolean;
  v_regal		Varchar2(1);
  v_valc		Gcppar.valc%Type;
  d_derclot		Date;
  n_idbrd_prev	Gcbrdd.idbrd%Type;
  n_numlig_prev	Gcbrdd.numlig%Type;
  v_sens_prev	Varchar2(1);
  v_codtbrd_zsr	Varchar2(5) := 'ZSR';
  d_datdep		Date;
  n_idbrd		Number;

	FUNCTION FN_PROCHAIN_PUREV (v_codeta VARCHAR2, v_codart VARCHAR2, d_datarr DATE, v_ste_regal Varchar2, d_date_next OUT DATE) RETURN NUMBER IS
	  n_next_prmp			gcprmp.prmp%type;
	  v_date_pu				Varchar2(30);
	  d_dder_entree		DATE;
	  d_dder_sortie		DATE;
	BEGIN
	   BEGIN
		 SELECT min(to_char(e.datbrd,'yyyymmdd')||to_char(round(purevient,2))) Into v_date_pu
		   FROM gcbrdd d, gcbrde e, gcpdep dp
		  WHERE d.idbrd=e.idbrd
			AND d.codart=v_codart
			And d.typlig = '0' and e.etat != 'A'
			And d.qtebrd != 0
			AND e.datbrd > d_datarr/*
			  And (   v_codeta is null
					 or (v_codeta is not null and d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=v_codeta))
					) */
			And d.coddep = dp.coddep
			And dp.codeta=nvl(v_codeta, dp.codeta)
			  AND d.codtbrd in (SELECT codtbrd FROM gcptbrd WHERE majstock='O' and opsais='P')
			  And ( (v_ste_regal='O' and not (d.codtbrd='IN' and dp.type_depot='M'))
					or (v_ste_regal='N')
				  )
			  AND nvl(purevient,0) > 0;
			 n_next_prmp := To_number(substr(v_date_pu,9));
			 d_date_next := To_date(substr(v_date_pu,1,8),'yyyymmdd');
	   EXCEPTION
		 WHEN no_data_found THEN
					  n_next_prmp := 0;
	   END;

	   RETURN nvl(n_next_prmp,0);
	END;

	FUNCTION FN_DERNIER_PUREV (v_codeta VARCHAR2, v_codart VARCHAR2, d_datarr DATE) RETURN NUMBER IS
	  n_last_prmp			gcprmp.prmp%type;
	  n_last_prmp_e		gcprmp.prmp%type;
	  n_last_prmp_s		gcprmp.prmp%type;
	  d_dder_entree		DATE;
	  d_dder_sortie		DATE;
	  v_date_pu				Varchar2(30);
	BEGIN
	  -- PremiŠrement dans le dernier mouvement valoris‚ lors de la fin du mois.
	  BEGIN
		 --SELECT max(purevient), max(e.datbrd) INTO n_last_prmp_s, d_dder_sortie
		 SELECT max(to_char(e.datbrd,'yyyymmdd')||to_char(round(purevient,2))) Into v_date_pu
		   FROM gcbrdd d, gcbrde e
		  WHERE d.idbrd=e.idbrd
			AND d.codart=v_codart
			AND d.typlig = '0'
			AND e.datbrd <= d_datarr
			AND e.etat != 'A'
			And d.qtebrd != 0
			/*  And (   v_codeta is null
					 or (v_codeta is not null and d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=v_codeta))
					) */
			And d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=nvl(v_codeta, codeta))
			  AND d.codtbrd in (SELECT codtbrd FROM gcptbrd WHERE majstock='O' and opsais = 'Q')
			  AND nvl(purevient,0) > 0;
		  d_dder_sortie := To_date(substr(v_date_pu,1,8),'yyyymmdd');
		  n_last_prmp := To_number(substr(v_date_pu,9));
	   EXCEPTION
		  WHEN no_data_found THEN
					 n_last_prmp_s := 0;
					 n_last_prmp := 0;
	   END;

	   -- Si echec alors rechercher le dernier mouvement valoris‚ … la saisie.
	   If Nvl(n_last_prmp,0) = 0 Then
			   BEGIN
				 --SELECT max(purevient), max(e.datbrd) INTO n_last_prmp_s, d_dder_sortie
				 SELECT max(to_char(e.datbrd,'yyyymmdd')||to_char(round(purevient,2))) Into v_date_pu
				   FROM gcbrdd d, gcbrde e
				  WHERE d.idbrd=e.idbrd
					AND d.codart=v_codart and d.typlig='0'
					AND e.datbrd <= d_datarr
					AND e.etat != 'A'
					/*
					  And (   v_codeta is null
							 or (v_codeta is not null and d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=v_codeta))
							) */
					And d.coddep in (SELECT coddep FROM gcpdep WHERE codeta=nvl(v_codeta, codeta))
					  AND d.codtbrd in (SELECT codtbrd FROM gcptbrd WHERE majstock='O' and opsais='P')
					  AND nvl(purevient,0) > 0;
				  d_dder_entree := To_date(substr(v_date_pu,1,8),'yyyymmdd');
				  n_last_prmp := To_number(substr(v_date_pu,9));
			   EXCEPTION
				 WHEN no_data_found THEN
							  --n_last_prmp_e := 0;
							  n_last_prmp := 0;
							d_dder_entree := to_date('01/01/1900','dd/mm/yyyy');
			   END;
		 End if;
	   RETURN nvl(n_last_prmp,0);
	END;
BEGIN
	Select count(*) Into n_count From Gcpart Where codart=v_codart;
	If n_count = 0 Then
	   Return;
	End if;

	Select max(valc) Into v_codtbrd_zsr From Gcppar Where codpar='BORDEREAUX' and cle='ZSR';

	Select max(valc) Into v_valc From Gcppar Where codpar='BORDEREAUX' and cle='DDC';
	If v_valc is not null Then
		 Begin
		 	  d_derclot := To_date(v_valc,'dd/mm/yyyy');
		 Exception
		 		When others Then d_derclot := null;
		 End;
	End if;

	If d_derclot is not null Then
	   d_datdep := greatest(d_date,d_derclot);
	End if;

	select count(*) Into n_count From Gcpetab Where libeta like '%REGAL%';
	b_regal := (n_count > 0);
	If b_regal Then
	   v_regal := 'O';
	Else
	   v_regal := 'N';
	End if;

	-- Calculer le prix moyen pond‚r‚ … DATREC-1
	SELECT sum(decode(t.sens,'E',d.qtebrd,-d.qtebrd)*nvl(coeff,1)),
		 sum(decode(t.sens,'E', d.montrevient, -d.montrevient))
	INTO n_qte, n_montant
	FROM gcbrdd d, gcbrde e, gcptbrd t
	 WHERE d.codart=v_codart and d.typlig = '0'
	   AND d.idbrd = e.idbrd
	   --And (e.codeta = v_codeta or v_codeta is null)
	   And e.codeta = nvl(v_codeta, codeta)
	   And e.etat != 'A'
	   AND e.codtbrd = t.codtbrd and t.majstock = 'O'
	   AND e.datbrd < d_datdep; --e.datbrd < d_date;

	n_montant 	:= NVL(n_montant,0);
	n_qte 			:= NVL(n_qte, 0);

	n_niveau := n_niveau + 1;

	-- PRMP ISSUE DES MVTS A DATE-1
	n_prmp_next := Fn_prochain_purev(v_codeta, v_codart, d_datdep, v_regal, d_date_next);
	if n_qte <= 0 or n_montant = 0 or sign(n_montant) != sign(n_qte) then
		 n_prmp := FN_DERNIER_PUREV(v_codeta, v_codart, d_datdep);
		 If nvl(n_prmp,0) = 0 Then
			  n_prmp := n_prmp_next;
		 End if;
	else
		 n_prmp := Round(n_montant / n_qte,3);
	end if;
	-- MSG('OUI_INFO','(… DATE-1) montant ='||to_char(n_montant)||' , quantite ='||to_char(n_qte));

	-- D‚sactiver le trigger pendant la revalorisation
	Begin
		Insert into Gcpart_rvals (codart, dattrt) values (v_codart, sysdate);
	Exception
		When others Then null;
	End;

	n_niveau := n_niveau + 1;
	Update gcbrdd set purevient = 1, montrevient = Round(qtebrd*nvl(coeff,1))
	 Where codtbrd in (Select codtbrd from Gcptbrd Where majstock='O' and opsais='Q')
	   And typlig='0'
	   and codart = v_codart
	   And exists (Select * From Gcbrde Where idbrd = Gcbrdd.idbrd and datbrd >= d_datdep  and codeta = nvl(v_codeta, codeta)/*(codeta=v_codeta or v_codeta is null)*/);

	For i_row In (Select d.idbrd From Gcbrdd d, Gcbrde e Where d.codtbrd=v_codtbrd_zsr and d.codart=v_codart and d.idbrd=e.idbrd and e.datbrd >= d_datdep) Loop
		Delete gcbrdd where idbrd=i_row.idbrd;
		Delete gcbrde where idbrd=i_row.idbrd;
		Delete gcbrde_log where idbrd=i_row.idbrd;
	End Loop;

	-- REVALORISER TOUS LES MOUVEMENTS
	FOR mvt_row IN c_mvt(v_codeta, v_codart, d_datdep) LOOP
	  IF (mvt_row.opsais in ('P','M') and Not (b_regal and mvt_row.codtbrd = 'IN' and mvt_row.type_depot = 'M'))
	  THEN
			IF n_qte <= 0 or n_montant < 0 THEN
			  If d_date_next < mvt_row.datbrd Then
				 n_prmp_next := Fn_prochain_purev(v_codeta, v_codart, mvt_row.datbrd, v_regal, d_date_next);
			  End if;

			  -- S'il n'ya plus de PRMP next alors next_prmp = prmp du mouvement.
			  If nvl(n_prmp_next,0) = 0 and mvt_row.opsais = 'P' Then
				 n_prmp_next := mvt_row.purevient;
			  End if;
			End if;

				-- Recalculer le PRMP.
			if mvt_row.sens='E' then
			   n_montant := NVL(n_montant,0)+ NVL(mvt_row.montrevient,0);
			   n_qte     := NVL(n_qte,0)+ NVL(mvt_row.qtebrd,0)* Nvl(mvt_row.coeff,1);
			else
			   n_montant := NVL(n_montant,0)- NVL(mvt_row.montrevient,0);
			   n_qte     := NVL(n_qte,0)- NVL(mvt_row.qtebrd,0)* Nvl(mvt_row.coeff,1);
			end if;

					-- Recalculer le PRMP.
			if n_qte = 0 then 	null; -- n_prmp := 0;  ne pas annuler le prmp.
			elsif n_qte < 0 or n_montant < 0 then null;
			else	    					n_prmp := Round(n_montant / n_qte,3);
			end if;

/*
			If n_qte = 0 and n_montant != 0 and n_idbrd_prev is not null Then
			   -- Repercuter l'‚cart de montant sur le dernier mouvement qui a ‚t‚ valoris‚
--				If n_qte = 0 and n_montant != 0 and abs(n_montant) <= 200 Then
				   If v_sens_prev='E' Then		n_montant := -n_montant;
				   End if;
				   UPDATE gcbrdd set montrevient=nvl(montrevient,0)+Nvl(n_montant,0), purevient=(nvl(montrevient,0)+Nvl(n_montant,0))/qtebrd*nvl(coeff,1)
					WHERE idbrd = n_idbrd_prev and numlig = n_numlig_prev;
				   n_montant := 0;
--				End if;

			End if;
*/
			   --dbms_output.put_line(mvt_row.codtbrd||'/'||to_char(mvt_row.numbrd)||', prmp = '||to_char(round(n_prmp,2)));
			--MSG('OUI_INFO','(aprŠs une entr‚e) montant ='||to_char(n_montant)||' , quantite ='||to_char(n_qte));
		ELSIF d_derclot is not null and mvt_row.datbrd <= d_derclot THEN
		    if mvt_row.sens='E' then
		       n_montant := NVL(n_montant,0)+ NVL(mvt_row.montrevient,0);
		       n_qte     := NVL(n_qte,0)+ NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
		    else
		       n_montant := NVL(n_montant,0)- NVL(mvt_row.montrevient,0);
		       n_qte     := NVL(n_qte,0)- NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
		    end if;
		ELSE
			--MSG('OUI_INFO','Maj d''un mvt PRMP ='||to_char(n_prmp));
			-- Valoriser le mouvement.
			-- Si prmp est ‚gale … 0 conserver le montant du mouvement.
			IF (n_qte <= 0 or n_montant < 0) THEN
				 --n_prmp := n_prmp_next;
			   If d_date_next < mvt_row.datbrd Then
				  n_prmp_next := Fn_prochain_purev(v_codeta, v_codart, mvt_row.datbrd, v_regal, d_date_next);
			   End if;

			   If nvl(n_prmp_next,0) != 0 THEN
				  n_prmp := n_prmp_next;
			   End if;
			End if;

			IF nvl(n_prmp,0) != 0 THEN
			   UPDATE gcbrdd set montrevient=ROUND(qtebrd*Nvl(coeff,1)*n_prmp), purevient=n_prmp
				WHERE current of c_mvt;
			   n_idbrd_prev := mvt_row.idbrd;
			   n_numlig_prev := mvt_row.numlig;
			   v_sens_prev := mvt_row.sens;

				 IF mvt_row.typven is null and mvt_row.type != 'VEN' and mvt_row.type != 'CVT' THEN
						-- 2016-04-15, Tenir compte du coeffrev et du cours de change
						If nvl(mvt_row.coeffrev,1)*nvl(mvt_row.crschg,1) != 0  Then
							 n_pubrd := (n_prmp*nvl(mvt_row.coeff,1)) / (nvl(mvt_row.coeffrev,1)*nvl(mvt_row.crschg,1));
						Else
							 n_pubrd := (n_prmp*nvl(mvt_row.coeff,1));
						End if;
							UPDATE gcbrdd set pubrd=n_pubrd, montbrd=ROUND(qtebrd*Nvl(coeff,1)*n_prmp)
					   WHERE current of c_mvt;
				 END IF;

						-- Mettre … jour les montants et les quantites.
				if mvt_row.sens='E' then
				   n_montant := NVL(n_montant,0)+ NVL(ROUND(mvt_row.qtebrd*Nvl(mvt_row.coeff,1)*n_prmp,0),0);
				   n_qte     := NVL(n_qte,0)+ NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				else
				   n_montant := NVL(n_montant,0)- NVL(ROUND(mvt_row.qtebrd*Nvl(mvt_row.coeff,1)*n_prmp,0),0);
				   n_qte     := NVL(n_qte,0)- NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				end if;

				-- Gestion des arrondis si < 200 on sort toute la valeur lorsque le stock est ‚gal … z‚ro.
				If n_qte = 0 and n_montant != 0 and abs(n_montant) <= 200 and mvt_row.transfert='N' Then
				   If mvt_row.sens='E' Then		n_montant := -n_montant;
				   End if;
				   UPDATE gcbrdd set montrevient=nvl(montrevient,0)+Nvl(n_montant,0)
					WHERE current of c_mvt;
				   n_montant := 0;
				End if;
			  ELSE
				if mvt_row.sens='E' then
				   n_montant := NVL(n_montant,0)+ NVL(mvt_row.montrevient,0);
				   n_qte     := NVL(n_qte,0)+ NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				else
				   n_montant := NVL(n_montant,0)- NVL(mvt_row.montrevient,0);
				   n_qte     := NVL(n_qte,0)- NVL(mvt_row.qtebrd,0)*Nvl(mvt_row.coeff,1);
				end if;
			END IF;
			/* Pas de recalcul du prmp s'il s'agit d'un mvt … valoriser.
				-- MAJ le PRMP (surtout pour le cas ou la w_qte serait … z‚ro).
				if n_qte = 0 then 	null; -- ne pas annuler le prmp n_prmp := 0;
				else	    					n_prmp := n_montant / n_qte;
				end if;
			*/
		END IF;


		If n_qte = 0 and n_montant != 0 and v_codtbrd_zsr is not null Then
		   Select seq_gc_idbrd.nextval into n_idbrd From dual;
		   Insert into gcbrde (idbrd, codtbrd, codeta, coddep, numbrd, datbrd, comm, etat, cuti, datcre)
						values(n_idbrd, v_codtbrd_zsr, mvt_row.codeta, mvt_row.coddep, mvt_row.numbrd, mvt_row.datbrd, 'ZERO STOCK VALUE RECTIFICATION','C','AUTO',sysdate);
		   Insert into gcbrdd (idbrd, codtbrd, numlig, numord, coddep, codart, desbrd1, qtebrd, unibrd, pubrd, montbrd
							  ,tauxrem, typlig, coeff, ligne_solde, purevient, montrevient)
						values(n_idbrd, v_codtbrd_zsr, 1, 1, mvt_row.coddep, v_codart, mvt_row.desbrd1, 0, mvt_row.unibrd, n_montant, n_montant
							  ,0, '0', 1, 'N', n_montant, n_montant);
		   n_montant := 0;
		End if;
	END LOOP;

	  Update Gcprmp p set quantite = (select sum(qtestock) from Gcstock
									where codart=p.codart
										and coddep in (select coddep from Gcpdep where codeta=p.codeta))
	   Where codart=v_codart
	     And periode='999912';

	  Insert into Gcprmp (codart, codeta, periode, quantite)
							 Select v_codart, codeta, '999912', sum(qtestock) From Gcstock s, Gcpdep d
							  Where s.codart = v_codart
								And s.coddep = d.coddep
								And not exists (Select * From Gcprmp Where codart=v_codart and codeta=d.codeta and periode='999912')
							 Group by codeta;


	UPDATE GCPRMP SET prmp = n_prmp, montant = Round(quantite*n_prmp)
	 WHERE (codeta = v_codeta or v_codeta is null)
	   AND codart = v_codart
	   AND periode = '999912';


	Delete Gcpart_rvals Where codart = v_codart;
END;
/
 
-- CONNECT XCPTA
CREATE PROCEDURE
       connect_compta(i_type_user IN VARCHAR2, i_user VARCHAR2) as
--=========================================================--
-- Attribution des grants sur les tables environnement
-- par USER
---------------------------------------------------------------------
-- Entrees : i_type_user      Type utilisateur :
-- 						  1 User application
-- 						  2 DELTA ADMINISTRATEUR
--           i_user           code user
---------------------------------------------------------------------

  cursor_name INTEGER;
  ret         INTEGER;


  w_string	         VARCHAR2(100);

BEGIN


  -- ouverture du curseur.
  cursor_name := DBMS_SQL.OPEN_CURSOR;

  -- Debut attribution des grants sur les tables

  IF i_type_user = '1' THEN
     w_string := 'GRANT ROLE_compta_USE TO '||i_user;
     dbms_sql.parse(cursor_name,w_string,dbms_sql.v7);
     ret := dbms_sql.execute(cursor_name);
  ELSE
     w_string := 'GRANT ROLE_compta_ADM TO '||i_user;
     dbms_sql.parse(cursor_name,w_string,dbms_sql.v7);
     ret := dbms_sql.execute(cursor_name);
  END IF;


  dbms_sql.close_cursor(cursor_name);

END connect_compta;

/
 
CREATE PROCEDURE
       disconnect_compta(i_type_user IN VARCHAR2, i_user VARCHAR2) as
--=========================================================--
-- Revokation des grants sur les tables environnement
-- par USER
---------------------------------------------------------------------
-- Entrees : i_type_user      Type utilisateur :
-- 						  1 User application
-- 						  2 DELTA ADMINISTRATEUR
--           i_user           code user
---------------------------------------------------------------------

  cursor_name INTEGER;
  ret         INTEGER;

  w_string	     VARCHAR2(100);
  w_count        INTEGER;
BEGIN


  -- MM 23-07-2003 controle de sortie ... si plusieurs session pour le meme user pas de revoke.
  SELECT count(*) INTO w_count
    FROM v$session
   WHERE username = i_user;

  IF w_count = 0 THEN

  	-- ouverture du curseur.
  	cursor_name := DBMS_SQL.OPEN_CURSOR;

  	-- Debut attribution des grants sur les tables
  	IF i_type_user = '1' THEN
     	   w_string := 'REVOKE ROLE_compta_USE FROM '||i_user;
         dbms_sql.parse(cursor_name,w_string,dbms_sql.v7);
         ret := dbms_sql.execute(cursor_name);
      ELSE
         w_string := 'REVOKE ROLE_compta_ADM FROM '||i_user;
         dbms_sql.parse(cursor_name,w_string,dbms_sql.v7);
         ret := dbms_sql.execute(cursor_name);
      END IF;

      dbms_sql.close_cursor(cursor_name);

  END IF;

END disconnect_compta;

/
 
-- new object type path: DATABASE_EXPORT/SCHEMA/PROCEDURE/GRANT/OWNER_GRANT/OBJECT_GRANT
GRANT EXECUTE ON "XCPTA"."DISCONNECT_COMPTA" TO "KERNEL";
 
