-- new object type path: DATABASE_EXPORT/SCHEMA/VIEW/VIEW
-- CONNECT CAISSE
CREATE FORCE VIEW "CAISSE"."GCVREL_TIE" ("CODETA", "DATPCE", "NUMPCE", "TYPE", "TYPPCE", "DATECH", "CODTIE", "NOMTIE", "MT_CREDIT", "MT_DEBIT") AS 
  SELECT  e.CODETA, e.DATFAC Datpce, e.NUMFAC Numpce, 'F' Type, e.CODTBRD Typpce, e.DATECH,
        e.CODTIE, e.NOMTIE,
        0 Mt_credit, SUM(e.MTTC) Mt_debit
FROM GCBRDE e
WHERE e.NUMFAC IS NOT NULL and e.ETAT != 'A'
GROUP BY e.CODETA, e.DATFAC, e.NUMFAC, e.CODTBRD, e.DATECH,
        e.CODTIE, e.NOMTIE
UNION
SELECT  e.CODETA, e.DATRGL, e.NUMRGL, 'R', e.CODTRGL Typpce, e.DATRGL,
        e.CODTIE, null,
        Mtrgl Mt_credit, 0
FROM GCRGLE e
WHERE e.ETAT != 'A'
;
 
CREATE FORCE VIEW "CAISSE"."GCVMVT" ("IDBRD", "NUM_PTVTE", "CODETA", "CODTBRD", "TYPVEN", "DATBRD", "NUMBRD", "NUMDOC", "COMM", "CODTIE", "NOMTIE", "STATDES", "DEPDES", "CUTI", "DATCRE", "CODART", "NUMLIG", "NUMORD", "CODDEP", "CODSTAT", "PUBRD", "CODDEV", "MONTBRD", "QTEBRD", "QTETRANS", "QTEVALID", "LIGNE_SOLDE", "UNIBRD", "COEFF", "TYPLIG", "PUVEN", "TAUXREM", "PUREVIENT", "MONTREVIENT", "PROMO", "DLV", "SENS", "TYPE", "MAJRESERV", "MAJPRET", "MAJCDE", "MAJSTATUT", "TRANSFERT", "MAJSTOCK", "OPSAIS") AS 
  SELECT a.IDBRD, a.NUM_PTVTE, a.CODETA, a.CODTBRD, a.TYPVEN, a.DATBRD, a.NUMBRD, a.NUMDOC, a.COMM, 
	 a.CODTIE, a.NOMTIE, b.STATDES, a.DEPDES, a.CUTI, a.DATCRE,
	 b.CODART, b.NUMLIG, b.NUMORD, Nvl(b.CODDEP, a.CODDEP) CODDEP, b.CODSTAT, b.PUBRD, a.CODDEV, b.MONTBRD, b.QTEBRD, b.QTETRANS, b.QTEVALID, b.LIGNE_SOLDE, b.UNIBRD, b.COEFF, b.TYPLIG,
	 b.PUVEN, b.TAUXREM, b.PUREVIENT, b.MONTREVIENT, b.promo, b.dlv,
	 c.SENS, c.TYPE, c.MAJRESERV, c.MAJPRET, c.MAJCDE, c.MAJSTATUT, c.TRANSFERT, c.MAJSTOCK, c.OPSAIS
  FROM GCBRDE a, GCBRDD b, GCPTBRD c
 WHERE a.CODTBRD = c.CODTBRD
   AND a.IDBRD = b.IDBRD
   AND b.typlig = '0'
   AND a.etat != 'A';
 
CREATE FORCE VIEW "CAISSE"."GCVBRD" ("IDBRD", "CODETA", "NUM_PTVTE", "CODTBRD", "TYPE", "DATBRD", "NUMBRD", "NUMDOC", "DATDOC", "COMM", "CODTIE", "NOMTIE", "ADRTIE1", "ADRTIE2", "ADRTIE3", "CODDEV", "CRSCHG", "NUMFAC", "DATFAC", "TAUXREM", "DATECH", "CODMRGL", "ETAT", "CUTI", "MUTI", "DATCRE", "DATMOD", "CODRTAX", "MHT", "MTAX1", "MTAX2", "MTAX3", "MTAX4", "MTTC", "TYPVEN", "NUMBRD_RET", "IDBRD_SCE", "OPTION_SCE", "MONTREV", "QTE", "MHT_TAXABLE") AS 
  SELECT 	a.IDBRD, a.CODETA, a.NUM_PTVTE, a.CODTBRD, c.TYPE, a.DATBRD, a.NUMBRD, a.NUMDOC, a.DATDOC, a.COMM,
        a.CODTIE, a.NOMTIE, a.ADRTIE1, a.ADRTIE2, a.ADRTIE3, a.CODDEV, a.CRSCHG, a.NUMFAC, a.DATFAC,
	a.TAUXREM, a.DATECH, a.CODMRGL, a.ETAT, a.CUTI, a.MUTI, a.DATCRE, a.DATMOD, a.CODRTAX,
	a.MHT, a.MTAX1, a.MTAX2, a.MTAX3, a.MTAX4, a.MTTC, a.TYPVEN, a.NUMBRD_RET, a.IDBRD_SCE, a.OPTION_SCE,
	SUM(d.montrevient) MONTREV,
	SUM(d.qtebrd*NVL(d.coeff,1)) QTE,	
	SUM(decode(d.exonere,'N',d.montht,0)) MHT_TAXABLE
  FROM GCBRDE a, GCBRDD d, GCPTBRD c
 WHERE a.IDBRD = d.IDBRD
   AND a.CODTBRD = c.CODTBRD
   AND d.TYPLIG in ('0','1','2')
GROUP BY a.IDBRD, a.CODETA, a.NUM_PTVTE, a.CODTBRD, c.TYPE, a.DATBRD, a.NUMBRD, a.NUMDOC, a.DATDOC, a.COMM,
        a.CODTIE, a.NOMTIE, a.ADRTIE1, a.ADRTIE2, a.ADRTIE3, a.CODDEV, a.CRSCHG, a.NUMFAC, a.DATFAC,
	a.TAUXREM, a.DATECH, a.CODMRGL, a.ETAT, a.CUTI, a.MUTI, a.DATCRE, a.DATMOD, a.CODRTAX,
	a.MHT, a.MTAX1, a.MTAX2, a.MTAX3, a.MTAX4, a.MTTC, a.TYPVEN, a.NUMBRD_RET, a.IDBRD_SCE, a.OPTION_SCE;
 
