CREATE FORCE VIEW "CAISSE"."GCVSTOCK_LOT" ("CODART", "CODDEP", "NUMLOT", "DATE_EXPIR", "DATE_FABR", "QTEIN", "QTEOUT") AS 
  Select d.codart, d.coddep, l.numlot, al.date_expir, al.date_fabr, Sum(Decode(tb.sens,'E', d.qtebrd*nvl(d.coeff,1))) qtein, Sum(Decode(tb.sens,'S', d.qtebrd)*nvl(d.coeff,1)) qteout
  From Gcbrdd d, Gcpart a, Gcbrdd_lot l, Gcpart_lot al, Gcptbrd tb
 Where d.codart = a.codart
   And d.typlig = '0'
   And a.geslot = 'O'
   And tb.majstock = 'O'
   And d.idbrd = l.idbrd(+) and d.numlig = l.numlig (+)
   And d.codtbrd = tb.codtbrd
   And l.numlot = al.numlot and al.codart = d.codart
Group by d.codart, d.coddep, l.numlot, al.date_expir, al.date_fabr;
 
CREATE FORCE VIEW "CAISSE"."TARIF_STAND" ("CODART", "UNITE", "COEFF", "CODTARIF", "MIN_PUVEN", "MAX_PUVEN") AS 
  Select d.codart, d.unite, d.coeff, c.codtarif, min(d.puven) min_puven, max(d.puven) max_puven
From Ceticketd d, Cepcaisse c
Where d.codcai = c.codcai
And c.codtarif is not null
And not exists (Select * From Gcptarif_art Where codart=d.codart and codtarif=c.codtarif)
group by codart, d.unite, d.coeff, c.codtarif
order by 1,2;
 
CREATE FORCE VIEW "CAISSE"."CEVBON_LOT" ("NUMLOT", "DATE_EMISSION", "TYPBON", "CODCLI_BENEF", "NOMCLI", "CODUTI_CREAT", "NBRE_EMIS", "VALEUR_BON_EMIS", "NBRE_ENCAI", "VALEUR_BON_ENCAI") AS 
  Select numlot, Trunc(b.date_emission,'dd') date_emission, typbon, codcli_benef, nomcli, coduti_creat, count(*) nbre_emis, sum(valeur_bon) valeur_bon_emis
	   ,sum(decode(code_encai,'O',1)) nbre_encai, sum(decode(code_encai,'O',valeur_bon)) valeur_bon_encai
  From CAISSE.CEBON b
 Where code_etat != 'A'
Group by numlot, Trunc(b.date_emission,'dd'), typbon, codcli_benef, nomcli, coduti_creat;
 
