-- CONNECT XCPTA
CREATE FORCE VIEW "XCPTA"."VCP_ECR_LET_CC" ("CDOS", "CODETS", "NUMSAI", "NUMLIG", "NUMSLG", "NUMCPT", "NUMTIE", "CODLET", "DATLET", "REFLET", "NUMLET", "DATCPT", "DATCPT2", "DATECH", "CODABR", "DOS_MTDB", "DOS_MTCR", "GRP_MTDB", "GRP_MTCR", "CPT_MTDB", "CPT_MTCR", "DOS_MTDB_LET", "DOS_MTCR_LET", "GRP_MTDB_LET", "GRP_MTCR_LET", "CPT_MTDB_LET", "CPT_MTCR_LET") AS 
  select a.cdos,a.codets,a.numsai,a.numlig,a.numslg,a.numcpt,a.numtie,a.codlet,a.datlet,a.reflet,
a.numlet,a.datcpt,a.datcpt2,a.datech,b.codabr,
sum(nvl(a.dos_mtdb,0)) dos_mtdb,
sum(nvl(a.dos_mtcr,0)) dos_mtcr,
sum(nvl(a.grp_mtdb,0)) grp_mtdb,
sum(nvl(a.grp_mtcr,0)) grp_mtcr,
sum(nvl(a.cpt_mtdb,0)) cpt_mtdb,
sum(nvl(a.cpt_mtcr,0)) cpt_mtcr,
decode(codlet,null,0,sum(nvl(a.dos_mtdb,0))) dos_mtdb_let,
decode(codlet,null,0,sum(nvl(a.dos_mtcr,0))) dos_mtcr_let,
decode(codlet,null,0,sum(nvl(a.grp_mtdb,0))) grp_mtdb_let,
decode(codlet,null,0,sum(nvl(a.grp_mtcr,0))) grp_mtcr_let,
decode(codlet,null,0,sum(nvl(a.cpt_mtdb,0))) cpt_mtdb_let,
decode(codlet,null,0,sum(nvl(a.cpt_mtcr,0))) cpt_mtcr_let
from cp_ecr_let a, cp_ecr_gen b
where a.cdos='01'
and substr(a.numcpt,1,4) between '4111' and '4116'
and a.numtie is not null
and a.cdos = b.cdos
and a.codets = b.codets
and a.numsai = b.numsai
and a.numlig = b.numlig
/*
and ( (b.codabr in (select codabr from cp_abr where cdos=a.cdos and typsuivi != 'AUT'))
      or b.codabr is null )
*/
group by a.cdos,a.codets,a.numsai,a.numlig,a.numslg,a.numcpt,a.numtie,a.codlet,a.datlet,a.reflet,
a.numlet,a.datcpt,a.datcpt2,a.datech,b.codabr;
 
-- CONNECT KERNEL
