-- new object type path: DATABASE_EXPORT/SCHEMA/PACKAGE_BODIES/PACKAGE/PACKAGE_BODY
-- CONNECT KERNEL
CREATE PACKAGE BODY        PA_COMPTA
AS


--------------------------------------------------------------------------------
FUNCTION Format_Mt (mt IN NUMBER,      ndc IN NUMBER,
                   long_ret IN NUMBER, Avec_Zero IN BOOLEAN) RETURN VARCHAR2
IS

  mtf1     CHAR(20);
  c20      VARCHAR2(20);

BEGIN
  IF Avec_Zero THEN
     IF ndc = 3 THEN
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G990D999')),20,' ');
     ELSIF ndc = 2 THEN
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'9G999G999G999G990D99')),20,' ');
     ELSIF ndc = 1 THEN
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'99G999G999G999G990D9')),20,' ');
     ELSE
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G999G990')),20,' ');
     END IF;
  ELSE
     IF NOT NouZ(mt) THEN
       IF ndc = 3 THEN
          mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G999D999')),20,' ');
       ELSIF ndc = 2 THEN
          mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'9G999G999G999G999D99')),20,' ');
       ELSIF ndc = 1 THEN
         mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'99G999G999G999G999D9')),20,' ');
       ELSE
         mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G999G999')),20,' ');
       END IF;
     ELSE
       mtf1 := LPAD(' ',20,' ');
     END IF;
  END IF;
  c20  := ' ';
  c20 := SUBSTR(mtf1,20-long_ret+1);
  RETURN c20;

END Format_Mt;

---------------------------------------------------------------------
FUNCTION NouB(l_champ VARCHAR2) RETURN BOOLEAN
IS
BEGIN
   IF l_champ IS NULL THEN
      RETURN TRUE;
   ELSIF LTRIM(RTRIM(l_champ)) IS NULL OR LTRIM(RTRIM(l_champ)) = ''  THEN
      RETURN TRUE;
   ELSE
      RETURN FALSE;
   END IF;
END NouB;

---------------------------------------------------------------------
FUNCTION NouZ(l_champ NUMBER) RETURN BOOLEAN
IS
BEGIN
   IF l_champ IS NULL THEN
      RETURN TRUE;
   ELSIF l_champ = 0 THEN
      RETURN TRUE;
   ELSE
      RETURN FALSE;
   END IF;
END NouZ;

----------------------------------------------------------------------------
END PA_COMPTA;

-----------------------------------------------------------------------------
/

ALTER PACKAGE "KERNEL"."PA_COMPTA" 
  COMPILE BODY 
    PLSQL_OPTIMIZE_LEVEL=  2
    PLSQL_CODE_TYPE=  INTERPRETED
    PLSQL_DEBUG=  FALSE
    PLSCOPE_SETTINGS=  'IDENTIFIERS:NONE'
 REUSE SETTINGS TIMESTAMP '2019-08-11 10:27:01'
/
 
CREATE PACKAGE BODY
PR_IMPORTER_DELTA_XCAISSE AS

FUNCTION FN_GET_CEPARAMC(v_codpar VARCHAR2, v_cle VARCHAR2) RETURN VARCHAR2 IS
   w_valc			CEPPAR.VALC%TYPE;
BEGIN
   SELECT valc INTO w_valc FROM CEPPAR
	WHERE codpar=v_codpar and cle=v_cle;
   RETURN (w_valc);
EXCEPTION
	 WHEN NO_DATA_FOUND THEN
	   RETURN (null);
END;

PROCEDURE PR_IMPORTER_NOMEN_ART IS
BEGIN
	-- Chapitre/Rubrique dans Famille et S/Famille
	INSERT INTO GCPFART (codfam, libfam)
				SELECT codcha, libchap FROM apchapitre
				 WHERE cdos=v_cdos
				   AND not exists (SELECT * FROM GCPFART
									WHERE codfam=apchapitre.codcha);

	INSERT INTO GCPSFART (codfam, codsfam, libsfam)
				SELECT codchap, codrub, librub FROM aprubrique
				 WHERE cdos=v_cdos
				   AND not exists (SELECT * FROM GCPSFART
									WHERE codfam=aprubrique.codchap and codsfam=aprubrique.codrub);
	-- Famille d'article dans type article
	DELETE GCPPAR
	WHERE codpar = 'TYPEART' and cle != '*';
	INSERT INTO GCPPAR (codpar, cle, libpar)
						SELECT 'TYPEART', codfam, libfam FROM apfam
						 WHERE cdos=v_cdos;

	-- Créer les unités à partir de APUNITE et de APCDT
	DELETE GCPPAR
	WHERE codpar = 'UNITES' and cle != '*';
	INSERT INTO GCPPAR (codpar, cle, libpar, valt, valn)
						SELECT 'UNITES', unite, libunite, nbdec, nbdec FROM apunite
						 WHERE cdos=v_cdos;
	INSERT INTO GCPPAR (codpar, cle, libpar, valt, valn)
						SELECT 'UNITES', codcdt, libcdt, 0, 0 FROM apcdt
						 WHERE cdos=v_cdos
						   AND codcdt not in (SELECT cle FROM GCPPAR WHERE codpar = 'UNITES' and cle != '*');
END;

PROCEDURE PR_ALIGNER_FICHIER_ARTICLE IS
  v_dlv					GCPPAR.valc%TYPE;
BEGIN
  -- Désactiver les articles non existants dans la table APART.
  -- Sauf bien sûr les DLV.
  DELETE GCPART_BARRE a
   WHERE not exists (SELECT * FROM apart
   					  WHERE cdos=v_cdos and codart=a.codart);

  SELECT max(valc) INTO v_dlv FROM GCPPAR
   WHERE codpar='PARGEN' and cle='DLV';
	IF v_dlv = 'O' THEN
	   -- Ne pas désactiver les DLV
	   UPDATE GCPART a SET codbarre=null, etat='I', datmod=sysdate, muti='IMP'
	    WHERE not exists (SELECT * FROM apart
	   					   WHERE cdos=v_cdos and codart=a.codart)
	   	  AND (codart not like '%*1' and codart not like '%*2' and codart not like '%*3');
	ELSE
	   UPDATE GCPART a SET codbarre=null, etat='I', datmod=SYSDATE, muti='IMP'
	    WHERE not exists (SELECT * FROM apart
	   					   WHERE cdos=v_cdos and codart=a.codart);
	END IF;
END;


PROCEDURE PR_IMPORTER_ARTICLE(v_codart Varchar2, v_apble Varchar2, v_coduti VARCHAR2) IS
	v_maj_tarif		VARCHAR2(1);
BEGIN
	If v_tarif_spe is not null Then
	   SELECT SUM(tarifec) INTO n_tarifspe FROM aptarif
		WHERE cdos=v_cdos
		 AND codart = v_codart and codtarif=v_tarif_spe;
	   n_tarifspe := NVL(n_tarifspe,0);
	Else
	   n_tarifspe := 0;
	End if;

	If nvl(n_tarifspe,0)=0 Then
	   SELECT SUM(tarifec) INTO n_tarifstd FROM aptarif
		WHERE cdos=v_cdos
	      AND codart = v_codart and codtarif=v_tarif_std;
	   n_tarifstd := NVL(n_tarifstd,0);
	Else
	   n_tarifstd := n_tarifspe;
	End if;

	SELECT SUM(tarifec) INTO n_tarifpro FROM aptarif
	 WHERE cdos=v_cdos
	   AND codart = v_codart and codtarif=v_tarif_pro;
	n_tarifpro := NVL(n_tarifpro,0);

	SELECT count(*) INTO n_test FROM GCPART
	 WHERE codart=v_codart;
  	IF n_test = 0 THEN
	   -- Insertion dans la table des ARTICLES
  	   INSERT INTO GCPART (codart, tensto, libartr, libart, libart2, unistk, uniach, univen, coeff_ach, coeff_ven,
						 kit, geslot, etat, divers, codrtax, codcrit, mrgmin,
						 typart, codray, codnata, codfam, codsfam, pdsnet, pdsbrut, volume,
						 tarifstd, tarifpro, promo, pro_ddeb, pro_dfin, pro_tauxrem,
						 prmp, codbarre, datcre, cuti)
				VALUES  (v_codart, c1_row.tensto, NVL(c1_row.libartr,'.'), c1_row.libart1, c1_row.libart2, c1_row.unisto, c1_row.uniach, c1_row.unisto, 1,1,
						'N', 'N', 'A', 'N', DECODE(c1_row.codtax1,'0',v_codrtax,null), v_codcrit,0,
						c1_row.codfam, v_codray, v_codnata, c1_row.codcha, c1_row.codrub, c1_row.poidsnet, c1_row.poidsbrut, c1_row.volume,
						n_tarifstd, n_tarifpro, DECODE(n_tarifpro,0,'N','O'),	d_pro_ddeb, d_pro_dfin, 0,
						0, c1_row.refcons, nvl(c1_row.datcre,sysdate),v_coduti);

  	   INSERT INTO GCPART_BARRE (codart, codbarre, desbarre, nbunite)
					     SELECT codart, codbarre,'EQUIVALENT', nbunite FROM apart_barre
						  WHERE codart=v_codart
						    AND cdos=v_cdos;
  	ELSE
	  IF v_tarif_delta = 'O' or v_apble = 'O' THEN
		  v_maj_tarif := 'O';
	  ELSE
		  v_maj_tarif := 'N';
	  END IF;

  	  If v_maj_tarif = 'O' Then
		  SELECT max(numord) INTO n_numord FROM GCPHTARIF_ART
		   WHERE codart = v_codart
			 AND codtarif = '0';

		  n_numord := NVL(n_numord,0)+1;
			INSERT INTO GCPHTARIF_ART (codart, codtarif, numord, datchg, anctarif, nouvtarif, motif)
												  Select codart, '0', n_numord, SYSDATE, tarifstd, n_tarifstd, 'Importation DELTA'
													From Gcpart
												   Where codart = v_codart
													 And tarifstd != n_tarifstd;
	  End if;

	  UPDATE GCPART SET libartr		=	NVL(c1_row.libartr,'.'),
										 libart			= c1_row.libart1,
										 libart2		= c1_row.libart2,
										 tensto			= c1_row.tensto,
										 unistk			= c1_row.unisto,
										 uniach			= c1_row.uniach,
										 univen			= c1_row.unisto,
										 typart			= c1_row.codfam,
										 codfam			= c1_row.codcha,
										 codsfam		= c1_row.codrub,
										 pdsnet			= c1_row.poidsnet,
										 pdsbrut		= c1_row.poidsbrut,
										 volume			= c1_row.volume,
										 tarifstd		= DECODE(v_maj_tarif,'O',n_tarifstd, decode(nvl(tarifstd,0),0,n_tarifstd,tarifstd)),
										 tarifpro		= DECODE(v_tarif_delta,'O',n_tarifpro, decode(nvl(tarifpro,0),0,n_tarifpro,tarifpro)),
										 promo			= DECODE(v_tarif_delta,'O',DECODE(n_tarifpro,0,'N','O'), promo),
										 pro_ddeb		= DECODE(v_tarif_delta,'O',d_pro_ddeb, pro_ddeb),
										 pro_dfin		= DECODE(v_tarif_delta,'O',d_pro_dfin, pro_dfin),
										 prmp			= 0,
										 codbarre		= DECODE(v_cb_delta,'O',c1_row.refcons,codbarre),
										 etat			= 'A',
										 datmod			= DECODE(v_maj_tarif,'O',sysdate,datmod),
										 muti			 = DECODE(v_maj_tarif,'O',v_coduti,muti)
	   WHERE codart = v_codart;

	  -- Désactiver la promo si la mise à jour s'éffectue à partir des arrivages
	  IF v_apble = 'O' THEN
		 UPDATE GCPART set promo='N', datmod=sysdate, muti=v_coduti
		  WHERE codart = v_codart;
	  END IF;

  	  -- Doit-on prendre les codes barres dans DELTA
	  n_niveau := 10;
  	  IF v_cb_delta = 'O' THEN
  	  	 -- Suppression des anciens code barres secondaire.
  	  	 DELETE GCPART_BARRE
  	  	  WHERE codart = v_codart;

  	  	 -- Insertion des nouveaux codes barre.
		 n_niveau := 11;
 	  	 INSERT INTO GCPART_BARRE (codart, codbarre, desbarre, nbunite)
  	  	 			   		SELECT codart, codbarre,'EQUIVALENT', nbunite FROM apart_barre
  	  	 		    		 WHERE codart=v_codart;
  	  END IF;

  	END IF;
END;

PROCEDURE PR_IMPORTER IS
	CURSOR c1 IS SELECT codart, libartr, libart1, libart2, libart3, tensto, refcons, codcha, codrub, codfam, codtyp, unisto, uniach
					  ,codcdt, nbunit, codtax1, codtax2, codtax3, codtax4, poidsnet, poidsbrut, volume, datcre
				   FROM apart
				  WHERE cdos=v_cdos and (v_tensto='O' or tensto='O')
					AND (datcre >= sysdate-10 or datmod >= sysdate-10)
				ORDER BY codart;
	c1_row		C1%Rowtype;
	n_art		NUMBER(8);
	n_niveau 	NUMBER(2);
BEGIN
	-- Nombre total des articles.
	SELECT count(*) INTO n_art FROM apart
	 WHERE cdos=v_cdos and (v_tensto='O' or tensto='O')
  	   AND (datcre >= sysdate-10 or datmod >= sysdate-10);

	IF n_art = 0 THEN
      Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
			     values ('DB','DB',null,null,sysdate,sysdate,'Aucune mise à jour en instance.');
	  Return;
	END IF;

    FOR c1_row IN c1 LOOP
  		n_niveau := 0;

  	    Pr_importer_article(c1_row.codart,'N','DB');

	    -- Sauvegarde par paquet de 1000
	    IF mod(n_evolution,1000) = 0 THEN
		   Standard.commit;
	    END IF;
    END LOOP;

	COMMIT;
EXCEPTION
	WHEN others THEN
         Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
			        values ('DB','DB',null,null,sysdate,sysdate,'Erreur lors de la mise à jour.');
         Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
			        values ('DB','DB',null,null,sysdate,sysdate,'SQL code = '||sqlcode||', '||sqlerrm||'.');
		 Rollback;
END;

-------------------------------------------------------------------------------
-- INITIALISATION DU PACKAGE LORS DU 1ER APPEL
-------------------------------------------------------------------------------
BEGIN
	-- Obtention des paramètres DELTA
	v_cdos 			:= FN_GET_CEPARAMC('DELTA','001');
	v_tarif_spe		:= FN_GET_CEPARAMC('DELTA','T02');
	v_tarif_std 	:= FN_GET_CEPARAMC('DELTA','002');
	v_tarif_pro 	:= FN_GET_CEPARAMC('DELTA','003');
	d_pro_ddeb	 	:= TO_DATE(FN_GET_CEPARAMC('DELTA','004'),'dd/mm/yyyy');
	d_pro_dfin		:= TO_DATE(FN_GET_CEPARAMC('DELTA','005'),'dd/mm/yyyy');
	v_typart		:= FN_GET_CEPARAMC('DELTA','A01');
	v_codfam		:= FN_GET_CEPARAMC('DELTA','A02');
	v_codsfam		:= FN_GET_CEPARAMC('DELTA','A03');
	v_codrtax		:= FN_GET_CEPARAMC('DELTA','A04');
	v_codcrit		:= FN_GET_CEPARAMC('DELTA','A05');
	v_codray		:= FN_GET_CEPARAMC('DELTA','A06');
	v_codnata		:= FN_GET_CEPARAMC('DELTA','A07');
	v_tensto		:= FN_GET_CEPARAMC('DELTA','A08');
	v_lst_cha		:= FN_GET_CEPARAMC('DELTA','A09');
	v_cb_delta		:= FN_GET_CEPARAMC('DELTA','015');
	v_tarif_delta	:= FN_GET_CEPARAMC('DELTA','016');

	IF v_cdos IS NULL or v_tarif_std IS NULL or v_codnata IS NULL THEN
	   Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
				  values ('DB','DB',null,null,sysdate,sysdate,'Problème lors de la récupération des paramètres d''importation.');
	   RETURN;
	END IF;
END PR_IMPORTER_DELTA_XCAISSE;
/

