-- CONNECT CAISSE
CREATE PACKAGE BODY
PR_IMPORTER_DELTA_XCAISSE AS

FUNCTION FN_GET_CEPARAMC(v_codpar VARCHAR2, v_cle VARCHAR2) RETURN VARCHAR2 IS
   w_valc			CEPPAR.VALC%TYPE;
BEGIN
   SELECT valc INTO w_valc FROM CEPPAR
	WHERE codpar=v_codpar and cle=v_cle;
   RETURN (w_valc);
EXCEPTION
	 WHEN NO_DATA_FOUND THEN
	   RETURN (null);
END;

PROCEDURE PR_IMPORTER_NOMEN_ART IS
BEGIN
	-- Chapitre/Rubrique dans Famille et S/Famille
	INSERT INTO GCPFART (codfam, libfam)
				SELECT codcha, libchap FROM apchapitre
				 WHERE cdos=v_cdos
				   AND not exists (SELECT * FROM GCPFART
									WHERE codfam=apchapitre.codcha);

	INSERT INTO GCPSFART (codfam, codsfam, libsfam)
				SELECT codchap, codrub, librub FROM aprubrique
				 WHERE cdos=v_cdos
				   AND not exists (SELECT * FROM GCPSFART
									WHERE codfam=aprubrique.codchap and codsfam=aprubrique.codrub);
	-- Famille d'article dans type article
	DELETE GCPPAR
	WHERE codpar = 'TYPEART' and cle != '*';
	INSERT INTO GCPPAR (codpar, cle, libpar)
						SELECT 'TYPEART', codfam, libfam FROM apfam
						 WHERE cdos=v_cdos;

	-- Créer les unités à partir de APUNITE et de APCDT
	DELETE GCPPAR
	WHERE codpar = 'UNITES' and cle != '*';
	INSERT INTO GCPPAR (codpar, cle, libpar, valt, valn)
						SELECT 'UNITES', unite, libunite, nbdec, nbdec FROM apunite
						 WHERE cdos=v_cdos;
	INSERT INTO GCPPAR (codpar, cle, libpar, valt, valn)
						SELECT 'UNITES', codcdt, libcdt, 0, 0 FROM apcdt
						 WHERE cdos=v_cdos
						   AND codcdt not in (SELECT cle FROM GCPPAR WHERE codpar = 'UNITES' and cle != '*');
END;

PROCEDURE PR_ALIGNER_FICHIER_ARTICLE IS
  v_dlv					GCPPAR.valc%TYPE;
BEGIN
  -- Désactiver les articles non existants dans la table APART.
  -- Sauf bien sûr les DLV.
  DELETE GCPART_BARRE a
   WHERE not exists (SELECT * FROM apart
   					  WHERE cdos=v_cdos and codart=a.codart);

  SELECT max(valc) INTO v_dlv FROM GCPPAR
   WHERE codpar='PARGEN' and cle='DLV';
	IF v_dlv = 'O' THEN
	   -- Ne pas désactiver les DLV
	   UPDATE GCPART a SET codbarre=null, etat='I', datmod=sysdate, muti='IMP'
	    WHERE not exists (SELECT * FROM apart
	   					   WHERE cdos=v_cdos and codart=a.codart)
	   	  AND (codart not like '%*1' and codart not like '%*2' and codart not like '%*3');
	ELSE
	   UPDATE GCPART a SET codbarre=null, etat='I', datmod=SYSDATE, muti='IMP'
	    WHERE not exists (SELECT * FROM apart
	   					   WHERE cdos=v_cdos and codart=a.codart);
	END IF;
END;


PROCEDURE PR_IMPORTER_ARTICLE(v_codart Varchar2, v_apble Varchar2, v_coduti VARCHAR2) IS
	v_maj_tarif		VARCHAR2(1);
	art_row			Apart%ROWTYPE;
BEGIN
	If v_tarif_spe is not null Then
	   SELECT SUM(tarifec) INTO n_tarifspe FROM aptarif
		WHERE cdos=v_cdos
		 AND codart = v_codart and codtarif=v_tarif_spe;
	   n_tarifspe := NVL(n_tarifspe,0);
	Else
	   n_tarifspe := 0;
	End if;

	If nvl(n_tarifspe,0)=0 Then
	   SELECT SUM(tarifec) INTO n_tarifstd FROM aptarif
		WHERE cdos=v_cdos
	      AND codart = v_codart and codtarif=v_tarif_std;
	   n_tarifstd := NVL(n_tarifstd,0);
	Else
	   n_tarifstd := n_tarifspe;
	End if;

	SELECT SUM(tarifec) INTO n_tarifpro FROM aptarif
	 WHERE cdos=v_cdos
	   AND codart = v_codart and codtarif=v_tarif_pro;
	n_tarifpro := NVL(n_tarifpro,0);

	SELECT * INTO art_row FROM apart
     Where cdos =v_cdos and codart = v_codart;

	SELECT count(*) INTO n_test FROM GCPART
	 WHERE codart=v_codart;
  	IF n_test = 0 THEN
	   -- Insertion dans la table des ARTICLES
  	   INSERT INTO GCPART (codart, tensto, libartr, libart, libart2, unistk, uniach, univen, coeff_ach, coeff_ven,
						 kit, geslot, etat, divers, codrtax, codcrit, mrgmin,
						 typart, codray, codnata, codfam, codsfam, pdsnet, pdsbrut, volume,
						 tarifstd, tarifpro, promo, pro_ddeb, pro_dfin, pro_tauxrem,
						 prmp, codbarre, datcre, cuti)
				VALUES  (v_codart, c1_row.tensto, NVL(c1_row.libartr,'.'), c1_row.libart1, c1_row.libart2, c1_row.unisto, c1_row.uniach, c1_row.unisto, 1,1,
						'N', 'N', 'A', 'N', DECODE(c1_row.codtax1,'0',v_codrtax,null), v_codcrit,0,
						c1_row.codfam, v_codray, v_codnata, c1_row.codcha, c1_row.codrub, c1_row.poidsnet, c1_row.poidsbrut, c1_row.volume,
						n_tarifstd, n_tarifpro, DECODE(n_tarifpro,0,'N','O'),	d_pro_ddeb, d_pro_dfin, 0,
						0, c1_row.refcons, nvl(c1_row.datcre,sysdate),v_coduti);

  	   INSERT INTO GCPART_BARRE (codart, codbarre, desbarre, nbunite)
					     SELECT codart, codbarre,'EQUIVALENT', nbunite FROM apart_barre
						  WHERE codart=v_codart
						    AND cdos=v_cdos;
  	ELSE
	  IF v_tarif_delta = 'O' or v_apble = 'O' THEN
		  v_maj_tarif := 'O';
	  ELSE
		  v_maj_tarif := 'N';
	  END IF;

  	  If v_maj_tarif = 'O' Then
		  SELECT max(numord) INTO n_numord FROM GCPHTARIF_ART
		   WHERE codart = v_codart
			 AND codtarif = '0';

		  n_numord := NVL(n_numord,0)+1;
			INSERT INTO GCPHTARIF_ART (codart, codtarif, numord, datchg, anctarif, nouvtarif, motif)
												  Select codart, '0', n_numord, SYSDATE, tarifstd, n_tarifstd, 'Importation DELTA'
													From Gcpart
												   Where codart = v_codart
													 And tarifstd != n_tarifstd;
	  End if;

	  UPDATE GCPART SET libartr		=	NVL(c1_row.libartr,'.'),
										 libart			= art_row.libart1,
										 libart2		= art_row.libart2,
										 tensto			= art_row.tensto,
										 unistk			= art_row.unisto,
										 uniach			= art_row.uniach,
										 univen			= art_row.unisto,
										 typart			= art_row.codfam,
										 codfam			= art_row.codcha,
										 codsfam		= art_row.codrub,
										 pdsnet			= art_row.poidsnet,
										 pdsbrut		= art_row.poidsbrut,
										 volume			= art_row.volume,
										 tarifstd		= DECODE(v_maj_tarif,'O',n_tarifstd, decode(nvl(tarifstd,0),0,n_tarifstd,tarifstd)),
										 tarifpro		= DECODE(v_tarif_delta,'O',n_tarifpro, decode(nvl(tarifpro,0),0,n_tarifpro,tarifpro)),
										 promo			= DECODE(v_tarif_delta,'O',DECODE(n_tarifpro,0,'N','O'), promo),
										 pro_ddeb		= DECODE(v_tarif_delta,'O',d_pro_ddeb, pro_ddeb),
										 pro_dfin		= DECODE(v_tarif_delta,'O',d_pro_dfin, pro_dfin),
										 prmp			= 0,
										 codbarre		= DECODE(v_cb_delta,'O',art_row.refcons,codbarre),
										 etat			= 'A',
										 datmod			= DECODE(v_maj_tarif,'O',sysdate,datmod),
										 muti			= DECODE(v_maj_tarif,'O',v_coduti,muti)
	   WHERE codart = v_codart;

	  -- Désactiver la promo si la mise à jour s'éffectue à partir des arrivages
	  IF v_apble = 'O' THEN
		 UPDATE GCPART set promo='N', datmod=sysdate, muti=v_coduti
		  WHERE codart = v_codart;
	  END IF;

  	  -- Doit-on prendre les codes barres dans DELTA
	  n_niveau := 10;
  	  IF v_cb_delta = 'O' THEN
  	  	 -- Suppression des anciens code barres secondaire.
  	  	 DELETE GCPART_BARRE
  	  	  WHERE codart = v_codart;

  	  	 -- Insertion des nouveaux codes barre.
		 n_niveau := 11;
 	  	 INSERT INTO GCPART_BARRE (codart, codbarre, desbarre, nbunite)
  	  	 			   		SELECT codart, codbarre,'EQUIVALENT', nbunite FROM apart_barre
  	  	 		    		 WHERE codart=v_codart;
  	  END IF;

  	END IF;
END;

PROCEDURE PR_IMPORTER IS
	CURSOR c1 IS SELECT codart
	/*, libartr, libart1, libart2, libart3, tensto, refcons, codcha, codrub, codfam, codtyp, unisto, uniach
					  ,codcdt, nbunit, codtax1, codtax2, codtax3, codtax4, poidsnet, poidsbrut, volume, datcre*/
				   FROM apart
				  WHERE cdos=v_cdos and (v_tensto='O' or tensto='O')
					AND (datcre >= sysdate-10 or datmod >= sysdate-10)
				ORDER BY codart;
	c1_row		C1%Rowtype;
	n_art		NUMBER(8);
	n_niveau 	NUMBER(2);
BEGIN
	-- Nombre total des articles.
	SELECT count(*) INTO n_art FROM apart
	 WHERE cdos=v_cdos and (v_tensto='O' or tensto='O')
  	   AND (datcre >= sysdate-10 or datmod >= sysdate-10);

	IF n_art = 0 THEN
      Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
			     values ('DB','DB',null,null,sysdate,sysdate,'Aucune mise à jour en instance.');
	  Return;
	END IF;

    FOR c1_row IN c1 LOOP
  		n_niveau := 0;

  	    Pr_importer_article(c1_row.codart,'N','DB');

	    -- Sauvegarde par paquet de 1000
	    IF mod(n_evolution,1000) = 0 THEN
		   Standard.commit;
	    END IF;
    END LOOP;

	COMMIT;
EXCEPTION
	WHEN others THEN
         Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
			        values ('DB','DB',null,null,sysdate,sysdate,'Erreur lors de la mise à jour.');
         Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
			        values ('DB','DB',null,null,sysdate,sysdate,'SQL code = '||sqlcode||', '||sqlerrm||'.');
		 Rollback;
END;

-------------------------------------------------------------------------------
-- INITIALISATION DU PACKAGE LORS DU 1ER APPEL
-------------------------------------------------------------------------------
BEGIN
	-- Obtention des paramètres DELTA
	v_cdos 			:= FN_GET_CEPARAMC('DELTA','001');
	v_tarif_spe		:= FN_GET_CEPARAMC('DELTA','T02');
	v_tarif_std 	:= FN_GET_CEPARAMC('DELTA','002');
	v_tarif_pro 	:= FN_GET_CEPARAMC('DELTA','003');
	d_pro_ddeb	 	:= TO_DATE(FN_GET_CEPARAMC('DELTA','004'),'dd/mm/yyyy');
	d_pro_dfin		:= TO_DATE(FN_GET_CEPARAMC('DELTA','005'),'dd/mm/yyyy');
	v_typart		:= FN_GET_CEPARAMC('DELTA','A01');
	v_codfam		:= FN_GET_CEPARAMC('DELTA','A02');
	v_codsfam		:= FN_GET_CEPARAMC('DELTA','A03');
	v_codrtax		:= FN_GET_CEPARAMC('DELTA','A04');
	v_codcrit		:= FN_GET_CEPARAMC('DELTA','A05');
	v_codray		:= FN_GET_CEPARAMC('DELTA','A06');
	v_codnata		:= FN_GET_CEPARAMC('DELTA','A07');
	v_tensto		:= FN_GET_CEPARAMC('DELTA','A08');
	v_lst_cha		:= FN_GET_CEPARAMC('DELTA','A09');
	v_cb_delta		:= FN_GET_CEPARAMC('DELTA','015');
	v_tarif_delta	:= FN_GET_CEPARAMC('DELTA','016');

	IF v_cdos IS NULL or v_tarif_std IS NULL or v_codnata IS NULL THEN
	   Insert into UTLOG (coduti_app, coduti_sys, numero_session, codprog, datedeb, datefin, comm)
				  values ('DB','DB',null,null,sysdate,sysdate,'Problème lors de la récupération des paramètres d''importation.');
	   RETURN;
	END IF;
END PR_IMPORTER_DELTA_XCAISSE;
/

ALTER PACKAGE "CAISSE"."PR_IMPORTER_DELTA_XCAISSE" 
  COMPILE BODY 
    PLSQL_OPTIMIZE_LEVEL=  2
    PLSQL_CODE_TYPE=  INTERPRETED
    PLSQL_DEBUG=  FALSE
    PLSCOPE_SETTINGS=  'IDENTIFIERS:NONE'
 REUSE SETTINGS TIMESTAMP '2019-08-11 10:27:11'
/
 
CREATE PACKAGE BODY        QUEUE_MANAGE
AS

  PROCEDURE process_queue IS
	n_count		Number;
	b_cb		Boolean;
	b_ok		Boolean;
	n_id		Number;
	v_site		Varchar2(30);
	n_nbbrd		Number;
  BEGIN
	-- Vérrouiller les bordereaux à traiter
/*
	Update gcbrde_queue set numsai = numsai;

	Lock table gcbrde_queue;
	Lock table gcbrdd_queue;
	Lock table gcbrdd_lot_queue;
	Lock table gcbrde_log_queue;
*/

	-- Nom du site
	Select max(valc) Into v_site From Kernel.Utppar
	 Where codpar = 'PARGEN' and cle = 'SIT';

	If v_site is not null Then
	   Select kernel.seq_synchro_log_id.nextval into n_id From dual;
	   Insert into kernel.Utsynchro_log (site, id, oper, hr_debut) values (v_site, n_id, 'QUEUE_UPL', sysdate);
	End if;

	Select count(*) Into n_nbbrd From Gcbrde_queue;

	-- Appliquer les fusions dans les tables QUEUE
	For f_row In (Select codart_dep, codart_arr From gcfuart_log f
								 Where codart_arr is not null
								   and exists (Select * From Gcbrdd_queue Where codart = f.codart_dep)
								)
	Loop
		Update gcbrdd_queue set codart = f_row.codart_arr
		 Where codart = f_row.codart_dep;
	End Loop;


	For b_row In (Select idbrd, typven From Gcbrde_queue) Loop
		Begin
			b_cb := False;
			b_ok := False;
			If b_row.typven is null Then
				Select count(*) Into n_count From Cepsession Where idbrd = b_row.idbrd;
				If n_count = 0 Then
				   Select count(*) Into n_count From Cepsession_arch Where idbrd = b_row.idbrd;
				End if;
				b_cb := (n_count > 0);
			End if;

			Select count(*) Into n_count From Gcbrde Where idbrd = b_row.idbrd;

			If n_count = 0 Then
			   Upload_ins_brd(b_row.idbrd, b_ok);
			ElsIf b_row.typven is not null or b_cb Then
			   Upload_maj_brd_vte(b_row.idbrd, b_ok);
			Else
			   b_ok := True;
			End if;

			If b_ok Then
			   Delete gcbrdd_queue Where idbrd = b_row.idbrd;
			   Delete gcbrdd_lot_queue Where idbrd = b_row.idbrd;
			   Delete gcbrde_log_queue Where idbrd = b_row.idbrd;
			   Delete gcbrde_vte_queue Where idbrd = b_row.idbrd;
			   Delete gcbrde_queue Where idbrd = b_row.idbrd;
			End if;
		End;
	End Loop;

	Update Kernel.Utsynchro_log set hr_fin = sysdate, obs=to_char(n_nbbrd)||' bordereau(x) traité(s)'
	 Where site=v_site and id=n_id;
  END;

  PROCEDURE UPLOAD_MAJ_BRD_VTE(n_idbrd Number, b_ok OUT Boolean) IS
	n_niveau			Number := 0;
	n_count				Number;
	n_count2			Number;
	n_ctrl				Number;
	n_ctrl2				Number;
	v_traceur			Varchar2(100);
  BEGIN
	-- Mise à jour des bordereaux de vte sur office puisque le POS garde la latitude de modifier ses BL tant que cela n'est pas clôturer.
	For c_row In (Select idbrd, codtbrd, numbrd, codeta, datbrd, coddep, numdoc, depdes, statdes, tbrdctrp
						,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
						,numfac, datfac, tauxrem, codtarif, datech, codmrgl, Decode(etat,'O','C',etat) etat, cuti, muti, datcre, datmod
						,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
						,numbrd_ret, idbrdctrp, idbrd_sce, option_sce, datdoc
						,modexp, delai, usage, coeffrev, mtrgl, afacturer, nbr_impr, num_ptvte, marrondi, numsai, mt_acompte
						,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
						,codtbrd_ret, codcpt_brd, codcpt_fac, codcpt_doc
					From gcbrde_queue
					Where idbrd = n_idbrd
				  Minus
				  Select idbrd, codtbrd, numbrd, codeta, datbrd, coddep, numdoc, depdes, statdes, tbrdctrp
						,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
						,numfac, datfac, tauxrem, codtarif, datech, codmrgl, etat, cuti, muti, datcre, datmod
						,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
						,numbrd_ret, idbrdctrp, idbrd_sce, option_sce, datdoc
						,modexp, delai, usage, coeffrev, mtrgl, afacturer, nbr_impr, num_ptvte, marrondi, numsai, mt_acompte
						,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
						,codtbrd_ret, codcpt_brd, codcpt_fac, codcpt_doc
					From gcbrde
					Where  idbrd = n_idbrd)
	Loop
		 Update gcbrde set codtbrd=c_row.codtbrd, numbrd=c_row.numbrd, codeta=c_row.codeta, datbrd=c_row.datbrd, coddep=c_row.coddep, numdoc=c_row.numdoc, depdes=c_row.depdes, statdes=c_row.statdes, tbrdctrp=c_row.tbrdctrp
							,comm=c_row.comm, memo=c_row.memo, codtie=c_row.codtie, nomtie=c_row.nomtie, adrtie1=c_row.adrtie1, adrtie2=c_row.adrtie2, adrtie3=c_row.adrtie3, coddev=c_row.coddev, crschg=c_row.crschg
							,numfac=c_row.numfac, datfac=c_row.datfac, tauxrem=c_row.tauxrem, codtarif=c_row.codtarif, datech=c_row.datech, codmrgl=c_row.codmrgl, etat=c_row.etat, cuti=c_row.cuti, muti=c_row.muti, datcre=c_row.datcre, datmod=c_row.datmod
							,codrtax=c_row.codrtax, mht=c_row.mht, mtax1=c_row.mtax1, mtax2=c_row.mtax2, mtax3=c_row.mtax3, mtax4=c_row.mtax4, mttc=c_row.mttc, mtax_art=c_row.mtax_art, mtax_unite=c_row.mtax_unite, typven=c_row.typven
							,numbrd_ret=c_row.numbrd_ret, idbrdctrp=c_row.idbrdctrp, idbrd_sce=c_row.idbrd_sce, option_sce=c_row.option_sce, datdoc=c_row.datdoc
							,modexp=c_row.modexp, delai=c_row.delai, usage=c_row.usage, coeffrev=c_row.coeffrev, mtrgl=c_row.mtrgl, afacturer=c_row.afacturer
							,nbr_impr=c_row.nbr_impr, num_ptvte=c_row.num_ptvte, marrondi=c_row.marrondi, numsai=c_row.numsai, mt_acompte=c_row.mt_acompte
							,zlibre_l1=c_row.zlibre_l1, zlibre_l2=c_row.zlibre_l2, zlibre_l3=c_row.zlibre_l3, zlibre_l4=c_row.zlibre_l4, zlibre_l5=c_row.zlibre_l5
							,zlibre_n1=c_row.zlibre_n1, zlibre_n2=c_row.zlibre_n2, zlibre_n3=c_row.zlibre_n3, zlibre_n4=c_row.zlibre_n4, zlibre_n5=c_row.zlibre_n5
							,zlibre_c1=c_row.zlibre_c1, zlibre_c2=c_row.zlibre_c2, zlibre_c3=c_row.zlibre_c3, zlibre_c4=c_row.zlibre_c4, zlibre_c5=c_row.zlibre_c5
							,codtbrd_ret=c_row.codtbrd_ret, codcpt_brd=c_row.codcpt_brd, codcpt_fac=c_row.codcpt_fac, codcpt_doc=c_row.codcpt_doc
		  Where idbrd=n_idbrd and codtbrd=c_row.codtbrd;
	End Loop;

	For d_row In (Select idbrd, numlig, numord, codtbrd, coddep, codstat, depdes, tbrdctrp
						,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
						,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde/*, zlibre_m1*/
						,/*1 purevient, qtebrd montrevient,*/ exonere, nbcolis, idbrd_sce, option_sce, qtevalid
						,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
						,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
				 From gcbrdd_queue q
				 Where idbrd = n_idbrd
				   And codtbrd = (Select codtbrd From Gcbrde Where idbrd=q.idbrd)
				Minus
				Select idbrd, numlig, numord, codtbrd, coddep, codstat, depdes, tbrdctrp
						,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
						,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde/*, zlibre_m1*/
						,/*purevient, montrevient,*/ exonere, nbcolis, idbrd_sce, option_sce, qtevalid
						,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
						,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
				 From gcbrdd
				 Where idbrd = n_idbrd)
	Loop
		 Update gcbrdd set numord=d_row.numord, codtbrd=d_row.codtbrd, coddep=d_row.coddep, codstat=d_row.codstat, depdes=d_row.depdes, tbrdctrp=d_row.tbrdctrp
							,codart=d_row.codart, desbrd1=d_row.desbrd1, qtebrd=d_row.qtebrd, unibrd=d_row.unibrd, pubrd=d_row.pubrd, montbrd=d_row.montbrd, tauxrem=d_row.tauxrem, puven=d_row.puven, typlig=d_row.typlig, puht=d_row.puht, montht=d_row.montht
							,numlig_sce=d_row.numlig_sce, qtetrans=d_row.qtetrans, coeff=d_row.coeff, desbrd2=d_row.desbrd2, delai=d_row.delai, qtededuite=d_row.qtededuite, ligne_solde=d_row.ligne_solde
							,/*purevient=d_row.purevient, montrevient=d_row.montrevient,*/ exonere=d_row.exonere, nbcolis=d_row.nbcolis
							,/*zlibre_m1=d_row.zlibre_m1, zlibre_l1=d_row.zlibre_l1, */idbrd_sce=d_row.idbrd_sce, option_sce=d_row.option_sce, qtevalid=d_row.qtevalid
							,tauxtax=d_row.tauxtax, mtax=d_row.mtax, statdes=d_row.statdes, promo=d_row.promo, dlv=d_row.dlv, codtaxe_unite=d_row.codtaxe_unite, tauxtaxe_unite=d_row.tauxtaxe_unite
							,zlibre_l1=d_row.zlibre_l1, zlibre_l2=d_row.zlibre_l2, zlibre_l3=d_row.zlibre_l3, zlibre_l4=d_row.zlibre_l4, zlibre_l5=d_row.zlibre_l5
							,zlibre_n1=d_row.zlibre_n1, zlibre_n2=d_row.zlibre_n2, zlibre_n3=d_row.zlibre_n3, zlibre_n4=d_row.zlibre_n4, zlibre_n5=d_row.zlibre_n5
							,zlibre_c1=d_row.zlibre_c1, zlibre_c2=d_row.zlibre_c2, zlibre_c3=d_row.zlibre_c3, zlibre_c4=d_row.zlibre_c4, zlibre_c5=d_row.zlibre_c5
		  Where idbrd=d_row.idbrd and numlig=d_row.numlig;
		 If Sql%rowcount = 0 Then
			Insert into gcbrdd (idbrd, numlig, numord, codtbrd, coddep, codstat, depdes, tbrdctrp
								,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
								,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde
								,purevient, montrevient, exonere, nbcolis, /*zlibre_m1, zlibre_l1, */idbrd_sce, option_sce, qtevalid
								,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
								,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
								,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
								,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
								)
						values(d_row.idbrd, d_row.numlig, d_row.numord, d_row.codtbrd, d_row.coddep, d_row.codstat, d_row.depdes, d_row.tbrdctrp
								,d_row.codart, d_row.desbrd1, d_row.qtebrd, d_row.unibrd, d_row.pubrd, d_row.montbrd, d_row.tauxrem, d_row.puven, d_row.typlig, d_row.puht, d_row.montht
								,d_row.numlig_sce, d_row.qtetrans, d_row.coeff, d_row.desbrd2, d_row.delai, d_row.qtededuite, d_row.ligne_solde
								,1, d_row.qtebrd, d_row.exonere, d_row.nbcolis, /*d_row.zlibre_m1, d_row.zlibre_l1, */d_row.idbrd_sce, d_row.option_sce, d_row.qtevalid
								,d_row.tauxtax, d_row.mtax, d_row.statdes, d_row.promo, d_row.dlv, d_row.codtaxe_unite, d_row.tauxtaxe_unite
								,d_row.zlibre_l1, d_row.zlibre_l2, d_row.zlibre_l3, d_row.zlibre_l4, d_row.zlibre_l5
								,d_row.zlibre_n1, d_row.zlibre_n2, d_row.zlibre_n3, d_row.zlibre_n4, d_row.zlibre_n5
								,d_row.zlibre_c1, d_row.zlibre_c2, d_row.zlibre_c3, d_row.zlibre_c4, d_row.zlibre_c5
								 );
		 End if;
	End loop;

	-- Supprimer au siège les lignes qui n'existent plus dans la queue
	Select count(*), sum(numlig) Into n_count, n_ctrl From Gcbrdd_queue
	 Where idbrd = n_idbrd;

	Select count(*), sum(numlig) Into n_count2, n_ctrl2 From Gcbrdd
	 Where idbrd = n_idbrd;

	-- Pour tester s'il y a une suppression de ligne
	If n_count > 0 and (n_count != n_count2 or n_ctrl != n_ctrl2) Then
		 Delete Gcbrdd
		  Where idbrd = n_idbrd
		  And numlig not in (Select numlig From Gcbrdd_queue Where idbrd = n_idbrd);
	End if;

	-- Transfert de GCBRDD_LOT
	n_niveau := n_niveau + 1;
	For d_row In (Select l.idbrd, l.numlig, l.numlot, l.date_fabr, l.date_expir, l.qtelot
					 From gcbrdd_lot_queue l--, gcbrdd_queue d
					 Where l.idbrd = n_idbrd
					Minus
					Select idbrd, numlig, numlot, date_fabr, date_expir, qtelot
					 From gcbrdd_lot
					 Where idbrd = n_idbrd)
	Loop
		 Update gcbrdd_lot set date_fabr=d_row.date_fabr, date_expir=d_row.date_expir, qtelot=d_row.qtelot
		  Where idbrd=d_row.idbrd and numlig=d_row.numlig and numlot=d_row.numlot;
		 If Sql%rowcount = 0 Then
			Insert into gcbrdd_lot (idbrd, numlig, numlot, date_fabr, date_expir, qtelot)
							values(d_row.idbrd, d_row.numlig, d_row.numlot, d_row.date_fabr, d_row.date_expir, d_row.qtelot);
		 End if;
	End loop;

	For d_row In (Select idbrd, codrep, nbr_impr_bl, nbr_impr_fact, opt_livr, opt_livr_date, opt_livr_heure, opt_livr_loc, code_ville, numsai From gcbrde_vte_queue a
				 Where idbrd = n_idbrd
				Minus
				Select idbrd, codrep, nbr_impr_bl, nbr_impr_fact, opt_livr, opt_livr_date, opt_livr_heure, opt_livr_loc, code_ville, numsai From gcbrde_vte
				 Where idbrd = n_idbrd)
	Loop
		 Begin
			  Update gcbrde_vte set codrep=d_row.codrep, nbr_impr_bl=d_row.nbr_impr_bl, nbr_impr_fact=d_row.nbr_impr_fact, opt_livr=d_row.opt_livr, opt_livr_date=d_row.opt_livr_date, opt_livr_heure=d_row.opt_livr_heure, opt_livr_loc=d_row.opt_livr_loc, code_ville=d_row.code_ville, numsai=d_row.numsai
			   Where idbrd = d_row.idbrd;
			  If sql%rowcount = 0 Then
				 Insert into gcbrde_vte (idbrd, codrep, nbr_impr_bl, nbr_impr_fact, opt_livr, opt_livr_date, opt_livr_heure, opt_livr_loc, code_ville, numsai)
								 values(d_row.idbrd, d_row.codrep, d_row.nbr_impr_bl, d_row.nbr_impr_fact, d_row.opt_livr, d_row.opt_livr_date, d_row.opt_livr_heure, d_row.opt_livr_loc, d_row.code_ville, d_row.numsai);
				End if;
		 Exception
				When others Then null;
		 End;
	End loop;

	-- Supprimer les lignes qui n'existent plus si le bordereau est présent au siège
	Select count(*) Into n_count From Gcbrdd_lot_queue
	 Where idbrd = n_idbrd;
	If n_count > 0 Then
		 Delete Gcbrdd_lot
		  Where idbrd = n_idbrd
		  And (numlig, numlot) not in (Select numlig, numlot From Gcbrdd_lot_queue Where idbrd = n_idbrd);
	End if;

  -- Mise à jour de GCBRDE_LOG.
	For d_row In (Select idbrd, datop, coduti, libop From gcbrde_log_queue a
								 Where idbrd = n_idbrd
								Minus
								Select idbrd, datop, coduti, libop From gcbrde_log
								 Where idbrd = n_idbrd)
	Loop
		 Begin
				Insert into gcbrde_log (idbrd, datop, coduti, libop)
												 values(d_row.idbrd, d_row.datop, d_row.coduti, d_row.libop);
		 Exception
				When others Then null;
		 End;
	End loop;

	b_ok := True;
  EXCEPTION
	When others Then
		 b_ok := False;
		 --v_lib := 'Erreur in UPLOAD_BRD_VTE : SQL Code '||sqlcode||','||sqlerrm;
  END;

  PROCEDURE UPLOAD_INS_BRD(n_idbrd Number, b_ok OUT Boolean) IS
	 v_codtbrd_ctrp			Gcbrde.codtbrd%Type;
	 v_depdes				Gcbrde.coddep%Type;
	 n_idbrdctrp			Gcbrde.idbrd%Type;
	 v_tbrdctrp				Gcbrde.codtbrd%Type;
  BEGIN
	 Insert into gcbrde
				 (idbrd, codtbrd, numbrd, codeta, datbrd, coddep, numdoc, depdes, statdes, tbrdctrp
					,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
					,numfac, datfac, tauxrem, codtarif, datech, codmrgl, etat, cuti, muti, datcre, datmod
					,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
					,numbrd_ret, idbrdctrp, idbrd_sce, option_sce, datdoc
					,modexp, delai, usage, coeffrev, mtrgl, afacturer
					,nbr_impr, num_ptvte, marrondi, numsai, mt_acompte
					,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
					,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
					,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
					,codtbrd_ret, codcpt_brd, codcpt_fac, codcpt_doc)
		  Select idbrd, codtbrd, numbrd, codeta, datbrd, coddep, numdoc, depdes, statdes, tbrdctrp
					,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
					,numfac, datfac, tauxrem, codtarif, datech, codmrgl, etat, cuti, muti, datcre, datmod
					,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
					,numbrd_ret, idbrdctrp, idbrd_sce, option_sce, datdoc
					,modexp, delai, usage, coeffrev, mtrgl, afacturer
					,nbr_impr, num_ptvte, marrondi, numsai, mt_acompte
					,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
					,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
					,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
					,codtbrd_ret, codcpt_brd, codcpt_fac, codcpt_doc
			From Gcbrde_queue Where idbrd = n_idbrd;

	 Insert into gcbrdd
				 (idbrd, numlig, numord, codtbrd, coddep, codstat, depdes, tbrdctrp
					,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
					,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde
					,purevient, montrevient, exonere, nbcolis, zlibre_m1, idbrd_sce, option_sce, qtevalid
					,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
					,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
					,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
					,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5)
			Select idbrd, numlig, numord, codtbrd, coddep, codstat, depdes, tbrdctrp
					,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
					,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde
					,purevient, montrevient, exonere, nbcolis, zlibre_m1, idbrd_sce, option_sce, qtevalid
					,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
					,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
					,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
					,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
				From gcbrdd_queue
			 Where idbrd = n_idbrd;

	 Begin
		 Insert into gcbrdd_lot (idbrd, numlig, numlot, date_fabr, date_expir, qtelot)
						Select idbrd, numlig, numlot, date_fabr, date_expir, qtelot From Gcbrdd_lot_queue
						 Where idbrd = n_idbrd;
	 Exception
		 When others Then null;
	 End;

	 Begin
		 Insert into gcbrde_log (idbrd, datop, coduti, libop)
						Select idbrd, datop, coduti, libop
							From gcbrde_log_queue
						 Where idbrd = n_idbrd;
	 Exception
		 When others Then null;
	 End;

	 Begin
		 Insert into gcbrde_vte (idbrd, codrep, nbr_impr_bl, nbr_impr_fact, opt_livr, opt_livr_date, opt_livr_heure, opt_livr_loc, code_ville, numsai)
						Select idbrd, codrep, nbr_impr_bl, nbr_impr_fact, opt_livr, opt_livr_date, opt_livr_heure, opt_livr_loc, code_ville, numsai
							From gcbrde_vte_queue
						 Where idbrd = n_idbrd;
	 Exception
		 When others Then null;
	 End;

	 Select depdes, idbrdctrp, tbrdctrp  Into v_depdes, n_idbrdctrp, v_tbrdctrp From Gcbrde
	  Where idbrd = n_idbrd;

	 -- s'il s'agit d'un transfert générer la contrepartie à recupérer par l'autre dépôt et mettre à jour le bordereau source
	 If v_depdes is not null and n_idbrdctrp is null Then
		  If v_tbrdctrp is null Then
			 Select max(valc) Into v_codtbrd_ctrp From Gcppar
			  Where codpar = 'REGAL' and cle='ETW';
		  Else
			 v_codtbrd_ctrp := v_tbrdctrp;
		  End if;

		  Select seq_gc_idbrd.nextval into n_idbrdctrp From dual;

		  Insert into gcbrde
							 (IDBRD, CODTBRD, numbrd, codeta, datbrd, CODDEP, numdoc, DEPDES, TBRDCTRP
							,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
							,numfac, datfac, tauxrem, codtarif, datech, codmrgl, etat, cuti, muti, datcre, datmod
							,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
							,numbrd_ret, IDBRDCTRP, idbrd_sce, option_sce, datdoc
							,modexp, delai, usage, coeffrev, mtrgl, afacturer
							,nbr_impr, num_ptvte, marrondi, numsai, mt_acompte)--, codtbrd_ret, codcpt_brd, codcpt_fac, codcpt_doc)
					Select  N_IDBRDCTRP, V_CODTBRD_CTRP, numbrd, codeta, datbrd, DEPDES, numdoc, CODDEP, CODTBRD
							,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
							,numfac, datfac, tauxrem, codtarif, datech, codmrgl, etat, cuti, null, sysdate, null
							,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
							,numbrd_ret, n_idbrd, null, null, datdoc
							,modexp, delai, usage, coeffrev, mtrgl, afacturer
							,nbr_impr, num_ptvte, marrondi, numsai, mt_acompte
					  From Gcbrde_queue Where idbrd = n_idbrd;

			Insert into gcbrdd
						 (IDBRD, numlig, numord, CODTBRD, CODDEP, DEPDES, CODSTAT, TBRDCTRP
						 ,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
						 ,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde
						 ,purevient, montrevient, exonere, nbcolis, zlibre_m1, idbrd_sce, option_sce, qtevalid
						 ,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
						 ,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						 ,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						 ,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5)
				  Select N_IDBRDCTRP, numlig, numord, V_CODTBRD_CTRP, DEPDES, CODDEP, statdes, CODTBRD
						 ,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
						 ,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde
						 ,purevient, montrevient, exonere, nbcolis, zlibre_m1, idbrd_sce, option_sce, qtevalid
						 ,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
						 ,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						 ,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						 ,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
				From gcbrdd_queue
			   Where idbrd = n_idbrd;

		  Insert into gcbrdd_lot (idbrd, numlig, numlot, date_fabr, date_expir, qtelot)
											Select n_idbrd, numlig, numlot, date_fabr, date_expir, qtelot From Gcbrdd_lot_queue
											 Where idbrd = n_idbrd;

		  Insert into gcbrde_log
												 (idbrd, datop, coduti, libop)
											Select n_idbrd, sysdate, 'QUEUE', 'Génération contrepartie office'
												From gcbrde_queue
											 Where idbrd = n_idbrd;

			-- Lier le bordereau existant avec le nouveau
			Update Gcbrde set idbrdctrp = n_idbrdctrp, tbrdctrp = v_codtbrd_ctrp
			 Where idbrd = n_idbrd;
	 End if;

	 b_ok := True;
  EXCEPTION
	When others Then
		 b_ok := False;
		 --v_lib := 'Erreur in UPLOAD_BRD_VTE : SQL Code '||sqlcode||','||sqlerrm;
  END;

  PROCEDURE GENERATE_MISSING_RW IS
	 n_idbrd				Gcbrde.idbrd%Type;
	 v_depdes				Gcbrde.coddep%Type;
	 n_idbrdctrp			Gcbrde.idbrd%Type;
	 v_tbrdctrp				Gcbrde.codtbrd%Type;
	 v_lib					Gcbrde_log.libop%Type;
  BEGIN
	 For brd_row In (Select datbrd, coddep, idbrd, numbrd, idbrdctrp, depdes, tbrdctrp
					  from gcbrde e where codtbrd='TW' and idbrdctrp is not null
					   and not exists (select * from gcbrde where idbrd=e.idbrdctrp) order by datbrd, coddep
					 )

	 Loop
		 n_idbrd		:= brd_row.idbrd;
		 v_depdes 		:= brd_row.depdes;
		 n_idbrdctrp	:= brd_row.idbrdctrp;
		 v_tbrdctrp		:= brd_row.tbrdctrp;

		  -- Générer la contrepartie manquante
		  Insert into gcbrde
							 (IDBRD, CODTBRD, numbrd, codeta, datbrd, CODDEP, numdoc, DEPDES, TBRDCTRP
							,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
							,numfac, datfac, tauxrem, codtarif, datech, codmrgl, etat, cuti, muti, datcre, datmod
							,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
							,numbrd_ret, IDBRDCTRP, idbrd_sce, option_sce, datdoc
							,modexp, delai, usage, coeffrev, mtrgl, afacturer
							,nbr_impr, num_ptvte, marrondi, numsai, mt_acompte)--, codtbrd_ret, codcpt_brd, codcpt_fac, codcpt_doc)
					Select  N_IDBRDCTRP, v_tbrdctrp, numbrd, codeta, datbrd, DEPDES, numdoc, CODDEP, CODTBRD
							,comm, memo, codtie, nomtie, adrtie1, adrtie2, adrtie3, coddev, crschg
							,numfac, datfac, tauxrem, codtarif, datech, codmrgl, etat, cuti, null, sysdate, null
							,codrtax, mht, mtax1, mtax2, mtax3, mtax4, mttc, mtax_art, mtax_unite, typven
							,numbrd_ret, n_idbrd, null, null, datdoc
							,modexp, delai, usage, coeffrev, mtrgl, afacturer
							,nbr_impr, num_ptvte, marrondi, numsai, mt_acompte
					  From Gcbrde Where idbrd = n_idbrd;

			Insert into gcbrdd
						 (IDBRD, numlig, numord, CODTBRD, CODDEP, DEPDES, CODSTAT, TBRDCTRP
						 ,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
						 ,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde
						 ,purevient, montrevient, exonere, nbcolis, zlibre_m1, idbrd_sce, option_sce, qtevalid
						 ,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
						 ,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						 ,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						 ,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5)
				  Select N_IDBRDCTRP, numlig, numord, v_tbrdctrp, DEPDES, CODDEP, statdes, CODTBRD
						 ,codart, desbrd1, qtebrd, unibrd, pubrd, montbrd, tauxrem, puven, typlig, puht, montht
						 ,numlig_sce, qtetrans, coeff, desbrd2, delai, qtededuite, ligne_solde
						 ,purevient, montrevient, exonere, nbcolis, zlibre_m1, idbrd_sce, option_sce, qtevalid
						 ,tauxtax, mtax, statdes, promo, dlv, codtaxe_unite, tauxtaxe_unite
						 ,zlibre_l1, zlibre_l2, zlibre_l3, zlibre_l4, zlibre_l5
						 ,zlibre_n1, zlibre_n2, zlibre_n3, zlibre_n4, zlibre_n5
						 ,zlibre_c1, zlibre_c2, zlibre_c3, zlibre_c4, zlibre_c5
				From gcbrdd
			   Where idbrd = n_idbrd;

		  Insert into gcbrdd_lot (idbrd, numlig, numlot, date_fabr, date_expir, qtelot)
											Select n_idbrd, numlig, numlot, date_fabr, date_expir, qtelot From Gcbrdd_lot
											 Where idbrd = n_idbrd;

		  Insert into gcbrde_log (idbrd, datop, coduti, libop)
						   values( N_IDBRDCTRP, sysdate, 'QUEUE', 'Generation contrepartie manquante office');

		  Insert into gcbrde_log (idbrd, datop, coduti, libop)
											Select n_idbrd, sysdate, 'QUEUE', 'Génération contrepartie manquante office'
												From gcbrde
											 Where idbrd = n_idbrd;

	 END LOOP;

  EXCEPTION
	When others Then
		 -- On annule ce qui a été généré
		 Delete gcbrdd where idbrd = N_IDBRDCTRP;
		 Delete gcbrde_log where idbrd = N_IDBRDCTRP;
		 Delete gcbrde where idbrd = N_IDBRDCTRP;
		 If sql%rowcount != 0 Then
			v_lib := Substr('Generation contrepartie manquante office, error : '||sqlcode||','||sqlerrm,1,255);
			Insert into gcbrde_log (idbrd, datop, coduti, libop)
						     values(n_idbrd, sysdate, 'QUEUE', v_lib);

		 End if;
  END;

END QUEUE_MANAGE;
/

