CREATE PACKAGE BODY cparrete
AS


-------------------------------------------------------------------------------
-- Edition de la balance generale
-------------------------------------------------------------------------------

   wcpt          cp_cpt%ROWTYPE;
   wpro          cp_pro%ROWTYPE;
--   wmvg          cp_ecr_ana%ROWTYPE;

   TYPE cpcum_type IS RECORD     -- zone de cumul compte
   (    sofina     NUMBER(15,3),
        ecartb     NUMBER(15,3),
        sofinc     NUMBER(15,3),
        bdfind     NUMBER(15,3),
        ecarte     NUMBER(15,3),
        sofinf     NUMBER(15,3),
        ecartg     NUMBER(15,3),
        smoish     NUMBER(15,3)
   );
   cpcum         cpcum_type;

   TYPE w_reg_sec_type IS TABLE OF VARCHAR2(1) INDEX BY BINARY_INTEGER;
   w_reg_sec     w_reg_sec_type;

   --sk
   w_ecr_non_maj VARCHAR2(1);
   w_sim         VARCHAR2(1);
   w_per_comp    VARCHAR2(1);
   w_rg_dev      VARCHAR2(1);
   w_dper_c      VARCHAR2(3);
   w_fper_c      VARCHAR2(3);
   w_exercice    VARCHAR2(3);
   w_session_id  NUMBER;
   --fin sk

   w_titre       VARCHAR2(30);
   w_dper        DATE;
   w_fper        DATE;
   w_dper_pre        DATE;
   w_fper_pre        DATE;
   w_date        DATE;
   w_ddex        DATE;
   w_reou        VARCHAR2(1);
   w_ran         VARCHAR2(1);
   w_reed        VARCHAR2(1);
   w_psec        CHAR(8);
   w_dsec        CHAR(8);
   w_section     VARCHAR2(8);
   w_ndec        NUMBER;
   w_axe        NUMBER;
   w_codets         VARCHAR2(3);
   w_coddes         VARCHAR2(8);
   w_ligne       NUMBER;
   w_numord_edi  NUMBER;
   w_page        NUMBER;
   w_nblg        NUMBER;
   w_maxlg       NUMBER;
   wi            NUMBER;
   larg_ed       NUMBER;
   w_cuti        VARCHAR2(4);

   w_ets         VARCHAR2(3);
   w_axa         VARCHAR2(1);
   w_etbdeb         VARCHAR2(3);
   w_etbfin         VARCHAR2(3);
   w_secdeb         VARCHAR2(8);
   w_secfin         VARCHAR2(8);
   sel_ets       cp_ets.codets%TYPE;
   ets_lib       VARCHAR2(30);
   Message       VARCHAR2(100);

   sauv_supl     NUMBER;
   w_supl        NUMBER;
   lig_as        VARCHAR2(1);

-------------------------------------------------------------------------------

PROCEDURE ledar01 (woptions IN VARCHAR2)
IS

    CURSOR ar_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN

--  lecture des parametres d'edition dans le fichier evlanc
-- i

dbms_output.enable(50000);

    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);
    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_etbdeb         := rtrim(substr(woptions,16,3));
    w_etbfin         := rtrim(substr(woptions,19,3));
    w_secdeb         := rtrim(substr(woptions,22,8));
    w_secfin         := rtrim(substr(woptions,30,8));
    w_rg_dev	  := substr(woptions,38,1);
    w_ecr_non_maj := substr(woptions,39,1);
    w_axe	  := to_number(substr(woptions,40,1));
    w_session_id  := to_number(substr(woptions,41,38));

dbms_output.put_line('w_sess '||woptions);
--dbms_output.put_line(' w_cdos '||w_etbdeb);

   w_nmois := to_number(w_fper_c) - to_number(w_dper_c) + 1;

    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
--dbms_output.put_line('w_fper '||to_char(w_fper));
    -- excercice précédent
    w_dannee := to_number(substr(to_char(w_dper,'dd/mm/yyyy'),7,4))-1;
    w_dper_pre := to_date(substr(to_char(w_dper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_dannee),'dd/mm/yyyy');
    w_fannee := to_number(substr(to_char(w_fper,'dd/mm/yyyy'),7,4))-1;
    w_fper_pre := to_date(substr(to_char(w_fper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_fannee),'dd/mm/yyyy');
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk

--dbms_output.put_line('w_annee '||to_char(w_annee));
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;


    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;

    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

    w_faitout := pae_tabtmp;
    ---partielle
   -- w_coddes := w_secfin;
   -- w_codets := w_etbfin;
   -- w_ets := w_etbfin;
--------
   for wetsdes in ( select distinct a.codets, a.coddes from cp_ecr_ana a
                  where a.cdos = wcdos and a.numaxe = w_axe
                  and a.codets between nvl(w_etbdeb,a.codets) and nvl(w_etbfin,'ZZZ')
                  and a.coddes between nvl(w_secdeb,a.coddes) and nvl(w_secfin,'ZZZZZZZZ')
                  order by a.codets, a.coddes)
                  LOOP     -- Plage des critères entrés au niveau du lanceur

                     w_coddes := wetsdes.coddes;
                     w_codets := wetsdes.codets;
                     w_ets := wetsdes.codets;

--------
--dbms_output.put_line('w_ets '||w_ets);
--dbms_output.put_line('w_coddes '||w_coddes);
--dbms_output.put_line('w_page '||w_page);
--dbms_output.put_line('w_numord_edi '||w_numord_edi);

    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT distinct a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;
    IF w_coddes IS NOT NULL AND w_coddes <> '        ' THEN
          SELECT libdes INTO des_lib FROM cp_des
        WHERE cdos = wcdos AND coddes = RTRIM(w_coddes);
    ELSE
     des_lib := ' ';
    END IF;

    w_ndec  :=   wdos.nddd;
--dbms_output.put_line('ets lib '||ets_lib);



--    w_nblg  :=   66;

--    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := gen_ar;
--dbms_output.put_line('gen_ar');

--dbms_output.put_line('w_ndec '||to_char(w_ndec));
    larg_ed             := 156;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,154) || ver;
    w_l3                := ver || RPAD(' ',154) || ver;
    w_l4                := SUBSTR(w_l3,1,9) ||
                           ver || SUBSTR(w_l3,11,30) ||
                           ver || SUBSTR(w_l3,42,13) ||
                           ver || SUBSTR(w_l3,56,13) ||
                           ver || SUBSTR(w_l3,70,13) ||
                           ver || SUBSTR(w_l3,84,13) ||
                           ver || SUBSTR(w_l3,98,13) ||
                           ver || SUBSTR(w_l3,112,13) ||
                           ver || SUBSTR(w_l3,126,13) ||
                           ver || SUBSTR(w_l3,140,15) || ver;

    w_numord_edi := 0;

--dbms_output.put_line('w_numordedi '||to_char(w_numord_edi));

    FOR indi IN 1..9
    LOOP
       clcum_c1(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       clcum_c5(indi)  := 0;
       clcum_c6(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;
   IF ar_list%ISOPEN THEN
    CLOSE ar_list;
  END IF;
    OPEN ar_list;
    LOOP
        FETCH ar_list INTO wpae;
        EXIT WHEN ar_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_ar_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_ar_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_ar_03;
            ELSIF wpae.codope = '04' THEN w_faitout := func_ar_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_ar_30;
            ELSIF wpae.codope = '31' THEN w_faitout := func_ar_31;
            ELSIF wpae.codope = '34' THEN w_faitout := func_ar_03;
                                          w_faitout := func_ar_30;
                                          w_faitout := func_ar_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_ar_03;
                                          w_faitout := func_ar_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_ar_40;
        END IF;

    END LOOP;
    CLOSE ar_list;
            END LOOP;   -- Pour la plage
    --w_faitout := ed_tmp_fic(w_led);

--EXCEPTION
-- when others then
 --  wmessage := substr('Erreur '||to_char(error_code)||error_text,1,100);
-- RAISE ;
END ledar01;

----------------------- EDITION DE L'ENTETE  -----------------------------

FUNCTION func_ar_01 RETURN BOOLEAN
IS

BEGIN

--lk    IF NVL(arg1,'0') = '1' THEN arg1 := '0';
--lk                           ELSE arg1 := '1';
--lk    END IF;
    w_page  := w_page + 1;
    w_ligne := 0;
    arg1    := w_page;   --lk

    w_supl := 0;

--    arg1 := '1';
    arg2 := w_l1;
    w_faitout := up_tmp_ar;

--    arg1 := '0';
--    w_page        := w_page + 1;
--ii
    w_l5          := RPAD(ver,2) ||
                    'Societe       : ' || wdos.cdos || '  ' ||
                     RPAD(wdos.nred,121) || 'Page' ||
                     TO_CHAR(w_page, '9999') || LPAD(ver,4);
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       w_l5          := RPAD(ver,2) ||
                       'Etablissement : ' || LPAD(w_ets,3) || ' ' ||
                        RPAD(ets_lib,133) || ver;
       arg2          := w_l5;
       w_faitout := up_tmp_ar;
    END IF;
      IF w_coddes is not null and w_coddes <> '        ' THEN
        w_l5          := RPAD(ver,2) || 'Sect. : '|| w_coddes ||' '||RPAD(des_lib,30);
      ELSE
          w_l5          := RPAD(ver,2) || RPAD(' ',47) ;
      END IF;

          w_l5       := substr(w_l5,1,49) || LPAD(w_titre,31)|| RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),4,7),29) ||' Periode du ' ||
                     TO_CHAR(w_dper, 'dd-mm-yyyy') || ' au ' ||
                     TO_CHAR(w_fper, 'dd-mm-yyyy') ||
                     LPAD(ver,11);
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    w_supl := 0;
    w_l5          := RPAD(ver,2) ||
                    'Edite le ' || TO_CHAR(sysdate, 'dd-mm-yyyy "a" hh:mi:ss') ||
                     LPAD('Util. : ',119) || w_cuti || LPAD(ver,1);
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    arg2          := w_l1;
    w_faitout := up_tmp_ar;
    --

    w_l5          := substr(w_l4,1,41) ||
                     LPAD(RPAD('ANNEE  EN  COURS',42),69)||ver||
                     LPAD(RPAD('ANNEE  PRECEDENTE',22),27)||substr(w_l4,139,18);

    arg2          := w_l5;
    w_faitout := up_tmp_ar;


    w_l5          := substr(w_l4,1,41) ||substr(w_l2,42,115);
    arg2          := w_l5;
    w_faitout := up_tmp_ar;


    --
    w_l5          := substr(w_l4,1,41) ||
                     LPAD(RPAD('SOLDE A FIN',12),13) ||
                     substr(w_l4,55,15) ||
                     LPAD(RPAD('SOLDE A FIN',12),13) ||
                   ver || RPAD(RPAD('BUDGET A FIN',12),13) ||
                     substr(w_l4,97,15) ||
                     LPAD(RPAD('SOLDE A FIN',12),13) ||
                     substr(w_l4,125,15) ||
                     LPAD(RPAD('MOIS DE',12),16) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    --
    w_l5          := ver ||LPAD(RPAD('COMPTE',7),8) ||ver || LPAD(RPAD('INTITULE',20),30) ||ver||
                      LPAD(RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),4,7),10),13) || ver||
                      LPAD(RPAD('ECART',9),13) ||
                     ver || LPAD(RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),4,7),10),13) ||
                     ver || LPAD(RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),4,7),10),13) ||
                     ver || LPAD(RPAD('ECART',9),13) ||
                     ver || LPAD(RPAD(substr(to_char(w_fper_pre,'dd/mm/yyyy'),4,7),10),13) ||
                     ver || LPAD(RPAD('ECART',9),13) ||
                     ver || LPAD(RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),4,7),12),16) ||
                     ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;


    w_l5          := substr(w_l4,1,69) || LPAD(RPAD('REVISE',10),13) ||
                     substr(w_l4,83,29) || LPAD(RPAD('REVISE',10),13) ||
                     substr(w_l4,125,32) ;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    w_l5          := substr(w_l4,1,41) || LPAD(RPAD('A',7),13) ||
                     ver || LPAD(RPAD('B',7),13)|| ver ||LPAD(RPAD('C = A + B',11),13) ||
                     ver || LPAD(RPAD('D',7),13)|| ver ||LPAD(RPAD('E = C - D',11),13) ||
                     ver || LPAD(RPAD('F',7),13)|| ver ||LPAD(RPAD('G = C - F',11),13) ||
                     ver || LPAD(RPAD('H',7),16)||ver;

    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    arg2          := w_l1;
    w_faitout := up_tmp_ar;

   -- arg2          := w_l4;
   -- w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_01;

----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_ar_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5          := RPAD(ver,12) || wpae.typope || LPAD(ver,89) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_ar;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_ar_02;

----------------------- EDITION D'UNE LIGNE DE TIRETS  -------------------
FUNCTION func_ar_03 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l2;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_03;

----------------------- EDITION D'UNE LIGNE ESPACE     -------------------
FUNCTION func_ar_04 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l4;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_04;

---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_ar_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.sofina := clcum_c1(p1);
       cpcum.ecartb := clcum_c5(p1);
       cpcum.sofinc := cpcum.sofina + cpcum.ecartb;
       cpcum.bdfind := clcum_c4(p1);
       cpcum.ecarte := cpcum.sofinc - cpcum.bdfind;
       cpcum.sofinf := clcum_c3(p1);
       cpcum.ecartg := cpcum.sofinc - cpcum.sofinf;
       cpcum.smoish := clcum_c2(p1);
        w_faitout := detail_ar(' ',wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_30;


FUNCTION func_ar_31 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.sofina := clcum_c1(p1)/w_nmois;
       cpcum.ecartb := 0;
       cpcum.sofinc := 0;
       cpcum.bdfind := 0;
       cpcum.ecarte := 0;
       cpcum.sofinf := 0;
       cpcum.ecartg := 0;
       cpcum.smoish := 0;

        w_faitout := detail_ar(' ',wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_31;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_ar_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
             and cp_res.numsec = w_coddes
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
   IF cur_wselres%ISOPEN THEN
    CLOSE cur_wselres;
  END IF;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        IF p2 != 0 THEN
             wedit          := 2;
             w_cum_solde_db := wres.mnt1 - wres.mnt2;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 AND wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 4 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 OR wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit = 1     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                  clcum_c1(wi)  := clcum_c1(wi) + wres.mnt1 - wres.mnt2;
                  clcum_c2(wi)  := clcum_c2(wi) + wres.mnt3 - wres.mnt4;
                  clcum_c3(wi)  := clcum_c3(wi) + wres.mnt5 - wres.mnt6;
                  clcum_c4(wi)  := clcum_c4(wi) + wres.mnt7 - wres.mnt8;
                  clcum_c5(wi)  := clcum_c5(wi) + wres.mnt9 - wres.mnt10;
                  w_cum_solde_db := wres.mnt3 - wres.mnt4;
                                 END IF;
           END LOOP;
        END IF;

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.sofina    :=  wres.mnt1 - wres.mnt2;
           cpcum.ecartb    :=  wres.mnt9 - wres.mnt10;
           cpcum.sofinc  :=  cpcum.sofina + cpcum.ecartb;
           cpcum.bdfind    :=  wres.mnt7 - wres.mnt8;
           cpcum.ecarte    :=  cpcum.sofinc - cpcum.bdfind;
           cpcum.sofinf    :=  wres.mnt5 - wres.mnt6;
           cpcum.ecartg    :=  cpcum.sofinc - cpcum.sofinf;
           cpcum.smoish    :=  wres.mnt3 - wres.mnt4;
     --   dbms_output.put_line(wres.numcpt||'    '||to_char(cpcum.sofina));
           w_faitout := detail_ar(wres.numcpt,wres.libe);
        END IF;

    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
EXCEPTION
 when others then RAISE;
END func_ar_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_ar(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2) RETURN BOOLEAN
IS

BEGIN

    w_l5      := ver || RPAD(ed_numcpt,8) ||ver ||
                        RPAD(ed_intr,30) || SUBSTR(w_l4,41,116);

    mtf := numfs(cpcum.sofina,w_ndec);
  --  dbms_output.put_line(wres.numcpt||' sofina   '||to_char(cpcum.sofina)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.sofina != 0 THEN
    --dbms_output.put_line(w_l5);
       w_l5   := SUBSTR(w_l5,1,41) || mtf || substr(w_l5,55,101);
    --dbms_output.put_line('fin');
    END IF;
    mtf := numfs(cpcum.ecartb,w_ndec);
  --  dbms_output.put_line(wres.numcpt||'  ecartb  '||to_char(cpcum.ecartb)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.ecartb != 0 THEN
       w_l5   := SUBSTR(w_l5,1,55) || mtf || substr(w_l5,69,87);
    END IF;
    mtf := numfs(cpcum.sofinc,w_ndec);
   -- dbms_output.put_line(wres.numcpt||'  sofinc  '||to_char(cpcum.sofinc)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.sofinc != 0 THEN
       w_l5   := SUBSTR(w_l5,1,69) || mtf || substr(w_l5,83,73);
    END IF;
    mtf := numfs(cpcum.bdfind,w_ndec);
   -- dbms_output.put_line(wres.numcpt||'  bdfind  '||to_char(cpcum.bdfind)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.bdfind != 0 THEN
       w_l5   := SUBSTR(w_l5,1,83) || mtf || substr(w_l5,97,59);
    END IF;
    mtf := numfs(cpcum.ecarte,w_ndec);
   -- dbms_output.put_line(wres.numcpt||'  ecarte  '||to_char(cpcum.ecarte)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.ecarte != 0 THEN
       w_l5   := SUBSTR(w_l5,1,97) || mtf || substr(w_l5,111,45);
    END IF;
    mtf := numfs(cpcum.sofinf,w_ndec);
   -- dbms_output.put_line(wres.numcpt||'  sofinf  '||to_char(cpcum.sofinf)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.sofinf != 0 THEN
       w_l5   := SUBSTR(w_l5,1,111) || mtf || substr(w_l5,125,31);
    END IF;
    mtf := numfs(cpcum.ecartg,w_ndec);
   -- dbms_output.put_line(wres.numcpt||' ecartg   '||to_char(cpcum.ecartg)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.ecartg != 0 THEN
       w_l5   := SUBSTR(w_l5,1,125) || mtf || substr(w_l5,139,17);
    END IF;
    mtf := numfs(cpcum.smoish,w_ndec);
    --dbms_output.put_line(wres.numcpt||' smoish   '||to_char(cpcum.smoish)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.smoish != 0 THEN
       w_l5   := SUBSTR(w_l5,1,139) || lpad(rpad(mtf,14),16) ;
    END IF;
    w_l5 := lpad(w_l5,155)||ver;
--    arg1           := 0;
    arg2           := w_l5;
    w_faitout := up_tmp_ar;
       -- dbms_output.put_line(wres.numcpt||'    '||to_char(cpcum.sofina)||'  '||to_char(w_ndec));

    RETURN TRUE;
END detail_ar;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_ar RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_ar_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_ar;
