----------------------- Calcul et MAJ des cumuls des comptes -------------

FUNCTION gen_ar RETURN BOOLEAN
IS

    CURSOR ar_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40' ORDER BY cdos,codeta,numord;

   CURSOR ar_cpt_list1 IS
         SELECT cdos,codnat, libnat from cp_nat
          WHERE cdos = wcdos
            AND codnat <= wpae.cptfin AND codnat >= wpae.cptdeb
	    and gesqte = 'N';
    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN

   IF ar_list1%ISOPEN THEN
    CLOSE ar_list1;
  END IF;
    OPEN ar_list1;
    LOOP
        FETCH ar_list1 INTO wpae;
        EXIT WHEN ar_list1%NOTFOUND;
   IF ar_cpt_list1%ISOPEN THEN
    CLOSE ar_cpt_list1;
  END IF;

        OPEN ar_cpt_list1;
        LOOP
            FETCH ar_cpt_list1 INTO wcpt.cdos, wcpt.codnat, wcpt.intcpt;
            EXIT WHEN ar_cpt_list1%NOTFOUND;

            continuer := false;
            begin

               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.codnat and cp_res.numsec = w_coddes;
             --     cp_res.numcpt = wcpt.numcpt;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := w_coddes;
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.mnt5      := 0;
            wres.mnt6      := 0;
            wres.mnt7      := 0;
            wres.mnt8      := 0;
            wres.mnt9      := 0;
            wres.mnt10      := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.codnat;
          --  if wpae.sel = 'I' then
          --    wres.libe      := wcpt.raccpt;
          --  else
              wres.libe      := wcpt.intcpt;
          --  end if;
            wres.sens      := 'X';
           -- wres.ctie      := substr(wpro.natcpt,1,1);
            w_cum_solde_cr := 0;
            w_cum_solde_db := 0;

         FOR wmvg IN
            (SELECT b.codjou, a.*
               FROM cp_ecr_ana a, cp_ecr b
              WHERE a.cdos =  wcdos AND
                    a.codnat = wcpt.codnat and
                    a.datcpt between w_dper_pre and w_fper
                    and a.codets = w_codets
                    and a.coddes = w_coddes
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w_fper_c
--                    and b.periode <= w_fper_c
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
		            and a.numaxe = w_axe
              ORDER BY a.cdos,a.codnat)
        LOOP

            CONTINUER := true;
            -- Dans le cas d'une balance de reouverture,
            -- seules les ecritures dont le code journal est egal au
            -- journal de cloture (dossier) sont prises en compte
--        IF w_reou = 'O' AND wmvg.codjou != wdos.dcjr THEN
--           CONTINUER := false;
--        END IF;

            -- Dans le cas d'une balance sur l'exercice suivant, si la
            -- "cloture simulee" (RAN) n'est pas demandee, seuls les
            -- mouvements >= date de debut de l'exercice suivant sont
            -- pris en compte
/*
            IF w_dper > wdos.dfex AND  w_ran = 'N' AND
               wmvg.datcpt < wdos.ddes THEN
               CONTINUER := false;
            END IF;
*/
            --  simulation de la cloture   :  cpt de gestion  = 0
            --             cpt de bilan    = solde au wdos.dfex (fin ex.)

--dbms_output.put_line (to_char(w_dper,'dd/mm/yyyy'));
--dbms_output.put_line (to_char(wdos.dfex,'dd/mm/yyyy'));
--dbms_output.put_line (to_char(wmvg.datcpt,'dd/mm/yyyy'));
--dbms_output.put_line (to_char(wdos.ddes,'dd/mm/yyyy'));
 /*           IF w_dper > wdos.dfex AND w_ran = 'O' AND wmvg.datcpt < wdos.ddes THEN
               IF wpro.codran = 'N' THEN
                  CONTINUER := false;
               END IF;
               if continuer then
               IF wmvg.sens = 'C' THEN
                    w_cum_solde_cr := w_cum_solde_cr + wmvg.grp_mtcr;
                    CONTINUER := false;
               ELSE w_cum_solde_db := w_cum_solde_db + wmvg.grp_mtdb;
                    CONTINUER := false;
               END IF;
               end if;
            END IF;
*/

             w_natjou := null;
             select NATJOU into w_natjou FROM CP_JOU
        				                WHERE CDOS = WCDOS
		      			                and codjou = wmvg.codjou;
            if continuer then
            IF  wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
             IF w_natjou != 'S' THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt1 := wres.mnt1 + wmvg.grp_mtdb;
               ELSE wres.mnt2 := wres.mnt2 + wmvg.grp_mtcr;
               END IF;
             ELSE
               IF wmvg.sens = 'D' THEN
                    wres.mnt9 := wres.mnt9 + wmvg.grp_mtdb;
               ELSE wres.mnt10 := wres.mnt10 + wmvg.grp_mtcr;
               END IF;

             END IF;
            END IF;
            -- Mois concerné
            IF substr(to_char(wmvg.datcpt,'dd/mm/yyyy'),4,7) = substr(to_char(w_fper,'dd/mm/yyyy'),4,7) THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt3 := wres.mnt3 + wmvg.grp_mtdb;
               ELSE wres.mnt4 := wres.mnt4 + wmvg.grp_mtcr;
               END IF;
            END IF;
            --période precedente
            IF wmvg.datcpt <= w_fper_pre AND wmvg.datcpt >= w_dper_pre THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt5 := wres.mnt5 + wmvg.grp_mtdb;
               ELSE wres.mnt6 := wres.mnt6 + wmvg.grp_mtcr;
               END IF;
            END IF;
            end if;
--dbms_output.put_line(wres.numcpt||' debit '||to_char(wmvg.grp_mtdb)||' Credit '||to_char(wmvg.grp_mtcr) );
         END LOOP;
         -- traitement du Budget
         If wcpt.codnat is not null then
            for wbud in
              ( select * from cp_buda
               where cdos = wcdos
                 and numaxe = w_axe
                 and codets = w_codets
                 and coddes = w_coddes
                 and codnat = wcpt.codnat
                 and periode between w_dper_c and w_fper_c)
               LOOP
                  IF wbud.sens = 'D' THEN
                    wres.mnt7 := wres.mnt7 + wbud.dos_mtbu;
                  ELSE wres.mnt8 := wres.mnt8 + wbud.dos_mtbu;
               END IF;

               END LOOP;
         END IF;

--dbms_output.put_line(wres.numcpt||' mnt1 '||to_char(wres.mnt1)||' mnt2 '||
--to_char(wres.mnt2)||' mnt3 '||to_char(wres.mnt3)||' mnt4 '||to_char(wres.mnt4)
--||' mnt5 '||to_char(wres.mnt5)||' mnt6 '||to_char(wres.mnt6)||' mnt7 '||to_char(wres.mnt7)
--||' mnt8 '||to_char(wres.mnt8)||' mnt9 '||to_char(wres.mnt9)||' mnt10 '||to_char(wres.mnt10));


	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
	                    w_session_id);   --lk
         commit; --lk

      END IF;
      END LOOP;
      CLOSE ar_cpt_list1;
   END LOOP;
   CLOSE ar_list1;
   RETURN TRUE;
EXCEPTION
 when others then RAISE;
END gen_ar;


