      clcum_c6(p1) := 0;
      clcum_c7(p1) := 0;
      clcum_c8(p1) := 0;
   END IF;
   IF p2 != 0     THEN
      clcum_c1(p2) := 0;
      clcum_c2(p2) := 0;
      clcum_c3(p2) := 0;
      clcum_c4(p2) := 0;
