      clcum_c3(p3) := 0;
      clcum_c4(p3) := 0;
      clcum_c5(p3) := 0;
      clcum_c6(p3) := 0;
      clcum_c7(p3) := 0;
      clcum_c8(p3) := 0;
   END IF;
   IF p4 != 0     THEN
      clcum_c1(p4) := 0;
      clcum_c2(p4) := 0;
      clcum_c3(p4) := 0;
      clcum_c4(p4) := 0;
      clcum_c5(p4) := 0;
      clcum_c6(p4) := 0;
      clcum_c7(p4) := 0;
      clcum_c8(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_10;

-----------------------  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_11 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0   THEN
      cpt_mjcum(p1) := 1;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 1;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 1;
   END IF;
   IF p4 != 0   THEN
