FUNCTION func_pae_13 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0   THEN
      cpt_mjcum(p1) := 0;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 0;
   END IF;
   IF p3 != 0   THEN
