CREATE PACKAGE BODY cpbilpp
AS


-------------------------------------------------------------------------------
-- Edition du bilan passif
-------------------------------------------------------------------------------

   wcpt          cp_cpt%ROWTYPE;
   wpro          cp_pro%ROWTYPE;
--   wmvg          cp_ecr_ana%ROWTYPE;

   TYPE cpcum_type IS RECORD     -- zone de cumul compte
   (
     cour        NUMBER(15,3),
     prec        NUMBER(15,3)
   );
   cpcum         cpcum_type;


   TYPE w_reg_sec_type IS TABLE OF VARCHAR2(1) INDEX BY BINARY_INTEGER;
   -- w_reg_sec     w_reg_sec_type;

   --sk
   w_ecr_non_maj VARCHAR2(1);
   w_exe_prec    VARCHAR2(1);
   w_sim         VARCHAR2(1);
   w_per_comp    VARCHAR2(1);
   w_rg_dev      VARCHAR2(1);
   w_dper_c      VARCHAR2(3);
   w_fper_c      VARCHAR2(3);
   w_dannee      NUMBER(4);
   w_fannee      NUMBER(4);
   w_dper_pre    DATE;
   w_fper_pre    DATE;
   w_exercice    VARCHAR2(3);
   w_session_id  NUMBER;
   --fin sk

   w_titre       VARCHAR2(30);
   w_dper        DATE;
   w_fper        DATE;
   w_date        DATE;
   w_ddex        DATE;
   w_reou        VARCHAR2(1);
   w_ran         VARCHAR2(1);
   w_reed        VARCHAR2(1);
   w_psec        CHAR(8);
   w_dsec        CHAR(8);
   w_section     VARCHAR2(8);
   w_ndec        NUMBER;
   w_ligne       NUMBER;
   w_numord_edi  NUMBER;
   w_page        NUMBER;
   w_nblg        NUMBER;
   w_maxlg       NUMBER;
   wi            NUMBER;
   larg_ed       NUMBER;
   w_cum_solde_p_db  NUMBER(15,3);
   w_cum_solde_c_db  NUMBER(15,3);
   w_cuti        VARCHAR2(4);

   w_ets         VARCHAR2(3);
   w_axa         VARCHAR2(1);
   sel_ets       cp_ets.codets%TYPE;
   ets_lib       VARCHAR2(30);

   sauv_supl     NUMBER;
   w_supl        NUMBER;
   lig_as        VARCHAR2(1);

-------------------------------------------------------------------------------

PROCEDURE ledbilp01 (woptions IN VARCHAR2)
IS

    CURSOR bip_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN
--  lecture des parametres d'edition

    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);

    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_ets         := rtrim(substr(woptions,16,3));
    w_session_id  := to_number(substr(woptions,19,38));
    w_ecr_non_maj := substr(woptions,57,1);
    w_exe_prec    := substr(woptions,58,1);



    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
    -- excercice précédent
    w_dannee := to_number(substr(to_char(w_dper,'dd/mm/yyyy'),7,4))-1;
    w_dper_pre := to_date(substr(to_char(w_dper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_dannee),'dd/mm/yyyy');
    w_fannee := to_number(substr(to_char(w_fper,'dd/mm/yyyy'),7,4))-1;
    w_fper_pre := to_date(substr(to_char(w_fper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_fannee),'dd/mm/yyyy');

--dbms_output.enable(50000);
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;

--dbms_output.put_line('sec ID'||to_char(w_session_ID));
--dbms_output.put_line('bala'||w_bala);
--dbms_output.put_line('C uti'||w_cuti);
--dbms_output.put_line('deb per'||to_char(w_dper));
--dbms_output.put_line('fin per'||to_char(w_fper));
    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;

    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := bip_maj_cpt;
--dbms_output.put_line('gen_bg');
/*
    larg_ed             := 136;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,134) || ver;
    w_l3                := ver || RPAD(' ',134) || ver;

    w_l4                := SUBSTR(w_l3,1,42) ||
                           ver || SUBSTR(w_l3,44,46) ||
                           ver || SUBSTR(w_l3,91,46) ;
                          -- ver || SUBSTR(w_l3,98,39);
                           --ver || SUBSTR(w_l3,106,30) || ver;
*/
    larg_ed             := 127;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,125) || ver;
    w_l3                := ver || RPAD(' ',125) || ver;

    w_l4                := SUBSTR(w_l3,1,42) ||
                           ver || SUBSTR(w_l3,44,46) ||
                           ver || SUBSTR(w_l3,91,37) ;
                          -- ver || SUBSTR(w_l3,98,39);
                           --ver || SUBSTR(w_l3,106,30) || ver;

    w_numord_edi := 0;

    FOR indi IN 1..9
    LOOP
       clcum_c1(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       clcum_c5(indi)  := 0;
       clcum_c6(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;

    OPEN bip_list;
    LOOP
        FETCH bip_list INTO wpae;
        EXIT WHEN bip_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_bip_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_bip_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_bip_03;
           -- ELSIF wpae.codope = '04' THEN w_faitout := func_bg_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_bip_30;
            ELSIF wpae.codope = '34' THEN w_faitout := func_bip_03;
                                          w_faitout := func_bip_30;
                                          w_faitout := func_bip_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_bip_03;
                                          w_faitout := func_bip_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_bip_40;
         --   ELSIF wpae.codope = '41' THEN w_faitout := func_bip_40;
        END IF;

    END LOOP;
    CLOSE bip_list;

END ledbilp01;

