PROCEDURE ledar01 (woptions IN VARCHAR2)
IS

    CURSOR ar_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN

--  lecture des parametres d'edition dans le fichier evlanc
-- i

dbms_output.enable(50000);

dbms_output.put_line('debut ');
    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);
    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_ets         := rtrim(substr(woptions,16,3));
    w_secdeb         := rtrim(substr(woptions,19,8));
    w_secfin         := rtrim(substr(woptions,27,8));
    w_rg_dev	  := substr(woptions,35,1);
    w_ecr_non_maj := substr(woptions,36,1);
    w_axe	  := to_number(substr(woptions,37,1));
    w_session_id  := to_number(substr(woptions,38,38));

    W_REG1	  := substr(woptions,76,1);
    W_REG2	  := substr(woptions,77,1);
    W_REG3	  := substr(woptions,78,1);
    W_REG4	  := substr(woptions,79,1);
    W_REG5	  := substr(woptions,80,1);
    W_REG6	  := substr(woptions,81,1);
    W_REG7	  := substr(woptions,82,1);
    W_REG8	  := substr(woptions,83,1);

dbms_output.put_line('w_sess '||woptions);
--dbms_output.put_line(' w_cdos '||w_etbdeb);

   w_nmois := to_number(w_fper_c) - to_number(w_dper_c) + 1;

    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

 IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;
dbms_output.put_line('sel_ets '||sel_ets);

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
dbms_output.put_line('w_fper '||to_char(w_fper));
    -- excercice précédent
    w_annee := to_number(substr(to_char(w_fper,'dd/mm/yyyy'),7,4))-1;
    w_dper_pre := to_date(substr(to_char(w_dper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_annee),'dd/mm/yyyy');
    w_fper_pre := to_date(substr(to_char(w_fper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_annee),'dd/mm/yyyy');
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk

dbms_output.put_line('w_annee '||to_char(w_annee));
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;


    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;

    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

    w_faitout := pae_tabtmp;
    ---partielle
   -- w_coddes := w_secfin;
   -- w_codets := w_etbfin;
   -- w_ets := w_etbfin;
--------
   IF w_reg8 = 'N' THEN
	w_nord := 8;
   ELSIF w_reg7 = 'N' THEN
	w_nord := 7;
   ELSIF w_reg6 = 'N' THEN
	w_nord := 6;
   ELSIF w_reg5 = 'N' THEN
	w_nord := 5;
   ELSIF w_reg4 = 'N' THEN
	w_nord := 4;
   ELSIF w_reg3 = 'N' THEN
	w_nord := 3;
   ELSIF w_reg2 = 'N' THEN
	w_nord := 2;
   ELSIF w_reg1 = 'N' THEN
	w_nord := 1;
   ELSE
	w_nord := 0;
   END IF;

dbms_output.put_line('w_nord '||w_nord);

   for wetsdes in ( select distinct
decode(w_reg1,'O','0',substr(a.coddes,1,1))||
decode(w_reg2,'O','0',substr(a.coddes,2,1))||
decode(w_reg3,'O','0',substr(a.coddes,3,1))||
decode(w_reg4,'O','0',substr(a.coddes,4,1))||
decode(w_reg5,'O','0',substr(a.coddes,5,1))||
decode(w_reg6,'O','0',substr(a.coddes,6,1))||
decode(w_reg7,'O','0',substr(a.coddes,7,1))||
decode(w_reg8,'O','0',substr(a.coddes,8,1)) coddes
                  from cp_ecr_ana a
                  where a.cdos = wcdos and a.numaxe = w_axe
                    AND a.codets LIKE sel_Ets
                  and a.coddes between nvl(w_secdeb,a.coddes) and nvl(w_secfin,'ZZZZZZZZ')
                  order by
decode(w_reg1,'O','0',substr(a.coddes,1,1))||
decode(w_reg2,'O','0',substr(a.coddes,2,1))||
decode(w_reg3,'O','0',substr(a.coddes,3,1))||
decode(w_reg4,'O','0',substr(a.coddes,4,1))||
decode(w_reg5,'O','0',substr(a.coddes,5,1))||
decode(w_reg6,'O','0',substr(a.coddes,6,1))||
decode(w_reg7,'O','0',substr(a.coddes,7,1))||
decode(w_reg8,'O','0',substr(a.coddes,8,1)) )
                  LOOP     -- Plage des critères entrés au niveau du lanceur

--dbms_output.put_line('w_ets '||w_ets);
                     w_coddes := wetsdes.coddes;
                     w_des := substr(wetsdes.coddes,1,w_nord)||'%';
                    -- w_codets := sel_Ets;
                    -- w_ets := sel_Ets;

--------
dbms_output.put_line('w_ets '||w_ets);
dbms_output.put_line('w_coddes '||w_coddes);
--dbms_output.put_line('w_page '||w_page);
--dbms_output.put_line('w_numord_edi '||w_numord_edi);

    IF w_coddes IS NOT NULL AND w_coddes <> '        ' THEN
       begin
          SELECT libdes INTO des_lib FROM cp_des
        WHERE cdos = wcdos AND coddes = RTRIM(w_coddes);
      exception
