        des_lib := 'Section inconnue';
	end ;
    ELSE
     des_lib := ' ';
    END IF;

    w_ndec  :=   wdos.nddd;
--dbms_output.put_line('ets lib '||ets_lib);



--    w_nblg  :=   66;

--    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := gen_ar;
--dbms_output.put_line('gen_ar');

--dbms_output.put_line('w_ndec '||to_char(w_ndec));
    larg_ed             := 156;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,154) || ver;
    w_l3                := ver || RPAD(' ',154) || ver;
    w_l4                := SUBSTR(w_l3,1,9) ||
                           ver || SUBSTR(w_l3,11,30) ||
                           ver || SUBSTR(w_l3,42,13) ||
                           ver || SUBSTR(w_l3,56,13) ||
                           ver || SUBSTR(w_l3,70,13) ||
                           ver || SUBSTR(w_l3,84,13) ||
                           ver || SUBSTR(w_l3,98,13) ||
                           ver || SUBSTR(w_l3,112,13) ||
                           ver || SUBSTR(w_l3,126,13) ||
                           ver || SUBSTR(w_l3,140,15) || ver;

    w_numord_edi := 0;

--dbms_output.put_line('w_numordedi '||to_char(w_numord_edi));

    FOR indi IN 1..9
    LOOP
       clcum_c1(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       clcum_c5(indi)  := 0;
       clcum_c6(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;
   IF ar_list%ISOPEN THEN
    CLOSE ar_list;
  END IF;
    OPEN ar_list;
    LOOP
        FETCH ar_list INTO wpae;
        EXIT WHEN ar_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_ar_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_ar_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_ar_03;
            ELSIF wpae.codope = '04' THEN w_faitout := func_ar_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_ar_30;
            ELSIF wpae.codope = '31' THEN w_faitout := func_ar_31;
            ELSIF wpae.codope = '34' THEN w_faitout := func_ar_03;
                                          w_faitout := func_ar_30;
                                          w_faitout := func_ar_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_ar_03;
                                          w_faitout := func_ar_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_ar_40;
        END IF;

    END LOOP;
    CLOSE ar_list;
            END LOOP;   -- Pour la plage
    --w_faitout := ed_tmp_fic(w_led);

--EXCEPTION
-- when others then
 --  wmessage := substr('Erreur '||to_char(error_code)||error_text,1,100);
