----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_ar_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5          := RPAD(ver,12) || wpae.typope || LPAD(ver,89) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_ar;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_ar_02;

