FUNCTION func_ar_03 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l2;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_03;

----------------------- EDITION D'UNE LIGNE ESPACE     -------------------
FUNCTION func_ar_04 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l4;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_04;

---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_ar_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.budga := clcum_c1(p1);
       cpcum.realb := clcum_c2(p1);
       cpcum.ecara := cpcum.budga - cpcum.realb;
     if cpcum.realb != 0 then
       cpcum.ecarb := cpcum.budga / cpcum.realb;
     end if;
       cpcum.budgc := clcum_c3(p1);
       cpcum.reald := clcum_c4(p1);
       cpcum.ecarc := cpcum.budgc - cpcum.reald;
    if cpcum.reald != 0 then
       cpcum.ecard := cpcum.budgc / cpcum.reald;
    end if;
        w_faitout := detail_ar(' ',wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_30;


FUNCTION func_ar_31 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.budga := clcum_c1(p1)/w_nmois;
       cpcum.realb := clcum_c2(p1)/w_nmois;
       cpcum.ecara := cpcum.budga-cpcum.realb;
     if cpcum.realb != 0 then
        cpcum.ecarb := cpcum.budga /cpcum.realb;
     end if;
       cpcum.budgc := clcum_c3(p1)/w_nmois;
       cpcum.reald := clcum_c4(p1)/w_nmois;
       cpcum.ecarc := cpcum.budgc-cpcum.reald;
     if cpcum.reald != 0 then
        cpcum.ecard := cpcum.budgc/cpcum.reald;
     end if;

        w_faitout := detail_ar(' ',wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_31;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_ar_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
             and cp_res.numsec = w_coddes
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
   IF cur_wselres%ISOPEN THEN
    CLOSE cur_wselres;
  END IF;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        IF p2 != 0 THEN
             wedit          := 2;
             w_cum_solde_db := wres.mnt1 - wres.mnt2;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 AND wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 4 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 OR wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit = 1     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                  clcum_c1(wi)  := clcum_c1(wi) + wres.mnt7 - wres.mnt8;
                  clcum_c2(wi)  := clcum_c2(wi) + wres.mnt1 - wres.mnt2;
                  clcum_c3(wi)  := clcum_c3(wi) + wres.mnt5 - wres.mnt6;
                  clcum_c4(wi)  := clcum_c4(wi) + wres.mnt3 - wres.mnt4;
                  w_cum_solde_db := wres.mnt1 - wres.mnt2;
                                 END IF;
           END LOOP;
        END IF;

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.budga    :=  wres.mnt7 - wres.mnt8;
           cpcum.realb    :=  wres.mnt1 - wres.mnt2;
           cpcum.ecara  :=  cpcum.budga - cpcum.realb;
          if cpcum.realb != 0 then
           cpcum.ecarb    :=  cpcum.budga / cpcum.realb;
          end if;
           cpcum.budgc    :=  wres.mnt5 - wres.mnt6;
           cpcum.reald    :=  wres.mnt3 - wres.mnt4;
           cpcum.ecarc    :=  cpcum.budgc - cpcum.reald;
          if cpcum.reald != 0 then
           cpcum.ecard    :=  cpcum.budgc / cpcum.reald;
	  end if;
     --   dbms_output.put_line(wres.numcpt||'    '||to_char(cpcum.sofina));
           w_faitout := detail_ar(wres.numcpt,wres.libe);
        END IF;

    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
EXCEPTION
 when others then RAISE;
END func_ar_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_ar(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2) RETURN BOOLEAN
IS

BEGIN

    w_l5      := ver || RPAD(ed_numcpt,8) ||ver ||
                        RPAD(ed_intr,30) || SUBSTR(w_l4,41,116);

    mtf := numfs(cpcum.budga,w_ndec);
    IF cpcum.budga != 0 THEN
       w_l5   := SUBSTR(w_l5,1,41) || mtf || substr(w_l5,55,101);
    END IF;
    mtf := numfs(cpcum.realb,w_ndec);
    IF cpcum.realb != 0 THEN
       w_l5   := SUBSTR(w_l5,1,55) || mtf || substr(w_l5,69,87);
    END IF;
    mtf := numfs(cpcum.ecara,w_ndec);
    IF cpcum.ecara != 0 THEN
       w_l5   := SUBSTR(w_l5,1,69) || mtf || substr(w_l5,83,73);
    END IF;
    mtf := numfs(cpcum.ecarb,2);
    IF cpcum.ecarb != 0 THEN
       w_l5   := SUBSTR(w_l5,1,83) || mtf || substr(w_l5,97,59);
    END IF;
    mtf := numfs(cpcum.budgc,w_ndec);
    IF cpcum.budgc != 0 THEN
       w_l5   := SUBSTR(w_l5,1,97) || mtf || substr(w_l5,111,45);
    END IF;
    mtf := numfs(cpcum.reald,w_ndec);
    IF cpcum.reald != 0 THEN
       w_l5   := SUBSTR(w_l5,1,111) || mtf || substr(w_l5,125,31);
    END IF;
    mtf := numfs(cpcum.ecarc,w_ndec);
    IF cpcum.ecarc != 0 THEN
       w_l5   := SUBSTR(w_l5,1,125) || mtf || substr(w_l5,139,17);
    END IF;
    mtf := numfs(cpcum.ecard,2);
    --dbms_output.put_line(wres.numcpt||' smoish   '||to_char(cpcum.smoish)||'  '||to_char(w_ndec)||mtf);
    IF cpcum.ecard != 0 THEN
       w_l5   := SUBSTR(w_l5,1,139) || lpad(rpad(mtf,14),16) ;
    END IF;
    w_l5 := lpad(w_l5,155)||ver;
--    arg1           := 0;
    arg2           := w_l5;
    w_faitout := up_tmp_ar;
       -- dbms_output.put_line(wres.numcpt||'    '||to_char(cpcum.sofina)||'  '||to_char(w_ndec));

    RETURN TRUE;
END detail_ar;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_ar RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_ar_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_ar;
