FUNCTION numfs(mt IN NUMBER, ndc IN NUMBER) RETURN VARCHAR2
IS

BEGIN

   IF      ndc  = 3 THEN mtf := TO_CHAR(mt, '99999990D000');
   ELSIF   ndc  = 2 THEN mtf := TO_CHAR(mt, '999999990D00');
   ELSIF   ndc  = 1 THEN mtf := TO_CHAR(mt, '9999999990.0');
   ELSE                  mtf := TO_CHAR(mt, '9999G999G990');
   END IF;

   RETURN mtf;

END numfs;

