---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_cex_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.cour := clcum_c1(p1);
      -- w_faitout := detail_cex(' ',wpae.typope,wpae.bil1);
       w_faitout := detail_cex(' ',wpae.typope,NULL);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_cex_30;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_cex_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        w_cum_solde_c_db := nvl(wres.mnt1,0) - nvl(wres.mnt2,0);
        w_cum_solde_p_db := nvl(wres.mnt3,0) - nvl(wres.mnt4,0);

        IF p2 != 0 THEN
             wedit          := 2;
             w_cum_solde_db := nvl(wres.mnt1,0) - nvl(wres.mnt2,0);
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 AND wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit != 2     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                  clcum_c1(wi)  := clcum_c1(wi) + w_cum_solde_c_db;
                  clcum_c2(wi)  := clcum_c2(wi) + w_cum_solde_p_db;
               end if;
           END LOOP;
        END IF;
  -- dbms_output.put_line('wedit '||wedit||' p1 '||p1||' p2 '||p2);

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.cour    :=  w_cum_solde_c_db;
           cpcum.prec    :=  w_cum_solde_p_db;
           w_faitout := detail_cex(wres.numcpt,wres.libe,NULL);
       END IF;
    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_cex_40;



----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_cex(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2, ed_bil1 VARCHAR2) RETURN BOOLEAN
IS

BEGIN

    w_l5  := w_l4;
    w_l5  := substr(w_l5,1,2)||RPAD(ed_intr,34)||substr(w_l5,37,90);
    if ed_bil1 IS NOT NULL THEN
        w_l5 := substr(w_l5,1,39)||ed_bil1||substr(w_l5,42,85);
    END IF;
    mtf := numfs(cpcum.cour,w_ndec);
    w_l5 := substr(w_l5,1,55)||mtf||substr(w_l5,71,54);
     mtf := numfs(cpcum.prec,w_ndec);
   --?? w_l5 := substr(w_l5,1,91)||mtf||substr(w_l5,110,26);
    w_l5 := substr(w_l5,1,101)||RPAD(' ',9)||substr(w_l5,111,16);
    w_l5 := substr(w_l5,1,126)||ver;
--    arg1           := 0;
    arg2           := w_l5;
    w_faitout := up_tmp_cex;

    RETURN TRUE;
END detail_cex;
----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_cex RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_cex_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_cex;
----------------------- Calcul et MAJ des cumuls des comptes -------------
FUNCTION cex_maj_cpt RETURN BOOLEAN
IS

    CURSOR cex_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40'  ORDER BY cdos,codeta,numord;

   CURSOR cex_cpt_list1 IS
         SELECT a.cdos,a.numcpt,a.intcpt, b.natcpt
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;

    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN
    OPEN cex_list1;
    LOOP
        FETCH cex_list1 INTO wpae;
        EXIT WHEN cex_list1%NOTFOUND;

        OPEN cex_cpt_list1;
        LOOP
            FETCH cex_cpt_list1 INTO wcpt.cdos, wcpt.numcpt,
                  wcpt.intcpt, wpro.natcpt;
            EXIT WHEN cex_cpt_list1%NOTFOUND;

            continuer := false;
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.numcpt;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := '00000000';
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.numcpt;
            wres.libe      := wcpt.intcpt;
            wres.ctie      := substr(wpro.natcpt,1,1);
       --     w_cum_solde_cr := 0;
       --     w_cum_solde_db := 0;

         FOR wmvg IN
            (SELECT  a.*
               FROM cp_ecr_gen a, cp_ecr b
              WHERE a.cdos =  wcdos
                    AND a.numcpt = wcpt.numcpt
                    AND a.datcpt between w_dper AND w_fper
                    AND a.codets LIKE sel_Ets
                    AND b.cdos = a.cdos
                    AND b.numsai = a.numsai
                    AND
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
         --           AND b.codmaj = 'O'
              ORDER BY a.cdos,a.numcpt)
         LOOP

            CONTINUER := true;

            IF wmvg.sens = 'C' THEN
               wres.mnt2 := wres.mnt2 + wmvg.grp_mtcr;
            ELSE
               wres.mnt1 := wres.mnt1 + wmvg.grp_mtdb;
            end if;

            -- Exercice précédent ?
        --??    Wres.mnt3 := 0;
        -- ??   Wres.mnt4 := 0;

         END LOOP;

	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, 0, 0,
	                    0,0, 0, 0,
	                    0, 0, wres.sens, wres.ctie,
	                    w_session_id);   --lk

         commit; --lk
         END IF;
      END LOOP;
      CLOSE cex_cpt_list1;
   END LOOP;
   CLOSE cex_list1;

   RETURN TRUE;
END cex_maj_cpt;

----------------------- Creation des tables temporaires ------------------
FUNCTION pae_tabtmp RETURN BOOLEAN
IS

BEGIN

   DELETE FROM cp_edi where session_id = w_session_id;
   DELETE FROM cp_res where session_id = w_session_id;

   COMMIT;

   RETURN TRUE;

END pae_tabtmp;

----------------------- REMISE A ZERO D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_10 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0     THEN
      clcum_c1(p1) := 0;
      clcum_c2(p1) := 0;
      clcum_c3(p1) := 0;
      clcum_c4(p1) := 0;
      clcum_c5(p1) := 0;
      clcum_c6(p1) := 0;
      clcum_c7(p1) := 0;
      clcum_c8(p1) := 0;
   END IF;
   IF p2 != 0     THEN
      clcum_c1(p2) := 0;
      clcum_c2(p2) := 0;
      clcum_c3(p2) := 0;
      clcum_c4(p2) := 0;
      clcum_c5(p2) := 0;
      clcum_c6(p2) := 0;
      clcum_c7(p2) := 0;
      clcum_c8(p2) := 0;
   END IF;
   IF p3 != 0     THEN
      clcum_c1(p3) := 0;
      clcum_c2(p3) := 0;
      clcum_c3(p3) := 0;
      clcum_c4(p3) := 0;
      clcum_c5(p3) := 0;
      clcum_c6(p3) := 0;
      clcum_c7(p3) := 0;
      clcum_c8(p3) := 0;
   END IF;
   IF p4 != 0     THEN
      clcum_c1(p4) := 0;
      clcum_c2(p4) := 0;
      clcum_c3(p4) := 0;
      clcum_c4(p4) := 0;
      clcum_c5(p4) := 0;
      clcum_c6(p4) := 0;
      clcum_c7(p4) := 0;
      clcum_c8(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_10;

-----------------------  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_11 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0   THEN
      cpt_mjcum(p1) := 1;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 1;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 1;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 1;
   END IF;

   RETURN TRUE;

END func_pae_11;

---------------- RAZ  +  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_12 RETURN BOOLEAN
IS

BEGIN

   w_faitout := func_pae_10;
   w_faitout := func_pae_11;

   RETURN TRUE;

END func_pae_12;

----------------------  SUSPENSION D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_13 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0   THEN
      cpt_mjcum(p1) := 0;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 0;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 0;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_13;

----------------------  TRANSFERT DE P1 --> P2  -----------------------
FUNCTION func_pae_20 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1);
      clcum_c2(p2)  := clcum_c2(p1);
      clcum_c3(p2)  := clcum_c3(p1);
      clcum_c4(p2)  := clcum_c4(p1);
      clcum_c5(p2)  := clcum_c5(p1);
      clcum_c6(p2)  := clcum_c6(p1);
      clcum_c7(p2)  := clcum_c7(p1);
      clcum_c8(p2)  := clcum_c8(p1);
   END IF;

   RETURN TRUE;

END func_pae_20;

----------------------  TRANSFERT DE P1 + P2  --> P3  -----------------
FUNCTION func_pae_21 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) + clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) + clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) + clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) + clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) + clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) + clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) + clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) + clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_21;

---------------  P1 - P2 --> P3  -----------------------------------------------
FUNCTION func_pae_22 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) - clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) - clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) - clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) - clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) - clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) - clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) - clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) - clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_22;


---------------  TRANSFERT AVEC INVERSION DE SIGNE P1 --> P2  ------------------
FUNCTION func_pae_25 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1) * -1;
      clcum_c2(p2)  := clcum_c2(p1) * -1;
      clcum_c3(p2)  := clcum_c3(p1) * -1;
      clcum_c4(p2)  := clcum_c4(p1) * -1;
      clcum_c5(p2)  := clcum_c5(p1) * -1;
      clcum_c6(p2)  := clcum_c6(p1) * -1;
      clcum_c7(p2)  := clcum_c7(p1) * -1;
      clcum_c8(p2)  := clcum_c8(p1) * -1;
   END IF;

   RETURN TRUE;

END func_pae_25;


