CREATE PACKAGE BODY cpcexp
AS


-------------------------------------------------------------------------------
-- Edition du bilan passif
-------------------------------------------------------------------------------

   wcpt          cp_cpt%ROWTYPE;
   wpro          cp_pro%ROWTYPE;
--   wmvg          cp_ecr_ana%ROWTYPE;

