                     LPAD('Util. : ',89) || w_cuti || LPAD(ver,2);
    arg2          := w_l5;
    w_faitout := up_tmp_cex;

    arg2          := w_l1;
    w_faitout := up_tmp_cex;

    arg2          := w_l4;
    w_faitout := up_tmp_cex;


    w_l5          := ver ||LPAD('RUBRIQUES',31)||substr(w_l4,33,27)||
                     'EXERCICE (N)'||
                     substr(w_l4,72,26)||lpad(RPAD('EXERCICE (N-1)',15),15)||substr(w_l4,113,24);


    arg2          := w_l5;
    w_faitout := up_tmp_cex;


    arg2          := w_l4;
    w_faitout := up_tmp_cex;

    arg2          := w_l1;
    w_faitout := up_tmp_cex;

    RETURN TRUE;
END func_cex_01;

