    w_faitout := up_tmp_cex;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_cex;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_cex_02;

