---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_bia_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.a  := clcum_c1(p1);
       cpcum.b1 := clcum_c2(p1);
       cpcum.b2 := clcum_c3(p1);
       cpcum.b3 := clcum_c4(p1);
       cpcum.c1 := clcum_c5(p1);
       cpcum.c2 := clcum_c6(p1);
       cpcum.c3 := clcum_c7(p1);
       cpcum.d  := clcum_c8(p1);
       w_faitout := detail_bia(' ',wpae.typope,NULL);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
       clcum_c7(p1)   := 0;
       clcum_c8(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_bia_30;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_bia_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        w_cum_solde_db := nvl(wres.mnt1,0) - nvl(wres.mnt2,0);
        w_cum_solde_c3 := nvl(wres.mnt5,0) - nvl(wres.mnt6,0);
        w_cum_solde_c2 := w_cum_solde_c3 + nvl(wres.mnt3,0) - nvl(wres.mnt4,0);
        w_cum_solde_c4 := nvl(wres.mnt7,0) - nvl(wres.mnt8,0);
        w_cum_solde_c5 := nvl(wres.mnt9,0) - nvl(wres.mnt10,0);

        IF p2 != 0 THEN
             wedit          := 2;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 AND wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit != 2     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                 IF wpae.codope = '40' THEN
                  clcum_c1(wi)  := clcum_c1(wi) + w_cum_solde_db;
                  clcum_c2(wi)  := clcum_c2(wi) + w_cum_solde_c2;
                  clcum_c3(wi)  := clcum_c3(wi) + w_cum_solde_c3;
                  clcum_c4(wi)  := clcum_c4(wi) + w_cum_solde_c4;
                  clcum_c5(wi)  := clcum_c5(wi) + w_cum_solde_c5;
                 END IF;
                 IF wpae.codope = '41' THEN
                  clcum_c6(wi)  := clcum_c6(wi) + w_cum_solde_db;
                 END IF;
                 IF wpae.codope = '42' THEN
                  clcum_c7(wi)  := clcum_c7(wi) + w_cum_solde_db;
                 END IF;
                 IF wpae.codope = '43' THEN
                  clcum_c8(wi)  := clcum_c8(wi) + w_cum_solde_db;
                 END IF;
               END IF;
           END LOOP;
        END IF;
  -- dbms_output.put_line('wedit '||wedit||' p1 '||p1||' p2 '||p2);

        IF wedit = 1 AND p1 = 1     THEN
         IF wpae.codope = '40' THEN
           cpcum.a   :=  w_cum_solde_db;
           cpcum.b1  :=  w_cum_solde_c2;
           cpcum.b2  :=  w_cum_solde_c3;
           cpcum.b3  :=  w_cum_solde_c4;
           cpcum.c1  :=  w_cum_solde_c5;
           cpcum.c2  :=  0; cpcum.c3  :=  0;
           cpcum.d   :=  0;
           w_faitout := detail_bia(wres.numcpt,wres.libe,NULL);
        END IF;
         IF wpae.codope = '41' THEN
           cpcum.a   :=  0;
           cpcum.b1  :=  0; cpcum.b2  :=  0; cpcum.b3  :=  0;
           cpcum.c1  :=  0; cpcum.c2  :=  w_cum_solde_db; cpcum.c3  :=  0;
           cpcum.d   :=  0;
           w_faitout := detail_bia(wres.numcpt,wres.libe,NULL);
        END IF;
         IF wpae.codope = '42' THEN
           cpcum.a   :=  0;
           cpcum.b1  :=  0; cpcum.b2  :=  0; cpcum.b3  :=  0;
           cpcum.c1  :=  0; cpcum.c2  :=  0; cpcum.c3  :=  w_cum_solde_db;
           cpcum.d   :=  0;
           w_faitout := detail_bia(wres.numcpt,wres.libe,NULL);
        END IF;
         IF wpae.codope = '43' THEN
           cpcum.a   :=  0;
           cpcum.b1  :=  0; cpcum.b2  :=  0; cpcum.b3  :=  0;
           cpcum.c1  :=  0; cpcum.c2  :=  0; cpcum.c3  :=  0;
           cpcum.d   :=  w_cum_solde_db;
           w_faitout := detail_bia(wres.numcpt,wres.libe,NULL);
        END IF;
       END IF;
    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_bia_40;



----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_bia(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2, ed_bil1 VARCHAR2) RETURN BOOLEAN
IS

BEGIN

    w_l5 := w_l4;
    w_l5 := substr(w_l5,1,2)||RPAD(ed_intr,34)||substr(w_l5,37);
     mtf := numfs(cpcum.a,w_ndec);
    w_l5 := substr(w_l5,1,44)||mtf||substr(w_l5,60);
     mtf := numfs(cpcum.b1,w_ndec);
    w_l5 := substr(w_l5,1,62)||mtf||substr(w_l5,78);
     mtf := numfs(cpcum.b2,w_ndec);
    w_l5 := substr(w_l5,1,80)||mtf||substr(w_l5,96);
     mtf := numfs(cpcum.b3,w_ndec);
    w_l5 := substr(w_l5,1,98)||mtf||substr(w_l5,114);
     mtf := numfs(cpcum.c1,w_ndec);
    w_l5 := substr(w_l5,1,116)||mtf||substr(w_l5,132);
     mtf := numfs(cpcum.c2,w_ndec);
    w_l5 := substr(w_l5,1,134)||mtf||substr(w_l5,150);
     mtf := numfs(cpcum.c3,w_ndec);
    w_l5 := substr(w_l5,1,152)||mtf||substr(w_l5,168);
     mtf := numfs(cpcum.d,w_ndec);
    w_l5 := substr(w_l5,1,170)||mtf||substr(w_l5,186);
    arg2           := w_l5;
    w_faitout := up_tmp_bia;

    RETURN TRUE;
END detail_bia;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_bia RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_bia_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_bia;
----------------------- Calcul et MAJ des cumuls des comptes -------------
FUNCTION bia_maj_cpt RETURN BOOLEAN
IS

    CURSOR bia_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope in ('40','41','42','43')
               ORDER BY cdos,codeta,numord;

   CURSOR bia_cpt_list1 IS
         SELECT a.cdos,a.numcpt,a.intcpt, b.natcpt
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;

    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN
    OPEN bia_list1;
    LOOP
        FETCH bia_list1 INTO wpae;
        EXIT WHEN bia_list1%NOTFOUND;

        OPEN bia_cpt_list1;
        LOOP
            FETCH bia_cpt_list1 INTO wcpt.cdos, wcpt.numcpt,
                  wcpt.intcpt, wpro.natcpt;
            EXIT WHEN bia_cpt_list1%NOTFOUND;

            continuer := false;
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.numcpt;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := '00000000';
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.mnt5      := 0;
            wres.mnt6      := 0;
            wres.mnt7      := 0;
            wres.mnt8      := 0;
            wres.mnt9      := 0;
            wres.mnt10     := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.numcpt;
            wres.libe      := wcpt.intcpt;
            wres.ctie      := substr(wpro.natcpt,1,1);
       --     w_cum_solde_cr := 0;
       --     w_cum_solde_db := 0;

         FOR wmvg IN
            (SELECT  a.*
               FROM cp_ecr_gen a, cp_ecr b
              WHERE a.cdos =  wcdos
                    AND a.numcpt = wcpt.numcpt
                    AND a.datcpt between w_dper AND w_fper
                    AND a.codets LIKE sel_Ets
                    AND b.cdos = a.cdos
                    AND b.numsai = a.numsai
                    AND
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
         --           AND b.codmaj = 'O'
              ORDER BY a.cdos,a.numcpt)
         LOOP

            CONTINUER := true;
            IF w_sens = 'D' THEN
               IF wmvg.sens = 'C' THEN
                  wres.mnt2 := wres.mnt2 + wmvg.grp_mtcr;
                  IF wmvg.datcpt <= wdos.dfex THEN
                    wres.mnt6 := wres.mnt6 + wmvg.grp_mtcr;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,12) THEN
                    wres.mnt4 := wres.mnt4 + wmvg.grp_mtcr;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,24) THEN
                    wres.mnt8 := wres.mnt8 + wmvg.grp_mtcr;
                  ELSIF wmvg.datcpt > add_months(wdos.dfex,24) THEN
                    wres.mnt10 := wres.mnt10 + wmvg.grp_mtcr;
                  END IF;
               ELSE
                  wres.mnt1 := wres.mnt1 + wmvg.grp_mtdb;
                  IF wmvg.datcpt <= wdos.dfex THEN
                    wres.mnt5 := wres.mnt5 + wmvg.grp_mtdb;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,12) THEN
                    wres.mnt3 := wres.mnt3 + wmvg.grp_mtdb;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,24) THEN
                    wres.mnt7 := wres.mnt7 + wmvg.grp_mtdb;
                  ELSIF wmvg.datcpt > add_months(wdos.dfex,24) THEN
                    wres.mnt9 := wres.mnt9 + wmvg.grp_mtdb;
                  END IF;
               end if;
            ELSIF w_sens = 'C' THEN
               IF wmvg.sens = 'C' THEN
                  wres.mnt1 := wres.mnt1 + wmvg.grp_mtcr;
                  IF wmvg.datcpt <= wdos.dfex THEN
                    wres.mnt5 := wres.mnt5 + wmvg.grp_mtcr;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,12) THEN
                    wres.mnt3 := wres.mnt3 + wmvg.grp_mtcr;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,24) THEN
                    wres.mnt7 := wres.mnt7 + wmvg.grp_mtcr;
                  ELSIF wmvg.datcpt > add_months(wdos.dfex,24) THEN
                    wres.mnt9 := wres.mnt9 + wmvg.grp_mtcr;
                  END IF;
               ELSE
                  wres.mnt2 := wres.mnt2 + wmvg.grp_mtdb;
                  IF wmvg.datcpt <= wdos.dfex THEN
                    wres.mnt6 := wres.mnt6 + wmvg.grp_mtdb;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,12) THEN
                    wres.mnt4 := wres.mnt4 + wmvg.grp_mtdb;
                  ELSIF wmvg.datcpt <= add_months(wdos.dfex,24) THEN
                    wres.mnt8 := wres.mnt8 + wmvg.grp_mtdb;
                  ELSIF wmvg.datcpt > add_months(wdos.dfex,24) THEN
                    wres.mnt10 := wres.mnt10 + wmvg.grp_mtdb;
                  END IF;
               end if;
            END IF;
          --  if wmvg.grp_mtcr != 0 then

--dbms_output.put_line('credit '||wmvg.numcpt||' mtant '||to_char(wmvg.grp_mtcr)||' mnt2 '||to_char(wres.mnt2));
         --   end if;
          --  if wmvg.grp_mtdb != 0 then

--dbms_output.put_line('debit '||wmvg.numcpt||' mtant '||to_char(wmvg.grp_mtdb)||' mnt1 '||to_char(wres.mnt1));
          --  end if;
         END LOOP;

	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    0, 0, wres.sens, wres.ctie,
	                    w_session_id);   --lk

         commit; --lk
         END IF;
      END LOOP;
      CLOSE bia_cpt_list1;
   END LOOP;
   CLOSE bia_list1;

   RETURN TRUE;
END bia_maj_cpt;

