     e         NUMBER(15,3),
     vabr      NUMBER(15,3),
     amor      NUMBER(15,3),
     vane      NUMBER(15,3),
     prec      NUMBER(15,3)
   );
   cpcum         cpcum_type;


   TYPE w_reg_sec_type IS TABLE OF VARCHAR2(1) INDEX BY BINARY_INTEGER;
   -- w_reg_sec     w_reg_sec_type;

   --sk
   w_ecr_non_maj VARCHAR2(1);
   w_sim         VARCHAR2(1);
   w_per_comp    VARCHAR2(1);
   w_rg_dev      VARCHAR2(1);
   w_dper_c      VARCHAR2(3);
   w_fper_c      VARCHAR2(3);
   w_exercice    VARCHAR2(3);
   w_session_id  NUMBER;
   --fin sk

   w_titre       VARCHAR2(30);
   w_dper        DATE;
   w_fper        DATE;
   w_date        DATE;
   w_ddex        DATE;
   w_reou        VARCHAR2(1);
   w_ran         VARCHAR2(1);
   w_reed        VARCHAR2(1);
   w_psec        CHAR(8);
   w_dsec        CHAR(8);
   w_section     VARCHAR2(8);
   w_ndec        NUMBER;
   w_ligne       NUMBER;
   w_numord_edi  NUMBER;
   w_page        NUMBER;
   w_nblg        NUMBER;
   w_maxlg       NUMBER;
   wi            NUMBER;
   larg_ed       NUMBER;
   w_cuti        VARCHAR2(4);

   w_ets         VARCHAR2(3);
   w_axa         VARCHAR2(1);
   sel_ets       cp_ets.codets%TYPE;
   ets_lib       VARCHAR2(30);

   sauv_supl     NUMBER;
   w_supl        NUMBER;
   lig_as        VARCHAR2(1);

-------------------------------------------------------------------------------

PROCEDURE labcde (woptions IN VARCHAR2)
IS

    CURSOR bia_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN
--  lecture des parametres d'edition

    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);

    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_ets         := rtrim(substr(woptions,16,3));
    w_session_id  := to_number(substr(woptions,19,38));
    w_ecr_non_maj := substr(woptions,57,1);



    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
--dbms_output.enable(50000);
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;

--dbms_output.put_line('sec ID'||to_char(w_session_ID));
--dbms_output.put_line('bala '||w_bala);
--dbms_output.put_line('C uti '||w_cuti);
--dbms_output.put_line('deb per '||to_char(w_dper));
--dbms_output.put_line('fin per '||to_char(w_fper));
--dbms_output.put_line('ets '||w_ets);
--dbms_output.put_line('codmaj '||w_ecr_non_maj);
    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;

    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := bia_maj_cpt;
--dbms_output.put_line('gen_bg');

    larg_ed             := 133;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,131) || ver;
    w_l3                := ver || RPAD(' ',131) || ver;
    w_l4                := SUBSTR(w_l3,1,42) ||
                           ver || SUBSTR(w_l3,44,17)  ||
                           ver || SUBSTR(w_l3,62,17)  ||
                           ver || SUBSTR(w_l3,80,17)  ||
                           ver || SUBSTR(w_l3,98,17)  ||
                           ver || SUBSTR(w_l3,116);

    w_numord_edi := 0;

    FOR indi IN 1..9
    LOOP
       clcum_c1(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       clcum_c5(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;

    OPEN bia_list;
    LOOP
        FETCH bia_list INTO wpae;
        EXIT WHEN bia_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_bia_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_bia_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_bia_03;
           -- ELSIF wpae.codope = '04' THEN w_faitout := func_bg_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_bia_30;
            ELSIF wpae.codope = '34' THEN w_faitout := func_bia_03;
                                          w_faitout := func_bia_30;
                                          w_faitout := func_bia_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_bia_03;
                                          w_faitout := func_bia_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_bia_40;
            ELSIF wpae.codope = '41' THEN w_faitout := func_bia_40;
            ELSIF wpae.codope = '42' THEN w_faitout := func_bia_40;
        END IF;

    END LOOP;
    CLOSE bia_list;

END labcde;

----------------------- EDITION DE L'ENTETE  -----------------------------

FUNCTION func_bia_01 RETURN BOOLEAN
IS

BEGIN

    w_page  := w_page + 1;
    w_ligne := 0;
    arg1    := w_page;   --lk

    w_supl := 0;

    arg2 := w_l1;
    w_faitout := up_tmp_bia;

    w_l5          := RPAD(ver,2) ||
                    'Societe       : ' || wdos.cdos || '  ' ||
                     RPAD(wdos.nred,97) || 'Page' ||
                     TO_CHAR(w_page, '9999') || LPAD(ver,5);

    arg2          := w_l5;
    w_faitout := up_tmp_bia;

    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       w_l5          := RPAD(ver,2) ||
                       'Etablissement : ' || LPAD(w_ets,3) || ' ' ||
                        RPAD(ets_lib,110) || ver;
       arg2          := w_l5;
       w_faitout := up_tmp_bia;
    END IF;

    w_l5          := RPAD(ver,2) || RPAD(' ',52) ||
                     RPAD(w_titre,30) ||' Periode du ' ||
                     TO_CHAR(w_dper, 'dd-mm-yyyy') || ' au ' ||
                     TO_CHAR(w_fper, 'dd-mm-yyyy') ||
                     LPAD(ver,13);
    arg2          := w_l5;
    w_faitout := up_tmp_bia;

    w_supl := 0;
    w_l5          := RPAD(ver,2) ||
                    'Edite le ' || TO_CHAR(sysdate, 'dd-mm-yyyy "a" hh:mi:ss') ||
                     LPAD('Util. : ',95) || w_cuti || LPAD(ver,2);
    arg2          := w_l5;
    w_faitout := up_tmp_bia;

    arg2          := w_l1;
    w_faitout := up_tmp_bia;

    arg2          := w_l4;
    w_faitout := up_tmp_bia;

    w_l5          := ver ||LPAD('RUBRIQUES',31)||
                     substr(w_l4,33,19)||'A'||
                     substr(w_l4,53,17)||'B'||
                     substr(w_l4,71,13)||'C = A - B'||
                     substr(w_l4,93,13)||'D'||
                     substr(w_l4,107,13)||'E = D - C'||
                     substr(w_l4,129);
    arg2          := w_l5;
    w_faitout := up_tmp_bia;

    arg2          := w_l4;
    w_faitout := up_tmp_bia;

    arg2          := w_l1;
    w_faitout := up_tmp_bia;

    RETURN TRUE;

END func_bia_01;

----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_bia_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5          := RPAD(ver,12) || wpae.typope;-- || LPAD(ver,89) ;
    arg2          := w_l5;
    w_faitout := up_tmp_bia;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_bia;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_bia_02;

----------------------- EDITION D'UNE LIGNE DE TIRETS  -------------------
FUNCTION func_bia_03 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l2;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_bia;

    RETURN TRUE;
END func_bia_03;

----------------------- EDITION D'UNE LIGNE ESPACE     -------------------
FUNCTION func_bia_04 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l4;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_bia;

    RETURN TRUE;
END func_bia_04;

---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_bia_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.a  := clcum_c1(p1);
       cpcum.b  := clcum_c2(p1);
       cpcum.c  := clcum_c3(p1);
       cpcum.d  := clcum_c4(p1);
       cpcum.e  := clcum_c5(p1);
       w_faitout := detail_bia(' ',wpae.typope,NULL);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_bia_30;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_bia_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        w_cum_solde_db := nvl(wres.mnt1,0) - nvl(wres.mnt2,0);

        IF p2 != 0 THEN
             wedit          := 2;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 AND wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit != 2     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                 IF wpae.codope = '40' THEN
                  clcum_c1(wi)  := clcum_c1(wi) + w_cum_solde_db;
                 END IF;
                 IF wpae.codope = '41' THEN
                  clcum_c2(wi)  := clcum_c2(wi) + w_cum_solde_db;
                 END IF;
                 clcum_c3(wi) := clcum_c1(wi) - clcum_c2(wi);
                 IF wpae.codope = '42' THEN
                  clcum_c4(wi)  := clcum_c4(wi) + w_cum_solde_db;
                 END IF;
                 clcum_c5(wi) := clcum_c4(wi) - (clcum_c1(wi) - clcum_c2(wi));
               END IF;
           END LOOP;
        END IF;
  -- dbms_output.put_line('wedit '||wedit||' p1 '||p1||' p2 '||p2);

        IF wedit = 1 AND p1 = 1     THEN
         IF wpae.codope = '40' THEN
           cpcum.a   :=  w_cum_solde_db;
           cpcum.b   :=  0;
           cpcum.c   :=  w_cum_solde_db;
           cpcum.d   :=  0;
           cpcum.e   :=  -w_cum_solde_db;
           w_faitout := detail_bia(wres.numcpt,wres.libe,NULL);
        END IF;
         IF wpae.codope = '41' THEN
           cpcum.a   :=  0;
           cpcum.b   :=  w_cum_solde_db;
           cpcum.c   :=  -w_cum_solde_db;
           cpcum.d   :=  0;
           cpcum.e   :=  w_cum_solde_db;
           w_faitout := detail_bia(wres.numcpt,wres.libe,NULL);
        END IF;
         IF wpae.codope = '42' THEN
           cpcum.a   :=  0;
           cpcum.b   :=  0;
           cpcum.c   :=  0;
           cpcum.d   :=  w_cum_solde_db;
           cpcum.e   :=  w_cum_solde_db;
           w_faitout := detail_bia(wres.numcpt,wres.libe,NULL);
        END IF;
       END IF;
    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_bia_40;



----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_bia(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2, ed_bil1 VARCHAR2) RETURN BOOLEAN
IS

BEGIN

    w_l5 := w_l4;
    w_l5 := substr(w_l5,1,2)||RPAD(ed_intr,34)||substr(w_l5,37);
     mtf := numfs(cpcum.a,w_ndec);
    w_l5 := substr(w_l5,1,44)||mtf||substr(w_l5,60);
     mtf := numfs(cpcum.b,w_ndec);
    w_l5 := substr(w_l5,1,62)||mtf||substr(w_l5,78);
     mtf := numfs(cpcum.c,w_ndec);
    w_l5 := substr(w_l5,1,80)||mtf||substr(w_l5,96);
     mtf := numfs(cpcum.d,w_ndec);
    w_l5 := substr(w_l5,1,98)||mtf||substr(w_l5,114);
     mtf := numfs(cpcum.e,w_ndec);
    w_l5 := substr(w_l5,1,116)||mtf||substr(w_l5,132);
    arg2           := w_l5;
    w_faitout := up_tmp_bia;

    RETURN TRUE;
END detail_bia;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_bia RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_bia_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_bia;
----------------------- Calcul et MAJ des cumuls des comptes -------------
FUNCTION bia_maj_cpt RETURN BOOLEAN
IS

    CURSOR bia_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope in ('40','41','42','43','44','45')
               ORDER BY cdos,codeta,numord;

   CURSOR bia_cpt_list1 IS
         SELECT a.cdos,a.numcpt,a.intcpt, b.natcpt
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;

    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN
    OPEN bia_list1;
    LOOP
        FETCH bia_list1 INTO wpae;
        EXIT WHEN bia_list1%NOTFOUND;

        OPEN bia_cpt_list1;
        LOOP
            FETCH bia_cpt_list1 INTO wcpt.cdos, wcpt.numcpt,
                  wcpt.intcpt, wpro.natcpt;
            EXIT WHEN bia_cpt_list1%NOTFOUND;

            continuer := false;
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.numcpt;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := '00000000';
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.numcpt;
            wres.libe      := wcpt.intcpt;
            wres.ctie      := substr(wpro.natcpt,1,1);
       --     w_cum_solde_cr := 0;
       --     w_cum_solde_db := 0;

         FOR wmvg IN
            (SELECT  a.*
               FROM cp_ecr_gen a, cp_ecr b
              WHERE a.cdos =  wcdos
                    AND a.numcpt = wcpt.numcpt
                    AND a.datcpt between w_dper AND w_fper
                    AND a.codets LIKE sel_Ets
                    AND b.cdos = a.cdos
                    AND b.numsai = a.numsai
                    AND
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
         --           AND b.codmaj = 'O'
              ORDER BY a.cdos,a.numcpt)
         LOOP

            CONTINUER := true;
            IF wpae.codope IN ('40','41','42','43') THEN
               IF wmvg.sens = 'C' THEN
                  wres.mnt2 := wres.mnt2 + wmvg.grp_mtcr;
               ELSE
                  wres.mnt1 := wres.mnt1 + wmvg.grp_mtdb;
               end if;
            ELSIF wpae.codope IN ('44','45') THEN
               IF wmvg.sens = 'C' THEN
                  wres.mnt1 := wres.mnt1 + wmvg.grp_mtcr;
               ELSE
                  wres.mnt2 := wres.mnt2 + wmvg.grp_mtdb;
               end if;

            END IF;
          --  if wmvg.grp_mtcr != 0 then

--dbms_output.put_line('credit '||wmvg.numcpt||' mtant '||to_char(wmvg.grp_mtcr)||' mnt2 '||to_char(wres.mnt2));
         --   end if;
          --  if wmvg.grp_mtdb != 0 then

--dbms_output.put_line('debit '||wmvg.numcpt||' mtant '||to_char(wmvg.grp_mtdb)||' mnt1 '||to_char(wres.mnt1));
          --  end if;
         END LOOP;

	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, 0, 0,
	                    0,0, 0, 0,
	                    0, 0, wres.sens, wres.ctie,
	                    w_session_id);   --lk

         commit; --lk
         END IF;
      END LOOP;
      CLOSE bia_cpt_list1;
   END LOOP;
   CLOSE bia_list1;

   RETURN TRUE;
END bia_maj_cpt;

----------------------- Creation des tables temporaires ------------------
FUNCTION pae_tabtmp RETURN BOOLEAN
IS

BEGIN

   DELETE FROM cp_edi where session_id = w_session_id;
   DELETE FROM cp_res where session_id = w_session_id;

   COMMIT;

   RETURN TRUE;

END pae_tabtmp;

----------------------- REMISE A ZERO D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_10 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0     THEN
      clcum_c1(p1) := 0;
      clcum_c2(p1) := 0;
      clcum_c3(p1) := 0;
      clcum_c4(p1) := 0;
      clcum_c5(p1) := 0;
      clcum_c6(p1) := 0;
      clcum_c7(p1) := 0;
      clcum_c8(p1) := 0;
   END IF;
   IF p2 != 0     THEN
      clcum_c1(p2) := 0;
      clcum_c2(p2) := 0;
      clcum_c3(p2) := 0;
      clcum_c4(p2) := 0;
      clcum_c5(p2) := 0;
      clcum_c6(p2) := 0;
      clcum_c7(p2) := 0;
      clcum_c8(p2) := 0;
   END IF;
   IF p3 != 0     THEN
      clcum_c1(p3) := 0;
      clcum_c2(p3) := 0;
      clcum_c3(p3) := 0;
      clcum_c4(p3) := 0;
      clcum_c5(p3) := 0;
      clcum_c6(p3) := 0;
      clcum_c7(p3) := 0;
      clcum_c8(p3) := 0;
   END IF;
   IF p4 != 0     THEN
      clcum_c1(p4) := 0;
      clcum_c2(p4) := 0;
      clcum_c3(p4) := 0;
      clcum_c4(p4) := 0;
      clcum_c5(p4) := 0;
      clcum_c6(p4) := 0;
      clcum_c7(p4) := 0;
      clcum_c8(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_10;

-----------------------  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_11 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0   THEN
      cpt_mjcum(p1) := 1;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 1;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 1;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 1;
   END IF;

   RETURN TRUE;

END func_pae_11;

---------------- RAZ  +  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_12 RETURN BOOLEAN
IS

BEGIN

   w_faitout := func_pae_10;
   w_faitout := func_pae_11;

   RETURN TRUE;

END func_pae_12;

----------------------  SUSPENSION D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_13 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0   THEN
      cpt_mjcum(p1) := 0;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 0;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 0;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_13;

----------------------  TRANSFERT DE P1 --> P2  -----------------------
FUNCTION func_pae_20 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1);
      clcum_c2(p2)  := clcum_c2(p1);
      clcum_c3(p2)  := clcum_c3(p1);
      clcum_c4(p2)  := clcum_c4(p1);
      clcum_c5(p2)  := clcum_c5(p1);
      clcum_c6(p2)  := clcum_c6(p1);
      clcum_c7(p2)  := clcum_c7(p1);
      clcum_c8(p2)  := clcum_c8(p1);
   END IF;

   RETURN TRUE;

END func_pae_20;

----------------------  TRANSFERT DE P1 + P2  --> P3  -----------------
FUNCTION func_pae_21 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) + clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) + clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) + clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) + clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) + clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) + clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) + clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) + clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_21;

---------------  P1 - P2 --> P3  -----------------------------------------------
FUNCTION func_pae_22 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) - clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) - clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) - clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) - clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) - clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) - clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) - clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) - clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_22;


---------------  TRANSFERT AVEC INVERSION DE SIGNE P1 --> P2  ------------------
FUNCTION func_pae_25 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1) * -1;
      clcum_c2(p2)  := clcum_c2(p1) * -1;
      clcum_c3(p2)  := clcum_c3(p1) * -1;
      clcum_c4(p2)  := clcum_c4(p1) * -1;
      clcum_c5(p2)  := clcum_c5(p1) * -1;
      clcum_c6(p2)  := clcum_c6(p1) * -1;
      clcum_c7(p2)  := clcum_c7(p1) * -1;
      clcum_c8(p2)  := clcum_c8(p1) * -1;
   END IF;

   RETURN TRUE;

END func_pae_25;


