CREATE PACKAGE BODY cplbgp
AS


-------------------------------------------------------------------------------
-- Edition de la balance generale
-------------------------------------------------------------------------------

   wcpt          cp_cpt%ROWTYPE;
   wpro          cp_pro%ROWTYPE;
--   wmvg          cp_ecr_ana%ROWTYPE;

   TYPE cpcum_type IS RECORD     -- zone de cumul compte
   (    mdpd     NUMBER(16,3),
        mcpd     NUMBER(16,3),
        mded     NUMBER(16,3),
        mced     NUMBER(16,3),
        sold     NUMBER(16,3),
        solc     NUMBER(16,3)
   );
   cpcum         cpcum_type;

   TYPE w_reg_sec_type IS TABLE OF VARCHAR2(1) INDEX BY BINARY_INTEGER;
   w_reg_sec     w_reg_sec_type;

   --sk
   w_ecr_non_maj VARCHAR2(1);
   w_sim         VARCHAR2(1);
   w_per_comp    VARCHAR2(1);
   w_rg_dev      VARCHAR2(1);
   w_dper_c      VARCHAR2(3);
   w_fper_c      VARCHAR2(3);
   w_exercice    VARCHAR2(3);
   w_session_id  NUMBER;
   --fin sk

   w_titre       VARCHAR2(30);
   w_dper        DATE;
   w_fper        DATE;
   w_date        DATE;
   w_ddex        DATE;
   w_reou        VARCHAR2(1);
   w_ran         VARCHAR2(1);
   w_reed        VARCHAR2(1);
   w_psec        CHAR(8);
   w_dsec        CHAR(8);
   w_section     VARCHAR2(8);
   w_ndec        NUMBER;
   w_ligne       NUMBER;
   w_numord_edi  NUMBER;
   w_page        NUMBER;
   w_nblg        NUMBER;
   w_maxlg       NUMBER;
   wi            NUMBER;
   larg_ed       NUMBER;
   w_cuti        VARCHAR2(4);

   w_ets         VARCHAR2(3);
   w_axa         VARCHAR2(1);
   sel_ets       cp_ets.codets%TYPE;
   ets_lib       VARCHAR2(30);

   sauv_supl     NUMBER;
   w_supl        NUMBER;
   lig_as        VARCHAR2(1);

-------------------------------------------------------------------------------

PROCEDURE ledbg01 (woptions IN VARCHAR2)
IS

    CURSOR bg_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN

--  lecture des parametres d'edition dans le fichier evlanc

    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);

    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_ets         := rtrim(substr(woptions,16,3));
    w_rg_dev	  := substr(woptions,19,1);
    w_ecr_non_maj := substr(woptions,20,1);
    w_per_comp	  := substr(woptions,21,1);
    w_sim	      := substr(woptions,22,1);
    w_ran         := substr(woptions,23,1);
    w_reou        := substr(woptions,24,1);
    w_session_id  := to_number(substr(woptions,25,38));

    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk

--dbms_output.enable(50000);
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;

--dbms_output.put_line(to_char(w_dper));
    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;

    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := gen_bg;
--dbms_output.put_line('gen_bg');

    larg_ed             := 136;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,134) || ver;
    w_l3                := ver || RPAD(' ',134) || ver;
    w_l4                := SUBSTR(w_l3,1,42) ||
                           ver || SUBSTR(w_l3,44,30) ||
                           ver || SUBSTR(w_l3,75,30) ||
                           ver || SUBSTR(w_l3,106,30) || ver;

    w_numord_edi := 0;

    FOR indi IN 1..9
    LOOP
       clcum_c1(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       clcum_c5(indi)  := 0;
       clcum_c6(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;

    OPEN bg_list;
    LOOP
        FETCH bg_list INTO wpae;
        EXIT WHEN bg_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_bg_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_bg_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_bg_03;
            ELSIF wpae.codope = '04' THEN w_faitout := func_bg_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_bg_30;
            ELSIF wpae.codope = '34' THEN w_faitout := func_bg_03;
                                          w_faitout := func_bg_30;
                                          w_faitout := func_bg_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_bg_03;
                                          w_faitout := func_bg_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_bg_40;
        END IF;

    END LOOP;
    CLOSE bg_list;

    --w_faitout := ed_tmp_fic(w_led);

END ledbg01;

----------------------- EDITION DE L'ENTETE  -----------------------------

FUNCTION func_bg_01 RETURN BOOLEAN
IS

BEGIN

--lk    IF NVL(arg1,'0') = '1' THEN arg1 := '0';
--lk                           ELSE arg1 := '1';
--lk    END IF;
    w_page  := w_page + 1;
    w_ligne := 0;
    arg1    := w_page;   --lk

    w_supl := 0;

--    arg1 := '1';
    arg2 := w_l1;
    w_faitout := up_tmp_bg;

--    arg1 := '0';
--    w_page        := w_page + 1;

    w_l5          := RPAD(ver,2) ||
                    'Societe       : ' || wdos.cdos || '  ' ||
                     RPAD(wdos.nred,91) || 'Page' ||
                     TO_CHAR(w_page, '9999') || LPAD(ver,14);
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       w_l5          := RPAD(ver,2) ||
                       'Etablissement : ' || LPAD(w_ets,3) || ' ' ||
                        RPAD(ets_lib,113) || ver;
       arg2          := w_l5;
       w_faitout := up_tmp_bg;
    END IF;

    w_l5          := RPAD(ver,2) || RPAD(' ',47) ||
                     RPAD(w_titre,40) ||' Periode du ' ||
                     TO_CHAR(w_dper, 'dd-mm-yyyy') || ' au ' ||
                     TO_CHAR(w_fper, 'dd-mm-yyyy') ||
                     LPAD(ver,11);
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    w_supl := 0;
    w_l5          := RPAD(ver,2) ||
                    'Edite le ' || TO_CHAR(sysdate, 'dd-mm-yyyy "a" hh:mi:ss') ||
                     LPAD('Util. : ',89) || w_cuti || LPAD(ver,11);
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    arg2          := w_l1;
    w_faitout := up_tmp_bg;

    w_l5          := RPAD(ver,3) || RPAD('Compte',21) || RPAD('Intitule',18) ||
                     RPAD(ver,11) || RPAD('Periode',20) ||
                     RPAD(ver,11) || RPAD('Exercice',20) ||
                     RPAD(ver,12) || RPAD('Soldes',19) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    w_l5          := RPAD(ver,42) ||
                     RPAD(ver,6) || RPAD('debit        Credit',25) ||
                     RPAD(ver,6) || RPAD('debit        Credit',25) ||
                     RPAD(ver,6) || RPAD('debit        Credit',25) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    arg2          := w_l1;
    w_faitout := up_tmp_bg;

    arg2          := w_l4;
    w_faitout := up_tmp_bg;

    RETURN TRUE;
END func_bg_01;

----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_bg_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5          := RPAD(ver,12) || wpae.typope || LPAD(ver,89) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_bg;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_bg;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_bg_02;

----------------------- EDITION D'UNE LIGNE DE TIRETS  -------------------
FUNCTION func_bg_03 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l2;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    RETURN TRUE;
END func_bg_03;

----------------------- EDITION D'UNE LIGNE ESPACE     -------------------
FUNCTION func_bg_04 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l4;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    RETURN TRUE;
END func_bg_04;

---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_bg_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.mdpd := clcum_c1(p1);
       cpcum.mcpd := clcum_c2(p1);
       cpcum.mded := clcum_c3(p1);
       cpcum.mced := clcum_c4(p1);
       cpcum.solc := 0;
       cpcum.sold := 0;
       IF p3 = 0  THEN
         IF clcum_c5(p1) > clcum_c6(p1)  THEN
               cpcum.sold   := clcum_c5(p1) - clcum_c6(p1);
               cpcum.solc   := 0;
               clcum_c5(p1) := cpcum.sold;
               clcum_c6(p1) := 0;
         ELSE  cpcum.solc   := clcum_c6(p1) - clcum_c5(p1);
               cpcum.sold   := 0;
               clcum_c5(p1) := 0;
               clcum_c6(p1) := cpcum.solc;
         END IF;
       ELSE null;
         cpcum.sold := clcum_c5(p1);
         cpcum.solc := clcum_c6(p1);
       END IF;
       w_faitout := detail_bg(' ',wpae.typope);
       -- Ligne des soldes sur les colonnes : periode, exercice et solde
       IF p3 = 1 THEN
          IF clcum_c1(p1) >= clcum_c2(p1) THEN
             cpcum.mdpd := clcum_c1(p1) - clcum_c2(p1);
             cpcum.mcpd := NULL;
          ELSE
             cpcum.mdpd := NULL;
             cpcum.mcpd := clcum_c2(p1) - clcum_c1(p1);
          END IF;
          IF clcum_c3(p1) >= clcum_c4(p1) THEN
             cpcum.mded := clcum_c3(p1) - clcum_c4(p1);
             cpcum.mced := NULL;
          ELSE
             cpcum.mded := NULL;
             cpcum.mced := clcum_c4(p1) - clcum_c3(p1);
          END IF;
          IF clcum_c5(p1) >= clcum_c6(p1) THEN
             cpcum.sold := clcum_c5(p1) - clcum_c6(p1);
             cpcum.solc := NULL;
          ELSE
             cpcum.sold := NULL;
             cpcum.solc := clcum_c6(p1) - clcum_c5(p1);
          END IF;
          w_faitout := detail_bg(' ',' ');
       END IF;
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_bg_30;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_bg_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        IF p2 != 0 THEN
             wedit          := 2;
             w_cum_solde_db := wres.mnt3 - wres.mnt4;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt3 != 0 AND wres.mnt4 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 4 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 OR wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit = 1     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                  clcum_c1(wi)  := clcum_c1(wi) + wres.mnt1;
                  clcum_c2(wi)  := clcum_c2(wi) + wres.mnt2;
                  clcum_c3(wi)  := clcum_c3(wi) + wres.mnt3;
                  clcum_c4(wi)  := clcum_c4(wi) + wres.mnt4;
                  w_cum_solde_db := wres.mnt3 - wres.mnt4;
                  IF w_cum_solde_db < 0 THEN
                     clcum_c6(wi) := clcum_c6(wi) + (w_cum_solde_db * -1);
                  ELSE
                     clcum_c5(wi) := clcum_c5(wi) + w_cum_solde_db;
                  END IF;
               END IF;
           END LOOP;
        END IF;

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.mdpd    :=  wres.mnt1;
           cpcum.mcpd    :=  wres.mnt2;
           cpcum.mded    :=  wres.mnt3;
           cpcum.mced    :=  wres.mnt4;
           cpcum.solc    :=  0;
           cpcum.sold    :=  0;
           IF cpcum.mded > cpcum.mced      THEN
                cpcum.sold := cpcum.mded - cpcum.mced;
                cpcum.solc := 0;
           ELSE cpcum.solc := cpcum.mced - cpcum.mded;
                cpcum.sold := 0;
           END IF;
           w_faitout := detail_bg(wres.numcpt,wres.libe);
        END IF;

    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_bg_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_bg(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2) RETURN BOOLEAN
IS

BEGIN

    w_l5      := RPAD(ver,2) || RPAD(ed_numcpt,10) ||
                        RPAD(ed_intr,30) || SUBSTR(w_l4,43,94);
    mtf := numfs(cpcum.mdpd,w_ndec);
    IF cpcum.mdpd != 0 THEN
       w_l5   := SUBSTR(w_l5,1,43) || mtf || substr(w_l5,59,78);
    END IF;
    mtf := numfs(cpcum.mcpd,w_ndec);
    IF cpcum.mcpd != 0 THEN
       w_l5   := SUBSTR(w_l5,1,58) || mtf || substr(w_l5,74,63);
    END IF;
    mtf := numfs(cpcum.mded,w_ndec);
    IF cpcum.mded != 0 THEN
       w_l5   := SUBSTR(w_l5,1,74) || mtf || substr(w_l5,90,47);
    END IF;
    mtf := numfs(cpcum.mced,w_ndec);
    IF cpcum.mced != 0 THEN
       w_l5   := SUBSTR(w_l5,1,89) || mtf || substr(w_l5,105,32);
    END IF;
    mtf := numfs(cpcum.sold,w_ndec);
    IF cpcum.sold != 0 THEN
       w_l5   := SUBSTR(w_l5,1,105) || mtf || substr(w_l5,121,16);
    END IF;
    mtf := numfs(cpcum.solc,w_ndec);
    IF cpcum.solc != 0 THEN
       w_l5   := SUBSTR(w_l5,1,120) || mtf || substr(w_l5,136,1);
    END IF;
--    arg1           := 0;
    arg2           := w_l5;
    w_faitout := up_tmp_bg;

    RETURN TRUE;
END detail_bg;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_bg RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_bg_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_bg;

----------------------- Calcul et MAJ des cumuls des comptes -------------

FUNCTION gen_bg RETURN BOOLEAN
IS

    CURSOR bg_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40' ORDER BY cdos,codeta,numord;

   CURSOR bg_cpt_list1 IS
         SELECT a.cdos, a.numcpt, a.typcpt, a.intcpt, b.codran, b.natcpt, a.raccpt
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;

    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN
    OPEN bg_list1;
    LOOP
        FETCH bg_list1 INTO wpae;
        EXIT WHEN bg_list1%NOTFOUND;

        OPEN bg_cpt_list1;
        LOOP
            FETCH bg_cpt_list1 INTO wcpt.cdos, wcpt.numcpt, wcpt.typcpt,
                  wcpt.intcpt, wpro.codran, wpro.natcpt, wcpt.raccpt;
            EXIT WHEN bg_cpt_list1%NOTFOUND;

            continuer := false;
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.numcpt;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := '00000000';
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.numcpt;
            if wpae.sel = 'I' then
              wres.libe      := wcpt.raccpt;
            else
              wres.libe      := wcpt.intcpt;
            end if;
            wres.sens      := 'X';
            wres.ctie      := substr(wpro.natcpt,1,1);
            w_cum_solde_cr := 0;
            w_cum_solde_db := 0;

         IF wcpt.typcpt = 'D' OR wpae.param2 not between 1 and 3 THEN

         FOR wmvg IN
            (SELECT b.codjou, a.*
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt and
                    --a.datcpt <= w_fper
                    a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w_fper_c
                    and b.periode <= w_fper_c
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
		            and
		            (
      		          (
	      	            (W_SIM = 'N')
		                    and
			              (b.CODJOU in (select CODJOU FROM CP_JOU
        				                WHERE CDOS = WCDOS
		      			                and NATJOU != 'S'
			      	                )
			               )
       		          )
	      	        or
  	                    (W_SIM = 'O')
      		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
	      	      and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            IF w_reou = 'O' AND wmvg.codjou != wdos.dcjr THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND  w_ran = 'N' AND
               wmvg.datcpt < wdos.ddes THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND w_ran = 'O' AND wmvg.datcpt < wdos.ddes THEN
               IF wpro.codran = 'N' THEN
                  CONTINUER := false;
               END IF;
               if continuer then
               IF wmvg.sens = 'C' THEN
                    w_cum_solde_cr := w_cum_solde_cr + nvl(wmvg.grp_mtcr,0);
                    CONTINUER := false;
               ELSE w_cum_solde_db := w_cum_solde_db + nvl(wmvg.grp_mtdb,0);
                    CONTINUER := false;
               END IF;
               end if;
            END IF;
            if continuer then
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt1 := wres.mnt1 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt2 := wres.mnt2 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_ddex THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt3 := wres.mnt3 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt4 := wres.mnt4 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            end if;
         END LOOP;

         ELSIF wpae.param2 = 1 THEN   -- Comptes à solde non nul

         FOR wmvg IN
            (SELECT b.codjou, a.*
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt
                    and numtie in (select numtie
                                   from cp_ecr_gen a, cp_ecr b, cp_per c
                                   where a.cdos = wcdos
                                   and numcpt = wcpt.numcpt and
                                   a.codets LIKE sel_Ets
                                   and b.cdos = a.cdos
                                   and b.numsai = a.numsai
                                   and b.periode <= w_fper_c
                                   and
                	                 (
		                           (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		                           or (w_ecr_non_maj = 'O')
        		                     )
		                           and
		                           (
      		                         (
	      	                           (W_SIM = 'N')
		                                   and
			                             (b.CODJOU in (select CODJOU FROM CP_JOU
        				                               WHERE CDOS = WCDOS
		      			                               and NATJOU != 'S'
			      	                               )
			                              )
       		                         )
	      	                       or
  	                                   (W_SIM = 'O')
      		                     )
	      	                     and c.cdos = b.cdos
    	                         and c.periode =b.periode
	      	                     and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
                                 group by numtie
                                 having sum(nvl(dos_mtdb,0))-sum(nvl(dos_mtcr,0))!=0)

                    --a.datcpt <= w_fper
                    and a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w_fper_c
                    and b.periode <= w_fper_c
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
		            and
		            (
      		          (
	      	            (W_SIM = 'N')
		                    and
			              (b.CODJOU in (select CODJOU FROM CP_JOU
        				                WHERE CDOS = WCDOS
		      			                and NATJOU != 'S'
			      	                )
			               )
       		          )
	      	        or
  	                    (W_SIM = 'O')
      		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
	      	      and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            IF w_reou = 'O' AND wmvg.codjou != wdos.dcjr THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND  w_ran = 'N' AND
               wmvg.datcpt < wdos.ddes THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND w_ran = 'O' AND wmvg.datcpt < wdos.ddes THEN
               IF wpro.codran = 'N' THEN
                  CONTINUER := false;
               END IF;
               if continuer then
               IF wmvg.sens = 'C' THEN
                    w_cum_solde_cr := w_cum_solde_cr + nvl(wmvg.grp_mtcr,0);
                    CONTINUER := false;
               ELSE w_cum_solde_db := w_cum_solde_db + nvl(wmvg.grp_mtdb,0);
                    CONTINUER := false;
               END IF;
               end if;
            END IF;
            if continuer then
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt1 := wres.mnt1 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt2 := wres.mnt2 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_ddex THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt3 := wres.mnt3 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt4 := wres.mnt4 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            end if;
         END LOOP;

         ELSIF wpae.param2 = 2 THEN   -- Comptes à solde débiteur

         FOR wmvg IN
            (SELECT b.codjou, a.*
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt
                    and numtie in (select numtie
                                   from cp_ecr_gen a, cp_ecr b, cp_per c
                                   where a.cdos = wcdos
                                   and numcpt = wcpt.numcpt and
                                   a.codets LIKE sel_Ets
                                   and b.cdos = a.cdos
                                   and b.numsai = a.numsai
                                   and b.periode <= w_fper_c
                                   and
                	                 (
		                           (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		                           or (w_ecr_non_maj = 'O')
        		                     )
		                           and
		                           (
      		                         (
	      	                           (W_SIM = 'N')
		                                   and
			                             (b.CODJOU in (select CODJOU FROM CP_JOU
        				                               WHERE CDOS = WCDOS
		      			                               and NATJOU != 'S'
			      	                               )
			                              )
       		                         )
	      	                       or
  	                                   (W_SIM = 'O')
      		                     )
	      	                     and c.cdos = b.cdos
    	                         and c.periode =b.periode
	      	                     and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
                                 group by numtie
                                 having sum(nvl(dos_mtdb,0))-sum(nvl(dos_mtcr,0))>0)

                    --a.datcpt <= w_fper
                    and a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w_fper_c
                    and b.periode <= w_fper_c
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
		            and
		            (
      		          (
	      	            (W_SIM = 'N')
		                    and
			              (b.CODJOU in (select CODJOU FROM CP_JOU
        				                WHERE CDOS = WCDOS
		      			                and NATJOU != 'S'
			      	                )
			               )
       		          )
	      	        or
  	                    (W_SIM = 'O')
      		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
	      	      and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            IF w_reou = 'O' AND wmvg.codjou != wdos.dcjr THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND  w_ran = 'N' AND
               wmvg.datcpt < wdos.ddes THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND w_ran = 'O' AND wmvg.datcpt < wdos.ddes THEN
               IF wpro.codran = 'N' THEN
                  CONTINUER := false;
               END IF;
               if continuer then
               IF wmvg.sens = 'C' THEN
                    w_cum_solde_cr := w_cum_solde_cr + nvl(wmvg.grp_mtcr,0);
                    CONTINUER := false;
               ELSE w_cum_solde_db := w_cum_solde_db + nvl(wmvg.grp_mtdb,0);
                    CONTINUER := false;
               END IF;
               end if;
            END IF;
            if continuer then
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt1 := wres.mnt1 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt2 := wres.mnt2 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_ddex THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt3 := wres.mnt3 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt4 := wres.mnt4 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            end if;
         END LOOP;

         ELSIF wpae.param2 = 3 THEN   -- Comptes à solde créditeur

         FOR wmvg IN
            (SELECT b.codjou, a.*
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt
                    and numtie in (select numtie
                                   from cp_ecr_gen a, cp_ecr b, cp_per c
                                   where a.cdos = wcdos
                                   and numcpt = wcpt.numcpt and
                                   a.codets LIKE sel_Ets
                                   and b.cdos = a.cdos
                                   and b.numsai = a.numsai
                                   and b.periode <= w_fper_c
                                   and
                	                 (
		                           (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		                           or (w_ecr_non_maj = 'O')
        		                     )
		                           and
		                           (
      		                         (
	      	                           (W_SIM = 'N')
		                                   and
			                             (b.CODJOU in (select CODJOU FROM CP_JOU
        				                               WHERE CDOS = WCDOS
		      			                               and NATJOU != 'S'
			      	                               )
			                              )
       		                         )
	      	                       or
  	                                   (W_SIM = 'O')
      		                     )
	      	                     and c.cdos = b.cdos
    	                         and c.periode =b.periode
	      	                     and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
                                 group by numtie
                                 having sum(nvl(dos_mtdb,0))-sum(nvl(dos_mtcr,0))<0)

                    --a.datcpt <= w_fper
                    and a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w_fper_c
                    and b.periode <= w_fper_c
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
		            and
		            (
      		          (
	      	            (W_SIM = 'N')
		                    and
			              (b.CODJOU in (select CODJOU FROM CP_JOU
        				                WHERE CDOS = WCDOS
		      			                and NATJOU != 'S'
			      	                )
			               )
       		          )
	      	        or
  	                    (W_SIM = 'O')
      		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
	      	      and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            IF w_reou = 'O' AND wmvg.codjou != wdos.dcjr THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND  w_ran = 'N' AND
               wmvg.datcpt < wdos.ddes THEN
               CONTINUER := false;
            END IF;
            IF w_dper > wdos.dfex AND w_ran = 'O' AND wmvg.datcpt < wdos.ddes THEN
               IF wpro.codran = 'N' THEN
                  CONTINUER := false;
               END IF;
               if continuer then
               IF wmvg.sens = 'C' THEN
                    w_cum_solde_cr := w_cum_solde_cr + nvl(wmvg.grp_mtcr,0);
                    CONTINUER := false;
               ELSE w_cum_solde_db := w_cum_solde_db + nvl(wmvg.grp_mtdb,0);
                    CONTINUER := false;
               END IF;
               end if;
            END IF;
            if continuer then
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt1 := wres.mnt1 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt2 := wres.mnt2 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_ddex THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt3 := wres.mnt3 + nvl(wmvg.grp_mtdb,0);
               ELSE wres.mnt4 := wres.mnt4 + nvl(wmvg.grp_mtcr,0);
               END IF;
            END IF;
            end if;
         END LOOP;

         END IF;

         IF w_cum_solde_cr > w_cum_solde_db THEN
              wres.mnt4 :=  wres.mnt4 - w_cum_solde_db + w_cum_solde_cr;
         ELSE wres.mnt3 :=  wres.mnt3 - w_cum_solde_cr + w_cum_solde_db;
         END IF;
         IF wres.mnt4 > wres.mnt3 THEN
              wres.mnt12 := wres.mnt4 - wres.mnt3;
         ELSE wres.mnt12 := wres.mnt3 - wres.mnt4;
         END IF;

         IF wpae.param2 != 0 THEN
              wedit          := 2;
              w_cum_solde_db := wres.mnt3 - wres.mnt4;

                 IF   wpae.param2 = 1 then
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;

                 elsif wpae.param2 = 2 then
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;

                 elsif wpae.param2 = 3 then
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;

                 elsif wpae.param2 = 4 then
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 OR wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
              END IF;

         ELSE wedit := 1;
         END IF;

         IF wedit = 1 THEN
	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
	                    w_session_id);   --lk
         END IF;
         commit; --lk

      END IF;
      END LOOP;
      CLOSE bg_cpt_list1;
   END LOOP;
   CLOSE bg_list1;

/*lk
            if w_rg_dev = 'D' then
                cpcum.mced := nvl(wmvg.dos_mtcr,0);
                cpcum.mded := nvl(wmvg.dos_mtdb,0);
            else
                cpcum.mced := nvl(wmvg.grp_mtcr,0);
                cpcum.mded := nvl(wmvg.grp_mtdb,0);
            end if;
*/
   RETURN TRUE;
END gen_bg;


-------------------------------------------------------------------------------
-- Modules communs aux etats parametres
-------------------------------------------------------------------------------

----------------------- Creation des tables temporaires ------------------
FUNCTION pae_tabtmp RETURN BOOLEAN
IS

BEGIN

   DELETE FROM cp_edi where session_id = w_session_id;
   DELETE FROM cp_res where session_id = w_session_id;

   COMMIT;

   RETURN TRUE;

END pae_tabtmp;

----------------------- REMISE A ZERO D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_10 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0     THEN
      clcum_c1(p1) := 0;
      clcum_c2(p1) := 0;
      clcum_c3(p1) := 0;
      clcum_c4(p1) := 0;
      clcum_c5(p1) := 0;
      clcum_c6(p1) := 0;
      clcum_c7(p1) := 0;
      clcum_c8(p1) := 0;
   END IF;
   IF p2 != 0     THEN
      clcum_c1(p2) := 0;
      clcum_c2(p2) := 0;
      clcum_c3(p2) := 0;
      clcum_c4(p2) := 0;
      clcum_c5(p2) := 0;
      clcum_c6(p2) := 0;
      clcum_c7(p2) := 0;
      clcum_c8(p2) := 0;
   END IF;
   IF p3 != 0     THEN
      clcum_c1(p3) := 0;
      clcum_c2(p3) := 0;
      clcum_c3(p3) := 0;
      clcum_c4(p3) := 0;
      clcum_c5(p3) := 0;
      clcum_c6(p3) := 0;
      clcum_c7(p3) := 0;
      clcum_c8(p3) := 0;
   END IF;
   IF p4 != 0     THEN
      clcum_c1(p4) := 0;
      clcum_c2(p4) := 0;
      clcum_c3(p4) := 0;
      clcum_c4(p4) := 0;
      clcum_c5(p4) := 0;
      clcum_c6(p4) := 0;
      clcum_c7(p4) := 0;
      clcum_c8(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_10;

-----------------------  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_11 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0   THEN
      cpt_mjcum(p1) := 1;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 1;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 1;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 1;
   END IF;

   RETURN TRUE;

END func_pae_11;

---------------- RAZ  +  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_12 RETURN BOOLEAN
IS

BEGIN

   w_faitout := func_pae_10;
   w_faitout := func_pae_11;

   RETURN TRUE;

END func_pae_12;

----------------------  SUSPENSION D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_13 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0   THEN
      cpt_mjcum(p1) := 0;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 0;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 0;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_13;

----------------------  TRANSFERT DE P1 --> P2  -----------------------
FUNCTION func_pae_20 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1);
      clcum_c2(p2)  := clcum_c2(p1);
      clcum_c3(p2)  := clcum_c3(p1);
      clcum_c4(p2)  := clcum_c4(p1);
      clcum_c5(p2)  := clcum_c5(p1);
      clcum_c6(p2)  := clcum_c6(p1);
      clcum_c7(p2)  := clcum_c7(p1);
      clcum_c8(p2)  := clcum_c8(p1);
   END IF;

   RETURN TRUE;

END func_pae_20;

----------------------  TRANSFERT DE P1 + P2  --> P3  -----------------
FUNCTION func_pae_21 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) + clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) + clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) + clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) + clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) + clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) + clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) + clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) + clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_21;

---------------  P1 - P2 --> P3  -----------------------------------------------
FUNCTION func_pae_22 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) - clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) - clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) - clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) - clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) - clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) - clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) - clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) - clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_22;

/*
----------------------  SOLDE 1 COMPTEUR P1   --> P2  -----------------
--                      SI P3 = 1 EN DEBIT OU CREDIT
--                      SI P3 = 2 EN DEBIT OBLIGAT.
--                      SI P3 = 3 EN CREDIT  "  "
FUNCTION func_pae_23 RETURN BOOLEAN
IS

BEGIN

   IF p1 = 0 OR p2 = 0 OR p3 = 0 OR p3 > 3  THEN
        w_l5 := ' ';
   ELSE FOR indi IN 1..2
        LOOP
           indic       := 0;
           w_cum_solde_db := clcum_c1(p1) - clcum_c2(p1);
           IF w_cum_solde_db >= 0 THEN
              indic := 1;
           END IF;
        END LOOP;
  END IF;

   RETURN TRUE;

END func_pae_23;
*/

---------------  TRANSFERT AVEC INVERSION DE SIGNE P1 --> P2  ------------------
FUNCTION func_pae_25 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1) * -1;
      clcum_c2(p2)  := clcum_c2(p1) * -1;
      clcum_c3(p2)  := clcum_c3(p1) * -1;
      clcum_c4(p2)  := clcum_c4(p1) * -1;
      clcum_c5(p2)  := clcum_c5(p1) * -1;
      clcum_c6(p2)  := clcum_c6(p1) * -1;
      clcum_c7(p2)  := clcum_c7(p1) * -1;
      clcum_c8(p2)  := clcum_c8(p1) * -1;
   END IF;

   RETURN TRUE;

END func_pae_25;

