PROCEDURE ledbg01 (woptions IN VARCHAR2)
IS

    CURSOR bg_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN

--  lecture des parametres d'edition dans le fichier evlanc

    w_bala       := ltrim(rtrim(substr(woptions,1,3)));
    w_dper_c     := substr(woptions,4,3);
    w_fper_c     := substr(woptions,7,3);

    w_cuti       := substr(woptions,10,4);
    wcdos        := substr(woptions,14,2);
    w_ets        := substr(woptions,16,3);
    w_rg_dev	 := substr(woptions,19,1);
    w_ecr_non_maj := substr(woptions,20,1);
    w_per_comp	 := substr(woptions,21,1);
    w_sim	 := substr(woptions,22,1);
    w_session_id := to_number(substr(woptions,23,38));
    w_numexe := substr(w_dper_c,1,1);

    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk

      begin
         select count(*) into w_nb_per_exe
         from cp_per
         where cdos = wcdos
         and substr(periode,1,1) = w_numexe;
      exception
         when others then null;
      end;

--dbms_output.enable(50000);
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;

--dbms_output.put_line(to_char(w_dper));
    IF ltrim(w_ets) IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;

    w_faitout := pae_tabtmp;
    w_faitout := gen_bg;

    larg_ed             := 199;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,210);
    w_l3                := ver || RPAD(' ',210) || ver;

    w_l4                := ver || RPAD(' ',17);

    for w in (select periode,datdeb from cp_per
               where cdos = wcdos
               and substr(periode,1,1) = w_numexe
               order by periode)
    loop
       w_l4 :=    w_l4||
                  ver|| RPAD(' ',14);
    end loop;
    w_l4 := w_l4||ver;

    w_numord_edi := 0;

    for w in (select periode,datdeb from cp_per
               where cdos = wcdos
               and substr(periode,1,1) = w_numexe
               order by periode)
    loop
    i := fcalc_rg_per(w.periode);
    FOR indi IN 1..9
    LOOP

       if i = 1 then
          clcum_c1_1(indi)  := 0;
          clcum_c2_1(indi)  := 0;
          clcum_c3_1(indi)  := 0;
          clcum_c4_1(indi)  := 0;
          clcum_c5_1(indi)  := 0;
          clcum_c6_1(indi)  := 0;
          cpt_mjcum_1(indi) := 0;
       elsif i = 2 then
          clcum_c1_2(indi)  := 0;
          clcum_c2_2(indi)  := 0;
          clcum_c3_2(indi)  := 0;
          clcum_c4_2(indi)  := 0;
          clcum_c5_2(indi)  := 0;
          clcum_c6_2(indi)  := 0;
          cpt_mjcum_2(indi) := 0;
       elsif i = 3 then
          clcum_c1_3(indi)  := 0;
          clcum_c2_3(indi)  := 0;
          clcum_c3_3(indi)  := 0;
          clcum_c4_3(indi)  := 0;
          clcum_c5_3(indi)  := 0;
          clcum_c6_3(indi)  := 0;
          cpt_mjcum_3(indi) := 0;
       elsif i = 4 then
          clcum_c1_4(indi)  := 0;
          clcum_c2_4(indi)  := 0;
          clcum_c3_4(indi)  := 0;
          clcum_c4_4(indi)  := 0;
          clcum_c5_4(indi)  := 0;
          clcum_c6_4(indi)  := 0;
          cpt_mjcum_4(indi) := 0;
       elsif i = 5 then
          clcum_c1_5(indi)  := 0;
          clcum_c2_5(indi)  := 0;
          clcum_c3_5(indi)  := 0;
          clcum_c4_5(indi)  := 0;
          clcum_c5_5(indi)  := 0;
          clcum_c6_5(indi)  := 0;
          cpt_mjcum_5(indi) := 0;
       elsif i = 6 then
          clcum_c1_6(indi)  := 0;
          clcum_c2_6(indi)  := 0;
          clcum_c3_6(indi)  := 0;
          clcum_c4_6(indi)  := 0;
          clcum_c5_6(indi)  := 0;
          clcum_c6_6(indi)  := 0;
          cpt_mjcum_6(indi) := 0;
       elsif i = 7 then
          clcum_c1_7(indi)  := 0;
          clcum_c2_7(indi)  := 0;
          clcum_c3_7(indi)  := 0;
          clcum_c4_7(indi)  := 0;
          clcum_c5_7(indi)  := 0;
          clcum_c6_7(indi)  := 0;
          cpt_mjcum_7(indi) := 0;
       elsif i = 8 then
          clcum_c1_8(indi)  := 0;
          clcum_c2_8(indi)  := 0;
          clcum_c3_8(indi)  := 0;
          clcum_c4_8(indi)  := 0;
          clcum_c5_8(indi)  := 0;
          clcum_c6_8(indi)  := 0;
          cpt_mjcum_8(indi) := 0;
       elsif i = 9 then
          clcum_c1_9(indi)  := 0;
          clcum_c2_9(indi)  := 0;
          clcum_c3_9(indi)  := 0;
          clcum_c4_9(indi)  := 0;
          clcum_c5_9(indi)  := 0;
          clcum_c6_9(indi)  := 0;
          cpt_mjcum_9(indi) := 0;
       elsif i = 10 then
          clcum_c1_10(indi)  := 0;
          clcum_c2_10(indi)  := 0;
          clcum_c3_10(indi)  := 0;
          clcum_c4_10(indi)  := 0;
          clcum_c5_10(indi)  := 0;
          clcum_c6_10(indi)  := 0;
          cpt_mjcum_10(indi) := 0;
       elsif i = 11 then
          clcum_c1_11(indi)  := 0;
          clcum_c2_11(indi)  := 0;
          clcum_c3_11(indi)  := 0;
          clcum_c4_11(indi)  := 0;
          clcum_c5_11(indi)  := 0;
          clcum_c6_11(indi)  := 0;
          cpt_mjcum_11(indi) := 0;
       elsif i = 12 then
          clcum_c1_12(indi)  := 0;
          clcum_c2_12(indi)  := 0;
          clcum_c3_12(indi)  := 0;
          clcum_c4_12(indi)  := 0;
          clcum_c5_12(indi)  := 0;
          clcum_c6_12(indi)  := 0;
          cpt_mjcum_12(indi) := 0;
       elsif i = 13 then
          clcum_c1_13(indi)  := 0;
          clcum_c2_13(indi)  := 0;
          clcum_c3_13(indi)  := 0;
          clcum_c4_13(indi)  := 0;
          clcum_c5_13(indi)  := 0;
          clcum_c6_13(indi)  := 0;
          cpt_mjcum_13(indi) := 0;
       end if;
    END LOOP;
    end loop; --fin loop période

    OPEN bg_list;
    LOOP
        FETCH bg_list INTO wpae;
        EXIT WHEN bg_list%NOTFOUND;

        p1  := wpae.param1;
