FUNCTION func_bg_01 RETURN BOOLEAN
IS

BEGIN

    w_page  := w_page + 1;
    w_ligne := 0;
    arg1    := w_page;   --lk

    w_supl := 0;

    arg2 := w_l1;
    w_faitout := up_tmp_bg;


    w_l5          := RPAD(ver,2) ||
                    'Societe       : ' || wdos.cdos || '  ' ||
                     RPAD(wdos.nred,154) || 'Page' ||
                     TO_CHAR(w_page, '9999') || LPAD(ver,14);
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       w_l5          := RPAD(ver,2) ||
                       'Etablissement : ' || LPAD(w_ets,3) || ' ' ||
                        RPAD(ets_lib,183) || ver;
       arg2          := w_l5;
       w_faitout := up_tmp_bg;
    END IF;

    w_l5          := RPAD(ver,2) || RPAD(' ',96) ||
                     RPAD(w_titre,63) ||' Periode du ' ||
                     TO_CHAR(w_dper, 'dd-mm-yyyy') || ' au ' ||
                     TO_CHAR(w_fper, 'dd-mm-yyyy') ||
                     LPAD(ver,2);
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    w_supl := 0;
    w_l5          := ver ||
                    'Edite le ' || TO_CHAR(sysdate, 'dd-mm-yyyy "a" hh:mi:ss') ||
                     rpad(' ',80)||LPAD('Util. : ',73) || w_cuti || LPAD(ver,11);
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    arg2          := w_l1;
    w_faitout := up_tmp_bg;

    w_l5          := ver || RPAD('LIBELLE',17) ;
    for w in (select periode,datdeb from cp_per
               where cdos = wcdos
               and substr(periode,1,1) = w_numexe
               order by periode)
    loop
       w_l5 :=   w_l5||ver|| RPAD(substr(to_char(w.datdeb,'Month'),1,9),14);
    end loop;

    w_l5 :=       w_l5||ver;
    arg2          := w_l5;
    w_faitout := up_tmp_bg;

    arg2          := w_l1;
    w_faitout := up_tmp_bg;

    arg2          := w_l4;
    w_faitout := up_tmp_bg;

    RETURN TRUE;
END func_bg_01;

----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_bg_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5  := ver || RPAD(' ',28) ;
    for w in (select periode,datdeb from cp_per
               where cdos = wcdos
               and substr(periode,1,1) = w_numexe
               order by periode)
    loop
       w_l5 :=   w_l5||ver|| RPAD(' ',14);
    end loop;

    w_l5 :=       w_l5||ver;
    arg2          := w_l5;
    w_faitout := up_tmp_bg;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_bg;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_bg_02;

