----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_bg(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2) RETURN BOOLEAN
IS
  i integer := 1;
BEGIN

    w_l5      := ver ||
                 RPAD(nvl(ed_intr,' '),17) ||ver|| SUBSTR(nvl(w_l4,' '),30,14);

    i := 1;
       for w in (select periode from cp_per
                  where cdos = wcdos
                  and substr(periode,1,1) = w_numexe
                  order by periode)
       loop
         if length(w_l5) < 18 then
            w_l5 := rpad(' ',18);
         end if;

         if i = 1 then

          IF cpcum2.sold1 != 0 THEN
             mtf := numfs(cpcum2.sold1,w_ndec);
          ELSE
             mtf := numfs(cpcum2.solc1,w_ndec);
          END IF;

          w_l5   :=  SUBSTR(w_l5,1,19+(i-1)*15)
                     || lpad(nvl(mtf,' '),14)||ver
