----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_bg RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

    w_nblg     := w_needlg + w_ligne;
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_bg_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;
    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_bg;

----------------------- Calcul et MAJ des cumuls des comptes -------------

FUNCTION gen_bg RETURN BOOLEAN
IS

    CURSOR bg_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40' ORDER BY cdos,codeta,numord;

   CURSOR bg_cpt_list1 IS
         SELECT a.cdos, a.numcpt, a.intcpt, b.codran, b.natcpt, a.raccpt
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;

    rupt                 VARCHAR2(16);
    continuer            BOOLEAN;

BEGIN
    OPEN bg_list1;
    LOOP
        FETCH bg_list1 INTO wpae;
        EXIT WHEN bg_list1%NOTFOUND;
        for w in (select periode from cp_per where cdos = wcdos
                  and substr(periode,1,1) = w_numexe
                  order by periode)
        loop

           OPEN bg_cpt_list1;
           LOOP
               FETCH bg_cpt_list1 INTO wcpt.cdos, wcpt.numcpt,
                     wcpt.intcpt, wpro.codran, wpro.natcpt, wcpt.raccpt;
               EXIT WHEN bg_cpt_list1%NOTFOUND;

               continuer := false;

               begin
                  --SELECT numcpt INTO char8 FROM cp_res_exe WHERE
                  SELECT count(numcpt) INTO w_un_nb FROM cp_res_exe WHERE
                     cdos = wcpt.cdos
                     AND session_id = w_session_id
                     and numcpt = wcpt.numcpt
                     and periode = w.periode;

                  if w_un_nb = 0 then
                     continuer := true;
                  end if;
               exception
                  when no_data_found then
                     continuer := true;
                  when others then
                     continuer := true;
               end;

            if continuer then
   --lk           INITIALIZE wres.* TO NULL
               wres.numsec    := '00000000';
               wres.mnt1      := 0;
               wres.mnt2      := 0;
               wres.mnt3      := 0;
               wres.mnt4      := 0;
               wres.cdos      := wcdos;
               wres.numcpt      := wcpt.numcpt;
               if wpae.sel = 'I' then
                 wres.libe      := wcpt.raccpt;
               else
                 wres.libe      := wcpt.intcpt;
               end if;
               wres.sens      := 'X';
               wres.ctie      := substr(wpro.natcpt,1,1);
               w_numper := fcalc_rg_per(w.periode);
               w_cum_solde_cr(w_numper) := 0;
               w_cum_solde_db(w_numper) := 0;

            FOR wmvg IN
               (SELECT b.codjou,b.periode, a.*
                  FROM cp_ecr_gen a, cp_ecr b, cp_per c
                 WHERE a.cdos =  wcdos AND
                       numcpt = wcpt.numcpt
                       and a.codets LIKE sel_Ets
                       and b.cdos = a.cdos
                       and b.numsai = a.numsai
                       --and b.periode between w_exercice and w_fper_c
                       and b.periode = w.periode
                       and
                   	  (
   		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
   		            or (w_ecr_non_maj = 'O')
           		      )
   		            and
   		            (
         		          (
   	      	            (W_SIM = 'N')
   		                    and
   			              (b.CODJOU in (select CODJOU FROM CP_JOU
           				                WHERE CDOS = WCDOS
   		      			                and NATJOU != 'S'
   			      	                )
   			               )
          		          )
   	      	        or
     	                    (W_SIM = 'O')
         		      )
   	      	      and c.cdos = b.cdos
       	          and c.periode =b.periode
   	      	      and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))

                 ORDER BY a.cdos,a.numcpt)
           LOOP
               -- Dans le cas d'une balance de reouverture,
               -- seules les ecritures dont le code journal est egal au
               -- journal de cloture (dossier) sont prises en compte

               IF w_reou = 'O' AND wmvg.codjou != wdos.dcjr THEN
                  CONTINUER := false;
               END IF;

               -- Dans le cas d'une balance sur l'exercice suivant, si la
               -- "cloture simulee" (RAN) n'est pas demandee, seuls les
               -- mouvements >= date de debut de l'exercice suivant sont
               -- pris en compte

               IF w_dper > wdos.dfex AND w_ran = 'N' AND
                  wmvg.datcpt < wdos.ddes THEN
                  CONTINUER := false;
               END IF;

               --  simulation de la cloture   :  cpt de gestion  = 0
               --             cpt de bilan    = solde au wdos.dfex (fin ex.)

               IF w_dper > wdos.dfex AND w_ran = 'O' AND wmvg.datcpt < wdos.ddes THEN
                  IF wpro.codran = 'N' THEN
                     CONTINUER := false;
                  END IF;
                  if continuer then

                  IF wmvg.sens = 'C' THEN
                       w_cum_solde_cr(w_numper) := w_cum_solde_cr(w_numper) + wmvg.grp_mtcr;
                       CONTINUER := false;
                  ELSE w_cum_solde_db(w_numper) := w_cum_solde_db(w_numper) + wmvg.grp_mtdb;
                       CONTINUER := false;
                  END IF;

                  end if;
               END IF;

               if continuer then
               IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
                  IF wmvg.sens = 'D' THEN
                       wres.mnt1 := wres.mnt1 + wmvg.grp_mtdb;
                  ELSE wres.mnt2 := wres.mnt2 + wmvg.grp_mtcr;
                  END IF;
               END IF;

               IF wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_ddex THEN
                  IF wmvg.sens = 'D' THEN
                       wres.mnt3 := wres.mnt3 + wmvg.grp_mtdb;
                  ELSE wres.mnt4 := wres.mnt4 + wmvg.grp_mtcr;
                  END IF;
               END IF;
               end if;

            END LOOP;  --fin loop mvt

            IF w_cum_solde_cr(w_numper) > w_cum_solde_db(w_numper) THEN
                 wres.mnt4 :=  wres.mnt4 - w_cum_solde_db(w_numper) + w_cum_solde_cr(w_numper);
            ELSE wres.mnt3 :=  wres.mnt3 - w_cum_solde_cr(w_numper) + w_cum_solde_db(w_numper);
            END IF;
            IF wres.mnt4 > wres.mnt3 THEN
                 wres.mnt12 := wres.mnt4 - wres.mnt3;
            ELSE wres.mnt12 := wres.mnt3 - wres.mnt4;
            END IF;

            IF wpae.param2 != 0 THEN
                 wedit          := 2;
                 w_cum_solde_db(w_numper) := wres.mnt3 - wres.mnt4;

                    IF   wpae.param2 = 1 then
                         IF w_cum_solde_db(w_numper) != 0 THEN
                            wedit := 1;
                         END IF;

                    elsif wpae.param2 = 2 then
                         IF w_cum_solde_db(w_numper) > 0 THEN
                            wedit := 1;
                         END IF;

                    elsif wpae.param2 = 3 then
                         IF w_cum_solde_db(w_numper) < 0 THEN
                            wedit := 1;
                         END IF;

                    elsif wpae.param2 = 4 then
                         IF w_cum_solde_db(w_numper) != 0 THEN
                            wedit := 1;
                         END IF;
                         IF wres.mnt1 != 0 OR wres.mnt2 != 0 THEN
                            wedit := 1;
                         END IF;
                    END IF;

            ELSE wedit := 1;
            END IF;

            IF wedit = 1 THEN
   	          INSERT INTO cp_res_exe VALUES (wres.cdos, wres.numcpt,
   	                wres.numsec, wres.libe, w.periode, wres.mnt1, wres.mnt2,
   	                wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
   	                wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
   	                wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
   	                w_session_id);
            END IF;
            commit; --lk
         END IF;
         END LOOP;
         CLOSE bg_cpt_list1;
      end loop;     --loop sur périodes
   END LOOP;
   CLOSE bg_list1;

   RETURN TRUE;
END gen_bg;


