--                      SI P3 = 2 EN DEBIT OBLIGAT.
--                      SI P3 = 3 EN CREDIT  "  "
FUNCTION func_pae_23 RETURN BOOLEAN
IS
 i integer;
BEGIN

   IF p1 = 0 OR p2 = 0 OR p3 = 0 OR p3 > 3  THEN
        w_l5 := ' ';
   ELSE FOR indi IN 1..2
        LOOP
         for w2 in (select periode from cp_per
                     where cdos = wcdos
                     and substr(periode,1,1) = w_numexe
                     order by periode)
         loop
            i := fcalc_rg_per(w2.periode);
           indic       := 0;
           if i = 1 then
               w_cum_solde_db(i) := clcum_c1_1(p1) - clcum_c2_1(p1);
           elsif i = 2 then
               w_cum_solde_db(i) := clcum_c1_2(p1) - clcum_c2_2(p1);
           elsif i = 3 then
               w_cum_solde_db(i) := clcum_c1_3(p1) - clcum_c2_3(p1);
           elsif i = 4 then
               w_cum_solde_db(i) := clcum_c1_4(p1) - clcum_c2_4(p1);
           elsif i = 5 then
               w_cum_solde_db(i) := clcum_c1_5(p1) - clcum_c2_5(p1);
           elsif i = 6 then
               w_cum_solde_db(i) := clcum_c1_6(p1) - clcum_c2_6(p1);
           elsif i = 7 then
               w_cum_solde_db(i) := clcum_c1_7(p1) - clcum_c2_7(p1);
           elsif i = 8 then
               w_cum_solde_db(i) := clcum_c1_8(p1) - clcum_c2_8(p1);
           elsif i = 9 then
               w_cum_solde_db(i) := clcum_c1_9(p1) - clcum_c2_9(p1);
           elsif i = 10 then
               w_cum_solde_db(i) := clcum_c1_10(p1) - clcum_c2_10(p1);
           elsif i = 11 then
               w_cum_solde_db(i) := clcum_c1_11(p1) - clcum_c2_11(p1);
           elsif i = 12 then
               w_cum_solde_db(i) := clcum_c1_12(p1) - clcum_c2_12(p1);
           elsif i = 13 then
               w_cum_solde_db(i) := clcum_c1_13(p1) - clcum_c2_13(p1);
           end if;
           IF w_cum_solde_db(i) >= 0 THEN
              indic := 1;
           END IF;
          end loop;
        END LOOP;
  END IF;

   RETURN TRUE;

END func_pae_23;
