FUNCTION numfs(mt IN NUMBER, ndc IN NUMBER) RETURN VARCHAR2
IS
 wmtf varchar2(14);
BEGIN

   IF      nvl(ndc,0) = 3 THEN wmtf := substr(TO_CHAR(mt, '999999990D000'),1,14);
   ELSIF   nvl(ndc,0) = 2 THEN wmtf := substr(TO_CHAR(mt, '9999999990D00'),1,14);
   ELSIF   nvl(ndc,0) = 1 THEN wmtf := substr(TO_CHAR(mt, '99999999990D0'),1,14);
   ELSE                  wmtf := substr(TO_CHAR(mt, '99999G999G990'),1,14);
   END IF;

   RETURN wmtf;

END numfs;

function fcalc_rg_per(wper cp_res_exe.periode%type) return number
is
  i integer := 0;
begin
  i := 0;
  for w in (select periode
            from cp_per
            where cdos = wcdos
            and substr(periode,1,1) = substr(wper,1,1)
            order by periode
            )
  loop
    i := i + 1;
    exit when w.periode = wper;
  end loop;
  return i;
end fcalc_rg_per;


