                     substr(w_l4,43,4)  || 'Fevrier'   ||
                     substr(w_l4,54,6)  || 'Mars'      ||
                     substr(w_l4,64,6)  || 'Avril'     ||
                     substr(w_l4,75,7)  || 'Mai'       ||
                     substr(w_l4,85,8)  || 'Juin'      ||
                     substr(w_l4,97,5)  || 'Juillet'   ||
                     substr(w_l4,109,6) || 'Aout'      ||
                     substr(w_l4,119,4) || 'Septembre' ||
                     substr(w_l4,132,3) || 'Octobre'   ||
                     substr(w_l4,142,4) || 'Novembre'  ||
                     substr(w_l4,154,3) || 'Decembre'  ||
                     substr(w_l4,165,4) || 'Total'     ||
                     substr(w_l4,174);
    arg2          := w_l5;
    w_faitout := up_tmp_cr1;

    arg2          := w_l1;
    w_faitout := up_tmp_cr1;

    RETURN TRUE;
END func_cr1_01;

