---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_cr1_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.jan := clcum_c1(p1);
       cpcum.fev := clcum_c2(p1);
       cpcum.mar := clcum_c3(p1);
       cpcum.avr := clcum_c4(p1);
       cpcum.mai := clcum_c5(p1);
       cpcum.jun := clcum_c6(p1);
       cpcum.jul := clcum_c7(p1);
       cpcum.aou := clcum_c8(p1);
       cpcum.sep := clcum_c9(p1);
       cpcum.oct := clcum_c10(p1);
       cpcum.nov := clcum_c11(p1);
       cpcum.dec := clcum_c12(p1);
       w_faitout := detail_cr1(' ',wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
       clcum_c7(p1)   := 0;
       clcum_c8(p1)   := 0;
       clcum_c9(p1)   := 0;
       clcum_c10(p1)  := 0;
       clcum_c11(p1)  := 0;
       clcum_c12(p1)  := 0;
    END IF;

    RETURN TRUE;
END func_cr1_30;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_cr1_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        w_cum_solde_db := nvl(wres.mnt1,0)+nvl(wres.mnt2,0)+nvl(wres.mnt3,0)+nvl(wres.mnt4,0)
                         +nvl(wres.mnt5,0)+nvl(wres.mnt6,0)+nvl(wres.mnt7,0)+nvl(wres.mnt8,0)
                         +nvl(wres.mnt9,0)+nvl(wres.mnt10,0)+nvl(wres.mnt11,0)+nvl(wres.mnt12,0);

        IF p2 != 0 THEN
             wedit          := 2;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 AND wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit != 2     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                 clcum_c1(wi)  := clcum_c1(wi) + nvl(wres.mnt1,0);
                 clcum_c2(wi)  := clcum_c2(wi) + nvl(wres.mnt2,0);
                 clcum_c3(wi)  := clcum_c3(wi) + nvl(wres.mnt3,0);
                 clcum_c4(wi)  := clcum_c4(wi) + nvl(wres.mnt4,0);
                 clcum_c5(wi)  := clcum_c5(wi) + nvl(wres.mnt5,0);
                 clcum_c6(wi)  := clcum_c6(wi) + nvl(wres.mnt6,0);
                 clcum_c7(wi)  := clcum_c7(wi) + nvl(wres.mnt7,0);
                 clcum_c8(wi)  := clcum_c8(wi) + nvl(wres.mnt8,0);
                 clcum_c9(wi)  := clcum_c9(wi) + nvl(wres.mnt9,0);
                 clcum_c10(wi) := clcum_c10(wi) + nvl(wres.mnt10,0);
                 clcum_c11(wi) := clcum_c11(wi) + nvl(wres.mnt11,0);
                 clcum_c12(wi) := clcum_c12(wi) + nvl(wres.mnt12,0);
               END IF;
           END LOOP;
        END IF;
  -- dbms_output.put_line('wedit '||wedit||' p1 '||p1||' p2 '||p2);

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.jan :=  nvl(wres.mnt1,0);
           cpcum.fev :=  nvl(wres.mnt2,0);
           cpcum.mar :=  nvl(wres.mnt3,0);
           cpcum.avr :=  nvl(wres.mnt4,0);
           cpcum.mai :=  nvl(wres.mnt5,0);
           cpcum.jun :=  nvl(wres.mnt6,0);
           cpcum.jul :=  nvl(wres.mnt7,0);
           cpcum.aou :=  nvl(wres.mnt8,0);
           cpcum.sep :=  nvl(wres.mnt9,0);
           cpcum.oct :=  nvl(wres.mnt10,0);
           cpcum.nov :=  nvl(wres.mnt11,0);
           cpcum.dec :=  nvl(wres.mnt12,0);
           w_faitout := detail_cr1(wres.numcpt,wres.libe);
        END IF;
    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_cr1_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_cr1(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2) RETURN BOOLEAN
IS
  w_tot number;
BEGIN

    w_l5      := RPAD(ver,2) || RPAD(ed_intr,30) || SUBSTR(w_l4,33);
    mtf := numfs(cpcum.jan,w_ndec);
    IF cpcum.jan != 0 THEN
       w_l5   := SUBSTR(w_l5,1,34) || mtf || substr(w_l5,45);
    END IF;
    mtf := numfs(cpcum.fev,w_ndec);
    IF cpcum.fev != 0 THEN
       w_l5   := SUBSTR(w_l5,1,45) || mtf || substr(w_l5,56);
    END IF;
    mtf := numfs(cpcum.mar,w_ndec);
    IF cpcum.mar != 0 THEN
       w_l5   := SUBSTR(w_l5,1,56) || mtf || substr(w_l5,67);
    END IF;
    mtf := numfs(cpcum.avr,w_ndec);
    IF cpcum.avr != 0 THEN
       w_l5   := SUBSTR(w_l5,1,67) || mtf || substr(w_l5,78);
    END IF;
    mtf := numfs(cpcum.mai,w_ndec);
    IF cpcum.mai != 0 THEN
       w_l5   := SUBSTR(w_l5,1,78) || mtf || substr(w_l5,89);
    END IF;
    mtf := numfs(cpcum.jun,w_ndec);
    IF cpcum.jun != 0 THEN
       w_l5   := SUBSTR(w_l5,1,89) || mtf || substr(w_l5,100);
    END IF;
    mtf := numfs(cpcum.jul,w_ndec);
    IF cpcum.jul != 0 THEN
       w_l5   := SUBSTR(w_l5,1,100) || mtf || substr(w_l5,111);
    END IF;
    mtf := numfs(cpcum.aou,w_ndec);
    IF cpcum.aou != 0 THEN
       w_l5   := SUBSTR(w_l5,1,111) || mtf || substr(w_l5,122);
    END IF;
    mtf := numfs(cpcum.sep,w_ndec);
    IF cpcum.sep != 0 THEN
       w_l5   := SUBSTR(w_l5,1,122) || mtf || substr(w_l5,133);
    END IF;
    mtf := numfs(cpcum.oct,w_ndec);
    IF cpcum.oct != 0 THEN
       w_l5   := SUBSTR(w_l5,1,133) || mtf || substr(w_l5,144);
    END IF;
    mtf := numfs(cpcum.nov,w_ndec);
    IF cpcum.nov != 0 THEN
       w_l5   := SUBSTR(w_l5,1,144) || mtf || substr(w_l5,155);
    END IF;
    mtf := numfs(cpcum.dec,w_ndec);
    IF cpcum.dec != 0 THEN
       w_l5   := SUBSTR(w_l5,1,155) || mtf || substr(w_l5,166);
    END IF;
    w_tot := cpcum.jan+cpcum.fev+cpcum.mar+cpcum.avr+cpcum.mai+cpcum.jun
            +cpcum.jul+cpcum.aou+cpcum.sep+cpcum.oct+cpcum.nov+cpcum.dec;
    mtf := numfs2(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,166) || mtf || substr(w_l5,179);
    END IF;
    arg2           := w_l5;
    w_faitout := up_tmp_cr1;

    RETURN TRUE;
END detail_cr1;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_cr1 RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_cr1_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_cr1;

----------------------- Calcul et MAJ des cumuls des comptes -------------

FUNCTION cr1_maj_cpt RETURN BOOLEAN
IS

    CURSOR cr1_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40'
               ORDER BY cdos,codeta,numord;

   CURSOR cr1_cpt_list1 IS
         SELECT a.cdos,a.numcpt,a.intcpt, b.natcpt
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;

    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN
    OPEN cr1_list1;
    LOOP
        FETCH cr1_list1 INTO wpae;
        EXIT WHEN cr1_list1%NOTFOUND;

        OPEN cr1_cpt_list1;
        LOOP
            FETCH cr1_cpt_list1 INTO wcpt.cdos, wcpt.numcpt,
                  wcpt.intcpt, wpro.natcpt;
            EXIT WHEN cr1_cpt_list1%NOTFOUND;

            continuer := false;
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.numcpt;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := '00000000';
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.mnt5      := 0;
            wres.mnt6      := 0;
            wres.mnt7      := 0;
            wres.mnt8      := 0;
            wres.mnt9      := 0;
            wres.mnt10     := 0;
            wres.mnt11     := 0;
            wres.mnt12     := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.numcpt;
            wres.libe      := wcpt.intcpt;
            wres.ctie      := substr(wpro.natcpt,1,1);
       --     w_cum_solde_cr := 0;
       --     w_cum_solde_db := 0;

         FOR wmvg IN
            (SELECT  a.*, b.periode
               FROM cp_ecr_gen a, cp_ecr b
              WHERE a.cdos =  wcdos
                    AND a.numcpt = wcpt.numcpt
                    AND a.datcpt between w_dper AND w_fper
                    AND a.codets LIKE sel_Ets
                    AND b.cdos = a.cdos
                    AND b.numsai = a.numsai
                    AND
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
         --           AND b.codmaj = 'O'
              ORDER BY a.cdos,a.numcpt)
         LOOP

            CONTINUER := true;
            IF substr(wmvg.periode,2) = '01' THEN
               wres.mnt1 := wres.mnt1 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '02' THEN
               wres.mnt2 := wres.mnt2 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '03' THEN
               wres.mnt3 := wres.mnt3 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '04' THEN
               wres.mnt4 := wres.mnt4 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '05' THEN
               wres.mnt5 := wres.mnt5 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '06' THEN
               wres.mnt6 := wres.mnt6 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '07' THEN
               wres.mnt7 := wres.mnt7 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '08' THEN
               wres.mnt8 := wres.mnt8 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '09' THEN
               wres.mnt9 := wres.mnt9 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '10' THEN
               wres.mnt10 := wres.mnt10 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '11' THEN
               wres.mnt11 := wres.mnt11 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            ELSIF substr(wmvg.periode,2) = '12' THEN
               wres.mnt12 := wres.mnt12 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
            END IF;
          --  if wmvg.grp_mtcr != 0 then

--dbms_output.put_line('credit '||wmvg.numcpt||' mtant '||to_char(wmvg.grp_mtcr)||' mnt2 '||to_char(wres.mnt2));
         --   end if;
          --  if wmvg.grp_mtdb != 0 then

--dbms_output.put_line('debit '||wmvg.numcpt||' mtant '||to_char(wmvg.grp_mtdb)||' mnt1 '||to_char(wres.mnt1));
          --  end if;
         END LOOP;

	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
	                    w_session_id);   --lk

         commit; --lk
         END IF;
      END LOOP;
      CLOSE cr1_cpt_list1;
   END LOOP;
   CLOSE cr1_list1;

   RETURN TRUE;
END cr1_maj_cpt;


