------------------------------------ AFF_SOC ----------------------------------

FUNCTION numfs(mt IN NUMBER, ndc IN NUMBER) RETURN VARCHAR2
IS

BEGIN

   IF      ndc  = 3 THEN mtf := TO_CHAR(ROUND(mt/1000), '9999999990D000');
   ELSIF   ndc  = 2 THEN mtf := TO_CHAR(ROUND(mt/1000), '99999999990D00');
   ELSIF   ndc  = 1 THEN mtf := TO_CHAR(ROUND(mt/1000), '999999999990.0');
   ELSE                  mtf := TO_CHAR(ROUND(mt/1000), '999999G999G990');
   END IF;

   mtf := lpad(ltrim(mtf),10);

   RETURN mtf;

END numfs;

------------------------------------ AFF_SOC ----------------------------------

FUNCTION numfs2(mt IN NUMBER, ndc IN NUMBER) RETURN VARCHAR2
IS

BEGIN

   IF      ndc  = 3 THEN mtf := TO_CHAR(ROUND(mt/1000), '9999999990D000');
   ELSIF   ndc  = 2 THEN mtf := TO_CHAR(ROUND(mt/1000), '99999999990D00');
   ELSIF   ndc  = 1 THEN mtf := TO_CHAR(ROUND(mt/1000), '999999999990.0');
   ELSE                  mtf := TO_CHAR(ROUND(mt/1000), '999999G999G990');
   END IF;

   mtf := lpad(ltrim(mtf),12);

   RETURN mtf;

END numfs2;

