CREATE PACKAGE BODY cplcr3
AS


-------------------------------------------------------------------------------
-- Edition de la balance generale
-------------------------------------------------------------------------------

   wcpt          cp_cpt%ROWTYPE;
   wpro          cp_pro%ROWTYPE;
--   wmvg          cp_ecr_ana%ROWTYPE;

   TYPE cpcum_type IS RECORD     -- zone de cumul compte
   (    jan      NUMBER(16,3),
        fev      NUMBER(16,3),
        mar      NUMBER(16,3),
        avr      NUMBER(16,3),
        mai      NUMBER(16,3),
        jun      NUMBER(16,3),
        jul      NUMBER(16,3),
        aou      NUMBER(16,3),
        sep      NUMBER(16,3),
        oct      NUMBER(16,3),
        nov      NUMBER(16,3),
        dec      NUMBER(16,3)
   );
   cpcum         cpcum_type;

   TYPE w_reg_sec_type IS TABLE OF VARCHAR2(1) INDEX BY BINARY_INTEGER;
   w_reg_sec     w_reg_sec_type;

   --sk
   w_ecr_non_maj VARCHAR2(1);
   w_exe_prec    VARCHAR2(1);
   w_sim         VARCHAR2(1);
   w_per_comp    VARCHAR2(1);
   w_rg_dev      VARCHAR2(1);
   w_dper_c      VARCHAR2(3);
   w_fper_c      VARCHAR2(3);
   w_exercice    VARCHAR2(3);
   w_session_id  NUMBER;
   --fin sk

   w_titre       VARCHAR2(30);
   w_dper        DATE;
   w_fper        DATE;
   w_date        DATE;
   w_ddex        DATE;
   w_reou        VARCHAR2(1);
   w_ran         VARCHAR2(1);
   w_reed        VARCHAR2(1);
   w_psec        CHAR(8);
   w_dsec        CHAR(8);
   w_section     VARCHAR2(8);
   w_ndec        NUMBER;
   w_ligne       NUMBER;
   w_numord_edi  NUMBER;
   w_page        NUMBER;
   w_nblg        NUMBER;
   w_maxlg       NUMBER;
   wi            NUMBER;
   larg_ed       NUMBER;
   w_cuti        VARCHAR2(4);

   w_ets         VARCHAR2(3);
   w_axa         VARCHAR2(1);
   sel_ets       cp_ets.codets%TYPE;
   ets_lib       VARCHAR2(30);

   sauv_supl     NUMBER;
   w_supl        NUMBER;
   lig_as        VARCHAR2(1);

-------------------------------------------------------------------------------

PROCEDURE ledcr3 (woptions IN VARCHAR2)
IS

    CURSOR cr3_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN

--  lecture des parametres d'edition dans le fichier evlanc

    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);

    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_ets         := rtrim(substr(woptions,16,3));
    w_session_id  := to_number(substr(woptions,19,38));
    w_ecr_non_maj := substr(woptions,57,1);
    w_exe_prec    := substr(woptions,58,1);

    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk

--dbms_output.enable(50000);
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;

--dbms_output.put_line(to_char(w_dper));
    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH24:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;

    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := cr3_maj_cpt;
--dbms_output.put_line('cr3_maj_cpt');

    larg_ed             := 166;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,164) || ver;
    w_l3                := ver || RPAD(' ',164) || ver;
    w_l4                := SUBSTR(w_l3,1,33) ||
                           ver || SUBSTR(w_l3,35,10) ||
                           ver || SUBSTR(w_l3,46,10) ||
                           ver || SUBSTR(w_l3,57,10) ||
                           ver || SUBSTR(w_l3,68,10) ||
                           ver || SUBSTR(w_l3,79,10) ||
                           ver || SUBSTR(w_l3,90,10) ||
                           ver || SUBSTR(w_l3,101,10) ||
                           ver || SUBSTR(w_l3,112,10) ||
                           ver || SUBSTR(w_l3,123,10) ||
                           ver || SUBSTR(w_l3,134,10) ||
                           ver || SUBSTR(w_l3,145,10) ||
                           ver || SUBSTR(w_l3,156);

    w_numord_edi := 0;

    FOR indi IN 1..9
    LOOP
       clcum_c1(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       clcum_c5(indi)  := 0;
       clcum_c6(indi)  := 0;
       clcum_c7(indi)  := 0;
       clcum_c8(indi)  := 0;
       clcum_c9(indi)  := 0;
       clcum_c10(indi)  := 0;
       clcum_c11(indi)  := 0;
       clcum_c12(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;

    OPEN cr3_list;
    LOOP
        FETCH cr3_list INTO wpae;
        EXIT WHEN cr3_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_cr3_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_cr3_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_cr3_03;
            ELSIF wpae.codope = '04' THEN w_faitout := func_cr3_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_cr3_30;
            ELSIF wpae.codope = '34' THEN w_faitout := func_cr3_03;
                                          w_faitout := func_cr3_30;
                                          w_faitout := func_cr3_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_cr3_03;
                                          w_faitout := func_cr3_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_cr3_40;
        END IF;

    END LOOP;
    CLOSE cr3_list;

    --w_faitout := ed_tmp_fic(w_led);

END ledcr3;

----------------------- EDITION DE L'ENTETE  -----------------------------

FUNCTION func_cr3_01 RETURN BOOLEAN
IS

BEGIN

--lk    IF NVL(arg1,'0') = '1' THEN arg1 := '0';
--lk                           ELSE arg1 := '1';
--lk    END IF;
    w_page  := w_page + 1;
    w_ligne := 0;
    arg1    := w_page;   --lk

    w_supl := 0;

--    arg1 := '1';
    arg2 := w_l1;
    w_faitout := up_tmp_cr3;

--    arg1 := '0';
--    w_page        := w_page + 1;

    w_l5          := RPAD(ver,2) ||
                    'Societe       : ' || wdos.cdos || '  ' ||
                     RPAD(wdos.nred,130) || 'Page' ||
                     TO_CHAR(w_page, '9999') || LPAD(ver,5);

    arg2          := w_l5;
    w_faitout := up_tmp_cr3;

    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       w_l5          := RPAD(ver,2) ||
                       'Etablissement : ' || LPAD(w_ets,3) || ' ' ||
                        RPAD(ets_lib,156) || ver;
       arg2          := w_l5;
       w_faitout := up_tmp_cr3;
    END IF;

    w_l5          := RPAD(ver,2) || RPAD(' ',62) ||
                     RPAD(w_titre,41) ||' Periode du ' ||
                     TO_CHAR(w_dper, 'dd-mm-yyyy') || ' au ' ||
                     TO_CHAR(w_fper, 'dd-mm-yyyy') ||
                     LPAD(ver,25);
    arg2          := w_l5;
    w_faitout := up_tmp_cr3;

    w_supl := 0;
    w_l5          := RPAD(ver,2) ||
                    'Edite le ' || TO_CHAR(sysdate, 'dd-mm-yyyy "a" hh24:mi:ss') ||
                     LPAD('Util. : ',128) || w_cuti || LPAD(ver,2);
    arg2          := w_l5;
    w_faitout := up_tmp_cr3;

    arg2          := w_l1;
    w_faitout := up_tmp_cr3;

    w_l5          := ver || RPAD(' RUBRIQUES',20) ||
                     substr(w_l4,22,14) || 'Janvier'   ||
                     substr(w_l4,43,4)  || 'Fevrier'   ||
                     substr(w_l4,54,6)  || 'Mars'      ||
                     substr(w_l4,64,6)  || 'Avril'     ||
                     substr(w_l4,75,7)  || 'Mai'       ||
                     substr(w_l4,85,8)  || 'Juin'      ||
                     substr(w_l4,97,5)  || 'Juillet'   ||
                     substr(w_l4,109,6) || 'Aout'      ||
                     substr(w_l4,119,4) || 'Septembre' ||
                     substr(w_l4,132,3) || 'Octobre'   ||
                     substr(w_l4,142,4) || 'Novembre'  ||
                     substr(w_l4,154,3) || 'Decembre'  ||
                     substr(w_l4,165);
    arg2          := w_l5;
    w_faitout := up_tmp_cr3;

    arg2          := w_l1;
    w_faitout := up_tmp_cr3;

    RETURN TRUE;
END func_cr3_01;

----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_cr3_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5          := RPAD(ver,2) || RPAD(wpae.typope,30) || SUBSTR(w_l4,33);
    arg2          := w_l5;
    w_faitout := up_tmp_cr3;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_cr3;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_cr3_02;

----------------------- EDITION D'UNE LIGNE DE TIRETS  -------------------
FUNCTION func_cr3_03 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l2;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_cr3;

    RETURN TRUE;
END func_cr3_03;

----------------------- EDITION D'UNE LIGNE ESPACE     -------------------
FUNCTION func_cr3_04 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l4;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_cr3;

    RETURN TRUE;
END func_cr3_04;

---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_cr3_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.jan := clcum_c1(p1);
       cpcum.fev := clcum_c2(p1);
       cpcum.mar := clcum_c3(p1);
       cpcum.avr := clcum_c4(p1);
       cpcum.mai := clcum_c5(p1);
       cpcum.jun := clcum_c6(p1);
       cpcum.jul := clcum_c7(p1);
       cpcum.aou := clcum_c8(p1);
       cpcum.sep := clcum_c9(p1);
       cpcum.oct := clcum_c10(p1);
       cpcum.nov := clcum_c11(p1);
       cpcum.dec := clcum_c12(p1);
       w_faitout := detail_cr3(' ',wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
       clcum_c7(p1)   := 0;
       clcum_c8(p1)   := 0;
       clcum_c9(p1)   := 0;
       clcum_c10(p1)  := 0;
       clcum_c11(p1)  := 0;
       clcum_c12(p1)  := 0;
    END IF;

    RETURN TRUE;
END func_cr3_30;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_cr3_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        w_cum_sldjan := nvl(wres.mnt1,0);
        w_cum_sldfev := nvl(wres.mnt2,0);
        w_cum_sldmar := nvl(wres.mnt3,0);
        w_cum_sldavr := nvl(wres.mnt4,0);
        w_cum_sldmai := nvl(wres.mnt5,0);
        w_cum_sldjun := nvl(wres.mnt6,0);
        w_cum_sldjul := nvl(wres.mnt7,0);
        w_cum_sldaou := nvl(wres.mnt8,0);
        w_cum_sldsep := nvl(wres.mnt9,0);
        w_cum_sldoct := nvl(wres.mnt10,0);
        w_cum_sldnov := nvl(wres.mnt11,0);
        w_cum_slddec := nvl(wres.mnt12,0);

        IF p2 != 0 THEN
             wedit          := 2;
             IF    p2 = 1 THEN
                      IF w_cum_sldjan != 0
                      OR w_cum_sldfev != 0
                      OR w_cum_sldmar != 0
                      OR w_cum_sldavr != 0
                      OR w_cum_sldmai != 0
                      OR w_cum_sldjun != 0
                      OR w_cum_sldjul != 0
                      OR w_cum_sldaou != 0
                      OR w_cum_sldsep != 0
                      OR w_cum_sldoct != 0
                      OR w_cum_sldnov != 0
                      OR w_cum_slddec != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_sldjan >  0
                      OR w_cum_sldfev >  0
                      OR w_cum_sldmar >  0
                      OR w_cum_sldavr >  0
                      OR w_cum_sldmai >  0
                      OR w_cum_sldjun >  0
                      OR w_cum_sldjul >  0
                      OR w_cum_sldaou >  0
                      OR w_cum_sldsep >  0
                      OR w_cum_sldoct >  0
                      OR w_cum_sldnov >  0
                      OR w_cum_slddec >  0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_sldjan <  0
                      OR w_cum_sldfev <  0
                      OR w_cum_sldmar <  0
                      OR w_cum_sldavr <  0
                      OR w_cum_sldmai <  0
                      OR w_cum_sldjun <  0
                      OR w_cum_sldjul <  0
                      OR w_cum_sldaou <  0
                      OR w_cum_sldsep <  0
                      OR w_cum_sldoct <  0
                      OR w_cum_sldnov <  0
                      OR w_cum_slddec <  0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit != 2     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                 clcum_c1(wi)  := clcum_c1(wi) + nvl(wres.mnt1,0);
                 clcum_c2(wi)  := clcum_c2(wi) + nvl(wres.mnt2,0);
                 clcum_c3(wi)  := clcum_c3(wi) + nvl(wres.mnt3,0);
                 clcum_c4(wi)  := clcum_c4(wi) + nvl(wres.mnt4,0);
                 clcum_c5(wi)  := clcum_c5(wi) + nvl(wres.mnt5,0);
                 clcum_c6(wi)  := clcum_c6(wi) + nvl(wres.mnt6,0);
                 clcum_c7(wi)  := clcum_c7(wi) + nvl(wres.mnt7,0);
                 clcum_c8(wi)  := clcum_c8(wi) + nvl(wres.mnt8,0);
                 clcum_c9(wi)  := clcum_c9(wi) + nvl(wres.mnt9,0);
                 clcum_c10(wi) := clcum_c10(wi) + nvl(wres.mnt10,0);
                 clcum_c11(wi) := clcum_c11(wi) + nvl(wres.mnt11,0);
                 clcum_c12(wi) := clcum_c12(wi) + nvl(wres.mnt12,0);
               END IF;
           END LOOP;
        END IF;
  -- dbms_output.put_line('wedit '||wedit||' p1 '||p1||' p2 '||p2);

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.jan :=  nvl(wres.mnt1,0);
           cpcum.fev :=  nvl(wres.mnt2,0);
           cpcum.mar :=  nvl(wres.mnt3,0);
           cpcum.avr :=  nvl(wres.mnt4,0);
           cpcum.mai :=  nvl(wres.mnt5,0);
           cpcum.jun :=  nvl(wres.mnt6,0);
           cpcum.jul :=  nvl(wres.mnt7,0);
           cpcum.aou :=  nvl(wres.mnt8,0);
           cpcum.sep :=  nvl(wres.mnt9,0);
           cpcum.oct :=  nvl(wres.mnt10,0);
           cpcum.nov :=  nvl(wres.mnt11,0);
           cpcum.dec :=  nvl(wres.mnt12,0);
           w_faitout := detail_cr3(wres.numcpt,wres.libe);
        END IF;
    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_cr3_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_cr3(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2) RETURN BOOLEAN
IS
  w_tot number;
BEGIN

    w_l5      := RPAD(ver,2) || RPAD(ed_intr,30) || SUBSTR(w_l4,33);
    w_tot := cpcum.jan;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,34) || mtf || substr(w_l5,45);
    END IF;
    w_tot := cpcum.fev;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,45) || mtf || substr(w_l5,56);
    END IF;
    w_tot := cpcum.mar;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,56) || mtf || substr(w_l5,67);
    END IF;
    w_tot := cpcum.avr;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,67) || mtf || substr(w_l5,78);
    END IF;
    w_tot := cpcum.mai;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,78) || mtf || substr(w_l5,89);
    END IF;
    w_tot := cpcum.jun;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,89) || mtf || substr(w_l5,100);
    END IF;
    w_tot := cpcum.jul;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,100) || mtf || substr(w_l5,111);
    END IF;
    w_tot := cpcum.aou;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,111) || mtf || substr(w_l5,122);
    END IF;
    w_tot := cpcum.sep;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,122) || mtf || substr(w_l5,133);
    END IF;
    w_tot := cpcum.oct;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,133) || mtf || substr(w_l5,144);
    END IF;
    w_tot := cpcum.nov;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,144) || mtf || substr(w_l5,155);
    END IF;
    w_tot := cpcum.dec;
    mtf := numfs(w_tot,w_ndec);
    IF w_tot != 0 THEN
       w_l5   := SUBSTR(w_l5,1,155) || mtf || substr(w_l5,166);
    END IF;
    arg2           := w_l5;
    w_faitout := up_tmp_cr3;

    RETURN TRUE;
END detail_cr3;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_cr3 RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_cr3_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_cr3;

----------------------- Calcul et MAJ des cumuls des comptes -------------
FUNCTION cr3_maj_cpt RETURN BOOLEAN
IS

    CURSOR bg_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40' ORDER BY cdos,codeta,numord;

   CURSOR bg_cpt_list1 IS
         SELECT a.cdos, a.numcpt, a.typcpt, a.intcpt, b.codran, b.natcpt, a.raccpt
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;

    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN
    OPEN bg_list1;
    LOOP
        FETCH bg_list1 INTO wpae;
        EXIT WHEN bg_list1%NOTFOUND;

        OPEN bg_cpt_list1;
        LOOP
            FETCH bg_cpt_list1 INTO wcpt.cdos, wcpt.numcpt, wcpt.typcpt,
                  wcpt.intcpt, wpro.codran, wpro.natcpt, wcpt.raccpt;
            EXIT WHEN bg_cpt_list1%NOTFOUND;

            continuer := false;
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.numcpt;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := '00000000';
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.mnt5      := 0;
            wres.mnt6      := 0;
            wres.mnt7      := 0;
            wres.mnt8      := 0;
            wres.mnt9      := 0;
            wres.mnt10     := 0;
            wres.mnt11     := 0;
            wres.mnt12     := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.numcpt;
            if wpae.sel = 'I' then
              wres.libe      := wcpt.raccpt;
            else
              wres.libe      := wcpt.intcpt;
            end if;
            wres.sens      := 'X';
            wres.ctie      := substr(wpro.natcpt,1,1);
            w_cum_sldjan := 0;
            w_cum_sldfev := 0;
            w_cum_sldmar := 0;
            w_cum_sldavr := 0;
            w_cum_sldmai := 0;
            w_cum_sldjun := 0;
            w_cum_sldjul := 0;
            w_cum_sldaou := 0;
            w_cum_sldsep := 0;
            w_cum_sldoct := 0;
            w_cum_sldnov := 0;
            w_cum_slddec := 0;

         FOR w IN (SELECT PERIODE FROM CP_PER WHERE cdos = wcdos
                   AND PERIODE BETWEEN substr(w_fper_c,1,1)||'01' AND w_fper_c) LOOP

         IF wcpt.typcpt = 'D' OR wpae.param2 not between 1 and 3 THEN

         FOR wmvg IN
            (SELECT b.codjou, a.*, b.periode
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt and
                    --a.datcpt <= w_fper
                    a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w.periode
                    and b.periode <= w.periode
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            if continuer then
              IF substr(w.periode,2) = '01' THEN
                 wres.mnt1 := wres.mnt1 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjan := nvl(wres.mnt1,0);
              ELSIF substr(w.periode,2) = '02' THEN
                 wres.mnt2 := wres.mnt2 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldfev := nvl(wres.mnt2,0);
              ELSIF substr(w.periode,2) = '03' THEN
                 wres.mnt3 := wres.mnt3 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmar := nvl(wres.mnt3,0);
              ELSIF substr(w.periode,2) = '04' THEN
                 wres.mnt4 := wres.mnt4 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldavr := nvl(wres.mnt4,0);
              ELSIF substr(w.periode,2) = '05' THEN
                 wres.mnt5 := wres.mnt5 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmai := nvl(wres.mnt5,0);
              ELSIF substr(w.periode,2) = '06' THEN
                 wres.mnt6 := wres.mnt6 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjun := nvl(wres.mnt6,0);
              ELSIF substr(w.periode,2) = '07' THEN
                 wres.mnt7 := wres.mnt7 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjul := nvl(wres.mnt7,0);
              ELSIF substr(w.periode,2) = '08' THEN
                 wres.mnt8 := wres.mnt8 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldaou := nvl(wres.mnt8,0);
              ELSIF substr(w.periode,2) = '09' THEN
                 wres.mnt9 := wres.mnt9 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldsep := nvl(wres.mnt9,0);
              ELSIF substr(w.periode,2) = '10' THEN
                 wres.mnt10 := wres.mnt10 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldoct := nvl(wres.mnt10,0);
              ELSIF substr(w.periode,2) = '11' THEN
                 wres.mnt11 := wres.mnt11 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldnov := nvl(wres.mnt11,0);
              ELSIF substr(w.periode,2) = '12' THEN
                 wres.mnt12 := wres.mnt12 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_slddec := nvl(wres.mnt12,0);
              END IF;
            end if;
         END LOOP;

         ELSIF wpae.param2 = 1 THEN   -- Comptes à solde non nul

         FOR wmvg IN
            (SELECT b.codjou, a.*, b.periode
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt
                    and numtie in (select numtie
                                   from cp_ecr_gen a, cp_ecr b, cp_per c
                                   where a.cdos = wcdos
                                   and numcpt = wcpt.numcpt and
                                   a.codets LIKE sel_Ets
                                   and b.cdos = a.cdos
                                   and b.numsai = a.numsai
                                   and b.periode <= w.periode
                                   and
                	                 (
		                           (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		                           or (w_ecr_non_maj = 'O')
        		                     )
	      	                     and c.cdos = b.cdos
    	                         and c.periode =b.periode
                                 group by numtie
                                 having sum(nvl(dos_mtdb,0))-sum(nvl(dos_mtcr,0))!=0)

                    --a.datcpt <= w_fper
                    and a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w.periode
                    and b.periode <= w.periode
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            if continuer then
              IF substr(w.periode,2) = '01' THEN
                 wres.mnt1 := wres.mnt1 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjan := nvl(wres.mnt1,0);
              ELSIF substr(w.periode,2) = '02' THEN
                 wres.mnt2 := wres.mnt2 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldfev := nvl(wres.mnt2,0);
              ELSIF substr(w.periode,2) = '03' THEN
                 wres.mnt3 := wres.mnt3 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmar := nvl(wres.mnt3,0);
              ELSIF substr(w.periode,2) = '04' THEN
                 wres.mnt4 := wres.mnt4 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldavr := nvl(wres.mnt4,0);
              ELSIF substr(w.periode,2) = '05' THEN
                 wres.mnt5 := wres.mnt5 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmai := nvl(wres.mnt5,0);
              ELSIF substr(w.periode,2) = '06' THEN
                 wres.mnt6 := wres.mnt6 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjun := nvl(wres.mnt6,0);
              ELSIF substr(w.periode,2) = '07' THEN
                 wres.mnt7 := wres.mnt7 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjul := nvl(wres.mnt7,0);
              ELSIF substr(w.periode,2) = '08' THEN
                 wres.mnt8 := wres.mnt8 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldaou := nvl(wres.mnt8,0);
              ELSIF substr(w.periode,2) = '09' THEN
                 wres.mnt9 := wres.mnt9 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldsep := nvl(wres.mnt9,0);
              ELSIF substr(w.periode,2) = '10' THEN
                 wres.mnt10 := wres.mnt10 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldoct := nvl(wres.mnt10,0);
              ELSIF substr(w.periode,2) = '11' THEN
                 wres.mnt11 := wres.mnt11 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldnov := nvl(wres.mnt11,0);
              ELSIF substr(w.periode,2) = '12' THEN
                 wres.mnt12 := wres.mnt12 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_slddec := nvl(wres.mnt12,0);
              END IF;
            end if;
         END LOOP;

         ELSIF wpae.param2 = 2 THEN   -- Comptes à solde débiteur

         FOR wmvg IN
            (SELECT b.codjou, a.*, b.periode
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt
                    and numtie in (select numtie
                                   from cp_ecr_gen a, cp_ecr b, cp_per c
                                   where a.cdos = wcdos
                                   and numcpt = wcpt.numcpt and
                                   a.codets LIKE sel_Ets
                                   and b.cdos = a.cdos
                                   and b.numsai = a.numsai
                                   and b.periode <= w.periode
                                   and
                	                 (
		                           (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		                           or (w_ecr_non_maj = 'O')
        		                     )
	      	                     and c.cdos = b.cdos
    	                         and c.periode =b.periode
                                 group by numtie
                                 having sum(nvl(dos_mtdb,0))-sum(nvl(dos_mtcr,0))>0)

                    --a.datcpt <= w_fper
                    and a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w.periode
                    and b.periode <= w.periode
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            if continuer then
              IF substr(w.periode,2) = '01' THEN
                 wres.mnt1 := wres.mnt1 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjan := nvl(wres.mnt1,0);
              ELSIF substr(w.periode,2) = '02' THEN
                 wres.mnt2 := wres.mnt2 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldfev := nvl(wres.mnt2,0);
              ELSIF substr(w.periode,2) = '03' THEN
                 wres.mnt3 := wres.mnt3 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmar := nvl(wres.mnt3,0);
              ELSIF substr(w.periode,2) = '04' THEN
                 wres.mnt4 := wres.mnt4 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldavr := nvl(wres.mnt4,0);
              ELSIF substr(w.periode,2) = '05' THEN
                 wres.mnt5 := wres.mnt5 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmai := nvl(wres.mnt5,0);
              ELSIF substr(w.periode,2) = '06' THEN
                 wres.mnt6 := wres.mnt6 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjun := nvl(wres.mnt6,0);
              ELSIF substr(w.periode,2) = '07' THEN
                 wres.mnt7 := wres.mnt7 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjul := nvl(wres.mnt7,0);
              ELSIF substr(w.periode,2) = '08' THEN
                 wres.mnt8 := wres.mnt8 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldaou := nvl(wres.mnt8,0);
              ELSIF substr(w.periode,2) = '09' THEN
                 wres.mnt9 := wres.mnt9 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldsep := nvl(wres.mnt9,0);
              ELSIF substr(w.periode,2) = '10' THEN
                 wres.mnt10 := wres.mnt10 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldoct := nvl(wres.mnt10,0);
              ELSIF substr(w.periode,2) = '11' THEN
                 wres.mnt11 := wres.mnt11 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldnov := nvl(wres.mnt11,0);
              ELSIF substr(w.periode,2) = '12' THEN
                 wres.mnt12 := wres.mnt12 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_slddec := nvl(wres.mnt12,0);
              END IF;
            end if;
         END LOOP;

         ELSIF wpae.param2 = 3 THEN   -- Comptes à solde créditeur

         FOR wmvg IN
            (SELECT b.codjou, a.*, b.periode
               FROM cp_ecr_gen a, cp_ecr b, cp_per c
              WHERE a.cdos =  wcdos AND
                    numcpt = wcpt.numcpt
                    and numtie in (select numtie
                                   from cp_ecr_gen a, cp_ecr b, cp_per c
                                   where a.cdos = wcdos
                                   and numcpt = wcpt.numcpt and
                                   a.codets LIKE sel_Ets
                                   and b.cdos = a.cdos
                                   and b.numsai = a.numsai
                                   and b.periode <= w.periode
                                   and
                	                 (
		                           (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		                           or (w_ecr_non_maj = 'O')
        		                     )
	      	                     and c.cdos = b.cdos
    	                         and c.periode =b.periode
                                 group by numtie
                                 having sum(nvl(dos_mtdb,0))-sum(nvl(dos_mtcr,0))<0)

                    --a.datcpt <= w_fper
                    and a.codets LIKE sel_Ets
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w.periode
                    and b.periode <= w.periode
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
	      	      and c.cdos = b.cdos
    	          and c.periode =b.periode
              ORDER BY a.cdos,a.numcpt)
        LOOP
            CONTINUER := true;
            if continuer then
              IF substr(w.periode,2) = '01' THEN
                 wres.mnt1 := wres.mnt1 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjan := nvl(wres.mnt1,0);
              ELSIF substr(w.periode,2) = '02' THEN
                 wres.mnt2 := wres.mnt2 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldfev := nvl(wres.mnt2,0);
              ELSIF substr(w.periode,2) = '03' THEN
                 wres.mnt3 := wres.mnt3 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmar := nvl(wres.mnt3,0);
              ELSIF substr(w.periode,2) = '04' THEN
                 wres.mnt4 := wres.mnt4 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldavr := nvl(wres.mnt4,0);
              ELSIF substr(w.periode,2) = '05' THEN
                 wres.mnt5 := wres.mnt5 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldmai := nvl(wres.mnt5,0);
              ELSIF substr(w.periode,2) = '06' THEN
                 wres.mnt6 := wres.mnt6 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjun := nvl(wres.mnt6,0);
              ELSIF substr(w.periode,2) = '07' THEN
                 wres.mnt7 := wres.mnt7 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldjul := nvl(wres.mnt7,0);
              ELSIF substr(w.periode,2) = '08' THEN
                 wres.mnt8 := wres.mnt8 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldaou := nvl(wres.mnt8,0);
              ELSIF substr(w.periode,2) = '09' THEN
                 wres.mnt9 := wres.mnt9 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldsep := nvl(wres.mnt9,0);
              ELSIF substr(w.periode,2) = '10' THEN
                 wres.mnt10 := wres.mnt10 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldoct := nvl(wres.mnt10,0);
              ELSIF substr(w.periode,2) = '11' THEN
                 wres.mnt11 := wres.mnt11 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_sldnov := nvl(wres.mnt11,0);
              ELSIF substr(w.periode,2) = '12' THEN
                 wres.mnt12 := wres.mnt12 + (nvl(wmvg.grp_mtdb,0) - nvl(wmvg.grp_mtcr,0));
                 w_cum_slddec := nvl(wres.mnt12,0);
              END IF;
            end if;
         END LOOP;

         END IF;

         END LOOP;

         IF wpae.param2 != 0 THEN
              wedit          := 2;

                 IF   wpae.param2 = 1 then
                         wedit := 1;

                 elsif wpae.param2 = 2 then
                         wedit := 1;
                      IF w_cum_sldjan <  0 THEN
                        wres.mnt1 := 0;
                      END IF;
                      IF w_cum_sldfev <  0 THEN
                        wres.mnt2 := 0;
                      END IF;
                      IF w_cum_sldmar <  0 THEN
                        wres.mnt3 := 0;
                      END IF;
                      IF w_cum_sldavr <  0 THEN
                        wres.mnt4 := 0;
                      END IF;
                      IF w_cum_sldmai <  0 THEN
                        wres.mnt5 := 0;
                      END IF;
                      IF w_cum_sldjun <  0 THEN
                        wres.mnt6 := 0;
                      END IF;
                      IF w_cum_sldjul <  0 THEN
                        wres.mnt7 := 0;
                      END IF;
                      IF w_cum_sldaou <  0 THEN
                        wres.mnt8 := 0;
                      END IF;
                      IF w_cum_sldsep <  0 THEN
                        wres.mnt9 := 0;
                      END IF;
                      IF w_cum_sldoct <  0 THEN
                        wres.mnt10 := 0;
                      END IF;
                      IF w_cum_sldnov <  0 THEN
                        wres.mnt11 := 0;
                      END IF;
                      IF w_cum_slddec <  0 THEN
                        wres.mnt12 := 0;
                      END IF;

                 elsif wpae.param2 = 3 then
                         wedit := 1;
                      IF w_cum_sldjan >  0 THEN
                        wres.mnt1 := 0;
                      END IF;
                      IF w_cum_sldfev >  0 THEN
                        wres.mnt2 := 0;
                      END IF;
                      IF w_cum_sldmar >  0 THEN
                        wres.mnt3 := 0;
                      END IF;
                      IF w_cum_sldavr >  0 THEN
                        wres.mnt4 := 0;
                      END IF;
                      IF w_cum_sldmai >  0 THEN
                        wres.mnt5 := 0;
                      END IF;
                      IF w_cum_sldjun >  0 THEN
                        wres.mnt6 := 0;
                      END IF;
                      IF w_cum_sldjul >  0 THEN
                        wres.mnt7 := 0;
                      END IF;
                      IF w_cum_sldaou >  0 THEN
                        wres.mnt8 := 0;
                      END IF;
                      IF w_cum_sldsep >  0 THEN
                        wres.mnt9 := 0;
                      END IF;
                      IF w_cum_sldoct >  0 THEN
                        wres.mnt10 := 0;
                      END IF;
                      IF w_cum_sldnov >  0 THEN
                        wres.mnt11 := 0;
                      END IF;
                      IF w_cum_slddec >  0 THEN
                        wres.mnt12 := 0;
                      END IF;

              END IF;

         ELSE wedit := 1;
         END IF;

         IF wedit = 1 THEN
	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
	                    w_session_id);   --lk
         END IF;
         commit; --lk

      END IF;
      END LOOP;
      CLOSE bg_cpt_list1;
   END LOOP;
   CLOSE bg_list1;

/*lk
            if w_rg_dev = 'D' then
                cpcum.mced := nvl(wmvg.dos_mtcr,0);
                cpcum.mded := nvl(wmvg.dos_mtdb,0);
            else
                cpcum.mced := nvl(wmvg.grp_mtcr,0);
                cpcum.mded := nvl(wmvg.grp_mtdb,0);
            end if;
*/
   RETURN TRUE;
END cr3_maj_cpt;

