CREATE PACKAGE BODY cpleap
AS


-------------------------------------------------------------------------------
-- Edition des etats analytiques
-------------------------------------------------------------------------------

   wcoa          cp_nat%ROWTYPE;
   wsec          cp_des%ROWTYPE;
   wmva          cp_ecr_ana%ROWTYPE;

   TYPE cpcum_type IS RECORD     -- zone de cumul compte
   (    mdpd     NUMBER(15,3),
        mcpd     NUMBER(15,3),
        mded     NUMBER(15,3),
        mced     NUMBER(15,3),
        sold     NUMBER(15,3),
        solc     NUMBER(15,3)
   );
   cpcum         cpcum_type;

   TYPE w_reg_sec_type IS TABLE OF VARCHAR2(1) INDEX BY BINARY_INTEGER;
   w_reg_sec     w_reg_sec_type;

   --sk
   w_ecr_non_maj VARCHAR2(1);
   w_sim         VARCHAR2(1);
   w_per_comp    VARCHAR2(1);
   w_rg_dev      VARCHAR2(1);
   w_dper_c      VARCHAR2(3);
   w_fper_c      VARCHAR2(3);
   w_exercice    VARCHAR2(3);
   w_session_id  NUMBER;
   --fin sk

   w_titre       VARCHAR2(30);
   w_dper        DATE;
   w_fper        DATE;
   w_date        DATE;
   w_ddex        DATE;
   w_reou        VARCHAR2(1);
   w_ran         VARCHAR2(1);
   w_reed        VARCHAR2(1);
   w_psec        VARCHAR2(8);
   w_dsec        VARCHAR2(8);
   w_section     VARCHAR2(8);
   w_ndec        NUMBER;
   w_ligne       NUMBER;
   w_numord_edi  NUMBER;
   w_page        NUMBER;
   w_nblg        NUMBER;
   w_maxlg       NUMBER;
   wi            NUMBER;
   larg_ed       NUMBER;
   w_cuti        VARCHAR2(4);

   w_ets         VARCHAR2(3);
   w_axa         VARCHAR2(1);
   sel_ets       cp_ets.codets%TYPE;
   ets_lib       VARCHAR2(30);

   sauv_supl     NUMBER;
   w_supl        NUMBER;
   lig_as        VARCHAR2(1);

-------------------------------------------------------------------------------

PROCEDURE ledea01 (woptions IN VARCHAR2)
IS

    CURSOR ea_res_list IS
        SELECT cdos, numsec, numcpt FROM cp_res
         WHERE session_id = w_session_id  --lk
         ORDER BY cdos,numsec,numcpt;

BEGIN

--  lecture des parametres d'edition dans le fichier evlanc

    w_bala       := rtrim(substr(woptions,1,3));
    w_reg_sec(1) := substr(woptions,4,1);
    w_reg_sec(2) := substr(woptions,5,1);
    w_reg_sec(3) := substr(woptions,6,1);
    w_reg_sec(4) := substr(woptions,7,1);
    w_reg_sec(5) := substr(woptions,8,1);
    w_reg_sec(6) := substr(woptions,9,1);
    w_reg_sec(7) := substr(woptions,10,1);
    w_reg_sec(8) := substr(woptions,11,1);

    --sk 03 09 98
    /*
    w_dper       := TO_DATE(substr(woptions,12,10),'DD/MM/YYYY');
    w_fper       := TO_DATE(substr(woptions,22,10),'DD/MM/YYYY');
    w_psec       := substr(woptions,32,8);
    w_dsec       := substr(woptions,40,8);

    w_cuti       := substr(woptions,48,4);
    wcdos        := substr(woptions,52,2);
    w_axa        := substr(woptions,54,1);
    w_ets        := rtrim(substr(woptions,55,3));
    */
    w_dper_c     := substr(woptions,12,3);
    w_fper_c     := substr(woptions,15,3);
    w_psec       := nvl(RTRIM(substr(woptions,18,8)),RPAD(' ',8));
    w_dsec       := RTRIM(substr(woptions,26,8));

    w_cuti       := substr(woptions,34,4);
    wcdos        := substr(woptions,38,2);
    w_axa        := substr(woptions,40,1);
    w_ets        := rtrim(substr(woptions,41,3));
    w_rg_dev	 := substr(woptions,44,1);
    w_ecr_non_maj := substr(woptions,45,1);
    w_per_comp	 := substr(woptions,46,1);
    w_sim	 := substr(woptions,47,1);
    w_session_id := to_number(substr(woptions,48,38));
/*
--
insert into ss values(w_fper_c);
insert into ss values(w_ecr_non_maj);
insert into ss values(w_sim);
insert into ss values(w_per_comp);
commit;
--
*/
    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk

--dbms_output.enable(50000);
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;

--dbms_output.put_line(to_char(w_dper));
    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);

       BEGIN
         SELECT a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;
    w_section   := '********';

    w_faitout := pae_tabtmp;
    w_faitout := gen_ea;

    larg_ed             := 132;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,130) || ver;
    w_l3                := ver || RPAD(' ',130) || ver;
    w_l4                := SUBSTR(w_l3,1,41) ||
                           ver || SUBSTR(w_l3,43,29) ||
                           ver || SUBSTR(w_l3,73,29) ||
                           ver || SUBSTR(w_l3,103,29) || ver;

    w_numord_edi := 0;

    OPEN ea_res_list;
    LOOP
        FETCH ea_res_list INTO wres.cdos,wres.numsec,wres.numcpt;
        EXIT WHEN ea_res_list%NOTFOUND;

        IF wres.numsec != w_section THEN
             w_section := wres.numsec;
             w_faitout := ea_ed_res;
/*
           WHILE mod(w_numord_edi, w_maxlg) > 0
           LOOP
               arg1 := '0';
               arg2 := null;
               w_faitout := up_tmp_ea;
           END LOOP;
*/
        END IF;
    END LOOP;
    CLOSE ea_res_list;

    --w_faitout := ed_tmp_fic(w_led);

END ledea01;

----------------------- EDITION DES ETATS ANALYTIQUES -------------------

FUNCTION ea_ed_res RETURN BOOLEAN
IS

    CURSOR ea_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN

    FOR indi IN 1..9
    LOOP
       clcum_c2(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;

    OPEN ea_list;
    LOOP
        FETCH ea_list INTO wpae;
        EXIT WHEN ea_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_ea_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_ea_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_ea_03;
            ELSIF wpae.codope = '04' THEN w_faitout := func_ea_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_ea_30;
            ELSIF wpae.codope = '34' THEN w_faitout := func_ea_03;
                                          w_faitout := func_ea_30;
                                          w_faitout := func_ea_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_ea_03;
                                          w_faitout := func_ea_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_ea_40;
        END IF;

    END LOOP;
    CLOSE ea_list;

    RETURN TRUE;
END ea_ed_res;

----------------------- EDITION DE L'ENTETE  -----------------------------

FUNCTION func_ea_01 RETURN BOOLEAN
IS

BEGIN

--lk    IF NVL(arg1,'0') = '1' THEN arg1 := '0';
--lk                           ELSE arg1 := '1';
--lk    END IF;
    w_page  := w_page + 1;
    w_ligne := 0;
    arg1    := w_page;   --lk

    w_supl := 0;

--    arg1 := '1';
    arg2 := w_l1;
    w_faitout := up_tmp_ea;

--    arg1 := '0';
--    w_page        := w_page + 1;

    w_l5          := RPAD(ver,2) ||
                    'Societe       : ' || wdos.cdos || '  ' ||
                     RPAD(wdos.nred,87) || 'Page' ||
                     TO_CHAR(w_page, '9999') || LPAD(ver,14);
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       w_l5          := RPAD(ver,2) ||
                       'Etablissement : ' || LPAD(w_ets,3) || ' ' ||
                        RPAD(ets_lib,109) || ver;
       arg2          := w_l5;
       w_faitout := up_tmp_ea;
    END IF;

--  w_l5          := RPAD(ver,48) || RPAD(w_titre,30) ||
--                  ' ( Axe : ' || w_axa || ' )' || LPAD (ver,42);
    w_l5          := RPAD(ver,48) || RPAD(w_titre ||
                    ' ( Axe : ' || w_axa || ' )',42) || LPAD (ver,42);
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    w_supl := 1;
    w_l5          := w_l3;
    BEGIN
        SELECT * INTO wsec FROM cp_des
               WHERE cp_des.cdos = wcdos AND cp_des.numaxe = w_axa
                 AND cp_des.coddes = w_section;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
           wsec.libdes := ' ';
    END;

    w_l5          := RPAD(ver,2) ||
                    'Section : ' || RPAD(w_section,8) || ' ' ||
                     RPAD(wsec.libdes,25) ||' Periode du ' ||
                     TO_CHAR(w_dper, 'dd-mm-yyyy') || ' au ' ||
                     TO_CHAR(w_fper, 'dd-mm-yyyy') ||
                     LPAD('Regr. : ',35) || w_reg_sec(1) || w_reg_sec(2) ||
                     w_reg_sec(3) || w_reg_sec(4) || w_reg_sec(5) ||
                     w_reg_sec(6) || w_reg_sec(7) || w_reg_sec(8) ||
                     LPAD(ver,7);
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    w_supl := 0;
    w_l5          := RPAD(ver,2) ||
                    'Edite le ' || TO_CHAR(sysdate, 'dd-mm-yyyy "a" hh:mi:ss') ||
                     LPAD('Util. : ',85) || w_cuti || LPAD(ver,11);
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    arg2          := w_l1;
    w_faitout := up_tmp_ea;

    w_l5          := RPAD(ver,3) || RPAD('Compte',21) || RPAD('Intitule',17) ||
                     RPAD(ver,11) || RPAD('Periode',19) ||
                     RPAD(ver,11) || RPAD('Exercice',19) ||
                     RPAD(ver,12) || RPAD('Soldes',18) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    w_l5          := RPAD(ver,41) ||
                     RPAD(ver,6) || RPAD('debit        Credit',24) ||
                     RPAD(ver,6) || RPAD('debit        Credit',24) ||
                     RPAD(ver,6) || RPAD('debit        Credit',24) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    arg2          := w_l1;
    w_faitout := up_tmp_ea;

    arg2          := w_l4;
    w_faitout := up_tmp_ea;

    RETURN TRUE;
END func_ea_01;

----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_ea_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5          := RPAD(ver,12) || wpae.typope || LPAD(ver,89) || ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ea;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_ea;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_ea_02;

----------------------- EDITION D'UNE LIGNE DE TIRETS  -------------------
FUNCTION func_ea_03 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l2;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    RETURN TRUE;
END func_ea_03;

----------------------- EDITION D'UNE LIGNE ESPACE     -------------------
FUNCTION func_ea_04 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l4;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ea;

    RETURN TRUE;
END func_ea_04;

---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_ea_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.mdpd := clcum_c1(p1);
       cpcum.mcpd := clcum_c2(p1);
       cpcum.mded := clcum_c3(p1);
       cpcum.mced := clcum_c4(p1);
       cpcum.solc := 0;
       cpcum.sold := 0;
       IF cpcum.mded > cpcum.mced   THEN
            cpcum.sold := cpcum.mded - cpcum.mced;
            cpcum.solc := 0;
       ELSE cpcum.solc := cpcum.mced - cpcum.mded;
            cpcum.sold := 0;
       END IF;
       w_faitout := detail_ea(' ',wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ea_30;

----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_ea_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin AND
             cp_res.numsec = w_section
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
--dbms_output.put_line(wpae.cptdeb||' '||wpae.cptfin||' '||w_section);
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

--    IF wres.numsec = w_section THEN

        IF p2 != 0 THEN
             wedit          := 2;
             w_cum_solde_db := wres.mnt3 - wres.mnt4;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt3 != 0 AND wres.mnt4 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit != 2     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                  clcum_c1(wi)  := clcum_c1(wi) + wres.mnt1;
                  clcum_c2(wi)  := clcum_c2(wi) + wres.mnt2;
                  clcum_c3(wi)  := clcum_c3(wi) + wres.mnt3;
                  clcum_c4(wi)  := clcum_c4(wi) + wres.mnt4;
               END IF;
           END LOOP;
        END IF;

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.mdpd    :=  wres.mnt1;
           cpcum.mcpd    :=  wres.mnt2;
           cpcum.mded    :=  wres.mnt3;
           cpcum.mced    :=  wres.mnt4;
           cpcum.solc    :=  0;
           cpcum.sold    :=  0;
           IF cpcum.mded > cpcum.mced      THEN
                cpcum.sold := cpcum.mded - cpcum.mced;
                cpcum.solc := 0;
           ELSE cpcum.solc := cpcum.mced - cpcum.mded;
                cpcum.sold := 0;
           END IF;
           SELECT * INTO wcoa FROM cp_nat
            WHERE cp_nat.cdos = wcdos AND cp_nat.codnat = wres.numcpt;
           w_faitout := detail_ea(wres.numcpt,wcoa.libnat);
        END IF;

--    END IF;

    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_ea_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_ea(ed_numcpt IN VARCHAR2, ed_intr IN VARCHAR2) RETURN BOOLEAN
IS

BEGIN

    w_l5      := RPAD(ver,2) || RPAD(ed_numcpt,10) ||
                        RPAD(ed_intr,29) || SUBSTR(w_l4,42,91);
    mtf := numfs(cpcum.mdpd,w_ndec);
    IF cpcum.mdpd != 0 THEN
       w_l5   := SUBSTR(w_l5,1,42) || mtf || substr(w_l5,57,76);
    END IF;
    mtf := numfs(cpcum.mcpd,w_ndec);
    IF cpcum.mcpd != 0 THEN
       w_l5   := SUBSTR(w_l5,1,56) || mtf || substr(w_l5,71,62);
    END IF;
    mtf := numfs(cpcum.mded,w_ndec);
    IF cpcum.mded != 0 THEN
       w_l5   := SUBSTR(w_l5,1,72) || mtf || substr(w_l5,87,46);
    END IF;
    mtf := numfs(cpcum.mced,w_ndec);
    IF cpcum.mced != 0 THEN
       w_l5   := SUBSTR(w_l5,1,86) || mtf || substr(w_l5,101,32);
    END IF;
    mtf := numfs(cpcum.sold,w_ndec);
    IF cpcum.sold != 0 THEN
       w_l5   := SUBSTR(w_l5,1,102) || mtf || substr(w_l5,117,16);
    END IF;
    mtf := numfs(cpcum.solc,w_ndec);
    IF cpcum.solc != 0 THEN
       w_l5   := SUBSTR(w_l5,1,116) || mtf || substr(w_l5,131,2);
    END IF;
--    arg1           := 0;
    arg2           := w_l5;
    w_faitout := up_tmp_ea;

    RETURN TRUE;
END detail_ea;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_ea RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_ea_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_ea;

----------------------- Calcul et MAJ des cumuls des comptes -------------

FUNCTION gen_ea RETURN BOOLEAN
IS

    CURSOR ea_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40' ORDER BY cdos,codeta,numord;
/*
    CURSOR cur_wselmva IS
       SELECT * FROM cp_ecr_ana
        WHERE cp_ecr_ana.cdos =  wcdos AND
              cp_ecr_ana.codnat BETWEEN wpae.cptdeb AND wpae.cptfin AND
              cp_ecr_ana.coddes BETWEEN w_psec AND w_dsec AND
              cp_ecr_ana.datcpt BETWEEN w_ddex AND w_fper AND
              cp_ecr_ana.numaxe = w_axa AND
              cp_ecr_ana.codets LIKE sel_Ets
              --AND cp_ecr_ana.codmaj > 0
        ORDER BY cp_ecr_ana.cdos,cp_ecr_ana.coddes,cp_ecr_ana.codnat;
        */

        --sk
    CURSOR cur_wselmva IS
       SELECT a.* FROM cp_ecr_ana a, cp_ecr b, cp_per c
        WHERE a.cdos =  wcdos AND
              a.codnat BETWEEN wpae.cptdeb AND wpae.cptfin AND
              a.coddes BETWEEN w_psec AND w_dsec AND
              --a.datcpt BETWEEN w_ddex AND w_fper AND
              a.numaxe = w_axa AND
              a.codets LIKE sel_Ets
              and b.cdos = a.cdos
              and b.numsai = a.numsai
              and b.periode between w_exercice and w_fper_c
              and
        	  (
		        (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		        or (w_ecr_non_maj = 'O')
		      )
		      and
		      (
		          (
		            (W_SIM = 'N')
		              and
			        (b.CODJOU in (select CODJOU FROM CP_JOU
					                WHERE CDOS = WCDOS
					                and NATJOU != 'S'
				                )
			         )
 		          )
		        or
  	              (W_SIM = 'O')
		      )
		      and c.cdos = b.cdos
		      and c.periode =b.periode
		      and (W_PER_COMP = 'O' or (c.PERCOM = 'N' OR c.PERCOM IS NULL))
        ORDER BY a.cdos,a.coddes,a.codnat;
      --fin sk

    rupt                 CHAR(16);

BEGIN
--dbms_output.put_line('DEB ' || w_bala);
    OPEN ea_list1;
    LOOP
        FETCH ea_list1 INTO wpae;
        EXIT WHEN ea_list1%NOTFOUND;
--dbms_output.put_line('40 ' || to_char(w_ddex));

        OPEN cur_wselmva;
        LOOP

        FETCH cur_wselmva  INTO wmva;
        EXIT WHEN cur_wselmva%NOTFOUND;
--dbms_output.put_line('MVA ');

            rupt := RPAD(wmva.coddes,8) || RPAD(wmva.codnat,8);
            FOR indi IN 1..8
            LOOP
                IF w_reg_sec(indi) = 'O' AND SUBSTR(rupt,indi,1) != ' ' THEN
                   rupt := SUBSTR(rupt,1,indi-1) || '0' || SUBSTR(rupt,indi+1,16-indi);
                END IF;
            END LOOP;

	        wres.cdos   := wcdos;
	        wres.numsec := RTRIM(SUBSTR(rupt,1,8));
	        wres.numcpt := wmva.codnat;
	        --wres.libe   := ?

	        BEGIN
	            SELECT * INTO wres FROM cp_res
	             WHERE cp_res.cdos   = wcdos
 	               AND session_id = w_session_id  --lk
	               AND cp_res.numsec = wres.numsec
	               AND cp_res.numcpt = wres.numcpt;
	        EXCEPTION
	            WHEN NO_DATA_FOUND THEN
	                wres.mnt1   := 0;
	                wres.mnt2   := 0;
                    wres.mnt3   := 0;
	                wres.mnt4   := 0;
	                wres.mnt5   := 0;
	                wres.mnt6   := 0;
	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
	                    w_session_id);   --lk
	        END;
	        commit;  --lk

            if w_rg_dev = 'D' then
                cpcum.mced := nvl(wmva.dos_mtcr,0);
                cpcum.mded := nvl(wmva.dos_mtdb,0);
            else
                cpcum.mced := nvl(wmva.grp_mtcr,0);
                cpcum.mded := nvl(wmva.grp_mtdb,0);
            end if;

            IF wmva.datcpt >= w_dper THEN
                if w_rg_dev = 'D' then
                    cpcum.mcpd := nvl(wmva.dos_mtcr,0);
                    cpcum.mdpd := nvl(wmva.dos_mtdb,0);
                else
                    cpcum.mcpd := nvl(wmva.grp_mtcr,0);
                    cpcum.mdpd := nvl(wmva.grp_mtdb,0);
                end if;
            ELSE
               cpcum.mcpd := 0;
               cpcum.mdpd := 0;
            END IF;

            wres.mnt1   := wres.mnt1 + cpcum.mdpd;
            wres.mnt2   := wres.mnt2 + cpcum.mcpd;
            wres.mnt3   := wres.mnt3 + cpcum.mded;
            wres.mnt4   := wres.mnt4 + cpcum.mced;
            wres.mnt12  := wres.mnt4 - wres.mnt3;

            UPDATE cp_res
               SET mnt1  = wres.mnt1,
                   mnt2  = wres.mnt2,
                   mnt3  = wres.mnt3,
                   mnt4  = wres.mnt4,
                   mnt12 = wres.mnt12
            WHERE cdos  = wcdos AND
                  numsec  = wres.numsec AND session_id = w_session_id  AND --lk
                  numcpt  = wres.numcpt;

            COMMIT;

        END LOOP;
       CLOSE cur_wselmva;

    END LOOP;
    CLOSE ea_list1;

    RETURN TRUE;
END gen_ea;


