----------------------- REMISE A ZERO D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_10 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0     THEN
      clcum_c1(p1) := 0;
      clcum_c2(p1) := 0;
      clcum_c3(p1) := 0;
      clcum_c4(p1) := 0;
      clcum_c5(p1) := 0;
      clcum_c6(p1) := 0;
      clcum_c7(p1) := 0;
      clcum_c8(p1) := 0;
   END IF;
   IF p2 != 0     THEN
      clcum_c1(p2) := 0;
      clcum_c2(p2) := 0;
      clcum_c3(p2) := 0;
      clcum_c4(p2) := 0;
      clcum_c5(p2) := 0;
      clcum_c6(p2) := 0;
      clcum_c7(p2) := 0;
      clcum_c8(p2) := 0;
   END IF;
   IF p3 != 0     THEN
      clcum_c1(p3) := 0;
      clcum_c2(p3) := 0;
      clcum_c3(p3) := 0;
      clcum_c4(p3) := 0;
      clcum_c5(p3) := 0;
      clcum_c6(p3) := 0;
      clcum_c7(p3) := 0;
      clcum_c8(p3) := 0;
   END IF;
   IF p4 != 0     THEN
      clcum_c1(p4) := 0;
      clcum_c2(p4) := 0;
      clcum_c3(p4) := 0;
      clcum_c4(p4) := 0;
      clcum_c5(p4) := 0;
      clcum_c6(p4) := 0;
      clcum_c7(p4) := 0;
      clcum_c8(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_10;

-----------------------  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_11 RETURN BOOLEAN
IS

BEGIN
   IF p1 != 0   THEN
      cpt_mjcum(p1) := 1;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 1;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 1;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 1;
   END IF;

   RETURN TRUE;

END func_pae_11;

---------------- RAZ  +  OUVERTURE D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_12 RETURN BOOLEAN
IS

BEGIN

   w_faitout := func_pae_10;
   w_faitout := func_pae_11;

   RETURN TRUE;

END func_pae_12;

----------------------  SUSPENSION D'UN OU PLUSIEURS COMPTEURS --------
FUNCTION func_pae_13 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0   THEN
      cpt_mjcum(p1) := 0;
   END IF;
   IF p2 != 0   THEN
      cpt_mjcum(p2) := 0;
   END IF;
   IF p3 != 0   THEN
      cpt_mjcum(p3) := 0;
   END IF;
   IF p4 != 0   THEN
      cpt_mjcum(p4) := 0;
   END IF;

   RETURN TRUE;

END func_pae_13;

----------------------  TRANSFERT DE P1 --> P2  -----------------------
FUNCTION func_pae_20 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1);
      clcum_c2(p2)  := clcum_c2(p1);
      clcum_c3(p2)  := clcum_c3(p1);
      clcum_c4(p2)  := clcum_c4(p1);
      clcum_c5(p2)  := clcum_c5(p1);
      clcum_c6(p2)  := clcum_c6(p1);
      clcum_c7(p2)  := clcum_c7(p1);
      clcum_c8(p2)  := clcum_c8(p1);
   END IF;

   RETURN TRUE;

END func_pae_20;

----------------------  TRANSFERT DE P1 + P2  --> P3  -----------------
FUNCTION func_pae_21 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) + clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) + clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) + clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) + clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) + clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) + clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) + clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) + clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_21;

---------------  P1 - P2 --> P3  -----------------------------------------------
FUNCTION func_pae_22 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0 AND p3 != 0  THEN
      clcum_c1(p3)  := clcum_c1(p1) - clcum_c1(p2);
      clcum_c2(p3)  := clcum_c2(p1) - clcum_c2(p2);
      clcum_c3(p3)  := clcum_c3(p1) - clcum_c3(p2);
      clcum_c4(p3)  := clcum_c4(p1) - clcum_c4(p2);
      clcum_c5(p3)  := clcum_c5(p1) - clcum_c5(p2);
      clcum_c6(p3)  := clcum_c6(p1) - clcum_c6(p2);
      clcum_c7(p3)  := clcum_c7(p1) - clcum_c7(p2);
      clcum_c8(p3)  := clcum_c8(p1) - clcum_c8(p2);
   END IF;

   RETURN TRUE;

END func_pae_22;

/*
----------------------  SOLDE 1 COMPTEUR P1   --> P2  -----------------
--                      SI P3 = 1 EN DEBIT OU CREDIT
--                      SI P3 = 2 EN DEBIT OBLIGAT.
--                      SI P3 = 3 EN CREDIT  "  "
FUNCTION func_pae_23 RETURN BOOLEAN
IS

BEGIN

   IF p1 = 0 OR p2 = 0 OR p3 = 0 OR p3 > 3  THEN
        w_l5 := " ";
   ELSE FOR indi IN 1..2
        LOOP
           indic       := 0;
           w_cum_solde_db := clcum_c1(p1) - clcum_c2(p1);
           IF w_cum_solde_db >= 0 THEN
              indic := 1;
           END IF;
        END LOOP;
  END IF;

   RETURN TRUE;

END func_pae_23;
*/

---------------  TRANSFERT AVEC INVERSION DE SIGNE P1 --> P2  ------------------
FUNCTION func_pae_25 RETURN BOOLEAN
IS

BEGIN

   IF p1 != 0 AND p2 != 0   THEN
      clcum_c1(p2)  := clcum_c1(p1) * -1;
      clcum_c2(p2)  := clcum_c2(p1) * -1;
      clcum_c3(p2)  := clcum_c3(p1) * -1;
      clcum_c4(p2)  := clcum_c4(p1) * -1;
      clcum_c5(p2)  := clcum_c5(p1) * -1;
      clcum_c6(p2)  := clcum_c6(p1) * -1;
      clcum_c7(p2)  := clcum_c7(p1) * -1;
      clcum_c8(p2)  := clcum_c8(p1) * -1;
   END IF;

   RETURN TRUE;

END func_pae_25;

/*
---------------- Si P1 debiteur edition ligne total P1  ------------------
FUNCTION func_pae_32 RETURN BOOLEAN
IS

BEGIN

        indic             := 0;
        w_cum_solde_db    := clcum_c3(p1) - clcum_c4(p1);
        IF w_cum_solde_db >= 0   THEN
--         w_faitout := func_pae_30;
        END IF;

   RETURN TRUE;

END func_pae_32;
*/

---------------- Tri du fichier CPRES  ----------------------------------------
FUNCTION tri_cpres RETURN BOOLEAN
IS

BEGIN

   RETURN TRUE;

END tri_cpres;


------------------------------------ AFF_SOC ----------------------------------

FUNCTION numfs(mt IN NUMBER, ndc IN NUMBER) RETURN VARCHAR2
IS

BEGIN

   IF      ndc  = 3 THEN mtf := TO_CHAR(mt, '999999990D000');
   ELSIF   ndc  = 2 THEN mtf := TO_CHAR(mt, '9999999990D00');
   ELSIF   ndc  = 1 THEN mtf := TO_CHAR(mt, '99999999990.0');
   ELSE                  mtf := TO_CHAR(mt, '99999G999G990');
   END IF;

   RETURN mtf;

END numfs;

