PROCEDURE ledar01 (woptions IN VARCHAR2)
IS

    CURSOR ar_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;
BEGIN

--  lecture des parametres d'edition dans le fichier evlanc
-- i
dbms_output.enable(50000);

    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);
    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_ets         := rtrim(substr(woptions,16,3));
    w_ecr_non_maj := substr(woptions,19,1);
    w_sim	  := substr(woptions,20,1);
    w_axe	  := to_number(substr(woptions,21,1));
    w_session_id  := to_number(substr(woptions,22,38));
    w_sec_boue         := rtrim(substr(woptions,60,8));
    w_sec_mboumi         := rtrim(substr(woptions,68,8));
    w_sec_pk27         := rtrim(substr(woptions,76,8));
    w_sec_scierie         := rtrim(substr(woptions,84,8));
    w_sec_fgen         := rtrim(substr(woptions,92,8));

--dbms_output.put_line('w_sess '||woptions);
--dbms_output.put_line(woptions);
--dbms_output.put_line('w_sec_boue '||w_sec_boue);
--dbms_output.put_line('w_sec_mboumi '||w_sec_mboumi);
--dbms_output.put_line('w_sec_pk27 '||w_sec_pk27);
--dbms_output.put_line('w_sec_scierie '||w_sec_scierie);
--dbms_output.put_line('w_sec_fgen '||w_sec_fgen);
--dbms_output.put_line('w_session '||w_session_id);
--dbms_output.put_line('w_axe '||w_axe);
--dbms_output.put_line('w_sim '||w_sim);

   w_nmois := to_number(w_fper_c) - to_number(w_dper_c) + 1;


  --  w_ets := w_etbfin;

   begin
	SELECT LIBDES INTO w_LIBDES1 FROM CP_DES
     	WHERE cdos = wcdos AND numaxe = w_axe
       	AND CODDES = w_SEC_BOUE;
    exception
	when no_data_found then
		w_libdes1 := 'Inconnue';
        when others then
		raise;
    end;

   begin
	SELECT LIBDES INTO w_LIBDES2 FROM CP_DES
     	WHERE cdos = wcdos AND numaxe = w_axe
       	AND CODDES = w_SEC_MBOUMI;
    exception
	when no_data_found then
		w_libdes2 := 'Inconnue';
        when others then
		raise;
    end;
   begin
	SELECT LIBDES INTO w_LIBDES3 FROM CP_DES
     	WHERE cdos = wcdos AND numaxe = w_axe
       	AND CODDES = w_SEC_pk27;
    exception
	when no_data_found then
		w_libdes3 := 'Inconnue';
        when others then
		raise;
    end;
   begin
	SELECT LIBDES INTO w_LIBDES4 FROM CP_DES
     	WHERE cdos = wcdos AND numaxe = w_axe
       	AND CODDES = w_SEC_SCIERIE;
    exception
	when no_data_found then
		w_libdes4 := 'Inconnue';
        when others then
		raise;
    end;

   begin
	SELECT LIBDES INTO w_LIBDES5 FROM CP_DES
     	WHERE cdos = wcdos AND numaxe = w_axe
       	AND CODDES = w_SEC_FGEN;
    exception
	when no_data_found then
		w_libdes5 := 'Inconnue';
        when others then
		raise;
    end;

    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
--dbms_output.put_line('w_fper '||to_char(w_fper));
    -- excercice précédent
    /*
    w_annee := to_number(substr(to_char(w_fper,'dd/mm/yyyy'),7,4))-1;
    w_dper_pre := to_date(substr(to_char(w_dper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_annee),'dd/mm/yyyy');
    w_fper_pre := to_date(substr(to_char(w_fper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_annee),'dd/mm/yyyy');
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk
 */
--dbms_output.put_line('w_annee '||to_char(w_annee));
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;


--dbms_output.put_line('w_ets '||w_ets);
--dbms_output.put_line('wcdos '||wcdos);
    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);
--dbms_output.put_line('w_ets '||w_ets);
       BEGIN
         SELECT distinct a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

--dbms_output.put_line('ets lib '||ets_lib);
    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;

    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := gen_ar;
--dbms_output.put_line('gen_ar');

--dbms_output.put_line('w_ndec '||to_char(w_ndec));
    larg_ed             := 156;

    w_l1                := RPAD(hor,larg_ed,hor);
    w_l2                := ver || SUBSTR(w_l1,2,154) || ver;
    w_l3                := ver || RPAD(' ',154) || ver;
    w_l4                := SUBSTR(w_l3,1,35) ||
                           ver || SUBSTR(w_l3,37,19) ||
                           ver || SUBSTR(w_l3,57,19) ||
                           ver || SUBSTR(w_l3,77,19) ||
                           ver || SUBSTR(w_l3,97,19) ||
                           ver || SUBSTR(w_l3,117,19) ||
                           ver || SUBSTR(w_l3,137,19) || ver;

    w_numord_edi := 0;

--dbms_output.put_line('w_numordedi '||to_char(w_numord_edi));

    FOR indi IN 1..9
    LOOP
       clcum_c1(indi)  := 0;
       clcum_c2(indi)  := 0;
       clcum_c3(indi)  := 0;
       clcum_c4(indi)  := 0;
       clcum_c5(indi)  := 0;
       clcum_c6(indi)  := 0;
       cpt_mjcum(indi) := 0;
    END LOOP;

    OPEN ar_list;
    LOOP
        FETCH ar_list INTO wpae;
        EXIT WHEN ar_list%NOTFOUND;

        p1  := wpae.param1;
        p2  := wpae.param2;
        p3  := wpae.param3;
        p4  := wpae.param4;
        IF wpae.codope = '01'   THEN
           w_titre := wpae.typope;
        END IF;

        IF        wpae.codope = '01' THEN w_faitout := func_ar_01;
            ELSIF wpae.codope = '02' THEN w_faitout := func_ar_02;
            ELSIF wpae.codope = '03' THEN w_faitout := func_ar_03;
            ELSIF wpae.codope = '04' THEN w_faitout := func_ar_04;
            ELSIF wpae.codope = '10' THEN w_faitout := func_pae_10;
            ELSIF wpae.codope = '11' THEN w_faitout := func_pae_11;
            ELSIF wpae.codope = '12' THEN w_faitout := func_pae_12;
            ELSIF wpae.codope = '13' THEN w_faitout := func_pae_13;
            ELSIF wpae.codope = '20' THEN w_faitout := func_pae_20;
            ELSIF wpae.codope = '21' THEN w_faitout := func_pae_21;
            ELSIF wpae.codope = '22' THEN w_faitout := func_pae_22;
            ELSIF wpae.codope = '25' THEN w_faitout := func_pae_25;
            ELSIF wpae.codope = '30' THEN w_faitout := func_ar_30;
            ELSIF wpae.codope = '34' THEN w_faitout := func_ar_03;
                                          w_faitout := func_ar_30;
                                          w_faitout := func_ar_03;
            ELSIF wpae.codope = '35' THEN w_faitout := func_ar_03;
                                          w_faitout := func_ar_30;
            ELSIF wpae.codope = '40' THEN w_faitout := func_ar_40;
            ELSIF wpae.codope = '41' THEN w_faitout := func_ar_40;
            ELSIF wpae.codope = '42' THEN w_faitout := func_ar_40;
            ELSIF wpae.codope = '43' THEN w_faitout := func_ar_40;
            ELSIF wpae.codope = '44' THEN w_faitout := func_ar_40;
            ELSIF wpae.codope = '45' THEN w_faitout := func_ar_40;
        END IF;

    END LOOP;
    CLOSE ar_list;

    --w_faitout := ed_tmp_fic(w_led);

END ledar01;

