    END IF;

    w_l5          := RPAD(ver,2) || RPAD(' ',47) ||
                     LPAD(w_titre,30)||' '|| RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),4,7),29) ||' Periode du ' ||
                     TO_CHAR(w_dper, 'dd-mm-yyyy') || ' au ' ||
                     TO_CHAR(w_fper, 'dd-mm-yyyy') ||
                     LPAD(ver,11);
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    w_supl := 0;
    w_l5          := RPAD(ver,2) ||
                    'Edite le ' || TO_CHAR(sysdate, 'dd-mm-yyyy "a" hh:mi:ss') ||
                     LPAD('Util. : ',119) || w_cuti || LPAD(ver,1);
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    arg2          := w_l1;
    w_faitout := up_tmp_ar;


    --
/*
    w_l5          := ver || LPAD(RPAD('RUBRIQUES',22),34)||ver||
                     LPAD(RPAD('BENOUE',14),19) ||ver||
                     LPAD(RPAD('MBOUMI',14),19) ||ver ||
                     RPAD(RPAD('PK 27',14),19) ||ver||
                    LPAD(RPAD('SCIERIE',13),19) ||ver||
