                     LPAD(RPAD('TOTAL BUDGET',15),19) ||
                     ver;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

   */

w_l5          := ver || LPAD(RPAD('RUBRIQUES',22),34)||ver||
                     LPAD(RPAD(substr(w_libdes1,1,15),17),19) ||ver||
                     LPAD(RPAD(substr(w_libdes2,1,15),17),19) ||ver ||
                     LPAD(RPAD(substr(w_libdes3,1,15),17),19) ||ver||
                    LPAD(RPAD(substr(w_libdes4,1,15),17),19) ||ver||
                     LPAD(RPAD(substr(w_libdes5,1,15),17),19) || ver ||
                     LPAD(RPAD('TOTAL REALISATION',18),19) ||
                     ver;
