---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_ar_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.booue := clcum_c1(p1);
       cpcum.mboumi := clcum_c2(p1);
       cpcum.pk27 := clcum_c3(p1);
       cpcum.scierie :=clcum_c4(p1);
       cpcum.fraisgen := clcum_c5(p1);
       cpcum.totbud := cpcum.booue + cpcum.mboumi +
               cpcum.pk27 + cpcum.fraisgen;
       w_faitout := detail_ar(wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_30;


----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_ar_40 RETURN BOOLEAN
IS
w_section	varchar2(8);

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
	     and cp_res.numsec = w_section
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN


	  if wpae.codope = '40' then
            w_section    := w_sec_boue;
	  elsif wpae.codope = '41' then
            w_section    := w_sec_mboumi;
	  elsif wpae.codope = '42' then
            w_section    := w_sec_pk27;
	  elsif wpae.codope = '43' then
            w_section    := w_sec_scierie;
	  elsif wpae.codope = '44' then
            w_section    := w_sec_fgen;
	  end if;

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        IF p2 != 0 THEN
             wedit          := 2;
             w_cum_solde_db := wres.mnt1 - wres.mnt2;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 AND wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 4 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt1 != 0 OR wres.mnt2 != 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit = 1     THEN
           FOR wi IN 1..9
           LOOP
             IF cpt_mjcum(wi) != 0   THEN
               IF wpae.codope = '40' THEN
                  clcum_c1(wi)  := clcum_c1(wi) + wres.mnt1 - wres.mnt2;
               ELSIF wpae.codope = '41' THEN
                  clcum_c2(wi)  := clcum_c2(wi) + wres.mnt1 - wres.mnt2;
               ELSIF wpae.codope = '42' THEN
                  clcum_c3(wi)  := clcum_c3(wi) + wres.mnt1 - wres.mnt2;
               ELSIF wpae.codope = '43' THEN
                  clcum_c4(wi)  := clcum_c4(wi) + wres.mnt1 - wres.mnt2;
               ELSIF wpae.codope = '44' THEN
                  clcum_c5(wi)  := clcum_c5(wi) + wres.mnt1 - wres.mnt2;
               END IF;
                  w_cum_solde_db := wres.mnt1 - wres.mnt2;
            END IF;
           END LOOP;
        END IF;

        IF wedit = 1 AND p1 = 1     THEN
          IF wpae.codope = '40' THEN
           cpcum.booue    :=  wres.mnt1 - wres.mnt2;
           cpcum.mboumi    :=  0;
           cpcum.pk27  :=  0;
           cpcum.fraisgen    :=  0;
           cpcum.scierie    :=  0;
           cpcum.totbud    :=  0;
         ELSIF wpae.codope = '41' THEN
           cpcum.booue    :=  0;
           cpcum.mboumi    :=  wres.mnt1 - wres.mnt2;
           cpcum.pk27  :=  0;
           cpcum.fraisgen    :=  0;
           cpcum.scierie    :=  0;
           cpcum.totbud  :=  0;
         ELSIF wpae.codope = '42' THEN
           cpcum.booue    :=  0;
           cpcum.mboumi    :=  0;
           cpcum.pk27  :=  wres.mnt1 - wres.mnt2;
           cpcum.fraisgen    :=  0;
           cpcum.scierie    :=  0;
           cpcum.totbud  :=  0;
         ELSIF wpae.codope = '43' THEN
           cpcum.booue    :=  0;
           cpcum.mboumi    :=  0;
           cpcum.pk27  :=  0;
           cpcum.fraisgen    :=  0;
           cpcum.scierie    :=  wres.mnt1 - wres.mnt2;
           cpcum.totbud  :=  0;
         ELSIF wpae.codope = '44' THEN
           cpcum.booue    :=  0;
           cpcum.mboumi    :=  0;
           cpcum.pk27  :=  0;
           cpcum.fraisgen    :=  wres.mnt1 - wres.mnt2;
           cpcum.scierie    :=  0;
           cpcum.totbud  :=  0;
         END IF;
     --   dbms_output.put_line(wres.numcpt||'    '||to_char(cpcum.sofina));
           w_faitout := detail_ar(wres.libe);
        END IF;

    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_ar_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_ar(ed_intr IN VARCHAR2) RETURN BOOLEAN
IS

BEGIN

--dbms_output.put_line('debut detail' );
    w_l5      := ver || RPAD(ed_intr,34) || SUBSTR(w_l4,36,121);

    mtf := numfs(cpcum.booue,w_ndec);

    IF cpcum.booue != 0 THEN
       w_l5   := SUBSTR(w_l5,1,36) || LPAD(mtf,19) || substr(w_l5,56,100);

    END IF;

    mtf := numfs(cpcum.mboumi,w_ndec);
    IF cpcum.mboumi != 0 THEN
       w_l5   := SUBSTR(w_l5,1,56) || LPAD(mtf,19) || substr(w_l5,76,80);

    END IF;
    mtf := numfs(cpcum.pk27,w_ndec);
    IF cpcum.pk27 != 0 THEN
       w_l5   := SUBSTR(w_l5,1,76) || LPAD(mtf,19) || substr(w_l5,96,60);
    END IF;
    mtf := numfs(cpcum.scierie,w_ndec);
    IF cpcum.scierie != 0 THEN
       w_l5   := SUBSTR(w_l5,1,96) || LPAD(mtf,19) || substr(w_l5,116,40);
    END IF;
    mtf := numfs(cpcum.fraisgen,w_ndec);
    IF cpcum.fraisgen != 0 THEN
       w_l5   := SUBSTR(w_l5,1,116) || LPAD(mtf,19) || substr(w_l5,136,20);
    END IF;
    w_total := cpcum.booue+cpcum.mboumi+cpcum.pk27+cpcum.scierie+cpcum.fraisgen;
    mtf := numfs(w_total,w_ndec);
    IF w_total != 0 THEN
       w_l5   := SUBSTR(w_l5,1,136) || LPAD(mtf,19) ;
    END IF;
    w_l5 := lpad(w_l5,155)||ver;
--    arg1           := 0;
    arg2           := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END detail_ar;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_ar RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_ar_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_ar;

----------------------- Calcul et MAJ des cumuls des comptes -------------

FUNCTION gen_ar RETURN BOOLEAN
IS

    CURSOR ar_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope in ('40','41','42','43','44') ORDER BY cdos,codeta,numord;
/*
   CURSOR ar_cpt_list1 IS
         SELECT a.cdos, a.numcpt, a.intcpt, b.codran, b.natcpt, a.raccpt,a.codnat
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;
*/
    CURSOR ar_cpt_list1 IS
         SELECT cdos,codnat, libnat from cp_nat
          WHERE cdos = wcdos
            AND codnat <= wpae.cptfin AND codnat >= wpae.cptdeb
	    and gesqte = 'N';
    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN

    OPEN ar_list1;
    LOOP
        FETCH ar_list1 INTO wpae;
        EXIT WHEN ar_list1%NOTFOUND;

        OPEN ar_cpt_list1;
        LOOP
            FETCH ar_cpt_list1 INTO wcpt.cdos, wcpt.codnat, wcpt.intcpt;
            EXIT WHEN ar_cpt_list1%NOTFOUND;

            continuer := false;

	  if wpae.codope = '40' then
            wres.numsec    := w_sec_boue;
	  elsif wpae.codope = '41' then
            wres.numsec    := w_sec_mboumi;
	  elsif wpae.codope = '42' then
            wres.numsec    := w_sec_pk27;
	  elsif wpae.codope = '43' then
            wres.numsec    := w_sec_scierie;
	  elsif wpae.codope = '44' then
            wres.numsec    := w_sec_fgen;
	  end if;
	    w_sec_reg	 := substr(wres.numsec,1,4)||'%';
--dbms_output.put_line('debut du calcul '||'codope '||wpae.codope||' numsec '||wres.numsec||' numcpt '||wcpt.numcpt);
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.codnat and cp_res.numsec = wres.numsec;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
/*
	  if wpae.codope = '40' then
            wres.numsec    := w_sec_boue;
	  elsif wpae.codope = '41' then
            wres.numsec    := w_sec_mboumi;
	  elsif wpae.codope = '42' then
            wres.numsec    := w_sec_pk27;
	  elsif wpae.codope = '43' then
            wres.numsec    := w_sec_scierie;
	  elsif wpae.codope = '44' then
            wres.numsec    := w_sec_fgen;
	  end if;
*/
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.mnt5      := 0;
            wres.mnt6      := 0;
            wres.mnt7      := 0;
            wres.mnt8      := 0;
            wres.mnt9      := 0;
            wres.mnt10      := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.codnat;
         --   if wpae.sel = 'I' then
          --    wres.libe      := wcpt.raccpt;
           -- else
              wres.libe      := wcpt.intcpt;
          --  end if;
            wres.sens      := 'X';
          --  wres.ctie      := substr(wpro.natcpt,1,1);
            w_cum_solde_cr := 0;
            w_cum_solde_db := 0;

--dbms_output.put_line('w_numcpt '||wcpt.numcpt||' codeope '||wpae.codope||' w_sec_reg '||w_sec_reg);

         FOR wmvg IN
            (SELECT b.codjou, a.*
               FROM cp_ecr_ana a, cp_ecr b
              WHERE a.cdos =  wcdos AND
                    a.codnat = wcpt.codnat and
                    a.datcpt between w_dper and w_fper
                    and a.codets LIKE sel_Ets
            --        and a.coddes = w_coddes

		    and a.coddes like w_sec_reg

                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w_fper_c
--                    and b.periode <= w_fper_c
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
		            and a.numaxe = w_axe
              ORDER BY a.cdos,a.numcpt)
        LOOP

            CONTINUER := true;

             w_natjou := null;
             select NATJOU into w_natjou FROM CP_JOU
        				                WHERE CDOS = WCDOS
		      			                and codjou = wmvg.codjou;
            if continuer then
            IF  wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
            IF w_sim = 'O' or w_natjou != 'S' THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt1 := wres.mnt1 + wmvg.grp_mtdb;
               ELSE wres.mnt2 := wres.mnt2 + wmvg.grp_mtcr;
               END IF;
             END IF;

         --    END IF;
            END IF;
                        end if;
--dbms_output.put_line(wres.numcpt||' debit '||to_char(wmvg.grp_mtdb)||' Credit '||to_char(wmvg.grp_mtcr) );
         END LOOP;


	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
	                    w_session_id);   --lk
         commit; --lk
--dbms_output.put_line(wres.numcpt||' fin');
      END IF;
      END LOOP;
      CLOSE ar_cpt_list1;
   END LOOP;
   CLOSE ar_list1;

-- dbms_output.put_line('fin gen_ar' );
   RETURN TRUE;
END gen_ar;


