PROCEDURE ledar01 (woptions IN VARCHAR2)
IS

    CURSOR ar_list IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala
         ORDER BY cdos,codeta,numord;

BEGIN

--  lecture des parametres d'edition dans le fichier evlanc
-- i

dbms_output.enable(50000);

    w_bala        := rtrim(substr(woptions,1,3));
    w_dper_c      := substr(woptions,4,3);
    w_fper_c      := substr(woptions,7,3);
    w_cuti        := substr(woptions,10,4);
    wcdos         := substr(woptions,14,2);
    w_ets         := rtrim(substr(woptions,16,3));
    w_secdeb         := rtrim(substr(woptions,19,8));
    w_secfin         := rtrim(substr(woptions,27,8));
    w_ecr_non_maj := substr(woptions,35,1);
    w_sim	  := substr(woptions,36,1);
    w_axe	  := to_number(substr(woptions,37,1));
    w_session_id  := to_number(substr(woptions,38,38));

-- dbms_output.put_line('w_sess '||woptions);
dbms_output.put_line('Option'||woptions);
dbms_output.put_line('wdper_c '||w_dper_c);
dbms_output.put_line('wfperc '||w_fper_c);
dbms_output.put_line('w_ets '||w_ets);
dbms_output.put_line('wcdos '||wcdos);
dbms_output.put_line('w_axe '||w_axe);
dbms_output.put_line('w_secdeb '||w_secdeb);
dbms_output.put_line('w_secfin '||w_secfin);
dbms_output.put_line('w_sim '||w_sim);
dbms_output.put_line('w_session_id '||w_session_id);

   w_nmois := to_number(w_fper_c) - to_number(w_dper_c) + 1;


    w_ets := w_etbfin;

    begin
	SELECT datdeb INTO w_dper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_dper_c;
    exception
	when no_data_found then
		w_dper := to_date('01/07/0001','dd/mm/yyyy');
        when others then
		raise;
    end;

    begin
    	SELECT datfin INTO w_fper FROM CP_PER
     	WHERE cdos = wcdos
       	AND periode = w_fper_c;
    exception
	when no_data_found then
		w_fper := to_date('30/06/2050','dd/mm/yyyy');
        when others then
		raise;
    end;
    begin
    	SELECT max(numord) INTO w_maxnb FROM CP_PAE
     	WHERE cdos = wcdos
       	AND codope = '02' and codeta = w_bala;
    exception
	when no_data_found then
		w_maxnb := 0;
        when others then
		raise;
    end;

dbms_output.put_line('w_fper '||to_char(w_fper));
    -- excercice précédent

    w_annee := to_number(substr(to_char(w_fper,'dd/mm/yyyy'),7,4))-1;
    w_dper_pre := to_date(substr(to_char(w_dper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_annee),'dd/mm/yyyy');
    w_fper_pre := to_date(substr(to_char(w_fper,'dd/mm/yyyy'),1,6)||
                                    to_char(w_annee),'dd/mm/yyyy');
    w_exercice := substr(w_dper_c,1,1) || '00';
    --fin sk

dbms_output.put_line('w_annee '||to_char(w_annee));
    SELECT * INTO wdos FROM cp_dos
     WHERE cdos = wcdos;


dbms_output.put_line('w_ets '||w_ets);
dbms_output.put_line('wcdos '||wcdos);
    IF w_ets IS NOT NULL AND w_ets <> ' ' AND w_ets <> '   ' then
       sel_ets := w_ets;
       SELECT libets INTO ets_lib FROM cp_ets
        WHERE cdos = wcdos AND codets = RTRIM(w_ets);
dbms_output.put_line('w_ets '||w_ets);
       BEGIN
         SELECT distinct a.nbrdec INTO w_ndec FROM CP_DEV A, CP_ETS B
          WHERE a.cdos = wcdos
            AND a.cdos = b.cdos
            AND a.coddev = b.coddev
            AND b.codets = w_ets;
       EXCEPTION
         WHEN NO_DATA_FOUND THEN
            w_ndec := wdos.nddd;
       END;
    ELSE
       sel_ets := '%';
       ets_lib := ' ';
    END IF;

dbms_output.put_line('ets lib '||ets_lib);
    IF w_dper > wdos.dfex THEN
       w_ddex       := wdos.ddes;
    ELSE
       w_ddex       := wdos.ddex;
    END IF;


    w_time  :=   TO_CHAR(SYSDATE,'HH:MI:SS');
    w_date  :=   SYSDATE;
    w_ndec  :=   wdos.nddd;
    w_page  :=   0;
    w_ligne :=   0;
    w_maxlg :=   66;

--    w_nblg  :=   66;

    w_faitout := pae_tabtmp;
--dbms_output.put_line(to_char(wdos.dfex));
--dbms_output.put_line(to_char(w_ddex));
    w_faitout := gen_ar;
--dbms_output.put_line('gen_ar');
