    w_l3                := ver || RPAD(' ',180) || ver;
    w_l4                := SUBSTR(w_l3,1,25) ||
                           ver || SUBSTR(w_l3,27,12) ||
                           ver || SUBSTR(w_l3,40,12) ||
                           ver || SUBSTR(w_l3,53,12) ||
                           ver || SUBSTR(w_l3,66,12) ||
                           ver || SUBSTR(w_l3,79,12) ||
                           ver || SUBSTR(w_l3,92,12) ||
                           ver || SUBSTR(w_l3,105,12) ||
                           ver || SUBSTR(w_l3,118,12) ||
                           ver || SUBSTR(w_l3,131,12) ||
                           ver || SUBSTR(w_l3,144,12) ||
                           ver || SUBSTR(w_l3,157,12) ||
                           ver || SUBSTR(w_l3,170,12) || ver;

    w_numord_edi := 0;

--dbms_output.put_line('w_numordedi '||to_char(w_numord_edi));

