BEGIN

        indic             := 0;
        w_cum_solde_db    := clcum_c3(p1) - clcum_c4(p1);
        IF w_cum_solde_db >= 0   THEN
--         w_faitout := func_pae_30;
        END IF;

   RETURN TRUE;

END func_pae_32;
*/

