FUNCTION numfs(mt IN NUMBER, ndc IN NUMBER) RETURN VARCHAR2
IS

BEGIN

--dbms_output.put_line('debut numfs ' ||to_char(ndc));
   IF      ndc  = 3 THEN mtf := TO_CHAR(mt, '9999999990D000');
   ELSIF   ndc  = 2 THEN mtf := TO_CHAR(mt, '99999999990D00');
   ELSIF   ndc  = 1 THEN mtf := TO_CHAR(mt, '999999999990.0');
   ELSE                  mtf := TO_CHAR(mt, '99G999G999G990');
   END IF;

--dbms_output.put_line('fin numfs' );
   RETURN mtf;

END numfs;

