                      LPAD(RPAD(to_char(w_fper_pre,'dd/mm/yyyy'),14),19) ||
                     ver || LPAD(RPAD(to_char(w_fper,'dd/mm/yyyy'),14),19) ||
                     ver || LPAD(RPAD(to_char(w_fper,'dd/mm/yyyy'),14),19) ||
                     ver || RPAD(' ',19) ||
                     ver || LPAD(RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),7,4)||'/'||
                        substr(to_char(w_fper_pre,'dd/mm/yyyy'),7,4),14),19) ||
                     ver || LPAD(RPAD(substr(to_char(w_fper,'dd/mm/yyyy'),7,4)||'/BUDGET',14),19) ||
                     ver;
