   -- arg2          := w_l4;
   -- w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_01;

----------------------- EDITION DE L'INTITULE + SAUT DE LIGNE ------------

FUNCTION func_ar_02 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    IF p1 = 0 THEN
       p1 := 1;
    END IF;
    w_needlg := p1;
    w_l5          := RPAD(ver,15) || wpae.typope || LPAD(ver,100) ;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;
    w_needlg := 1;
    IF p1 > 1 THEN
       arg2          := w_l3;
       FOR indi IN 2..p1
       LOOP
           w_faitout := up_tmp_ar;
       END LOOP;
    END IF;

    RETURN TRUE;
END func_ar_02;

----------------------- EDITION D'UNE LIGNE DE TIRETS  -------------------
FUNCTION func_ar_03 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l2;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_03;

----------------------- EDITION D'UNE LIGNE ESPACE     -------------------
FUNCTION func_ar_04 RETURN BOOLEAN
IS

BEGIN

    w_supl := 0;

    w_l5          := w_l4;
    w_needlg      := 1;
    arg2          := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END func_ar_04;

---------------- EDITION INTITULE ET DES MONTANT P1 - SI P2 := 1 RAZ P1 ---

FUNCTION func_ar_30 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.sofina := clcum_c1(p1);
       cpcum.bdfinb := clcum_c2(p1);
       cpcum.sofinc := clcum_c3(p1);
       cpcum.pcentd := 0;
       cpcum.ecarte := cpcum.sofinc - cpcum.sofina;
       cpcum.ecartf := cpcum.sofinc - cpcum.bdfinb;
       w_faitout := detail_ar(wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_30;


FUNCTION func_ar_31 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.sofina := clcum_c1(p1)/w_exprec;
       cpcum.bdfinb := clcum_c2(p1)/w_budget;
       cpcum.sofinc := clcum_c3(p1)/w_execn;
       cpcum.pcentd := 0;
       cpcum.ecarte := 0;
       cpcum.ecartf := 0;

        w_faitout := detail_ar(wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_31;

FUNCTION func_ar_32 RETURN BOOLEAN
IS

BEGIN

    w_supl := 1;

    IF p1 != 0 THEN
       cpcum.sofina := w_exprec;
       cpcum.bdfinb := w_budget;
       cpcum.sofinc := w_execn;
       cpcum.pcentd := 0;
       cpcum.ecarte := 0;
       cpcum.ecartf := 0;

        w_faitout := detail_ar(wpae.typope);
    END IF;

    IF p2 = 1                 THEN
       clcum_c1(p1)   := 0;
       clcum_c2(p1)   := 0;
       clcum_c3(p1)   := 0;
       clcum_c4(p1)   := 0;
       clcum_c5(p1)   := 0;
       clcum_c6(p1)   := 0;
    END IF;

    RETURN TRUE;
END func_ar_32;
----------------------- EDITION D'UNE FOURCHETTE DE COMPTES  -------------

FUNCTION func_ar_40 RETURN BOOLEAN
IS

   CURSOR cur_wselres IS
      SELECT * FROM cp_res
       WHERE cp_res.cdos =  wcdos AND session_id = w_session_id AND  --lk
             cp_res.numcpt BETWEEN wpae.cptdeb AND wpae.cptfin
       ORDER BY cp_res.cdos, cp_res.numcpt;

BEGIN

    w_faitout := tri_cpres;

    w_supl := 1;
    OPEN cur_wselres;
    LOOP
      FETCH cur_wselres INTO wres;
      EXIT WHEN cur_wselres%NOTFOUND;

        IF p2 != 0 THEN
             wedit          := 2;
             w_cum_solde_db := wres.mnt5 - wres.mnt6;
             IF    p2 = 1 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt5 != 0 AND wres.mnt6 != 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 2 THEN
                      IF w_cum_solde_db > 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 3 THEN
                      IF w_cum_solde_db < 0 THEN
                         wedit := 1;
                      END IF;
             ELSIF p2 = 4 THEN
                      IF w_cum_solde_db != 0 THEN
                         wedit := 1;
                      END IF;
                      IF wres.mnt5 != 0 OR wres.mnt6 != 0 THEN
                         wedit := 1;
                      END IF;
             END IF;
        ELSE wedit := 1;
        END IF;

        IF wedit = 1     THEN
           FOR wi IN 1..9
           LOOP
               IF cpt_mjcum(wi) != 0   THEN
                  clcum_c1(wi)  := clcum_c1(wi) + wres.mnt1 - wres.mnt2;
                  clcum_c2(wi)  := clcum_c2(wi) + wres.mnt3 - wres.mnt4;
                  clcum_c3(wi)  := clcum_c3(wi) + wres.mnt5 - wres.mnt6;
                  w_cum_solde_db := wres.mnt5 - wres.mnt6;
                                 END IF;
           END LOOP;
        END IF;

        IF wedit = 1 AND p1 = 1     THEN
           cpcum.sofina    :=  wres.mnt1 - wres.mnt2;
           cpcum.bdfinb    :=  wres.mnt3 - wres.mnt4;
           cpcum.sofinc  :=  wres.mnt5 - wres.mnt6;
           cpcum.pcentd    :=  0;
           cpcum.ecarte    :=  cpcum.sofinc - cpcum.sofina;
           cpcum.ecartf    :=  cpcum.sofinc - cpcum.bdfinb;
     --   dbms_output.put_line(wres.numcpt||'    '||to_char(cpcum.sofina));
           w_faitout := detail_ar(wres.libe);
        END IF;

    END LOOP;
    CLOSE cur_wselres;

    RETURN TRUE;
END func_ar_40;

----------------------- Edition d'une ligne de cumul  --------------------

FUNCTION detail_ar(ed_intr IN VARCHAR2) RETURN BOOLEAN
IS

BEGIN

--dbms_output.put_line('debut detail' );
    w_l5      := ver || RPAD(ed_intr,34) || SUBSTR(w_l4,36,121);

    mtf := numfs(cpcum.sofina,w_ndec);

--dbms_output.put_line('sofina' );
    IF cpcum.sofina != 0 THEN
       w_l5   := SUBSTR(w_l5,1,36) || LPAD(mtf,19) || substr(w_l5,56,100);
--dbms_output.put_line(mtf );
    END IF;

--dbms_output.put_line('bdfinb' );
    mtf := numfs(cpcum.bdfinb,w_ndec);
    IF cpcum.bdfinb != 0 THEN
       w_l5   := SUBSTR(w_l5,1,56) || LPAD(mtf,19) || substr(w_l5,76,80);
--dbms_output.put_line(mtf );
    END IF;
    mtf := numfs(cpcum.sofinc,w_ndec);
    IF cpcum.sofinc != 0 THEN
       w_l5   := SUBSTR(w_l5,1,76) || LPAD(mtf,19) || substr(w_l5,96,60);
    END IF;
    mtf := numfs(cpcum.pcentd,w_ndec);
    IF cpcum.pcentd != 0 THEN
       w_l5   := SUBSTR(w_l5,1,96) || LPAD(mtf,19) || substr(w_l5,116,40);
    END IF;
    mtf := numfs(cpcum.ecarte,w_ndec);
    IF cpcum.ecarte != 0 THEN
       w_l5   := SUBSTR(w_l5,1,116) || LPAD(mtf,19) || substr(w_l5,136,20);
    END IF;
    mtf := numfs(cpcum.ecartf,w_ndec);
    IF cpcum.ecartf != 0 THEN
       w_l5   := SUBSTR(w_l5,1,136) || LPAD(mtf,19) ;
    END IF;
    w_l5 := lpad(w_l5,155)||ver;
--    arg1           := 0;
    arg2           := w_l5;
    w_faitout := up_tmp_ar;

    RETURN TRUE;
END detail_ar;

----------------------- Creation des lignes du fichier d'edition ---------
FUNCTION up_tmp_ar RETURN BOOLEAN
IS

    w_arg2      cp_edi.lign%TYPE;

BEGIN

--    IF arg1 = '1' THEN
--       w_ligne := 0;
--    END IF;
    w_nblg     := w_needlg + w_ligne;
--  IF w_nblg > w_maxlg  THEN
    IF arg2 IS NOT NULL AND mod(w_numord_edi, w_maxlg) = w_maxlg -1 THEN
       wtmp.lign := w_l1;
       --wtmp.lign[250,250] := lig_as;
       w_numord_edi := w_numord_edi + 1;
       INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
       COMMIT;
       w_arg2    := arg2;
       sauv_supl := w_supl;
       w_faitout := func_ar_01;
       arg2      := w_arg2;
       w_supl    := sauv_supl;
    END IF;

    wtmp.saut  := arg1;
    wtmp.lign  := arg2;
    w_numord_edi := w_numord_edi + 1;
    INSERT INTO cp_edi VALUES (w_session_id,w_numord_edi, wtmp.saut, wtmp.lign);
    COMMIT;
    w_ligne    := w_ligne + 1;

    RETURN TRUE;
END up_tmp_ar;

----------------------- Calcul et MAJ des cumuls des comptes -------------

FUNCTION gen_ar RETURN BOOLEAN
IS

    CURSOR ar_list1 IS
        SELECT * FROM cp_pae
         WHERE cdos = wcdos AND codeta = w_bala AND
               codope = '40' ORDER BY cdos,codeta,numord;
/*
   CURSOR ar_cpt_list1 IS
         SELECT a.cdos, a.numcpt, a.intcpt, b.codran, b.natcpt, a.raccpt,a.codnat
           FROM cp_cpt a, cp_pro b
          WHERE a.cdos = wcdos
            AND a.numcpt <= wpae.cptfin AND a.numcpt >= wpae.cptdeb
            AND a.cdos = b.cdos and a.codpro = b.codpro
          ORDER BY a.cdos, a.numcpt;
*/

   CURSOR ar_cpt_list1 IS
         SELECT cdos,codnat, libnat from cp_nat
          WHERE cdos = wcdos
            AND codnat <= wpae.cptfin AND codnat >= wpae.cptdeb
	    and gesqte = 'N';
    rupt                 CHAR(16);
    continuer            BOOLEAN;

BEGIN
    OPEN ar_list1;
    LOOP
        FETCH ar_list1 INTO wpae;
        EXIT WHEN ar_list1%NOTFOUND;

        OPEN ar_cpt_list1;
        LOOP
             FETCH ar_cpt_list1 INTO wcpt.cdos, wcpt.codnat, wcpt.intcpt;
            EXIT WHEN ar_cpt_list1%NOTFOUND;

            continuer := false;
            begin
               SELECT numcpt INTO char8 FROM cp_res WHERE
                  cp_res.cdos = wcpt.cdos AND session_id = w_session_id  AND --lk
                  cp_res.numcpt = wcpt.codnat;
            exception
               when no_data_found then
                  continuer := true;
            end;

         if continuer then
--lk           INITIALIZE wres.* TO NULL
            wres.numsec    := '00000000';
            wres.mnt1      := 0;
            wres.mnt2      := 0;
            wres.mnt3      := 0;
            wres.mnt4      := 0;
            wres.mnt5      := 0;
            wres.mnt6      := 0;
            wres.mnt7      := 0;
            wres.mnt8      := 0;
            wres.mnt9      := 0;
            wres.mnt10      := 0;
            wres.cdos      := wcdos;
            wres.numcpt      := wcpt.codnat;
          --  if wpae.sel = 'I' then
           --   wres.libe      := wcpt.raccpt;
           -- else
              wres.libe      := wcpt.intcpt;
          --  end if;
            wres.sens      := 'X';
            wres.ctie      := substr(wpro.natcpt,1,1);
            w_cum_solde_cr := 0;
            w_cum_solde_db := 0;

         FOR wmvg IN
            (SELECT b.codjou, a.*
               FROM cp_ecr_ana a, cp_ecr b
              WHERE a.cdos =  wcdos AND
                    codnat = wcpt.codnat and
                    a.datcpt between w_dper_pre and w_fper
                    and a.codets = w_codets
                    and a.coddes between nvl(w_secdeb,a.coddes) and nvl(w_secfin,'ZZZZZZZZ')
                    and b.cdos = a.cdos
                    and b.numsai = a.numsai
--                    and b.periode between w_exercice and w_fper_c
--                    and b.periode <= w_fper_c
                    and
                	  (
		            (w_ecr_non_maj = 'N' and b.codmaj = 'O')
		            or (w_ecr_non_maj = 'O')
        		      )
		            and a.numaxe = w_axe
              ORDER BY a.cdos,a.codnat)
        LOOP

            CONTINUER := true;
            -- Dans le cas d'une balance de reouverture,
            -- seules les ecritures dont le code journal est egal au
            -- journal de cloture (dossier) sont prises en compte
--        IF w_reou = 'O' AND wmvg.codjou != wdos.dcjr THEN
--           CONTINUER := false;
--        END IF;

            -- Dans le cas d'une balance sur l'exercice suivant, si la
            -- "cloture simulee" (RAN) n'est pas demandee, seuls les
            -- mouvements >= date de debut de l'exercice suivant sont
            -- pris en compte
/*
            IF w_dper > wdos.dfex AND  w_ran = 'N' AND
               wmvg.datcpt < wdos.ddes THEN
               CONTINUER := false;
            END IF;
*/
            --  simulation de la cloture   :  cpt de gestion  = 0
            --             cpt de bilan    = solde au wdos.dfex (fin ex.)

----dbms_output.put_line (to_char(w_dper,'dd/mm/yyyy'));
----dbms_output.put_line (to_char(wdos.dfex,'dd/mm/yyyy'));
----dbms_output.put_line (to_char(wmvg.datcpt,'dd/mm/yyyy'));
----dbms_output.put_line (to_char(wdos.ddes,'dd/mm/yyyy'));
 /*           IF w_dper > wdos.dfex AND w_ran = 'O' AND wmvg.datcpt < wdos.ddes THEN
               IF wpro.codran = 'N' THEN
                  CONTINUER := false;
               END IF;
               if continuer then
               IF wmvg.sens = 'C' THEN
                    w_cum_solde_cr := w_cum_solde_cr + wmvg.grp_mtcr;
                    CONTINUER := false;
               ELSE w_cum_solde_db := w_cum_solde_db + wmvg.grp_mtdb;
                    CONTINUER := false;
               END IF;
               end if;
            END IF;
*/

             w_natjou := null;
             select NATJOU into w_natjou FROM CP_JOU
        				                WHERE CDOS = WCDOS
		      			                and codjou = wmvg.codjou;
            if continuer then
            IF  wmvg.datcpt <= w_fper AND wmvg.datcpt >= w_dper THEN
       --      IF w_natjou != 'S' THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt5 := wres.mnt5 + wmvg.grp_mtdb;
               ELSE wres.mnt6 := wres.mnt6 + wmvg.grp_mtcr;
               END IF;
       --      ELSE
        --       IF wmvg.sens = 'D' THEN
        --            wres.mnt9 := wres.mnt9 + wmvg.grp_mtdb;
        --       ELSE wres.mnt10 := wres.mnt10 + wmvg.grp_mtcr;
        --      END IF;

         --    END IF;
            END IF;
            --période precedente
            IF wmvg.datcpt <= w_fper_pre AND wmvg.datcpt >= w_dper_pre THEN
               IF wmvg.sens = 'D' THEN
                    wres.mnt1 := wres.mnt1 + wmvg.grp_mtdb;
               ELSE wres.mnt2 := wres.mnt2 + wmvg.grp_mtcr;
               END IF;
            END IF;
            end if;
-- dbms_output.put_line(wres.numcpt||' debit '||to_char(wmvg.grp_mtdb)||' Credit '||to_char(wmvg.grp_mtcr) );
         END LOOP;
         -- traitement du Budget
         If wcpt.codnat is not null then
            for wbud in
              ( select * from cp_buda
               where cdos = wcdos
                 and numaxe = w_axe
                 and codets = w_codets
                 and coddes between nvl(w_secdeb,coddes) and nvl(w_secfin,'ZZZZZZZZ')
                 and codnat = wcpt.codnat
                 and periode between w_dper_c and w_fper_c)
               LOOP
                  IF wbud.sens = 'D' THEN
                    wres.mnt3 := wres.mnt3 + wbud.dos_mtbu;
                  ELSE wres.mnt4 := wres.mnt4 + wbud.dos_mtbu;
               END IF;

               END LOOP;
         END IF;

	                INSERT INTO cp_res VALUES (wres.cdos, wres.numcpt,
	                    wres.numsec, wres.libe, wres.mnt1, wres.mnt2,
	                    wres.mnt3, wres.mnt4, wres.mnt5, wres.mnt6,
	                    wres.mnt7, wres.mnt8, wres.mnt9, wres.mnt10,
	                    wres.mnt11, wres.mnt12, wres.sens, wres.ctie,
	                    w_session_id);   --lk
         commit; --lk
--dbms_output.put_line(wres.numcpt||' fin');
      END IF;
      END LOOP;
      CLOSE ar_cpt_list1;
   END LOOP;
   CLOSE ar_list1;

-- dbms_output.put_line('fin gen_ar' );
   RETURN TRUE;
END gen_ar;


