CREATE PACKAGE BODY PA_COMPTA
AS


--------------------------------------------------------------------------------
FUNCTION Format_Mt (mt IN NUMBER,      ndc IN NUMBER,
                   long_ret IN NUMBER, Avec_Zero IN BOOLEAN) RETURN VARCHAR2
IS

  mtf1     CHAR(20);
  c20      VARCHAR2(20);

BEGIN
  IF Avec_Zero THEN
     IF ndc = 3 THEN
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G990D999')),20,' ');
     ELSIF ndc = 2 THEN
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'9G999G999G999G990D99')),20,' ');
     ELSIF ndc = 1 THEN
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'99G999G999G999G990D9')),20,' ');
     ELSE
        mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G999G990')),20,' ');
     END IF;
  ELSE
     IF NOT NouZ(mt) THEN
       IF ndc = 3 THEN
          mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G999D999')),20,' ');
       ELSIF ndc = 2 THEN
          mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'9G999G999G999G999D99')),20,' ');
       ELSIF ndc = 1 THEN
         mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0),'99G999G999G999G999D9')),20,' ');
       ELSE
         mtf1 := LPAD(LTRIM(TO_CHAR(NVL(mt,0), '999G999G999G999G999')),20,' ');
       END IF;
     ELSE
       mtf1 := LPAD(' ',20,' ');
     END IF;
  END IF;
  c20  := ' ';
  c20 := SUBSTR(mtf1,20-long_ret+1);
  RETURN c20;

END Format_Mt;

---------------------------------------------------------------------
FUNCTION NouB(l_champ VARCHAR2) RETURN BOOLEAN
IS
BEGIN
   IF l_champ IS NULL THEN
      RETURN TRUE;
   ELSIF LTRIM(RTRIM(l_champ)) IS NULL OR LTRIM(RTRIM(l_champ)) = ''  THEN
      RETURN TRUE;
   ELSE
      RETURN FALSE;
   END IF;
END NouB;

---------------------------------------------------------------------
FUNCTION NouZ(l_champ NUMBER) RETURN BOOLEAN
IS
BEGIN
   IF l_champ IS NULL THEN
      RETURN TRUE;
   ELSIF l_champ = 0 THEN
      RETURN TRUE;
   ELSE
      RETURN FALSE;
   END IF;
END NouZ;

----------------------------------------------------------------------------
END PA_COMPTA;

-----------------------------------------------------------------------------
/

