-- new object type path: DATABASE_EXPORT/SCHEMA/TABLE/TRIGGER
CREATE TRIGGER CAISSE.gcbrdd_gcstock
AFTER INSERT  OR DELETE  OR UPDATE
OF coddep, codart, codtbrd, qtebrd, coeff, typlig, ligne_solde, qtetrans, codstat
ON CAISSE.gcbrdd
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
declare
  v_sens 	    gcptbrd.sens%type;
  n_qtestock 	gcstock.qtestock%type;
  n_quantite	gcstock_statut.quantite%Type;
  d_date	    DATE;
  d_datbrd      DATE;
  d_ddersor	    gcstock.ddersor%type;
  d_dderent	    gcstock.dderent%type;

  v_type		gcptbrd.type%type;
  v_majpret		gcptbrd.majpret%type;
  v_majreserv	gcptbrd.majreserv%type;
  v_majcde		gcptbrd.majcde%type;
  v_majstock	gcptbrd.majstock%type;
  v_majstatut	gcptbrd.majstatut%type;

  v_codtbrd	    gcbrde.codtbrd%type;
  n_idbrd_sce	gcbrde.idbrdctrp%type;
  v_codstat		gcstock_statut.codstat%type;

  n_qte         gcbrdd.qtebrd%type;
  v_gesstatut	Gcppar.valc%Type := 'O';
begin
  Select max(valc) Into v_gesstatut From Gcppar
   Where codpar = 'BORDEREAUX' and cle='STA';
  v_gesstatut := Nvl(v_gesstatut,'N');

  if (deleting or updating) and (:old.typlig='0') then
    begin
      select codtbrd, idbrd_sce into v_codtbrd, n_idbrd_sce from gcbrde
       where idbrd = :old.idbrd;
    end;

    begin
      select sens, type, majpret, majstock, majreserv, majcde, majstatut
        into v_sens, v_type, v_majpret, v_majstock, v_majreserv, v_majcde, v_majstatut
        from gcptbrd
       where codtbrd = v_codtbrd;
    exception
      when no_data_found then
        raise_application_error (-20501,'Type de bordereau inconnu');
    end;

	If :old.coddep is not null Then
		begin
		  select qtestock, ddersor, dderent into n_qtestock, d_ddersor, d_dderent
			from gcstock
		   where coddep=:old.coddep and
				 codart=:old.codart;
		exception
		  when no_data_found then
			   n_qtestock := 0;
			   d_ddersor := null;
			   d_dderent := null;
		end;
	End if;

    -- Mise à jour du chanp QTESTOCK
    if :old.qtebrd < 0 then
       n_qte := :old.qtebrd;
	elsif :old.ligne_solde = 'O' Then
	   n_qte := 0;
    elsif nvl(:old.qtetrans,0) > :old.qtebrd then
       n_qte := 0;
    else
       n_qte := :old.qtebrd - nvl(:old.qtetrans,0);
    end if;
    n_qte := n_qte * nvl(:old.coeff,1);

    -- Si maj du stock on ne tient pas compte du champ QTETRANS
    if v_majstock = 'O' THEN
       if v_sens = 'E' then
          update gcstock
             set qtestock = nvl(qtestock,0) - :old.qtebrd * nvl(:old.coeff,1)
           where coddep=:old.coddep
             and codart=:old.codart;
       else
          update gcstock
             set qtestock = nvl(qtestock,0) + :old.qtebrd * nvl(:old.coeff,1)
           where coddep=:old.coddep
             and codart=:old.codart;
       end if;
    end if;

    -- Mise à jour du champ QTEPRET
    if v_majpret IS NOT NULL THEN
       if v_majpret = '+' then
          update gcstock set qtepret = nvl(qtepret,0) - n_qte
           where coddep=:old.coddep
             and codart=:old.codart;
       else
          update gcstock set qtepret = nvl(qtepret,0) + n_qte
           where coddep=:old.coddep
             and codart=:old.codart;
       end if;
    end if;

    -- Mise à jour du champ QTERESERV
    if v_majreserv IS NOT NULL THEN
       if v_majreserv = '+' then
          update gcstock set qtereserv = nvl(qtereserv,0) - n_qte
           where coddep=:old.coddep
             and codart=:old.codart;
       else
          update gcstock set qtereserv = nvl(qtereserv,0) + n_qte
           where coddep=:old.coddep
             and codart=:old.codart;
       end if;
    end if;

    -- Mise à jour du champ QTECDE
    if v_majcde IS NOT NULL THEN
       if v_majcde = '+' then
          update gcstock set qtecde = nvl(qtecde,0) - n_qte
           where coddep=:old.coddep
		     and codart=:old.codart;
       else
          update gcstock set qtecde = nvl(qtecde,0) + n_qte
           where coddep=:old.coddep
		     and codart=:old.codart;
       end if;
    end if;

    -- Mise à jour du champ QTEDA
    if v_type = 'DA' THEN
	   update gcstock set qteda = nvl(qteda,0) - n_qte
	    where coddep=:old.coddep
		  and codart=:old.codart;
    end if;

    if v_gesstatut='O' and Nvl(:old.qtebrd,0) != 0 and (v_majstatut is not null or v_majstock='O') Then --v_majstatut = 'O' or (:old.codstat is not null and :old.codstat != 'ST') THEN
	   v_codstat := Nvl(:old.codstat,'ST');

	   If v_majstatut is null and v_majstock = 'O' Then
	      If v_sens = 'E' Then		v_majstatut := '+';
		  Else						v_majstatut := '-';
		  End if;
	   End if;

	   If :old.coddep is not null and v_codstat is not null Then
			begin
			  select quantite into n_quantite from gcstock_statut
			   where coddep=:old.coddep
				 and codart=:old.codart
				 and codstat=v_codstat;
			exception
			  when no_data_found then
				   Insert into gcstock_statut (coddep, codstat, codart, quantite) values (:old.coddep, v_codstat, :old.codart, 0);
			end;

		   if v_majstatut = '+' then
			  update gcstock_statut set quantite = nvl(quantite,0) - :old.qtebrd * nvl(:old.coeff,1)
			   where coddep = :old.coddep
				 and codart = :old.codart
				 and codstat = v_codstat;
		   else
			  update gcstock_statut set quantite = nvl(quantite,0) + :old.qtebrd * nvl(:old.coeff,1)
			   where coddep = :old.coddep
				 and codart = :old.codart
				 and codstat = v_codstat;
		   end if;
	   End if;
    end if;
  end if;

  if (inserting or updating) and (:new.typlig='0') then
	v_codtbrd 	:= :new.codtbrd;
	n_idbrd_sce	:= :new.idbrd_sce;

    begin
      select sens, type, majpret, majstock, majreserv, majcde, majstatut
        into v_sens, v_type, v_majpret, v_majstock, v_majreserv, v_majcde, v_majstatut
        from gcptbrd
       where codtbrd = v_codtbrd;
    exception
      when no_data_found then
        raise_application_error (-20501,'Type de bordereau inconnu');
    end;
	If :new.coddep is not null Then
		begin
		  select qtestock, ddersor, dderent into n_qtestock, d_ddersor, d_dderent
			from gcstock
		   where coddep=:new.coddep and
				 codart=:new.codart;
		exception
		  when no_data_found then
			   n_qtestock := 0;
			   If :new.coddep is not null Then
				   insert into gcstock (coddep, codart, qtestock, qtecde, qtereserv, qtepret, ddersor, dderent, qteinv, dderinv)
								values (:new.coddep, :new.codart, 0, 0, 0, 0,null, null, 0, null);
			   End if;
		end;
	End if;

    -- Mise à jour du chanp QTESTOCK
    if :new.qtebrd < 0 then
       n_qte := :new.qtebrd;
	elsif :new.ligne_solde = 'O' Then
	   n_qte := 0;
    elsif nvl(:new.qtetrans,0) > :new.qtebrd then
       n_qte := 0;
    else
       n_qte := :new.qtebrd - nvl(:new.qtetrans,0);
    end if;
    n_qte := n_qte * nvl(:new.coeff, 1);

    -- Si maj du stock on ne tient pas compte du champ QTETRANS
    if v_majstock = 'O' then
       select datbrd into d_datbrd from gcbrde
       where idbrd = :new.idbrd;
       if v_sens = 'E' then
          if (d_datbrd > d_dderent or d_dderent is null) then d_dderent := d_datbrd;
          end if;

          update gcstock
             set qtestock = nvl(qtestock,0) + :new.qtebrd * nvl(:new.coeff, 1),
                 dderent = d_dderent
           where coddep=:new.coddep
		     and codart=:new.codart;
       else
          if (d_datbrd > d_ddersor or d_ddersor is null) then d_ddersor := d_datbrd;
      	  end if;
      	  update gcstock
             set qtestock = nvl(qtestock,0) - :new.qtebrd * nvl(:new.coeff, 1),
                 ddersor = d_ddersor
           where coddep=:new.coddep
		     and codart=:new.codart;
       end if;
    end if;

    -- Mise à jour du champ QTEPRET
    if v_majpret IS NOT NULL THEN
       if v_majpret = '+' then
          update gcstock set qtepret = nvl(qtepret,0) + n_qte
           where coddep=:new.coddep
             and codart=:new.codart;
       else
          update gcstock set qtepret = nvl(qtepret,0) - n_qte
           where coddep=:new.coddep
             and codart=:new.codart;
       end if;
    end if;

    -- Mise à jour du champ QTERESERV
    if v_majreserv IS NOT NULL THEN
       if v_majreserv = '+' then
          update gcstock set qtereserv = nvl(qtereserv,0) + n_qte
           where coddep=:new.coddep
             and codart=:new.codart;
       else
          update gcstock set qtereserv = nvl(qtereserv,0) - n_qte
           where coddep=:new.coddep
             and codart=:new.codart;
       end if;
    end if;

    -- Mise à jour du champ QTECDE
    if v_majcde IS NOT NULL THEN
       if v_majcde = '+' then
          update gcstock set qtecde = nvl(qtecde,0) + n_qte
           where coddep=:new.coddep
		     and codart=:new.codart;
       else
          update gcstock set qtecde = nvl(qtecde,0) - n_qte
           where coddep=:new.coddep
		     and codart=:new.codart;
       end if;
    end if;

    -- Mise à jour du champ QTEDA
    if v_type = 'DA' THEN
	   update gcstock set qteda = nvl(qteda,0) + n_qte
	    where coddep=:new.coddep
		  and codart=:new.codart;
    end if;

    -- Mise à jour du champ statut
    --if v_majstatut IS NOT NULL or (:new.codstat is not null and :new.codstat != 'ST') THEN
	--If v_gesstatut = 'O'  and nvl(:new.qtebrd,0) != 0 Then
    if v_gesstatut='O' and Nvl(:new.qtebrd,0) != 0 and (v_majstatut is not null or v_majstock='O') Then
	   v_codstat := Nvl(:new.codstat,'ST');
	   If v_majstatut is null and v_majstock = 'O' Then
	      If v_sens = 'E' Then		v_majstatut := '+';
		  Else						v_majstatut := '-';
		  End if;
	   End if;

	   If :new.coddep is not null and v_codstat is not null Then
			begin
			  select quantite into n_quantite from gcstock_statut
			   where coddep = :new.coddep
				 and codart = :new.codart
				 and codstat = v_codstat;
			exception
			  when no_data_found then
				   Insert into gcstock_statut (coddep, codstat, codart, quantite) values (:new.coddep, v_codstat, :new.codart, 0);
			end;

		   if v_majstatut = '+' then
			  update gcstock_statut
				 set quantite = nvl(quantite,0) + :new.qtebrd * nvl(:new.coeff, 1)
			   where coddep = :new.coddep
			     and codart = :new.codart
				 and codstat = v_codstat;
		   else
			  update gcstock_statut
				 set quantite = nvl(quantite,0) - :new.qtebrd * nvl(:new.coeff, 1)
			   where coddep = :new.coddep
			     and codart = :new.codart
				 and codstat = v_codstat;
		   end if;
	   End if;
    end if;

  end if;
end;
/

