;
 
CREATE TRIGGER CAISSE.gcptarif_art_htarif_ins_del
AFTER INSERT OR DELETE
ON CAISSE.gcptarif_art
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
declare
  n_numord				Gcphtarif_art.numord%Type;
BEGIN
  If inserting Then
	 Select max(numord) INTO n_numord FROM GCPHTARIF_ART
	  Where codart = :new.codart
		And codtarif = :new.codtarif;
    n_numord := NVL(n_numord,0)+1;

	Insert into Gcphtarif_art (codtarif, codart, numord, datchg, anctarif, nouvtarif, motif, coduti)
						values(:new.codtarif, :new.codart, n_numord, :new.datmaj, null, :new.tarif, 'Creation', :new.coduti);

  Else
	 Select max(numord) INTO n_numord FROM GCPHTARIF_ART
	  Where codart = :old.codart
		And codtarif = :old.codtarif;
	n_numord := NVL(n_numord,0)+1;

	Insert into Gcphtarif_art (codtarif, codart, numord, datchg, anctarif, nouvtarif, motif, coduti)
						values(:old.codtarif, :old.codart, n_numord, :old.datmaj, :old.tarif, null, 'Delete', :old.coduti);
  End if;
END;
/

