CREATE TRIGGER CAISSE.gcptarif_art_tarifstd_ht
BEFORE INSERT OR UPDATE
ON CAISSE.gcptarif_art
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
declare

  v_exonere		Varchar2(1);
  n_ttaxe		GCPTARIF.ttaxe_tarif%TYPE;
  v_codrtax		GCPART.codrtax%TYPE;
  v_calc		Gcptarif.calc%Type;
BEGIN
  Select calc Into v_calc From Gcptarif
   Where codtarif = :new.codtarif;
  If v_calc = 'O' Then
     -- Cette mise à jour sera faite par le triggr "Gcpart_gcptarif_art_calc"
     Return;
  End if;		

  Select codrtax Into v_codrtax From Gcpart
   Where codart = :new.codart;  
	If v_codrtax is not null Then
		 Select max(exonere) Into v_exonere From KERNEL.Utprtax
		  Where codrtax = v_codrtax;
	Else
		 v_exonere := 'N'; 
	End if;
	
	If v_exonere = 'O' Then
		 n_ttaxe := 0;
	Else		
	   Select max(ttaxe_tarif) Into n_ttaxe From GCPART a, GCPNATA n
	    Where a.codart = :new.codart
		  And a.codnata = n.codnata;
		  
	   If n_ttaxe is null Then		
		  Select max(ttaxe_tarif) INTO n_ttaxe From GCPTARIF
		   Where codtarif = '0';
	   End if;	   

	End if;    
   
  IF NVL(n_ttaxe,0) = 0 THEN
  	 :new.tarif_ht := :new.tarif;  	 
  ELSE
  	 :new.tarif_ht := :new.tarif / (1+(n_ttaxe/100));
  END IF;
end;
/

