CREATE TRIGGER CAISSE.gcbrdd_gcprmp
AFTER INSERT  OR DELETE  OR UPDATE
OF coddep, codart, codtbrd, qtebrd, coeff, typlig, purevient, montrevient, zlibre_l5
ON CAISSE.gcbrdd
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
declare
  v_sens        gcptbrd.sens%type;
  v_codart      gcprmp.codart%TYPE;
  n_qte			gcprmp.quantite%TYPE;
  n_mont		gcprmp.montant%type;
  n_nqte		Number; -- gcprmp.quantite%TYPE;
  n_nmont		Number;--gcprmp.montant%TYPE;
  n_sqte		Number; -- gcprmp.quantite%TYPE;
  n_smont		Number;--gcprmp.montant%TYPE;
  n_prmp		Number; --gcprmp.prmp%TYPE;
  v_codeta      gcpdep.codeta%TYPE;
  v_majstock    gcptbrd.majstock%TYPE;
  v_prmp_unique	Gcppar.valc%Type;
begin
  Select max(valc) Into v_prmp_unique From Gcppar
   Where codpar='PARGEN' and cle='PUN';
  v_prmp_unique := Nvl(v_prmp_unique,'N');

  if (deleting or updating) and :old.typlig='0' then
     begin --on récupère le sens du mvt
       select majstock, sens into v_majstock, v_sens
         from gcptbrd
        where codtbrd=:old.codtbrd;
     exception
       when no_data_found then
         raise_application_error (-20501,'Type de bordereau inconnu');
     end;

     if v_majstock != 'O' then
		RETURN;
     end if;

     begin --on récupère l'établissement
       select codeta into v_codeta
         from gcpdep
        where coddep =:old.coddep;
     exception
       when no_data_found then
         raise_application_error (-20502,'Code établissement inconnu');
     end;

     begin --on vérifie l'existence de l'article dans la table gcprmp
       select codart, NVL(montant,0), NVL(quantite,0) into v_codart, n_mont, n_qte
         from gcprmp
        where codeta = v_codeta  and
	          periode = '999912' and
              codart = :old.codart;
     exception
       when no_data_found then
           insert into gcprmp(codeta, periode, codart, quantite, montant, prmp)
           values (v_codeta, '999912',:old.codart, 0, 0, 0);
         --raise_application_error (-20503,'Article inexistant dans PRMP');
     end;

	 If v_prmp_unique = 'O' Then
		SELECT sum(montant), sum(quantite) INTO n_smont, n_sqte from Gcprmp
		 where periode = '999912'
		   and codart = :old.codart;
	 Else
		n_smont := n_mont;
		n_sqte 	:= n_qte;
	 End if;

     --MAJ DE LA TABLE DES PRIX MOYENS PONDERES
     IF v_sens = 'E' THEN
        n_nqte := NVL(n_qte,0) - nvl(:old.qtebrd,0) * nvl(:old.coeff,1);

		n_sqte := NVL(n_sqte,0) - nvl(:old.qtebrd,0) * nvl(:old.coeff,1);
        n_smont := NVL(n_smont,0) - nvl(:old.montrevient,0); -- * nvl(:old.coeff,1);
     ELSE
        n_nqte := NVL(n_qte,0) + Nvl(:old.qtebrd,0) * nvl(:old.coeff,1);

		n_sqte := NVL(n_sqte,0) + nvl(:old.qtebrd,0) * nvl(:old.coeff,1);
        n_smont := NVL(n_smont,0) + nvl(:old.montrevient,0); -- * nvl(:old.coeff,1);
	END IF;

     if n_sqte = 0 then
        update gcprmp
           set quantite = n_nqte,
               montant = Round(n_nqte*prmp)
--	       prmp = 0   /* on ne touche pas au PRMP */
         where codeta = v_codeta  and
	       periode = '999912' and
               codart = :old.codart;
     else
		Begin
			n_prmp := Round(n_smont/n_sqte,3);
		Exception
			when others then n_prmp := null;
		End;

		update gcprmp --mise à jour de la table des prmp
           set quantite = n_nqte,
               montant = n_nmont,
			   prmp = Round(n_prmp,3)
         where codeta = v_codeta  and
	       periode = '999912' and
               codart = :old.codart;

		-- Mise à jour du PRMP autres établissements
		If v_prmp_unique = 'O' Then
		   update gcprmp set montant = Round(quantite*n_prmp), prmp = Round(n_prmp,3)
            where codeta != v_codeta
	          and periode = '999912'
              and codart = :old.codart;
		End if;
	 end if;
  end if; /*DELETING or UPDATING*/

  if (inserting or updating) and :new.typlig='0'  then
     begin --on récupère le sens du mvt
       select majstock, sens into v_majstock, v_sens
         from gcptbrd
        where codtbrd=:new.codtbrd;
     exception
       when no_data_found then
         raise_application_error (-20501,'Type de bordereau inconnu');
     end;

     if v_majstock != 'O' then
		RETURN;
     end if;

     begin --on récupère l'établissement
       select codeta into v_codeta
         from gcpdep
        where coddep =:new.coddep;
     exception
       when no_data_found then
			Raise_application_error (-20502,'Code établissement inconnu');
     end;


     begin --on vérifie l'existence de l'article dans la table gcprmp
       select codart, NVL(montant,0), NVL(quantite,0) into v_codart, n_mont, n_qte
         from gcprmp
        where codeta = v_codeta
	      and periode = '999912'
          and codart = :new.codart;
     exception
       when no_data_found then
           insert into gcprmp(codeta, periode, codart, quantite, montant, prmp)
           values (v_codeta, '999912',:new.codart, 0, 0, 0);
           n_qte := 0;
           n_mont := 0;
     end;

	 If v_prmp_unique = 'O' Then
		SELECT sum(montant), sum(quantite) INTO n_smont, n_sqte from Gcprmp
		 where periode = '999912'
		   and codart = :new.codart;
	 Else
		n_smont := n_mont;
		n_sqte 	:= n_qte;
	 End if;

     IF v_sens = 'E' THEN
        n_nqte := NVL(n_qte,0) + Nvl(:new.qtebrd,0) * nvl(:new.coeff, 1);

		n_sqte := NVL(n_sqte,0) + nvl(:new.qtebrd,0) * nvl(:new.coeff,1);
        n_smont := NVL(n_smont,0) + nvl(:new.montrevient,0); -- * nvl(:old.coeff,1);
	 ELSE
        n_nqte := n_qte - Nvl(:new.qtebrd,0) * nvl(:new.coeff,1);

		n_sqte := NVL(n_sqte,0) - nvl(:new.qtebrd,0) * nvl(:new.coeff,1);
        n_smont := NVL(n_smont,0) - nvl(:new.montrevient,0); -- * nvl(:old.coeff,1);
	 END IF;

     if n_sqte=0 then
        update gcprmp --mise à jour de la table des prmp
           set quantite = n_nqte,
               montant = Round(n_nqte * prmp)
--	      prmp=0  /* On ne touche pas au PRMP */
         where codeta = v_codeta
	       and periode = '999912'
           and codart = :new.codart;
     else
		Begin
			n_prmp := Round(n_smont/n_sqte,3);
		Exception
			when others then n_prmp := null;
		End;
        update gcprmp --mise à jour de la table des prmp
           set quantite = n_nqte,
               montant = Round(n_nqte*n_prmp),
			   prmp=n_prmp
         where codeta = v_codeta
	        and periode = '999912'
            and codart = :new.codart;

		-- Mise à jour du PRMP autres établissements
		If v_prmp_unique = 'O' Then
		   update gcprmp set montant = Round(quantite*n_prmp), prmp = n_prmp
            where codeta != v_codeta
	          and periode = '999912'
              and codart = :new.codart;
		End if;
	 end if;
   end if;/*
exception
	when others then
         raise_application_error (-20599,'**** qte='||to_char(n_nqte)||',mont='||to_char(n_nmont)||',prmp='||to_char(n_prmp));
		 --raise_application_error (-20599,'sqlcode '||sqlcode||', '||sqlerrm);*/
end;
/

