CREATE TRIGGER Xcpta.cp_ecr_block_delete
BEFORE DELETE
ON Xcpta.cp_ecr
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
declare
  n_count		 Number;	
  n_numsai		 Number;
BEGIN
  n_numsai := :old.numsai;
  
  Select count(*) Into n_count From Copar
   Where codpar = 'ECRPROTECT'
     and valn = n_numsai;
	 
  If n_count > 0 Then		
	 raise_application_error (-20501,'delete not allowed for this account entry "'||to_char(n_numsai)||'".');
  End if;
END;
/

