CREATE TRIGGER XCPTA.block_doublon_cp_ecr_sales
BEFORE INSERT OR UPDATE
ON XCPTA.cp_ecr
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
 WHEN (new.codjou = 'SALES') declare
  n_count		Number;
begin
 if inserting Then
	Select count(*) Into n_count from cp_ecr where cdos=:new.cdos and libecr=:new.libecr and codjou=:new.codjou and datcpt=:new.datcpt and datpce=:new.datpce;
 elsif updating then
	Select count(*) Into n_count from cp_ecr where cdos=:new.cdos and numsai!=:new.numsai and libecr=:new.libecr and codjou=:new.codjou and datcpt=:new.datcpt and datpce=:new.datpce;
 end if;

 if n_count > 0 Then
    Raise_application_error(-20002,'Duplicate account entrie');
 End if;
end;
/

